	(1869, 2, 1784269033, 'theme_boost', 'scsspre', '.login-logo {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.login-logo::before {\r\n    content: "E-Learning SMPN 6 Bandar Lampung";\r\n    display: block;\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n    color: #333333;\r\n    margin-bottom: 15px;\r\n    text-align: center;\r\n}', ''),
	(1870, 2, 1784269353, 'theme_boost', 'scsspre', '.login-logo {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.login-logo::before {\r\n    content: "E-Learning SMPN 6 Bandar Lampung";\r\n    display: block;\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n    color: #333333;\r\n    margin-bottom: 15px;\r\n    text-align: center;\r\n}\r\n\r\n/* Menyembunyikan tombol Lupa Password */\r\n.forgetpass {\r\n    display: none !important;\r\n}\r\n\r\n/* Menyembunyikan peringatan Cookies */\r\n.logincookies {\r\n    display: none !important;\r\n}\r\n\r\n/* Menyembunyikan tombol dan teks Guest/Tamu */\r\n#guestlogin, .guestsub {\r\n    display: none !important;\r\n}', '.login-logo {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.login-logo::before {\r\n    content: "E-Learning SMPN 6 Bandar Lampung";\r\n    display: block;\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n    color: #333333;\r\n    margin-bottom: 15px;\r\n    text-align: center;\r\n}'),
	(1871, 2, 1784269906, 'theme_boost', 'scsspre', '.login-logo {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.login-logo::before {\r\n    content: "E-Learning SMPN 6 Bandar Lampung";\r\n    display: block;\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n    color: #333333;\r\n    margin-bottom: 15px;\r\n    text-align: center;\r\n}\r\n\r\n/* Menghapus paksa tombol Lupa Password */\r\n.forgotpass, a[href*="forgot_password.php"], .login-forgotpassword {\r\n    display: none !important;\r\n}\r\n\r\n/* Menghapus paksa peringatan Cookies */\r\n.cookieshelp, .login-settings, .login-instructions {\r\n    display: none !important;\r\n}\r\n\r\n/* Menghapus paksa sisa teks Guest jika masih ada */\r\n.guestsub, .loginguest, a[href*="guest=1"] {\r\n    display: none !important;\r\n}', '.login-logo {\r\n    display: flex !important;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n.login-logo::before {\r\n    content: "E-Learning SMPN 6 Bandar Lampung";\r\n    display: block;\r\n    font-size: 1.5rem;\r\n    font-weight: bold;\r\n    color: #333333;\r\n    margin-bottom: 15px;\r\n    text-align: center;\r\n}\r\n\r\n/* Menyembunyikan tombol Lupa Password */\r\n.forgetpass {\r\n    display: none !important;\r\n}\r\n\r\n/* Menyembunyikan peringatan Cookies */\r\n.logincookies {\r\n    display: none !important;\r\n}\r\n\r\n/* Menyembunyikan tombol dan teks Guest/Tamu */\r\n#guestlogin, .guestsub {\r\n    display: none !important;\r\n}'),
