	(597, 'id', 1, 'editthisactivity', 'Edit this activity', 'Ubah aktivitas ini', NULL, 1785718227, NULL, 0, 0),
	(598, 'id', 1, 'editthiscategory', 'Edit this category', 'Edit kategori ini', NULL, 1785718227, NULL, 0, 0),
	(599, 'id', 1, 'edituser', 'Edit user accounts', 'Ubah keanggotaan pengguna', NULL, 1785718227, NULL, 0, 0),
	(600, 'id', 1, 'edulevelother', 'Other', 'Lain-lain', NULL, 1785718227, NULL, 0, 0),
	(601, 'id', 1, 'edulevelteacher', 'Teaching', 'Mengajar', NULL, 1785718227, NULL, 0, 0),
	(602, 'id', 1, 'edulevelparticipating', 'Participating', 'Berpartisipasi', NULL, 1785718227, NULL, 0, 0),
	(603, 'id', 1, 'edulevel', 'All events', 'Semua acara', NULL, 1785718227, NULL, 0, 0),
	(604, 'id', 1, 'edulevel_help', '* Teaching - actions performed by a teacher, e.g. updating a resource\n* Participating - actions performed by a student, e.g. posting in a forum\n* Other - actions performed by a user with a role other than teacher or student', '* Pengajaran - tindakan yang dilakukan oleh seorang pangajar, mis. memperbarui sebuah sumber\n* Berpartisipasi - tindakan yang dilakukan oleh siswa, mis. mengirim pesan di forum\n* Lainnya - tindakan yang dilakukan oleh pengguna dengan peran selain pengajar atau siswa', NULL, 1785718227, NULL, 0, 0),
	(605, 'id', 1, 'email', 'Email address', 'Alamat surel', NULL, 1785718227, NULL, 0, 0),
	(606, 'id', 1, 'emailalreadysent', 'A password reset email has already been sent. Please check your email.', 'Sebuah surel berisi kata sandi telah dikirim. Silakan periksa surel Anda', NULL, 1785718227, NULL, 0, 0),
	(607, 'id', 1, 'emailactive', 'Email activated', 'Surel diaktifkan', NULL, 1785718227, NULL, 0, 0),
	(608, 'id', 1, 'emailagain', 'Email (again)', 'Surel (lagi)', NULL, 1785718227, NULL, 0, 0),
	(609, 'id', 1, 'emailconfirm', 'Confirm your account', 'Konfirmasikan keanggotaan Anda', NULL, 1785718227, NULL, 0, 0),
	(610, 'id', 1, 'emailconfirmation', 'Hi {$a->firstname},\n\nA new account has been requested at \'{$a->sitename}\' using your email address.\n\nTo confirm your new account, please click the link below:\n\n<a href="{$a->link}">Confirm your account</a>\n\n\nIf you need help, please contact the site administrator,\n{$a->admin}', 'Hai {$a->firstname},\n\nAkun baru telah diminta di \'{$a->sitename}\' menggunakan alamat surel Anda.\n\nUntuk mengonfirmasikan akun baru Anda, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Konfirmasikan akun Anda</a>\n\n\nJika Anda membutuhkan bantuan, silakan hubungi administrator situs,\n{$a->admin}', NULL, 1785718227, NULL, 0, 0),
	(611, 'id', 1, 'emailconfirmationresend', 'Resend confirmation email', 'Kirimkan kembali surel konfirmasi', NULL, 1785718227, NULL, 0, 0),
	(612, 'id', 1, 'emailconfirmationsubject', '{$a}: account confirmation', '{$a}: konfirmasi keanggotaan', NULL, 1785718227, NULL, 0, 0),
	(613, 'id', 1, 'emailconfirmsent', '<p>An email should have been sent to your address at <b>{$a}</b></p>\n   <p>It contains easy instructions to complete your registration.</p>\n   <p>If you continue to have difficulty, contact the site administrator.</p>', '<p> Sebuah surel seharusnya telah dikirimkan ke alamat Anda di <b>{$a}</b> </p> <p> Berisi petunjuk mudah untuk menyelesaikan pendaftaran Anda. </p> <p> Jika Anda melanjutkan mengalami kesulitan, hubungi administrator situs. </p>', NULL, 1785718227, NULL, 0, 0),
	(614, 'id', 1, 'emailconfirmsentfailure', 'Confirmation email failed to send', 'Pengiriman surel konfirmasi gagal', NULL, 1785718227, NULL, 0, 0),
	(615, 'id', 1, 'emailconfirmsentsuccess', 'Confirmation email sent successfully', 'Pengiriman surel konfirmasi sukses', NULL, 1785718227, NULL, 0, 0),
	(616, 'id', 1, 'emaildigest', 'Email digest type', 'Tipe intisari surel', NULL, 1785718227, NULL, 0, 0),
	(617, 'id', 1, 'emaildigest_help', 'This is the daily digest setting that forums will use by default.\n\n* No digest - you will receive one e-mail per forum post;\n* Digest - complete posts - you will receive one digest e-mail per day containing the complete contents of each forum post;\n* Digest - subjects only - you will receive one digest e-mail per day containing just the subject of each forum post.\n\nYou can also choose a different setting for each forum if you wish.', 'Ini adalah setelan intisari harian yang akan digunakan forum secara bawaan. <ul>\n<li> Tidak ada intisari - Anda akan menerima satu surel per kiriman forum;\n</li><li>Intisari - kiriman lengkap - Anda akan menerima satu surel intisari per hari yang berisi konten lengkap dari setiap kiriman forum;\n</li><li>Intisari - hanya subjek - Anda akan menerima satu surel intisari per hari yang hanya berisi subjek dari setiap kiriman forum. </li> </ul>\n\nAnda juga dapat memilih setelan berbeda untuk setiap forum jika diinginkan.', NULL, 1785718227, NULL, 0, 0),
	(618, 'id', 1, 'emaildigestcomplete', 'Complete (daily email with full posts)', 'Lengkap (surel harian dengan kiriman penuh)', NULL, 1785718227, NULL, 0, 0),
	(619, 'id', 1, 'emaildigestoff', 'No digest (single email per forum post)', 'Tidak dirangkum (surel tunggal per kiriman forum)', NULL, 1785718227, NULL, 0, 0),
	(620, 'id', 1, 'emaildigestsubjects', 'Subjects (daily email with subjects only)', 'Subjek (surel harian dengan subjek saja)', NULL, 1785718227, NULL, 0, 0),
	(621, 'id', 1, 'emaildisable', 'This email address is disabled', 'Alamat surel ini dinonaktifkan', NULL, 1785718227, NULL, 0, 0),
	(622, 'id', 1, 'emaildisableclick', 'Click here to disable all email from being sent to this address', 'Klik di sini untuk menonaktifkan semua surel yang dikirim ke alamat ini', NULL, 1785718227, NULL, 0, 0),
	(623, 'id', 1, 'emaildisplay', 'Email visibility', 'Tampilan surel', NULL, 1785718227, NULL, 0, 0),
	(624, 'id', 1, 'emaildisplay_help', '* Hidden - Only users with appropriate permissions such as teachers can view your email address.\n* Visible to everyone - All users on the site can view your email address.\n* Visible to course participants - Only participants of courses you are enrolled in can view your email address.', '* Tersembunyi - Hanya pengguna dengan izin yang sesuai seperti pengajar yang dapat melihat alamat surel Anda.\n* Dapat dilihat oleh semua orang - Semua pengguna di situs dapat melihat alamat surel Anda.\n* Dapat dilihat oleh peserta kursus - Hanya peserta kursus yang Anda ikuti yang dapat melihat alamat surel Anda.', NULL, 1785718227, NULL, 0, 0),
	(625, 'id', 1, 'emaildisplaycourse', 'Visible to course participants', 'Terlihat peserta kursus', NULL, 1785718227, NULL, 0, 0),
	(626, 'id', 1, 'emaildisplaycoursemembersonly', '(Visible to other course participants)', '(Terlihat oleh peserta kursus yang lain)', NULL, 1785718227, NULL, 0, 0),
	(627, 'id', 1, 'emaildisplayeveryone', '(Visible to everyone)', '(Terlihat oleh semua orang)', NULL, 1785718227, NULL, 0, 0),
	(628, 'id', 1, 'emaildisplayhide', '(Hidden from everyone except users with appropriate permissions)', '(Tersembunyi dari semua orang kecuali pengguna dengan izin yang sesuai)', NULL, 1785718227, NULL, 0, 0),
	(629, 'id', 1, 'emaildisplayno', 'Hidden', 'Tersembunyi', NULL, 1785718227, NULL, 0, 0),
	(630, 'id', 1, 'emaildisplayyes', 'Visible to everyone', 'Terlihat semua orang', NULL, 1785718227, NULL, 0, 0),
	(631, 'id', 1, 'emailenable', 'This email address is enabled', 'Alamat surel ini diaktifkan', NULL, 1785718227, NULL, 0, 0),
	(632, 'id', 1, 'emailenableclick', 'Click here to re-enable all email being sent to this address', 'Klik di sini untuk mengaktifkan kembali semua surel yang dikirim ke alamat ini', NULL, 1785718227, NULL, 0, 0),
	(633, 'id', 1, 'emailexists', 'This email address is already registered.', 'Surel ini telah terdaftar.', NULL, 1785718227, NULL, 0, 0),
	(634, 'id', 1, 'emailexistssignuphint', 'Perhaps you created an account in the past? {$a}', 'Mungkin sebelumnya Anda sudah membuat akun? {$a}', NULL, 1785718227, NULL, 0, 0),
	(635, 'id', 1, 'emailexistshintlink', 'Recover forgotten username or password', 'Pulihkan nama pengguna atau kata sandi yang terlupakan', NULL, 1785718227, NULL, 0, 0),
	(636, 'id', 1, 'emailformat', 'Email format', 'Format surel', NULL, 1785718227, NULL, 0, 0),
	(637, 'id', 1, 'emailcharset', 'Email charset', 'Karakter set surel', NULL, 1785718227, NULL, 0, 0),
	(638, 'id', 1, 'emailmustbereal', 'Note: your email address must be a real one', 'Catatan: alamat surel Ada harus yang asli', NULL, 1785718227, NULL, 0, 0),
	(639, 'id', 1, 'emailnotallowed', 'Email addresses in these domains are not allowed ({$a})', 'Alamat surel dengan domain {$a} tidak diperbolehkan', NULL, 1785718227, NULL, 0, 0),
	(640, 'id', 1, 'emailnotfound', 'The email address was not found in the database', 'Alamat surel tidak ditemukan dalam basis data', NULL, 1785718227, NULL, 0, 0),
	(641, 'id', 1, 'emailonlyallowed', 'This email cannot be used. Allowed email domains are: {$a}.', 'Surel ini tidak dapat digunakan. Domain surel yang diperbolehkan adalah: {$a}.', NULL, 1785718227, NULL, 0, 0),
	(642, 'id', 1, 'emailpasswordconfirmation', 'Hi {$a->firstname},\n\nSomeone (probably you) has requested a new password for your account on \'{$a->sitename}\'.\n\nTo confirm this and have a new password sent to you via email, please click the link below:\n\n<a href="{$a->link}">Get a new password</a>\n\n\nIf you need help, please contact the site administrator.\n{$a->admin}', 'Hai {$a->firstname},\n\nSeseorang (mungkin Anda) telah meminta kata sandi baru untuk akun Anda di \'{$a->sitename}\'.\n\nUntuk mengkonfirmasi hal ini dan mendapatkan kata sandi baru yang dikirimkan kepada Anda melalui surel, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Dapatkan kata sandi baru</a>\n\n\nJika Anda membutuhkan bantuan, silakan hubungi administrator situs.\n{$a->admin}', NULL, 1785718227, NULL, 0, 0),
	(643, 'id', 1, 'emailpasswordconfirmationsubject', '{$a}: Change password confirmation', '{$a}: konfirmasi penggantian kata sandi', NULL, 1785718227, NULL, 0, 0),
	(644, 'id', 1, 'emailpasswordconfirmmaybesent', '<p>If you supplied a correct username or unique email address then an email should have been sent to you.</p>\n   <p>It contains easy instructions to confirm and complete this password change.\nIf you continue to have difficulty, please contact the site administrator.</p>', '<p> Jika Anda memberikan nama pengguna atau alamat surel yang benar, maka seharusnya surel dikirimkan kepada Anda. </p> <p> Berisi instruksi mudah untuk mengonfirmasi dan menyelesaikan perubahan kata sandi ini. Jika Anda terus mengalami kesulitan, silakan hubungi administrator situs. </p>', NULL, 1785718227, NULL, 0, 0),
	(645, 'id', 1, 'emailpasswordconfirmnoemail', '<p>The user account you specified does not have a recorded email address.</p>\n   <p>Please contact the site administrator.</p>', '<p> Akun pengguna yang Anda tentukan tidak memiliki alamat surel yang tercatat. </p> <p>Sila hubungi Administrator situs. </p>', NULL, 1785718227, NULL, 0, 0),
	(646, 'id', 1, 'emailpasswordconfirmnotsent', '<p>The user detail you supplied does not identify an existing user account.</p>\n   <p>Please check the information you entered, then try again.\nIf you continue to have difficulty, please contact the site administrator.</p>', '<p>Detail pengguna yang Anda berikan tidak mengidentifikasi akun pengguna yang ada.</p>\n<p>Silakan periksa informasi yang Anda masukkan, lalu coba lagi. Jika Anda terus mengalami kesulitan, silakan hubungi Administrator situs. </p>', NULL, 1785718227, NULL, 0, 0),
	(647, 'id', 1, 'emailpasswordconfirmsent', 'An email should have been sent to your address at <b>{$a}</b>.\n<br />It contains easy instructions to confirm and complete this password change.\nIf you continue to have difficulty, contact the site administrator.', 'Sebuah surel telah dikirimkan ke alamat Anda di <b>{$a}</b>. <p>Surel ini berisi instruksi untuk melakukan konfirmasi terhadap penggantian kata sandi Anda. Jika Anda menemui kesulitan, Hubungi administrator situs.</p>', NULL, 1785718227, NULL, 0, 0),
	(648, 'id', 1, 'emailpasswordchangeinfo', 'Hi {$a->firstname},\n\nSomeone (probably you) has requested a new password for your account \'{$a->username}\' on \'{$a->sitename}\'.\n\nTo change your password, please click the link below:\n\n<a href="{$a->link}">Change password</a>\n\n\nIf you need help, please contact the site administrator.\n{$a->admin}', 'Hai {$a->firstname},\n\nSeseorang (mungkin Anda) telah meminta kata sandi baru untuk akun Anda \'{$a->username}\' di \'{$a->sitename}\'.\n\nUntuk mengubah kata sandi Anda, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Ubah kata sandi</a>\n\nJika Anda membutuhkan bantuan, silakan hubungi administrator situs.\n{$a->admin}', NULL, 1785718227, NULL, 0, 0),
	(649, 'id', 1, 'emailpasswordchangeinfodisabled', 'Hi {$a->firstname},\n\nSomeone (probably you) has requested a new password for your account on \'{$a->sitename}\'.\n\nUnfortunately your account on this site is disabled, so the password cannot be reset. Please contact the site administrator {$a->admin}.', 'Hai {$a->firstname},\n\nSeseorang (mungkin Anda) telah meminta kata sandi baru untuk akun anda di \'{$a->sitename}\'.\n\nSayangnya akun Anda di situs ini dinonaktifkan dan tidak dapat direset, silakan hubungi pengelola situs, {$a->admin}', NULL, 1785718227, NULL, 0, 0),
	(650, 'id', 1, 'emailpasswordchangeinfofail', 'Hi {$a->firstname},\n\nSomeone (probably you) has requested a new password for your account on \'{$a->sitename}\'.\n\nUnfortunately passwords cannot be reset on this site. Please contact the site administrator {$a->admin}.', 'Hai {$a->firstname},\n\nSeseorang (mungkin Anda) telah meminta kata sandi baru untuk akun Anda di \'{$a->sitename}\'.\n\nSayangnya kata sandi tersebut tidak dapat direset pada situs ini, silakan hubungi administrator situs {$a->admin}.', NULL, 1785718227, NULL, 0, 0),
	(651, 'id', 1, 'emailpasswordchangeinfosubject', '{$a}: Change password information', '{$a}: Informasi ubah kata sandi', NULL, 1785718227, NULL, 0, 0),
	(652, 'id', 1, 'emailresetconfirmation', 'Hi {$a->firstname},\n\nA password reset was requested for your account \'{$a->username}\' at {$a->sitename}.\n\nTo confirm this request, and set a new password for your account, please click the link below:\n\n<a href="{$a->link}">Reset password</a>\n\n\n(This link is valid for {$a->resetminutes} minutes from the time this reset was first requested.)\n\nIf this password reset was not requested by you, no action is needed.\n\nIf you need help, please contact the site administrator.\n{$a->admin}', 'Hai {$a->firstname},\n\nPermintaan pengaturan ulang kata sandi telah diajukan untuk akun Anda \'{$a->username}\' di {$a->sitename}.\n\nUntuk mengonfirmasikan permintaan ini, dan mengatur kata sandi baru untuk akun Anda, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Atur ulang kata sandi</a>\n\n\n(Tautan ini berlaku selama {$a->resetminutes} menit sejak permintaan pengaturan ulang pertama kali diajukan.)\n\nJika pengaturan ulang kata sandi ini bukan permintaan Anda, tidak perlu tindakan apa pun.\n\nJika Anda memerlukan bantuan, silakan hubungi administrator situs.\n{$a->admin}', NULL, 1785718227, NULL, 0, 0),
	(653, 'id', 1, 'emailresetconfirmationsubject', '{$a}: Password reset request', '{$a}: Permintaan reset kata sandi', NULL, 1785718227, NULL, 0, 0),
	(654, 'id', 1, 'emailresetconfirmsent', 'An email has been sent to your address at <b>{$a}</b>.\n<br />It contains easy instructions to confirm and complete this password change.\nIf you continue to have difficulty, contact the site administrator.', 'Sebuah surel telah dikirim ke alamat Anda di <b>{$a}.</b> <br />Berisi petunjuk mudah untuk mengonfirmasi dan menyelesaikan perubahan kata sandi ini.\n\nJika Anda terus mengalami kesulitan, silakan hubungi Administrator situs.', NULL, 1785718227, NULL, 0, 0),
	(655, 'id', 1, 'emailstop', 'Disable notifications', 'Nonaktifkan notifikasi', NULL, 1785718227, NULL, 0, 0),
	(656, 'id', 1, 'emailtoprivatefiles', 'You can also e-mail files as attachments straight to your private files space. Simply attach your files to an e-mail and send it to {$a}', 'Anda juga dapat mengirim berkas melalui berkas sebagai lampiran langsung ke ruang berkas pribadi Anda. Cukup lampirkan berkas Anda pada surel dan kirimkan ke {$a}', NULL, 1785718227, NULL, 0, 0),
	(657, 'id', 1, 'emailtoprivatefilesdenied', 'Your administrator has disabled the option to upload your own private files.', 'Administrator telah menonaktifkan opsi untuk mengunggah berkas pribadi Anda sendiri.', NULL, 1785718227, NULL, 0, 0),
