	(1325, 'id', 1, 'newactivityname', 'New name for activity {$a}', 'Nama baru untuk aktivitas {$a}', NULL, 1785718228, NULL, 0, 0),
	(1326, 'id', 1, 'newcourse', 'New course', 'Kursus baru', NULL, 1785718228, NULL, 0, 0),
	(1327, 'id', 1, 'newloginnotificationtitle', 'New sign in to your {$a} account', 'Anda baru saja log masuk ke akun {$a}', NULL, 1785718228, NULL, 0, 0),
	(1328, 'id', 1, 'newloginnotificationbodysmall', 'Your {$a} account was just signed in to from a new device.', 'Akun {$a} Anda baru saja masuk dari perangkat baru.', NULL, 1785718228, NULL, 0, 0),
	(1329, 'id', 1, 'newloginnotificationbodyfull', '<p>Hi {$a->userfullname},</p>\n<p>Your {$a->sitename} account was just signed in to from a new device.</p>\n<ul>\n<li>Your account: {$a->username} {$a->useremail}</li>\n<li>{$a->logintime}</li>\n<li>Device: {$a->logindevice}</li>\n<li>IP: {$a->loginip}</li>\n</ul>\n<p>If this was you, then you don\'t need to do anything.</p>\n<p>If you don\'t recognise this activity, please <a href="{$a->changepasswordlink}">change your password</a>.</p>', '<p>Hai {$a->userfullname},</p>\n<p>Akun Anda pada {$a->sitename} baru saja masuk dari perangkat baru.</p> <ul>\n <li>Akun Anda: {$a->username} {$a->useremail}</li>\n<li>{$a->logintime}</li>\n<li>Perangkat: {$a->logindevice}</li>\n<li>IP: {$a->loginip}</li>\n</ul>\n<p>Jika ini Anda, maka Anda dapat abaikan pesan ini.</p> <p>Jika Anda tidak mengenali aktivitas ini, harap  <a href="{$a->changepasswordlink}">ubah sandi Anda</a></p>', NULL, 1785718228, NULL, 0, 0),
	(1330, 'id', 1, 'newpassword', 'New password', 'Kata sandi baru', NULL, 1785718228, NULL, 0, 0),
	(1331, 'id', 1, 'newpassword_help', 'Enter a new password or leave blank to keep current password.', 'Masukkan kata sandi baru atau kosongkan untuk menggunakan kata sandi saat ini.', NULL, 1785718228, NULL, 0, 0),
	(1332, 'id', 1, 'newpasswordfromlost', '<strong>NOTICE:</strong> Your <strong>Current password</strong> will have been sent to you in the <strong>second</strong> of the two emails sent as part of the lost password recovery process. Make sure you have received your replacement password before continuing with this screen.', '<strong> PEMBERITAHUAN: </strong> <strong> kata sandi sekarang </strong> akan dikirim kepada Anda dalam <strong> beberapa detik </strong> dari dua surel yang dikirim sebagai bagian dari proses pemulihan sandi hilang. Pastikan Anda telah menerima sandi pengganti Anda sebelum melanjutkan dengan layar ini.', NULL, 1785718228, NULL, 0, 0),
	(1333, 'id', 1, 'newpicture', 'New picture', 'Foto baru', NULL, 1785718228, NULL, 0, 0),
	(1334, 'id', 1, 'newpicture_help', 'To add a new picture, browse and select an image (in JPG or PNG format) then click "Update profile". The image will be cropped to a square and resized to 100x100 pixels.', 'Untuk menambahkan gambar baru, telusuri dan pilih gambar (dalam format JPG atau PNG), lalu klik "Perbarui profil". Gambar akan dipangkas hingga persegi dan diubah ukurannya menjadi 100x100 piksel.', NULL, 1785718228, NULL, 0, 0),
	(1335, 'id', 1, 'newpictureusernotsetup', 'A profile picture can only be added once all required profile information has been saved.', 'Gambar profil hanya dapat ditambahkan setelah semua informasi profil yang diperlukan telah disimpan.', NULL, 1785718228, NULL, 0, 0),
	(1336, 'id', 1, 'newsectionname', 'New name for section {$a}', 'Nama baru untuk bagian {$a}', NULL, 1785718228, NULL, 0, 0),
	(1337, 'id', 1, 'newsitem', 'news item', 'item berita', NULL, 1785718228, NULL, 0, 0),
	(1338, 'id', 1, 'newsitems', 'announcements', 'pengumuman', NULL, 1785718228, NULL, 0, 0),
	(1339, 'id', 1, 'newsitemsnumber', 'Number of announcements', 'Jumlah pengumuman', NULL, 1785718228, NULL, 0, 0),
	(1340, 'id', 1, 'newsitemsnumber_help', 'The announcements forum has forced subscription set by default. Only teachers and other users with appropriate permission can post in it.\n\nIf you don\'t require an announcements forum, set this to zero.\n\nThis setting also determines how many recent announcements appear in the latest announcements block.', 'Forum pengumuman telah memaksa langganan ditetapkan secara bawaan. Hanya guru dan pengguna lain dengan izin yang sesuai yang dapat mengirim di dalamnya.\n\nJika Anda tidak memerlukan forum pengumuman, setel ke nol.\n\nSetelan ini juga menentukan berapa banyak pengumuman terbaru yang muncul di blok pengumuman terbaru.', NULL, 1785718228, NULL, 0, 0),
	(1341, 'id', 1, 'newuser', 'New user', 'Pengguna baru', NULL, 1785718228, NULL, 0, 0),
	(1342, 'id', 1, 'newusernewpasswordsubj', 'New user account', 'Akun pengguna baru', NULL, 1785718228, NULL, 0, 0),
	(1343, 'id', 1, 'newusernewpasswordtext', 'Hi {$a->firstname},\n\nAn account has been created for you at \'{$a->sitename}\'.\n\n   username: {$a->username}\n   password: {$a->newpassword}\n\n(You will be prompted to change your password when you log in for the first time.)\n\n\n<a href="{$a->link}">Click to log in</a> and start using \'{$a->sitename}\'.\n\nIf you need help, contact the site administrator.\n{$a->signoff}', 'Hai {$a->firstname},\n\nAkun telah dibuat untuk Anda di \'{$a->sitename}\'.\n\n   nama pengguna: {$a->username}\n   kata sandi: {$a->newpassword}\n\n(Anda akan diminta untuk mengubah kata sandi Anda saat pertama kali masuk.)\n\n\n<a href="{$a->link}">Klik untuk masuk</a> dan mulai menggunakan \'{$a->sitename}\'.\n\nJika Anda membutuhkan bantuan, hubungi administrator situs.\n{$a->signoff}', NULL, 1785718228, NULL, 0, 0),
