	(1397, 'id', 1, 'notenrolled', '{$a} is not enrolled in this course.', '{$a} tidak terdaftar pada kursus ini.', NULL, 1785718228, NULL, 0, 0),
	(1398, 'id', 1, 'notenrolledprofile', 'This profile is not available because this user is not enrolled in this course.', 'Profil ini belum tersedia karena pengguna belum didaftarkan di kursus ini.', NULL, 1785718228, NULL, 0, 0),
	(1399, 'id', 1, 'noteusercannotrolldatesoncontext', '<strong>Note:</strong> The ability to roll dates when restoring this backup has been disabled because you lack the required permissions.', '<strong> Catatan: </ strong> Kemampuan untuk menggulung tanggal ketika memulihkan cadangan ini telah dinonaktifkan karena Anda tidak memiliki izin yang diperlukan.', NULL, 1785718228, NULL, 0, 0),
	(1400, 'id', 1, 'noteuserschangednonetocourse', '<strong>Note:</strong> Course users need to be restored when restoring user data (in activities, files or messages). This setting has been changed for you.', '<strong>Catatan: </strong> Pengguna kursus perlu dipulihkan ketika sedang memulihkan data pengguna (dalam aktivitas, berkas atau pesan). Setelan ini telah diubah untuk Anda.', NULL, 1785718228, NULL, 0, 0),
	(1401, 'id', 1, 'nothingnew', 'No recent activity', 'Tidak ada aktivitas terbaru', NULL, 1785718228, NULL, 0, 0),
	(1402, 'id', 1, 'nothingtodisplay', 'Nothing to display', 'Tidak ada yang ditampilkan', NULL, 1785718228, NULL, 0, 0),
	(1403, 'id', 1, 'notice', 'Notice', 'Perhatian', NULL, 1785718228, NULL, 0, 0),
	(1404, 'id', 1, 'noticenewerbackup', 'This backup file has been created with Moodle {$a->backuprelease} ({$a->backupversion}) and it\'s newer than your currently installed Moodle {$a->serverrelease} ({$a->serverversion}). This could cause some inconsistencies because backwards compatibility of backup files cannot be guaranteed.', 'Berkas cadangan ini telah dibuat oleh Moodle {$a->backuprelease} ({$a->backupversion}) dan ini lebih baru dari Moodle yang terinstal saat ini {$a->serverrelease} ({$a->serverversion}). Hal ini dapat menyebabkan beberapa inkonsistensi karena kompatibilitas berkas cadangan versi sebelumnya yang tidak dapat dijamin.', NULL, 1785718228, NULL, 0, 0),
	(1405, 'id', 1, 'notifications', 'Notifications', 'Notifikasi', NULL, 1785718228, NULL, 0, 0),
	(1406, 'id', 1, 'notifyloginfailuresmessage', '{$a->time}, IP: {$a->ip}, User: {$a->info}, User full name: {$a->name}', '{$a->time}, IP: {$a->ip}, Pengguna: {$a->info}, Nama lengkap pengguna: {$a-> name}', NULL, 1785718228, NULL, 0, 0),
	(1407, 'id', 1, 'notifyloginfailuresmessageend', 'You can view these logs at {$a}', 'Anda dapat melihat log ini di {$a}', NULL, 1785718228, NULL, 0, 0),
	(1408, 'id', 1, 'notifyloginfailuresmessagestart', 'Here is a list of failed login attempts at {$a} since you were last notified', 'Berikut adalah daftar dari usaha login gagal pada {$a} sejak terakhir Anda diberitahu', NULL, 1785718228, NULL, 0, 0),
	(1409, 'id', 1, 'notifyloginfailuressubject', '{$a} :: Failed logins notification', '{$a} :: Notifikasi Login yang gagal', NULL, 1785718228, NULL, 0, 0),
