	(1743, 'id', 1, 'scalestip', 'To create custom scales, use the \'Scales...\' link in your course administration menu.', 'Untuk membuat skala yang dibuat sendiri, gunakan tautan \'Skala...\' pada menu administrator kursus.', NULL, 1785718228, NULL, 0, 0),
	(1744, 'id', 1, 'scalestip2', 'To create custom scales, click the Grades link in the course administration menu, then choose Edit, Scales.', 'Untuk membuat skala kustom, klik tautan Nilai di menu administrasi kursus, lalu pilih Edit, Skala.', NULL, 1785718228, NULL, 0, 0),
