	(2253, 'id', 1, 'passwordnohelp', 'No help is available to find your lost password. Please contact your Moodle administrator.', 'Tidak ada bantuan yang tersedia untuk menemukan kata sandi yang hilang. Silakan hubungi administrator Moodle Anda.', NULL, 1785718229, NULL, 0, 0),
