	(3098, 'id', 3, 'marketplaceavailablenotice', 'Browse and download plugins on <a href="{$a}" target="_blank" rel="noopener noreferrer">Moodle Marketplace <i class="fa fa-external-link" role="img" aria-label="Opens in new window" title="Opens in new window"></i></a>.', 'Telusuri dan unduh pengaya pada <a href="{$a}" target="_blank" rel="noopener noreferrer">Moodle Marketplace <i class="fa fa-external-link" role="img" aria-label="Opens in new window" title="Opens in new window"></i></a>.', NULL, 1785718230, NULL, 0, 0),
	(3099, 'id', 3, 'maturity50', 'Alpha', 'Alpha', NULL, 1785718230, NULL, 0, 0),
