	(3101, 'id', 3, 'maturity150', 'Release candidate', 'Kandidat rilis', NULL, 1785718230, NULL, 0, 0),
	(3102, 'id', 3, 'maturity200', 'Stable version', 'Versi stabil', NULL, 1785718230, NULL, 0, 0),
	(3103, 'id', 3, 'maturityallowunstable', 'Hint: You may want to run this script with --allow-unstable option', 'Petunjuk: Anda mungkin ingin menjalankan skrip ini dengan opsi --allow-unstable', NULL, 1785718230, NULL, 0, 0),
	(3104, 'id', 3, 'maturitycoreinfo', 'Your site is currently running unstable "{$a}" development code.', 'Situs Anda sedang menjalankan kode pengembangan "{$a}" yang tidak stabil.', NULL, 1785718230, NULL, 0, 0),
	(3105, 'id', 3, 'maturitycorewarning', 'The version of Moodle that you are about to install or upgrade to contains\nunstable "{$a}" development code that is not suitable for use on most production\nsites. If this is not what you wanted then you should make sure you are updating\nfrom a STABLE branch of the Moodle code. See Moodle Docs for more details.', 'Versi Moodle yang akan Anda pasang atau tingkatkan mengandung kode pengembangan "{$a}" yang tidak stabil dan tidak cocok untuk banyak situs. Jika ini bukan yang Anda inginkan, pastikan Anda memperbarui dari kode Moodle cabang STABIL. Lihat dokumen Moodle untuk detail lebih lanjut.', NULL, 1785718230, NULL, 0, 0),
	(3106, 'id', 3, 'maxbytes', 'Maximum uploaded file size', 'Ukuran maksimum pada pengunggahan file', NULL, 1785718230, NULL, 0, 0),
	(3107, 'id', 3, 'maxconsecutiveidentchars', 'Consecutive identical characters', 'Karakter identik berurutan', NULL, 1785718230, NULL, 0, 0),
	(3108, 'id', 3, 'maxcharacter', '{$a} character maximum', '{$a} maksimum karakter', NULL, 1785718230, NULL, 0, 0),
	(3109, 'id', 3, 'maxsizeperdownloadcoursefile', 'Maximum size per file', 'Ukuran maksimal tiap berkas', NULL, 1785718230, NULL, 0, 0),
	(3110, 'id', 3, 'maxsizeperdownloadcoursefile_desc', 'The maximum size of each file when downloading course content. Files exceeding this size will be omitted from the download.', 'Ukuran maksimal tiap berkas saat mengunduh isi kursus. Berkas yang melebihi ukuran ini akan dihilangkan dari pengunduhan.', NULL, 1785718230, NULL, 0, 0),
	(3111, 'id', 3, 'maxeditingtime', 'Maximum time to edit posts', 'Waktu maksimum untuk mengubah posting', NULL, 1785718230, NULL, 0, 0),
	(3112, 'id', 3, 'maxusersperpage', ' Maximum users per page', 'Pengguna maksimal tiap halaman', NULL, 1785718230, NULL, 0, 0),
	(3113, 'id', 3, 'configmaxusersperpage', 'Maximum number of users displayed within user selector in course, group, cohort, webservice etc.', 'Jumlah maksimum pengguna yang ditampilkan dalam pemilih pengguna dalam kursus, grup, kohor, layanan web, dll.', NULL, 1785718230, NULL, 0, 0),
	(3114, 'id', 3, 'mbstringrecommended', 'Installing the optional MBSTRING library is highly recommended in order to improve site performance, particularly if your site is supporting non-Latin languages.', 'Sangat disarankan untuk memasang pustaka MBSTRING untuk meningkatkan kinerja situs, terutama jika situs Anda mendukung bahasa yang tidak menggunakan karakter Latin.', NULL, 1785718230, NULL, 0, 0),
	(3115, 'id', 3, 'mbstringrequired', 'Installing the MBSTRING library is required in order to improve site performance, particularly if your site is supporting non-Latin languages.', 'Pustaka MBSTRING dibutuhkan untuk meningkatkan kinerja situs, terutama jika situs Anda tidak menggunakan karakter Latin.', NULL, 1785718230, NULL, 0, 0),
