	(3291, 'id', 3, 'profileeditfield', 'Editing profile field: {$a}', 'Mengedit ruas profil: {$a}', NULL, 1785718230, NULL, 0, 0),
	(3292, 'id', 3, 'profilefield', 'Profile field', 'Ruas profil', NULL, 1785718230, NULL, 0, 0),
	(3293, 'id', 3, 'profilefieldcolumns', 'Columns', 'Kolom', NULL, 1785718230, NULL, 0, 0),
	(3294, 'id', 3, 'profilefieldispassword', 'Is this a password field?', 'Apakah ini ruas kata sandi?', NULL, 1785718230, NULL, 0, 0),
	(3295, 'id', 3, 'profilefieldlink', 'Link', 'Tautan', NULL, 1785718230, NULL, 0, 0),
	(3296, 'id', 3, 'profilefieldlink_help', 'To transform the text into a link, enter a URL containing $$, where $$ will be replaced with the text. For example, to transform a Twitter ID to a link, enter https://twitter.com/$$.', 'Untuk mengubah teks menjadi tautan, masukkan URL yang berisi $$, di mana $$ akan diganti dengan teks. Misalnya, untuk mengubah ID Twitter menjadi tautan, masukkan https://twitter.com/$$.', NULL, 1785718230, NULL, 0, 0),
	(3297, 'id', 3, 'profilefieldlinktarget', 'Link target', 'Target tautan', NULL, 1785718230, NULL, 0, 0),
	(3298, 'id', 3, 'profilefieldmaxlength', 'Character limit', 'Limit karakter', NULL, 1785718230, NULL, 0, 0),
	(3299, 'id', 3, 'profilefieldmaxlength_help', 'To use this field in the setting \'Show user identity\', the limit must be 255 characters or less.', 'Untuk menggunakan ruas ini dalam setelan \'Tampilkan identitas pengguna\', batasnya harus 255 karakter atau kurang.', NULL, 1785718230, NULL, 0, 0),
	(3300, 'id', 3, 'profilefieldrows', 'Rows', 'Baris', NULL, 1785718230, NULL, 0, 0),
