	(3302, 'id', 3, 'profilefieldsize', 'Display size', 'Ukurang tampilan', NULL, 1785718230, NULL, 0, 0),
	(3303, 'id', 3, 'profileforceunique', 'Should the data be unique?', 'Data harus unik?', NULL, 1785718230, NULL, 0, 0),
