	(3306, 'id', 3, 'profilemenudefaultnotinoptions', 'The default value is not one of the options', 'Nilai bawaan bukan salah satu opsi', NULL, 1785718230, NULL, 0, 0),
	(3307, 'id', 3, 'profilemenunooptions', 'No menu options supplied', 'Tidak ada opsi menu yang disediakan', NULL, 1785718230, NULL, 0, 0),
