	(3394, 'id', 3, 'referrernone', 'Browser default', 'Peramban bawaan', NULL, 1785718230, NULL, 0, 0),
	(3395, 'id', 3, 'referrerpolicy', 'Referrer policy', 'Kebijakan perujuk', NULL, 1785718230, NULL, 0, 0),
	(3396, 'id', 3, 'referrerpolicydesc', 'Set the referrer policy header to be included with responses from your site.', 'Setel tajuk kebijakan perujuk untuk disertakan dengan tanggapan dari situs Anda.', NULL, 1785718230, NULL, 0, 0),
	(3397, 'id', 3, 'resetindentation_title', 'Reset indentation sitewide?', 'Setel ulang indentasi pada halaman kursus?', NULL, 1785718230, NULL, 0, 0),
	(3398, 'id', 3, 'resetindentation_help', 'This will remove any indentation previously set for all courses on the site in {$a->format}.', 'Ini akan menghapus indentasi yang sebelumnya ditetapkan untuk kursus dalam {$a->format}.', NULL, 1785718230, NULL, 0, 0),
	(3399, 'id', 3, 'resetindentation', 'Reset indentation sitewide', 'Setel ulang indentasi', NULL, 1785718230, NULL, 0, 0),
	(3400, 'id', 3, 'resetindentationsuccess', 'Indentation reset.', 'Setel ulang indentasi', NULL, 1785718230, NULL, 0, 0),
	(3401, 'id', 3, 'restorecourse', 'Restore course', 'Pulihkan kursus', NULL, 1785718230, NULL, 0, 0),
	(3402, 'id', 3, 'restorernewroleid', 'Restorers\' role in courses', 'Peran pemulih dalam kursus', NULL, 1785718230, NULL, 0, 0),
	(3403, 'id', 3, 'restorernewroleid_help', 'If the user does not already have the permission to manage the newly restored course, the user is automatically assigned this role and enrolled if necessary. Select "None" if you do not want restorers to be able to manage every restored course.', 'Jika pengguna belum memiliki izin untuk mengelola kursus yang baru dipulihkan, pengguna secara otomatis diberi peran ini dan didaftarkan jika perlu. Pilih "Tidak Ada" jika Anda tidak ingin pemulih dapat mengelola setiap kursus yang dipulihkan.', NULL, 1785718230, NULL, 0, 0),
	(3404, 'id', 3, 'resultfilter', 'Filter by result', 'Filter menurut hasil', NULL, 1785718230, NULL, 0, 0),
	(3405, 'id', 3, 'reverseproxy', 'Reverse proxy', 'Proksi terbalik', NULL, 1785718230, NULL, 0, 0),
	(3406, 'id', 3, 'reverseproxyignore', 'Ignore reverse proxies', 'Abaikan proksi terbalik', NULL, 1785718230, NULL, 0, 0),
	(3407, 'id', 3, 'riskconfig', 'Users could change site configuration and behaviour', 'Pengguna dapat mengubah konfigurasi dan perilaku situs', NULL, 1785718230, NULL, 0, 0),
	(3408, 'id', 3, 'riskconfigshort', 'Configuration risk', 'Risiko konfigurasi', NULL, 1785718230, NULL, 0, 0),
	(3409, 'id', 3, 'riskdataloss', 'Users could destroy large amounts of content or information', 'Pengguna dapat menghancurkan sejumlah besar konten atau informasi', NULL, 1785718230, NULL, 0, 0),
	(3410, 'id', 3, 'riskdatalossshort', 'Data loss risk', 'Risiko kehilangan data', NULL, 1785718230, NULL, 0, 0),
	(3411, 'id', 3, 'riskmanagetrust', 'Users could change trust settings of other users', 'Pengguna dapat mengubah setelan kepercayaan pengguna lain', NULL, 1785718230, NULL, 0, 0),
	(3412, 'id', 3, 'riskmanagetrustshort', 'Manage trusts', 'Kelola kepercayaan', NULL, 1785718230, NULL, 0, 0),
	(3413, 'id', 3, 'riskpersonal', 'Users could gain access to private information of other users', 'Pengguna dapat memperoleh akses ke informasi pribadi pengguna lain', NULL, 1785718230, NULL, 0, 0),
	(3414, 'id', 3, 'riskpersonalshort', 'Privacy risk', 'Risiko privasi', NULL, 1785718230, NULL, 0, 0),
	(3415, 'id', 3, 'riskspam', 'Users could send spam to site users or others', 'Pengguna dapat mengirim spam ke pengguna situs atau orang lain', NULL, 1785718230, NULL, 0, 0),
	(3416, 'id', 3, 'riskspamshort', 'Spam risk', 'Risiko spam', NULL, 1785718230, NULL, 0, 0),
	(3417, 'id', 3, 'riskxss', 'Users could add files and texts that allow cross-site scripting (XSS)', 'Pengguna dapat menambahkan file dan teks yang memungkinkan pembuatan skrip lintas situs (XSS)', NULL, 1785718230, NULL, 0, 0),
	(3418, 'id', 3, 'riskxssshort', 'XSS risk', 'risiko XSS', NULL, 1785718230, NULL, 0, 0),
