	(3542, 'id', 3, 'soaprecommended', 'Installing the optional SOAP extension is useful for web services and some plugins.', 'Menginstal ekstensi SOAP opsional berguna untuk layanan web dan beberapa pengaya.', NULL, 1785718231, NULL, 0, 0),
	(3543, 'id', 3, 'sort_fullname', 'Course full name', 'Nama lengkap kursus', NULL, 1785718231, NULL, 0, 0),
