	(3550, 'id', 3, 'stats', 'Statistics', 'Statistik', NULL, 1785718231, NULL, 0, 0),
	(3551, 'id', 3, 'statsfirstrun', 'Maximum processing interval', 'Interval pemrosesan maksimum', NULL, 1785718231, NULL, 0, 0),
	(3552, 'id', 3, 'statsmaxruntime', 'Maximum runtime', 'Waktu kerja maksimum', NULL, 1785718231, NULL, 0, 0),
	(3553, 'id', 3, 'statsmoodleorg', 'statistics', 'statistik', NULL, 1785718231, NULL, 0, 0),
	(3554, 'id', 3, 'statsruntimedays', 'Days to process', 'Jumlah hari pemrosesan', NULL, 1785718231, NULL, 0, 0),
	(3555, 'id', 3, 'statsruntimestart', 'Run at', 'Berjalan pada', NULL, 1785718231, NULL, 0, 0),
	(3556, 'id', 3, 'statsuserthreshold', 'User threshold', 'Ambang pengguna', NULL, 1785718231, NULL, 0, 0),
	(3557, 'id', 3, 'stickyblocks', 'Sticky blocks', 'Blok menempel', NULL, 1785718231, NULL, 0, 0),
	(3558, 'id', 3, 'stickyblockscourseview', 'Course page', 'Halaman kursus', NULL, 1785718231, NULL, 0, 0),
	(3559, 'id', 3, 'stickyblocksduplicatenotice', 'If any block you add here is already present in a particular page, it will result in a duplicate.<br />Only the pinned block will be non-editable, the duplicate will still be editable.', 'Jika ada blok yang Anda tambahkan di sini sudah ada di halaman tertentu, itu akan menghasilkan duplikat.<br />Hanya blok yang disematkan yang tidak dapat diedit, duplikatnya masih dapat diedit.', NULL, 1785718231, NULL, 0, 0),
	(3560, 'id', 3, 'stickyblocksmymoodle', 'My Moodle', 'Moodle saya', NULL, 1785718231, NULL, 0, 0),
	(3561, 'id', 3, 'stickyblockspagetype', 'Page type to configure', 'Jenis halaman untuk dikonfigurasi', NULL, 1785718231, NULL, 0, 0),
	(3562, 'id', 3, 'storedprogressbarcleanuptask', 'Stored progress bar cleanup task', 'Tugas pembersihan bilah kemajuan yang tersimpan', NULL, 1785718231, NULL, 0, 0),
	(3563, 'id', 3, 'strictformsrequired', 'Strict validation of required fields', 'Validasi ketat pada kolom yang diperlukan', NULL, 1785718231, NULL, 0, 0),
	(3564, 'id', 3, 'stripalltitletags', 'Remove HTML tags from all activity names', 'Hapus tag HTML dari semua nama aktivitas', NULL, 1785718231, NULL, 0, 0),
	(3565, 'id', 3, 'supportandservices', 'Support and services', 'Dukungan dan layanan', NULL, 1785718231, NULL, 0, 0),
	(3566, 'id', 3, 'supportcontact', 'Support contact', 'Dukungan kontak', NULL, 1785718231, NULL, 0, 0),
