	(3570, 'id', 3, 'supportname', 'Support name', 'Nama dukungan', NULL, 1785718231, NULL, 0, 0),
	(3571, 'id', 3, 'supportpage', 'Contact site support link', 'Hubungi tautan dukungan situs', NULL, 1785718231, NULL, 0, 0),
	(3572, 'id', 3, 'swaggerui', 'Moodle REST API UI (SwaggerUI)', 'UI API Moodle REST (SwaggerUI)', NULL, 1785718231, NULL, 0, 0),
	(3573, 'id', 3, 'suspenduser', 'Suspend user account', 'Tangguhkan akun pengguna', NULL, 1785718231, NULL, 0, 0),
	(3574, 'id', 3, 'switchlang', 'Switch lang directory', 'Beralih direktori bahasa', NULL, 1785718231, NULL, 0, 0),
	(3575, 'id', 3, 'systempaths', 'System paths', 'Letak sistem', NULL, 1785718231, NULL, 0, 0),
	(3576, 'id', 3, 'tablenosave', 'Changes in table above are saved automatically.', 'Perubahan pada tabel di atas disimpan secara otomatis.', NULL, 1785718231, NULL, 0, 0),
	(3577, 'id', 3, 'tablesnosave', 'Changes in tables above are saved automatically.', 'Perubahan tabel di atas disimpan secara otomatis.', NULL, 1785718231, NULL, 0, 0),
	(3578, 'id', 3, 'tabselectedtofront', 'On tables with tabs, should the row with the currently selected tab be placed at the front', 'Pada tabel dengan tab, sebaiknya baris dengan tab yang sedang dipilih ditempatkan di depan', NULL, 1785718231, NULL, 0, 0),
	(3579, 'id', 3, 'tabselectedtofronttext', 'Bring selected tab row to front', 'Bawa baris tab yang dipilih ke depan', NULL, 1785718231, NULL, 0, 0),
	(3580, 'id', 3, 'testsiteupgradewarning', 'You are currently using the {$a} test site, to upgrade it properly use the command line interface tool', 'Anda saat ini menggunakan situs pengujian {$a}, untuk meningkatkannya dengan benar, gunakan alat antarmuka baris perintah', NULL, 1785718231, NULL, 0, 0),
	(3581, 'id', 3, 'task_scheduled_concurrency_limit', 'Scheduled task concurrency limit', 'Batas konkurensi tugas terjadwal', NULL, 1785718231, NULL, 0, 0),
	(3582, 'id', 3, 'task_scheduled_concurrency_limit_desc', 'The number of scheduled task runners allowed to run concurrently. If the limit is high then the server may experience high load which affects performance. A setting of 0 will disable processing of scheduled tasks completely.', 'Jumlah proses tugas terjadwal yang diizinkan untuk berjalan secara bersamaan. Jika batasnya tinggi maka server mungkin mengalami beban tinggi yang memengaruhi kinerja. Setelan 0 akan menonaktifkan pemrosesan tugas terjadwal sepenuhnya.', NULL, 1785718231, NULL, 0, 0),
	(3583, 'id', 3, 'task_scheduled_max_runtime', 'Scheduled task runner lifetime', 'Usia proses tugas terjadwal', NULL, 1785718231, NULL, 0, 0),
	(3584, 'id', 3, 'task_scheduled_max_runtime_desc', 'The age of a scheduled task runner before it is freed.', 'Usia proses tugas terjadwal sebelum dibebaskan.', NULL, 1785718231, NULL, 0, 0),
	(3585, 'id', 3, 'task_adhoc_concurrency_limit', 'Ad hoc task concurrency limit', 'Batas konkurensi tugas ad hoc', NULL, 1785718231, NULL, 0, 0),
	(3586, 'id', 3, 'task_adhoc_concurrency_limit_desc', 'The number of ad hoc task runners allowed to run concurrently. If the limit is high then scheduled tasks may not run regularly when there are lots of ad hoc tasks. A setting of 0 will disable processing of ad hoc tasks completely.', 'Jumlah pelari tugas ad hoc yang diizinkan untuk berjalan secara bersamaan. Jika batasnya tinggi maka tugas terjadwal mungkin tidak berjalan secara teratur ketika ada banyak tugas ad hoc. Setelan 0 akan menonaktifkan pemrosesan tugas ad hoc sepenuhnya.', NULL, 1785718231, NULL, 0, 0),
	(3587, 'id', 3, 'task_adhoc_failed_retention', 'Failed ad hoc task retention period', 'Periode retensi tugas ad hoc gagal', NULL, 1785718231, NULL, 0, 0),
	(3588, 'id', 3, 'task_adhoc_failed_retention_desc', 'The maximum period that failed ad hoc tasks should remain in the queue once they have reached their retry limit.', 'Periode maksimum tugas ad hoc yang gagal harus tetap berada dalam antrean setelah mencapai batas percobaan ulang.', NULL, 1785718231, NULL, 0, 0),
	(3589, 'id', 3, 'task_adhoc_max_runtime', 'Ad hoc task runner lifetime', 'Waktu hidup proses tugas ad hoc', NULL, 1785718231, NULL, 0, 0),
	(3590, 'id', 3, 'task_adhoc_max_runtime_desc', 'The age of an ad hoc task runner before it is freed. A low duration is recommended as there is no limit to the number of ad hoc tasks queued. If this number is too high and you have a large ad hoc task queue then scheduled tasks may not be run regularly.', 'Usia pelari tugas ad hoc sebelum dibebaskan. Durasi yang rendah direkomendasikan karena tidak ada batasan jumlah tugas ad hoc yang antri. Jika angka ini terlalu tinggi dan Anda memiliki antrian tugas ad hoc yang besar, maka tugas yang dijadwalkan mungkin tidak dijalankan secara teratur.', NULL, 1785718231, NULL, 0, 0),
	(3591, 'id', 3, 'task_endtime', 'End time', 'Waktu berakhir', NULL, 1785718231, NULL, 0, 0),
	(3592, 'id', 3, 'task_logmode', 'When to log', 'Kapan untuk log', NULL, 1785718231, NULL, 0, 0),
	(3593, 'id', 3, 'task_logmode_desc', 'You can choose when you wish task logging to take place. By default logs are always captured. You can disable logging entirely, or change to only log tasks which fail.', 'Anda dapat memilih kapan Anda ingin melakukan pencatatan tugas. Secara bawaan, log selalu ditangkap. Anda dapat menonaktifkan pencatatan seluruhnya, atau mengubah ke hanya tugas pencatatan yang gagal.', NULL, 1785718231, NULL, 0, 0),
	(3594, 'id', 3, 'task_logmode_none', 'Do not log anything', 'Jangan catat apa pun', NULL, 1785718231, NULL, 0, 0),
	(3595, 'id', 3, 'task_logmode_all', 'Store the log output of all jobs', 'Simpan keluaran log dari semua pekerjaan', NULL, 1785718231, NULL, 0, 0),
	(3596, 'id', 3, 'task_logmode_failonly', 'Only store logs for jobs which fail', 'Hanya simpan log untuk pekerjaan yang gagal', NULL, 1785718231, NULL, 0, 0),
