	(3730, 'id', 3, 'unsuspenduser', 'Activate user account', 'Aktivasi akun pengguna', NULL, 1785718231, NULL, 0, 0),
	(3731, 'id', 3, 'updateaccounts', 'Update existing accounts', 'Perbarui akun yang ada', NULL, 1785718231, NULL, 0, 0),
	(3732, 'id', 3, 'updatecomponent', 'Update component', 'Perbarui komponen', NULL, 1785718231, NULL, 0, 0),
	(3733, 'id', 3, 'updateavailable', 'There is a newer Moodle version available!', 'Moodle versi terbaru telah tersedia!', NULL, 1785718231, NULL, 0, 0),
	(3734, 'id', 3, 'updateavailabledetailslink', 'See {$a->url} for more details', 'Lihat {$a->url} untuk lebih detail', NULL, 1785718231, NULL, 0, 0),
	(3735, 'id', 3, 'updateavailableforplugin', 'There is a newer version for some of your plugins available!', 'Tersedia beberapa pembaruan pengaya!', NULL, 1785718231, NULL, 0, 0),
	(3736, 'id', 3, 'updateavailable_moreinfo', 'More info...', 'Info lebih lanjut...', NULL, 1785718231, NULL, 0, 0),
	(3737, 'id', 3, 'updateavailable_release', 'Moodle {$a}', 'Moodle {$a}', NULL, 1785718231, NULL, 0, 0),
	(3738, 'id', 3, 'updateavailable_version', 'Version {$a}', 'Versi {$a}', NULL, 1785718231, NULL, 0, 0),
	(3739, 'id', 3, 'updateavailableinstall', 'Install this update', 'Pasang pembaruan ini', NULL, 1785718231, NULL, 0, 0),
	(3740, 'id', 3, 'updateavailableinstallall', 'Install available updates ({$a})', 'Pasang pembaruan tersedia ({$a})', NULL, 1785718231, NULL, 0, 0),
	(3741, 'id', 3, 'updateavailableinstallallhead', 'Installing available updates', 'Menginstal pembaruan yang tersedia', NULL, 1785718231, NULL, 0, 0),
	(3742, 'id', 3, 'updateavailablenot', 'Your Moodle code is up-to-date!', 'Versi Moodle anda terkini!', NULL, 1785718231, NULL, 0, 0),
	(3743, 'id', 3, 'updateavailablerecommendation', 'It is strongly recommended that you update your site to the latest version to obtain all recent security and bug fixes.', 'Sangat disarankan agar Anda memperbarui situs Anda ke versi terbaru untuk mendapatkan semua perbaikan kutu dan keamanan terkini.', NULL, 1785718231, NULL, 0, 0),
	(3744, 'id', 3, 'updatenotifications', 'Update notifications', 'Notifikasi Pembaruan', NULL, 1785718231, NULL, 0, 0),
	(3745, 'id', 3, 'updatenotificationfooter', 'Your Moodle site {$a->siteurl} is configured to automatically check for available updates. You are receiving this message as the administrator of the site. You can disable automatic checks for available updates in Site administration / Server / Update notifications or customise the delivery of this message via your preferences page.', 'Situs Moodle {$a->siteurl} Anda dikonfigurasi untuk secara otomatis memeriksa pembaruan yang tersedia. Anda menerima pesan ini sebagai administrator situs. Anda dapat menonaktifkan pemeriksaan otomatis untuk pembaruan yang tersedia di <strong> "Administrasi Situs/Server/Pemberitahuan Pembaharuan"</strong> atau menyesuaikan pengiriman pesan ini melalui halaman preferensi Anda.', NULL, 1785718231, NULL, 0, 0),
	(3746, 'id', 3, 'updatenotificationsubject', 'Moodle updates are available ({$a->siteurl})', 'Pembaruan Moodle tersedia di ({$a->siteurl})', NULL, 1785718231, NULL, 0, 0),
	(3747, 'id', 3, 'updateautocheck', 'Automatically check for available updates', 'Cek otomatis untuk pembaruan yang tersedia', NULL, 1785718231, NULL, 0, 0),
	(3748, 'id', 3, 'updateautocheck_desc', 'If enabled, your site will automatically check for available updates for both Moodle code and all additional plugins. If there is a new update available, a notification will be sent to site admins.', 'Jika diaktifkan, situs Anda akan secara otomatis memeriksa pembaruan yang tersedia untuk kode Moodle dan semua pengaya tambahan. Jika ada pembaruan baru yang tersedia, pemberitahuan akan dikirim ke admin situs.', NULL, 1785718231, NULL, 0, 0),
	(3749, 'id', 3, 'updateminmaturity', 'Required code maturity', 'Kematangan kode yang diperlukan', NULL, 1785718231, NULL, 0, 0),
	(3750, 'id', 3, 'updateminmaturity_desc', 'Notify about available updates only if the available code has the selected maturity level at least. Updates for plugins that do not declare their code maturity level are always reported regardless this setting.', 'Beri tahu tentang pembaruan yang tersedia hanya jika kode yang tersedia setidaknya memiliki tingkat kematangan yang dipilih. Pembaruan untuk pengaya yang tidak mendeklarasikan tingkat kematangan kodenya selalu dilaporkan terlepas dari setelan ini.', NULL, 1785718231, NULL, 0, 0),
	(3751, 'id', 3, 'updatenotifybuilds', 'Notify about new builds', 'Beritahukan pengembangan yang baru', NULL, 1785718231, NULL, 0, 0),
	(3752, 'id', 3, 'updatenotifybuilds_desc', 'If enabled, the available update for Moodle code is also reported when a new build for the current version is available. Builds are continuous improvements of a given Moodle version. They are generally released every week. If disabled, the available update will be reported only when there is a higher version of Moodle released. Checks for plugins are not affected by this setting.', 'Jika diaktifkan, pembaruan yang tersedia untuk kode Moodle juga dilaporkan ketika pengembangan baru untuk versi saat ini tersedia. Pengembangan adalah peningkatan berkelanjutan dari versi Moodle yang diberikan. Mereka umumnya dirilis setiap minggu. Jika dinonaktifkan, pembaruan yang tersedia hanya akan dilaporkan ketika ada versi Moodle yang lebih tinggi yang dirilis. Pemeriksaan pengaya tidak terpengaruh oleh setelan ini.', NULL, 1785718231, NULL, 0, 0),
	(3753, 'id', 3, 'upgradestart', 'Upgrade Moodle database now', 'Meningkatkan basis data Moodle sekarang', NULL, 1785718231, NULL, 0, 0),
	(3754, 'id', 3, 'upgradepluginsfirst', 'It is recommended to install all available updates first', 'Disarankan untuk memasang seluruh pembaruan yang tersedia terlebih dahulu.', NULL, 1785718231, NULL, 0, 0),
	(3755, 'id', 3, 'upgradepluginsinfo', 'Updating plugins', 'Memperbarui pengaya', NULL, 1785718231, NULL, 0, 0),
	(3756, 'id', 3, 'upgradepluginsinfo_help', 'There are available updates for some of your plugins. You should install them all prior to upgrading Moodle database. If your site does not support automatic updates deployment, you have to download and install new plugin versions at your server manually.', 'Ada pembaruan yang tersedia untuk beberapa pengaya Anda. Anda harus menginstal semuanya sebelum meningkatkan basis data Moodle. Jika situs Anda tidak mendukung penyebaran pembaruan otomatis, Anda harus mengunduh dan menginstal versi server baru di server Anda secara manual.', NULL, 1785718231, NULL, 0, 0),
	(3757, 'id', 3, 'upgradepluginsinfo_link', 'admin/upgradepluginsinfo', 'admin/upgradepluginsinfo', NULL, 1785718231, NULL, 0, 0),
	(3758, 'id', 3, 'upgradeerror', 'Unknown error upgrading {$a->plugin} to version {$a->version}. Cannot continue.', 'Galat yang tidak diketahui saat meningkatkan {$a->plugin} ke versi {$a->version}. Tidak bisa melanjutkan.', NULL, 1785718231, NULL, 0, 0),
	(3759, 'id', 3, 'upgradeforumread', 'A new feature has been added in Moodle 1.5 to track read/unread forum posts.<br />To use this functionality you need to <a href="{$a}">update your tables</a>.', 'Sebuah fitur baru telah ditambahkan di Moodle 1.5 untuk melacak kiriman forum yang telah dibaca/belum dibaca. <br /> Untuk menggunakan fungsi ini, Anda perlu <a href="{$a}"> memperbarui tabel Anda </a>.', NULL, 1785718231, NULL, 0, 0),
	(3760, 'id', 3, 'upgradeforumreadinfo', 'A new feature has been added in Moodle 1.5 to track read/unread forum posts.  To use this functionality you need to update your tables with all the tracking information for existing posts.  Depending on the size of your site this can take a long time (hours) and can be quite taxing on the database, so it\'s best to do it during a quiet period.  However, your site will continue functioning during this upgrade and users won\'t be affected.  Once you start this process you should let it finish (keep your browser window open).  However, if you stop the process by closing the window: don\'t worry, you can start over.<br /><br />Do you want to start the upgrading process now?', 'Sebuah fitur baru telah ditambahkan di Moodle 1.5 untuk melacak kiriman forum yang telah dibaca/belum dibaca. Untuk menggunakan fungsi ini, Anda perlu memperbarui tabel Anda dengan semua informasi pelacakan untuk kiriman yang ada. Bergantung pada ukuran situs Anda, ini bisa memakan waktu lama (jam) dan bisa sangat membebani basis data, jadi yang terbaik adalah melakukannya selama periode tenang. Namun, situs Anda akan terus berfungsi selama peningkatan ini dan pengguna tidak akan terpengaruh. Setelah Anda memulai proses ini, Anda harus membiarkannya selesai (biarkan jendela peramban Anda terbuka). Namun, jika Anda menghentikan proses dengan menutup jendela: jangan khawatir, Anda dapat memulai kembali. <br /> <br /> Apakah Anda ingin memulai proses peningkatan sekarang?', NULL, 1785718231, NULL, 0, 0),
	(3761, 'id', 3, 'upgradekeyreq', 'Upgrade key required', 'Kunci peningkatan dibutuhkan', NULL, 1785718231, NULL, 0, 0),
	(3762, 'id', 3, 'upgradekeyset', 'Upgrade key (leave empty to not set it)', 'Kunci peningkatan (biarkan kosong untuk tidak mengaturnya)', NULL, 1785718231, NULL, 0, 0),
	(3763, 'id', 3, 'upgradelogs', 'For full functionality, your old logs need to be upgraded.  <a href="{$a}">More information</a>', 'Untuk fungsionalitas penuh, log lama Anda perlu ditingkatkan. <a href="{$a}"> Informasi lebih lanjut </a>', NULL, 1785718231, NULL, 0, 0),
	(3764, 'id', 3, 'upgradelogsinfo', 'Some changes have recently been made in the way logs are stored.  To be able to view all of your old logs on a per-activity basis, your old logs need to be upgraded.  Depending on your site this can take a long time (eg several hours) and can be quite taxing on the database for large sites.  Once you start this process you should let it finish (by keeping the browser window open).  Don\'t worry - your site will work fine for other people while the logs are being upgraded.<br /><br />Do you want to upgrade your logs now?', 'Beberapa perubahan baru-baru ini dilakukan pada cara penyimpanan log. Untuk dapat melihat semua log lama Anda per aktivitas, log lama Anda perlu ditingkatkan. Bergantung pada situs Anda, ini bisa memakan waktu lama (misalnya beberapa jam) dan bisa sangat membebani basis data untuk situs besar. Setelah Anda memulai proses ini, Anda harus membiarkannya selesai (dengan tetap membuka jendela peramban). Jangan khawatir - situs Anda akan berfungsi dengan baik untuk orang lain saat log ditingkatkan. <br /> <br /> Apakah Anda ingin meningkatkan log Anda sekarang?', NULL, 1785718231, NULL, 0, 0),
	(3765, 'id', 3, 'upgradesettings', 'New settings', 'Setelan baru', NULL, 1785718231, NULL, 0, 0),
	(3766, 'id', 3, 'upgradesettingsintro', 'The settings shown below were added during your last Moodle upgrade. Make any changes necessary to the defaults and then click the \'Save changes\' button at the bottom of this page.', 'Setelan yang ditunjukkan di bawah ditambahkan selama peningkatan Moodle terakhir Anda. Lakukan perubahan yang diperlukan pada setelan bawaan dan kemudian klik tombol \'Simpan perubahan\' di bagian bawah halaman ini.', NULL, 1785718231, NULL, 0, 0),
	(3767, 'id', 3, 'upgradestalefiles', 'Mixed Moodle versions detected, upgrade cannot continue', 'Terdeteksi versi Moodle tercampur, peningkatan tidak dapat dilanjutkan', NULL, 1785718231, NULL, 0, 0),
	(3768, 'id', 3, 'upgradestalefilesinfo', 'The Moodle update process has been paused because PHP scripts from at least two major versions of Moodle have been detected in the Moodle directory.\n\nThis can cause significant problems later, so in order to continue you must ensure that the Moodle directory contains only files for a single version of Moodle.\n\nThe recommended way to clean your Moodle directory is as follows:\n\n* rename the current Moodle directory to "moodle_old"\n* create a new Moodle directory containing only files from either a standard Moodle package download, or from the Moodle Git repository\n* move the original config.php file and any non-standard plugins from the "moodle_old" directory to the new Moodle directory\n\nWhen you have a clean Moodle directory, refresh this page to resume the Moodle update process.\n\nThis warning is often caused by unzipping a standard Moodle package over a previous version of Moodle. While this is OK for minor upgrades, it is strongly discouraged for major Moodle upgrades.\n\nThis warning can also be caused by an incomplete checkout or update operation from the Git repository, in which case you may just have to wait for the operation to complete, or perhaps run the appropriate clean-up command and retry the operation.\n\nYou can find more information in upgrade documentation at <a href="{$a}">{$a}</a>.', 'Proses pembaruan Moodle telah dihentikan sementara karena skrip PHP dari setidaknya dua versi utama Moodle telah terdeteksi di direktori Moodle.\n\nIni dapat menyebabkan masalah yang signifikan nantinya, jadi untuk melanjutkan Anda harus memastikan bahwa direktori Moodle hanya berisi berkas untuk satu versi Moodle.\n\nCara yang disarankan untuk membersihkan direktori Moodle Anda adalah sebagai berikut:\n\n* ganti nama direktori Moodle saat ini menjadi "moodle_old"\n* buat direktori Moodle baru yang hanya berisi berkas baik dari unduhan paket Moodle standar, atau dari repositori Moodle Git\n* pindahkan file config.php asli dan semua pengaya non-standar dari direktori "moodle_old" ke direktori Moodle yang baru\n\nSaat Anda memiliki direktori Moodle yang bersih, segarkan halaman ini untuk melanjutkan proses pembaruan Moodle.\n\nPeringatan ini sering kali disebabkan oleh unzip paket Moodle standar dari versi Moodle sebelumnya. Meskipun ini tidak masalah untuk peningkatan kecil, sangat tidak disarankan untuk peningkatan Moodle besar.\n\nPeringatan ini juga dapat disebabkan oleh pembayaran yang tidak lengkap atau operasi pembaruan dari repositori Git, dalam hal ini Anda mungkin hanya perlu menunggu hingga operasi selesai, atau mungkin menjalankan perintah pembersihan yang sesuai dan mencoba kembali operasi.\n\nAnda dapat menemukan informasi lebih lanjut dalam dokumentasi peningkatan di <a href="{$a}"> {$a} </a>.', NULL, 1785718231, NULL, 0, 0),
	(3769, 'id', 3, 'upgradesure', '<p>Your Moodle files have been changed, and you are about to automatically upgrade your server to this version:</p>\n<p><strong>{$a}</strong></p>\n<p>Once you do this you can not go back again. Please note that this process can take a long time.</p>\n<p>Are you sure you want to upgrade this server to this version?</p>', '<p> Berkas Moodle Anda telah diubah, dan Anda akan secara otomatis meningkatkan server Anda ke versi ini: </p> <p><li>{$a}</i> </p> <p> Setelah Anda melakukan ini, Anda tidak bisa kembali lagi. Harap dicatat bahwa proses ini dapat memakan waktu lama. </p> <p> Apakah Anda yakin ingin meningkatkan server ini ke versi ini? </p>', NULL, 1785718231, NULL, 0, 0),
	(3770, 'id', 3, 'upgradetimedout', 'Upgrade timed out, please restart the upgrade.', 'Waktu peningkatan habis, harap mulai ulang peningkatan.', NULL, 1785718231, NULL, 0, 0),
	(3771, 'id', 3, 'upgradingdata', 'Upgrading data', 'Peningkatan data', NULL, 1785718231, NULL, 0, 0),
	(3772, 'id', 3, 'upgradinglogs', 'Upgrading logs', 'Riwayat pemutakhiran', NULL, 1785718231, NULL, 0, 0),
	(3773, 'id', 3, 'upgradingversion', 'Upgrading to new version', 'Tingkatkan ke versi baru', NULL, 1785718231, NULL, 0, 0),
	(3774, 'id', 3, 'upwards', 'upwards', 'ke atas', NULL, 1785718231, NULL, 0, 0),
	(3775, 'id', 3, 'useblogassociations', 'Enable associations', 'Aktifkan asosiasi', NULL, 1785718231, NULL, 0, 0),
	(3776, 'id', 3, 'user', 'User', 'Pengguna', NULL, 1785718231, NULL, 0, 0),
	(3777, 'id', 3, 'userbulk', 'Bulk user actions', 'Tindakan massal pengguna', NULL, 1785718231, NULL, 0, 0),
	(3778, 'id', 3, 'userbulkdownload', 'Export users as', 'Ekspor pengguna sebagai', NULL, 1785718231, NULL, 0, 0),
	(3779, 'id', 3, 'userfeedbackafterupgrade', 'After every major upgrade', 'Setelah setiap peningkatan besar', NULL, 1785718231, NULL, 0, 0),
	(3780, 'id', 3, 'userfeedbackencouragement', '<p>Moodle includes a feature which gives users the option to provide feedback about Moodle software via an external survey site hosted by Moodle HQ. No user-identifying information is forwarded to the survey site.</p>\n<p>Moodle HQ strives to be open and transparent about its data collection practices. Thus, we want to make sure that you are aware and in control of this functionality.</p>\n<p>Feedback from users helps Moodle HQ in improving the Moodle software. To enable this feature, please go to <a href="{$a}">Feedback settings</a>.</p>', '<p>Moodle menyertakan fitur yang memberi pengguna pilihan untuk memberikan umpan balik tentang perangkat lunak Moodle melalui situs survei eksternal yang diselenggarakan oleh Moodle HQ. Tidak ada informasi identitas pengguna yang diteruskan ke situs survei.</p>\n<p>Moodle HQ berupaya untuk bersikap terbuka dan transparan mengenai praktik pengumpulan datanya. Oleh karena itu, kami ingin memastikan bahwa Anda mengetahui dan mengontrol fungsi ini.</p> <p>Umpan balik dari pengguna membantu Moodle HQ dalam meningkatkan perangkat lunak Moodle. Untuk mengaktifkan fitur ini, buka <a href="{$a}">Setelan masukan</a>.</p>', NULL, 1785718231, NULL, 0, 0),
	(3781, 'id', 3, 'userfeedbacknextreminder', 'Next feedback reminder', 'Pengingat umpan balik berikutnya', NULL, 1785718231, NULL, 0, 0),
	(3782, 'id', 3, 'userfeedbacknextreminder_desc', 'When should we ask the user to give feedback again?', 'Kapan kita harus meminta pengguna untuk memberikan umpan balik lagi?', NULL, 1785718231, NULL, 0, 0),
	(3783, 'id', 3, 'userfeedbackperiodically', 'Periodically', 'Secara berkala', NULL, 1785718231, NULL, 0, 0),
	(3784, 'id', 3, 'userfeedbackremindafter', 'Show reminder after', 'Tunjukkan pengingat setelah', NULL, 1785718231, NULL, 0, 0),
	(3785, 'id', 3, 'userfeedbackremindafter_desc', 'Remind users again to give feedback after the given number of days.', 'Ingatkan pengguna lagi untuk memberikan umpan balik setelah jumlah hari yang ditentukan.', NULL, 1785718231, NULL, 0, 0),
	(3786, 'id', 3, 'userimagesdisabled', 'Profile user images are disabled', 'Gambar pengguna profil dinonaktifkan', NULL, 1785718231, NULL, 0, 0),
	(3787, 'id', 3, 'userlist', 'Browse list of users', 'Telusuri daftar pengguna', NULL, 1785718231, NULL, 0, 0),
	(3788, 'id', 3, 'userdefaultpreferences', 'User default preferences', 'Preferensi bawaan pengguna', NULL, 1785718231, NULL, 0, 0),
	(3789, 'id', 3, 'userfiltersdefault', 'Default user filters', 'Filter pengguna bawaan', NULL, 1785718231, NULL, 0, 0),
	(3790, 'id', 3, 'userfiltersdefault_desc', 'Choose the filters you want to display on the \'Bulk user actions\' page. To select multiple filters, hold down the Ctrl key. Filters not selected will still be available via the \'Show more\' link.', 'Pilih filter yang ingin Anda tampilkan di halaman \'Aksi pengguna massal\'. Untuk memilih beberapa filter, tahan tombol Ctrl. Filter yang tidak dipilih akan tetap dapat diakses melalui tautan \'Tampilkan lebih banyak\'', NULL, 1785718231, NULL, 0, 0),
	(3791, 'id', 3, 'usermanagement', 'User management', 'Manajemen pengguna', NULL, 1785718231, NULL, 0, 0),
	(3792, 'id', 3, 'userpreference', 'User preference', 'Preferensi pengguna', NULL, 1785718231, NULL, 0, 0),
	(3793, 'id', 3, 'userpolicies', 'User policies', 'Kebijakan pengguna', NULL, 1785718231, NULL, 0, 0),
	(3794, 'id', 3, 'users', 'Users', 'Pengguna', NULL, 1785718231, NULL, 0, 0),
	(3795, 'id', 3, 'userquota', 'Private files space', 'Ruang berkas pribadi', NULL, 1785718231, NULL, 0, 0),
	(3796, 'id', 3, 'userquota_desc', 'The maximum amount of data that each user can store in their private files area.', 'Jumlah maksimum data yang dapat disimpan oleh setiap pengguna di area berkas pribadi mereka.', NULL, 1785718231, NULL, 0, 0),
	(3797, 'id', 3, 'usesitenameforsitepages', 'Use site name for site pages', 'Gunakan nama situs untuk halaman situs', NULL, 1785718231, NULL, 0, 0),
	(3798, 'id', 3, 'usetags', 'Enable tags functionality', 'Aktifkan fungsi tagar', NULL, 1785718231, NULL, 0, 0),
	(3799, 'id', 3, 'validateemptylineerror', 'Empty lines are not valid', 'Baris kosong tidak valid', NULL, 1785718231, NULL, 0, 0),
	(3800, 'id', 3, 'validateerror', 'This value is not valid', 'Nilai ini tidak valid', NULL, 1785718231, NULL, 0, 0),
	(3801, 'id', 3, 'validateerrorlist', 'These entries are invalid: {$a}', 'Entri ini tidak valid: {$a}', NULL, 1785718231, NULL, 0, 0),
	(3802, 'id', 3, 'validateiperror', 'These IP addresses are invalid: {$a}', 'Alamat IP ini tidak valid: {$a}', NULL, 1785718231, NULL, 0, 0),
	(3803, 'id', 3, 'verifychangedemail', 'Restrict domains when changing email', 'Batasi domain saat mengubah surel', NULL, 1785718231, NULL, 0, 0),
	(3804, 'id', 3, 'warningcurrentsetting', 'Invalid current value: {$a}', 'Nilai saat ini tidak valid: {$a}', NULL, 1785718231, NULL, 0, 0),
	(3805, 'id', 3, 'warningiconvbuggy', 'Your version of the iconv library does not support the //IGNORE modifier. You should install the mbstring extension which can be used instead for cleaning strings containing invalid UTF-8 characters.', 'Versi pustaka iconv Anda tidak mendukung pengubah //IGNORE. Anda harus memasang ekstensi mbstring yang dapat digunakan sebagai gantinya untuk membersihkan string yang berisi karakter UTF-8 yang tidak valid.', NULL, 1785718231, NULL, 0, 0),
	(3806, 'id', 3, 'webproxy', 'Web proxy', 'Proksi web', NULL, 1785718231, NULL, 0, 0),
	(3807, 'id', 3, 'webproxyinfo', 'Fill in the following options if your Moodle server cannot access the internet directly. Internet access is required for the download of environment data, language packs, RSS feeds, timezones, etc.<br /><em>The PHP cURL extension is highly recommended.</em>', 'Isi opsi berikut jika server Moodle Anda tidak dapat mengakses internet secara langsung. Akses internet diperlukan untuk mengunduh data lingkungan, paket bahasa, umpan RSS, zona waktu, dll. <br /> <em> Ekstensi PHP cURL sangat disarankan. </em>', NULL, 1785718231, NULL, 0, 0),
	(3808, 'id', 3, 'xmlrpcwebserviceenabled', 'It has been detected that the XML-RPC Web Service protocol is enabled on your site. This feature relies on the PHP XML-RPC extension which is no longer maintained by PHP.', 'Telah terdeteksi bahwa protokol Layanan Web XML-RPC diaktifkan di situs Anda. Fitur ini mengandalkan ekstensi PHP XML-RPC yang tidak lagi dikelola oleh PHP.', NULL, 1785718231, NULL, 0, 0),
	(3809, 'id', 3, 'yuicomboloading', 'YUI combo loading', 'Pemuatan kombo YUI', NULL, 1785718231, NULL, 0, 0),
	(3810, 'id', 3, 'ziprequired', 'The Zip PHP extension is now required by Moodle, info-ZIP binaries or PclZip library are not used anymore.', 'Ekstensi Zip PHP sekarang dibutuhkan oleh Moodle, binari info-ZIP atau pustaka PclZip tidak digunakan lagi.', NULL, 1785718231, NULL, 0, 0),
	(3811, 'id', 3, 'manageqbanks', 'Manage question bank plugins', 'Atur pengaya bank soal', NULL, 1785718231, NULL, 0, 0),
	(3812, 'id', 3, 'modassignmentinuse', 'Your site is still using the Assignment 2.2 plugin. Before upgrading you must 1) backup any Assignment 2.2 activities that you want to keep and restore them as Assignment activities, and 2) delete all Assignment 2.2 data from the database.', 'Situs Anda masih menggunakan pengaya Penugasan 2.2. Sebelum memutakhirkan, Anda harus 1) mencadangkan aktivitas Penugasan 2.2 yang ingin Anda simpan dan memulihkannya sebagai aktivitas Penugasan, dan 2) menghapus semua data Penugasan 2.2 dari basis data.', NULL, 1785718231, NULL, 0, 0),
	(3813, 'id', 3, 'modassignmentsubpluginsexist', 'Assignment 2.2. subplugins may be present. The mod/assignment folder and all of its subplugins need to be removed before upgrading.', 'Sub-pengaya Penugasan 2.2 mungkin tersedia. Folder mod/assignment dan semua sub-pengayanya perlu dihapus sebelum memutakhirkan.', NULL, 1785718231, NULL, 0, 0),
	(3814, 'id', 3, 'caching', 'Caching', 'Singgahan', NULL, 1785718231, NULL, 0, 0),
	(3815, 'id', 3, 'cachesettings', 'Cache settings', 'Setelan Singgahan', NULL, 1785718231, NULL, 0, 0),
	(3816, 'id', 3, 'cacherequest', 'Request cache', 'Meminta singgahan', NULL, 1785718231, NULL, 0, 0),
	(3817, 'id', 3, 'cacherequesthelp', 'User specific cache that expires when the request is complete. Designed to replace areas where we are using the static stores.', 'Singgahan pengguna tertentu yang kedaluwarsa saat permintaan selesai. Dirancang untuk menggantikan area di mana kami menggunakan penyimpanan statis.', NULL, 1785718231, NULL, 0, 0),
	(3818, 'id', 3, 'cachesession', 'Session cache', 'Singgahan sesi', NULL, 1785718231, NULL, 0, 0),
	(3819, 'id', 3, 'cachesessionhelp', 'User specific cache that expires when the user\'s session ends. Designed to alleviate session bloat/strain.', 'Singgahan pengguna tertentu yang kedaluwarsa saat sesi pengguna berakhir. Dirancang untuk mengurangi ketegangan sesi.', NULL, 1785718231, NULL, 0, 0),
	(3820, 'id', 3, 'cacheapplication', 'Application cache', 'Singgahan aplikasi', NULL, 1785718231, NULL, 0, 0),
	(3821, 'id', 3, 'cacheapplicationhelp', 'Cached items are shared among all users and expire by a determined time to live (ttl).', 'Item yang disinggahkan dibagikan di antara semua pengguna dan kedaluwarsa dengan waktu yang ditentukan untuk ditayangkan (ttl).', NULL, 1785718231, NULL, 0, 0),
	(3822, 'id', 3, 'blockunprotect', 'Unprotect', 'Tidak terlindungi', NULL, 1785718231, NULL, 0, 0),
	(3823, 'id', 3, 'configenabledevicedetection', 'Enables detection of mobiles, smartphones, tablets or default devices (desktop PCs, laptops, etc) for the application of themes and other features.', 'Memungkinkan deteksi ponsel, ponsel cerdas, tablet atau perangkat bawaan (PC desktop, laptop, dll) untuk aplikasi tema dan fitur lainnya.', NULL, 1785718231, NULL, 0, 0),
	(3824, 'id', 3, 'devicedetectregex', 'Device detection regular expressions', 'Ekspresi reguler pendeteksian perangkat.', NULL, 1785718231, NULL, 0, 0),
	(3825, 'id', 3, 'devicedetectregex_desc', '<p>By default, Moodle can detect devices of the type default (desktop PCs, laptops, etc), mobile (phones and small hand held devices), tablet (iPads, Android tablets) and legacy (Internet Explorer 6 users).  The theme selector can be used to apply separate themes to all of these.  This setting allows regular expressions that allow the detection of extra device types (these take precedence over the default types).</p>\n<p>For example, you could enter the regular expression \'/(MIDP-1.0|Maemo|Windows CE)/\' to detect some commonly used feature phones add the return value \'featurephone\'.  This adds \'featurephone\' on the theme selector that would allow you to add a theme that would be used on these devices.  Other phones would still use the theme selected for the mobile device type.</p>', '<p> Secara bawaan, Moodle dapat mendeteksi perangkat dari tipe standar (PC desktop, laptop, dll), ponsel (ponsel dan perangkat genggam kecil), tablet (iPad, tablet Android), dan perangkat lama (pengguna Internet Explorer 6). Pemilih tema dapat digunakan untuk menerapkan tema yang terpisah untuk semua ini. Setelan ini memungkinkan ekspresi reguler yang memungkinkan deteksi jenis perangkat tambahan (ini lebih diutamakan daripada jenis bawaan). </p>\n<p> Misalnya, Anda dapat memasukkan ekspresi reguler \'/(MIDP-1.0|Maemo|Windows CE) / \'untuk mendeteksi beberapa ponsel fitur yang umum digunakan menambah nilai balik\' featurephone \'. Ini menambahkan \'featurephone\' pada pemilih tema yang memungkinkan Anda untuk menambahkan tema yang akan digunakan pada perangkat ini. Telepon lain akan tetap menggunakan tema yang dipilih untuk jenis perangkat seluler. </p>', NULL, 1785718231, NULL, 0, 0),
	(3826, 'id', 3, 'devicedetectregexexpression', 'Regular expression', 'Ekspresi regular', NULL, 1785718231, NULL, 0, 0),
	(3827, 'id', 3, 'devicedetectregexvalue', 'Return value', 'Nilai kembali', NULL, 1785718231, NULL, 0, 0),
	(3828, 'id', 3, 'enabledevicedetection', 'Enable device detection', 'Aktifkan pendeteksian perangkat', NULL, 1785718231, NULL, 0, 0),
	(3829, 'id', 3, 'selectdevice', 'Select device', 'Pilih perangkat', NULL, 1785718231, NULL, 0, 0),
	(3830, 'id', 3, 'selecttheme', 'Select theme for {$a} device', 'Pilih tema untuk perangkat {$a}', NULL, 1785718231, NULL, 0, 0),
	(3831, 'id', 3, 'themenoselected', 'No theme selected', 'Tidak ada tema dipilih', NULL, 1785718231, NULL, 0, 0),
	(3832, 'id', 3, 'unsettheme', 'Unset theme', 'Tema tidak disetel', NULL, 1785718231, NULL, 0, 0),
	(3833, 'id', 3, 'taskdeletecachetext', 'Delete old text cache records', 'Hapus rekaman singgahan teks lama', NULL, 1785718231, NULL, 0, 0),
	(3834, 'id', 3, 'themesettings', 'Theme settings', 'Setelan tema', NULL, 1785718231, NULL, 0, 0),
	(3835, 'id', 3, 'linkcoursesections', 'Always link course sections', 'Selalu tautkan topik kursus', NULL, 1785718231, NULL, 0, 0),
	(3836, 'id', 3, 'linkcoursesections_help', 'Always try to provide a link for course sections. Course sections are usually only shown as links if the course format displays a single section per page. If this setting is enabled a link will always be provided.', 'Usahakan selalu untuk menyediakan tautan untuk topik kursus. Topik kursus biasanya hanya ditampilkan sebagai tautan jika format kursus menampilkan satu bagian per halaman. Jika setelan ini diaktifkan, tautan akan selalu disediakan.', NULL, 1785718231, NULL, 0, 0),
	(3837, 'id', 3, 'moodleapp', 'Moodle app', 'Aplikasi Moodle', NULL, 1785718231, NULL, 0, 0),
	(3838, 'id', 3, 'moodleapp_help', '<p>The free Moodle app enables users to access their courses on mobile devices. Additional app features are available with a Pro or Premium app plan.</p>\n<a href="https://moodle.com/mobile-app">Get the Moodle app</a><br />\n<a href="https://apps.moodle.com">Moodle Apps Portal</a>', '<p> Jika Anda memiliki akun di situs Moodle, Anda dapat mengakses semua kursus di perangkat seluler Anda dengan aplikasi seluler gratis kami untuk Moodle. </p> <a href = "https://moodle.com/mobile-app"> Dapatkan aplikasi Moodle </a>', NULL, 1785718231, NULL, 0, 0),
	(3839, 'id', 3, 'moodlebrandedapp_help', '<p>The Branded Moodle app has all the functionality of our free mobile app for Moodle combined with your own custom branding.</p>\n<a href="https://moodle.com/branded-app">About the Branded Moodle app</a>', '<p> Aplikasi Moodle Bermerek memiliki semua fungsi aplikasi seluler gratis kami untuk Moodle yang dikombinasikan dengan merek kustom Anda sendiri. </p> <a href="https://moodle.com/branded-app"> Tentang Aplikasi Moodle bermerek</a>', NULL, 1785718231, NULL, 0, 0),
	(3840, 'id', 3, 'moodlepartners', 'Moodle Partners', 'Mitra Moodle', NULL, 1785718231, NULL, 0, 0),
	(3841, 'id', 3, 'moodlepartners_help', '<p>Moodle Partners are services providers that are certified by Moodle HQ to provide high quality Moodle services for your organisation\'s online learning environment.</p>\n<a href="https://moodle.com/about-partners/">About our Partners</a><br />\n<a href="https://moodle.com/partners">Find a Partner</a>', '<p> Mitra Moodle adalah penyedia layanan yang disertifikasi oleh Moodle HQ untuk memberikan layanan Moodle berkualitas tinggi untuk lingkungan pembelajaran online organisasi Anda. </p> <a href="https://moodle.com/about-partners/"> Tentang Mitra kami </a> <br /> <a href="https://moodle.com/partners"> Temukan Mitra </a>', NULL, 1785718231, NULL, 0, 0),
	(3842, 'id', 3, 'moodleservices', 'Moodle services', 'Layanan Moodle', NULL, 1785718231, NULL, 0, 0),
	(3843, 'id', 3, 'moodleservices_help', 'Make sure you get the best from your Moodle learning environment by using these Moodle services:', 'Pastikan Anda mendapatkan yang terbaik dari lingkungan belajar Moodle Anda dengan menggunakan layanan Moodle ini:', NULL, 1785718231, NULL, 0, 0),
	(3844, 'id', 3, 'registration_help', 'By registering:\n\n* You will receive security alerts\n* You can activate mobile app push notifications from your site\n* You are contributing to our Moodle statistics of the worldwide community', 'Dengan mendaftar:\n\n* Anda akan menerima peringatan keamanan\n* Anda dapat mengaktifkan pemberitahuan push aplikasi seluler dari situs Anda\n* Anda berkontribusi pada statistik Moodle kami dari komunitas di seluruh dunia', NULL, 1785718231, NULL, 0, 0),
