	(3850, 'id', 4, 'errornopreset', 'A preset with this name doesn\'t exist.', 'Preset dengan nama tersebut tidak ada.', NULL, 1785718231, NULL, 0, 0),
	(3851, 'id', 4, 'fullpreset', 'Full', 'Penuh', NULL, 1785718231, NULL, 0, 0),
	(3852, 'id', 4, 'fullpresetdescription', 'All the Starter features plus External (LTI) tool, SCORM, Workshop, Analytics, Badges, Competencies, Learning plans and lots more.', 'Semua fitur awal plus alat eksternal (LTI), SCORM, Lokakarya, Analisis, Lencana, Kompetensi, Rencana pembelajaran, dan banyak lagi.', NULL, 1785718231, NULL, 0, 0),
