	(3869, 'id', 4, 'privacy:metadata:adminpresets_app:userid', 'The user who applied the preset.', 'Pengguna yang menerapkan preset.', NULL, 1785718231, NULL, 0, 0),
	(3870, 'id', 4, 'sensiblesettings', 'Settings with passwords', 'Setelan dengan kata sandi', NULL, 1785718231, NULL, 0, 0),
	(3871, 'id', 4, 'sensiblesettingstext', 'Settings with passwords or other sensitive information can be excluded when creating a site admin preset. Enter additional settings with format SETTINGNAME@@PLUGINNAME separated by commas.', 'Setelan dengan kata sandi atau informasi sensitif lainnya dapat dikecualikan saat membuat preset admin situs. Masukkan setelan tambahan dengan format SETTINGNAME@@PLUGINNAME yang dipisahkan dengan koma.', NULL, 1785718231, NULL, 0, 0),
	(3872, 'id', 4, 'siteadminpresetspluginname', 'Site admin presets', 'Preset admin situs', NULL, 1785718231, NULL, 0, 0),
	(3873, 'id', 4, 'starterpreset', 'Starter', 'Starter', NULL, 1785718231, NULL, 0, 0),
	(3874, 'id', 4, 'starterpresetdescription', 'Moodle with all of the most popular features, including Assignment, Feedback, Forum, H5P, Quiz and Completion tracking.', 'Moodle dengan semua fitur paling populer, termasuk Penugasan, Umpan Balik, Forum, H5P, Kuis, dan Pelacakan Penyelesaian.', NULL, 1785718231, NULL, 0, 0),
	(3875, 'id', 4, 'wrongid', 'Wrong ID', 'ID salah', NULL, 1785718231, NULL, 0, 0),
	(3876, 'id', 5, 'acceptai', 'Accept and continue', 'Terima dan lanjutkan', NULL, 1785718231, NULL, 0, 0),
	(3877, 'id', 5, 'action', 'Action', 'Aksi', NULL, 1785718231, NULL, 0, 0),
	(3878, 'id', 5, 'action_generate_image', 'Generate image', 'Hasilkan gambar', NULL, 1785718231, NULL, 0, 0),
	(3879, 'id', 5, 'action_generate_image_desc', 'Generates an image based on a text prompt.', 'Hasilkan gambar berdasarkan perintah teks.', NULL, 1785718231, NULL, 0, 0),
	(3880, 'id', 5, 'action_generate_text', 'Generate text', 'Hasilkan teks', NULL, 1785718231, NULL, 0, 0),
	(3881, 'id', 5, 'action_generate_text_desc', 'Generates text based on a text prompt.', 'Menghasilkan teks berdasarkan perintah teks.', NULL, 1785718231, NULL, 0, 0),
	(3882, 'id', 5, 'action_generate_text_instruction', 'You will receive a text input from the user. Your task is to generate text based on their request. Follow these important instructions:\n    1. Return the summary in plain text only.\n    2. Do not include any markdown formatting, greetings, or platitudes.', 'Anda akan menerima masukan teks dari pengguna. Tugas Anda adalah membuat teks berdasarkan permintaan mereka. Ikuti petunjuk penting berikut:\n    1. Berikan ringkasan hanya dalam bentuk teks biasa.\n    2. Jangan sertakan format markdown, salam, atau basa-basi.', NULL, 1785718231, NULL, 0, 0),
	(3883, 'id', 5, 'action_summarise_text', 'Summarise text', 'Meringkas teks', NULL, 1785718231, NULL, 0, 0),
	(3884, 'id', 5, 'action_summarise_text_desc', 'Summarises the text content on a course page.', 'Meringkas konten teks pada halaman kursus.', NULL, 1785718231, NULL, 0, 0),
	(3885, 'id', 5, 'action_summarise_text_instruction', 'You will receive a text input from the user. Your task is to summarize the provided text. Follow these guidelines:\n    1. Condense: Shorten long passages into key points.\n    2. Simplify: Make complex information easier to understand, especially for learners.\n\nImportant Instructions:\n    1. Return the summary in plain text only.\n    2. Do not include any markdown formatting, greetings, or platitudes.\n    3. Focus on clarity, conciseness, and accessibility.\n\nEnsure the summary is easy to read and effectively conveys the main points of the original text.', 'Anda akan menerima masukan teks dari pengguna. Tugas Anda adalah meringkas teks yang diberikan. Ikuti panduan berikut:\n     1. Ringkas: Persingkat bagian yang panjang menjadi poin-poin penting.\n     2. Sederhanakan: Jadikan informasi yang rumit lebih mudah dipahami, terutama bagi pelajar.\n\nPetunjuk Penting:\n     1. Berikan ringkasan hanya dalam bentuk teks biasa.\n     2. Jangan sertakan format markdown, salam, atau basa-basi.\n     3. Fokus pada kejelasan, keringkasan, dan aksesibilitas.\n\nPastikan ringkasan mudah dibaca dan menyampaikan poin-poin utama teks asli secara efektif.', NULL, 1785718231, NULL, 0, 0),
	(3886, 'id', 5, 'action_translate_text', 'Translate text', 'Terjemahkan teks', NULL, 1785718231, NULL, 0, 0),
	(3887, 'id', 5, 'action_translate_text_desc', 'Translate provided text from one language to another.', 'Terjemahkan teks yang disediakan dari satu bahasa ke bahasa lain.', NULL, 1785718231, NULL, 0, 0),
	(3888, 'id', 5, 'actionsettingprovider', '{$a} action settings', 'Setelan aksi {$a}', NULL, 1785718231, NULL, 0, 0),
	(3889, 'id', 5, 'actionsettingprovider_desc', 'These settings control how the {$a->providername} performs the action {$a->actionname}.', 'Setelan ini mengontrol bagaimana {$a->providername} melakukan aksi {$a->actionname}.', NULL, 1785718231, NULL, 0, 0),
	(3890, 'id', 5, 'ai', 'AI', 'AI', NULL, 1785718231, NULL, 0, 0),
	(3891, 'id', 5, 'aiplacements', 'AI placements', 'Penempatan AI', NULL, 1785718231, NULL, 0, 0),
	(3892, 'id', 5, 'aiproviders', 'AI providers', 'Penyedia AI', NULL, 1785718231, NULL, 0, 0),
	(3893, 'id', 5, 'aiusagepolicy', 'AI usage policy', 'Pilih di mana tindakan AI tersedia', NULL, 1785718231, NULL, 0, 0),
	(3894, 'id', 5, 'availableplacements', 'Choose where AI actions are available', 'Pilih di mana tindakan AI tersedia', NULL, 1785718231, NULL, 0, 0),
	(3895, 'id', 5, 'availableplacements_desc', 'Placements define how and where AI actions can be used in your site. You can choose which actions are available in each placement through the settings.', 'Penempatan menentukan bagaimana dan di mana tindakan AI dapat digunakan di situs Anda. Anda dapat memilih tindakan mana yang tersedia di setiap penempatan melalui setelan.', NULL, 1785718231, NULL, 0, 0),
	(3896, 'id', 5, 'availableproviders', 'Manage the AI providers connected to your LMS', 'Kelola penyedia AI yang terhubung ke LMS Anda', NULL, 1785718231, NULL, 0, 0),
	(3897, 'id', 5, 'availableproviders_desc', 'AI providers add AI functionality to your site through \'actions\' like text summarisation or image generation.<br/>\nYou can manage the actions for each provider in their settings.', 'Penyedia AI menambahkan fungsionalitas AI ke situs Anda melalui \'tindakan\' seperti ringkasan teks atau pembuatan gambar.<br/>\nAnda dapat mengelola tindakan untuk setiap penyedia dalam setelan mereka.', NULL, 1785718231, NULL, 0, 0),
	(3898, 'id', 5, 'contentwatermark', 'Generated by AI', 'Dihasilkan oleh AI', NULL, 1785718231, NULL, 0, 0),
	(3899, 'id', 5, 'declineaipolicy', 'Decline', 'Tolak', NULL, 1785718231, NULL, 0, 0),
	(3900, 'id', 5, 'manageaiplacements', 'Manage AI placements', 'Kelola penempatan AI', NULL, 1785718231, NULL, 0, 0),
	(3901, 'id', 5, 'manageaiproviders', 'Manage AI providers', 'Kelola penyedia AI', NULL, 1785718231, NULL, 0, 0),
	(3902, 'id', 5, 'noproviders', 'This action is unavailable. No <a href="{$a}">AI providers</a> are configured for this action.', 'Aksi ini tidak tersedia. Tidak ada <a href="{$a}">penyedia AI</a> yang dikonfigurasi untuk aksi ini.', NULL, 1785718231, NULL, 0, 0),
	(3903, 'id', 5, 'placement', 'Placement', 'Penempatan', NULL, 1785718231, NULL, 0, 0),
	(3904, 'id', 5, 'placementactionsettings', 'Actions', 'Tindakan', NULL, 1785718231, NULL, 0, 0),
	(3905, 'id', 5, 'placementactionsettings_desc', 'The AI actions available for this placement.', 'Tindakan AI yang tersedia untuk penempatan ini.', NULL, 1785718231, NULL, 0, 0),
	(3906, 'id', 5, 'placementsettings', 'Placement-specific settings', 'Setelan khusus penempatan', NULL, 1785718231, NULL, 0, 0),
	(3907, 'id', 5, 'placementsettings_desc', 'These settings control how this AI placement connects to the AI service, and related operations.', 'Setelan ini mengontrol bagaimana penempatan AI ini terhubung ke layanan AI, dan operasi terkait.', NULL, 1785718231, NULL, 0, 0),
	(3908, 'id', 5, 'privacy:metadata:ai_action_generate_image', 'A table storing the image generation requests made by users.', 'Tabel yang menyimpan permintaan pembuatan gambar yang dibuat oleh pengguna.', NULL, 1785718231, NULL, 0, 0),
	(3909, 'id', 5, 'privacy:metadata:ai_action_generate_image:aspectratio', 'The aspect ratio of the generated images.', 'Rasio aspek gambar yang dihasilkan.', NULL, 1785718231, NULL, 0, 0),
