	(3913, 'id', 5, 'privacy:metadata:ai_action_generate_image:revisedprompt', 'The revised prompt of the generated images.', 'Perintah yang direvisi dari gambar yang dihasilkan.', NULL, 1785718231, NULL, 0, 0),
	(3914, 'id', 5, 'privacy:metadata:ai_action_generate_image:sourceurl', 'The source URL of the generated images.', 'URL sumber gambar yang dihasilkan.', NULL, 1785718231, NULL, 0, 0),
