	(3916, 'id', 5, 'privacy:metadata:ai_action_generate_text', 'A table storing the text generation requests made by users.', 'Tabel yang menyimpan permintaan pembuatan teks yang dibuat oleh pengguna.', NULL, 1785718231, NULL, 0, 0),
	(3917, 'id', 5, 'privacy:metadata:ai_action_generate_text:completiontoken', 'The completion tokens used to generate the text.', 'Token pelengkapan yang digunakan untuk menghasilkan teks.', NULL, 1785718231, NULL, 0, 0),
