	(4278, 'id', 8, 'user_activatenotsupportusertype', 'auth: ldap user_activate() does not support selected usertype: {$a}', 'autentikasi: ldap user_activate() tidak mendukung tipe pengguna terpilih: {$a}', NULL, 1785718232, NULL, 0, 0),
	(4279, 'id', 8, 'user_disablenotsupportusertype', 'auth: ldap user_disable() does not support selected usertype (..yet)', 'autentikasi: ldap user_disable() belum mendukung tipe pengguna terpilih', NULL, 1785718232, NULL, 0, 0),
