	(4329, 'id', 10, 'asyncbackupcomplete', 'The backup process has completed', 'Proses pencadangan selesai', NULL, 1785718232, NULL, 0, 0),
	(4330, 'id', 10, 'asyncbackupcompletebutton', 'Continue', 'Lanjutkan', NULL, 1785718232, NULL, 0, 0),
	(4331, 'id', 10, 'asyncbackupcompletedetail', 'The backup process has completed successfully. <br/> You can access the backup on the <a href="{$a}">restore page.</a>', 'Proses pencadangan berhasil diselesaikan. <br/> Anda dapat mengakses cadangan di <a href="{$a}"> halaman pemulihan. </a>', NULL, 1785718232, NULL, 0, 0),
	(4332, 'id', 10, 'asyncbackuperror', 'The backup process has failed', 'Proses pencadangan gagal', NULL, 1785718232, NULL, 0, 0),
	(4333, 'id', 10, 'asyncbackuperrordetail', 'The backup process has failed. Please contact your system administrator.', 'Proses pencadangan gagal. Silakan kontak administrator sistem.', NULL, 1785718232, NULL, 0, 0),
