	(4336, 'id', 10, 'asyncbadexecution', 'Bad backup controller execution. It is {$a} and should be 2.', 'Eksekusi pengontrol cadangan yang buruk. Ini adalah {$a} dan seharusnya 2.', NULL, 1785718232, NULL, 0, 0),
	(4337, 'id', 10, 'asynccheckprogress', 'You can check the progress at any time on the <a href="{$a}">restore page</a>.', 'Anda dapat memeriksa kemajuannya kapan saja di <a href="{$a}"> Laman pemulihan </a>.', NULL, 1785718232, NULL, 0, 0),
	(4338, 'id', 10, 'asyncgeneralsettings', 'Asynchronous backup/restore', 'Pencadangan/pemulihan asinkron', NULL, 1785718232, NULL, 0, 0),
	(4339, 'id', 10, 'asyncemailenable', 'Enable notifications', 'Aktifkan notifikasi', NULL, 1785718232, NULL, 0, 0),
	(4340, 'id', 10, 'asyncemailenabledetail', 'If enabled, users will receive a notification when an asynchronous backup or restore completes.', 'Jika diaktifkan, pengguna akan menerima pesan saat pencadangan atau pemulihan asinkron selesai.', NULL, 1785718232, NULL, 0, 0),
	(4341, 'id', 10, 'asyncmessagebody', 'Notification', 'Notifikasi', NULL, 1785718232, NULL, 0, 0),
	(4342, 'id', 10, 'asyncmessagebodydetail', 'Notification to send when an asynchronous backup or restore completes.', 'Notifikasi untuk dikirim ketika pencadangan atau pemulihan asinkron selesai.', NULL, 1785718232, NULL, 0, 0),
	(4343, 'id', 10, 'asyncmessagebodydefault', 'Your {operation} (ID: {backupid}) has completed successfully. You can access it here: <a href="{link}">{link}</a>.', 'Hai {user_firstname}, <br/> {operation} Anda (ID: {backupid}) berhasil diselesaikan. <br/> <br/> Anda dapat mengaksesnya di sini: {link}.', NULL, 1785718232, NULL, 0, 0),
	(4344, 'id', 10, 'asyncmessagesubject', 'Subject', 'Subjek', NULL, 1785718232, NULL, 0, 0),
	(4345, 'id', 10, 'asyncmessagesubjectdetail', 'Notification subject', 'Subjek Notifikasi', NULL, 1785718232, NULL, 0, 0),
	(4346, 'id', 10, 'asyncmessagesubjectdefault', 'Moodle {operation} completed successfully', 'Moodle {operation} berhasil diselesaikan', NULL, 1785718232, NULL, 0, 0),
	(4347, 'id', 10, 'asyncnowait', 'You don\'t need to wait here, as the process will continue in the background.', 'Anda tidak perlu menunggu di sini, karena prosesnya akan berlangsung di latar belakang.', NULL, 1785718232, NULL, 0, 0),
	(4348, 'id', 10, 'asyncprocesspending', 'Process pending', 'Proses ditangguhkan', NULL, 1785718232, NULL, 0, 0),
