	(4358, 'id', 10, 'asyncrestoreinprogress_help', 'Asynchronous course restores that are in progress are shown here.', 'Pemulihan kursus asinkron yang sedang berlangsung ditampilkan di sini.', NULL, 1785718232, NULL, 0, 0),
	(4359, 'id', 10, 'autoactivedisabled', 'Disabled', 'Dinonaktifkan', NULL, 1785718232, NULL, 0, 0),
	(4360, 'id', 10, 'autoactiveenabled', 'Enabled', 'Diaktifkan', NULL, 1785718232, NULL, 0, 0),
	(4361, 'id', 10, 'autoactivemanual', 'Manual', 'Manual', NULL, 1785718232, NULL, 0, 0),
	(4362, 'id', 10, 'autoactivedescription', 'Choose whether or not to do automated backups. If manual is selected automated backups will be possible only by through the automated backups CLI script. This can be done either manually on the command line or through cron.', 'Pilih apakah akan melakukan pencadangan otomatis atau tidak. Jika manual dipilih, cadangan otomatis hanya dimungkinkan melalui skrip CLI cadangan otomatis. Ini dapat dilakukan secara manual pada baris perintah atau melalui cron.', NULL, 1785718232, NULL, 0, 0),
	(4363, 'id', 10, 'automatedbackupschedule', 'Schedule', 'Jadwal', NULL, 1785718232, NULL, 0, 0),
	(4364, 'id', 10, 'automatedbackupschedulehelp', 'Choose which days of the week to perform automated backups.', 'Pilih hari dalam seminggu untuk melakukan pencadangan otomatis.', NULL, 1785718232, NULL, 0, 0),
	(4365, 'id', 10, 'automatedbackupsinactive', 'Automated backups haven\'t been enabled by the site admin', 'Pencadangan otomatis tidak diaktifkan oleh admin situs', NULL, 1785718232, NULL, 0, 0),
	(4366, 'id', 10, 'automatedbackupstatus', 'Automated backup status', 'Status jadwal pencadangan', NULL, 1785718232, NULL, 0, 0),
	(4367, 'id', 10, 'automateddeletedays', 'Delete backups older than', 'Hapus pencadangan yang lebih lama dari', NULL, 1785718232, NULL, 0, 0),
	(4368, 'id', 10, 'automatedmaxkept', 'Maximum number of backups kept', 'Jumlah cadangan maksimum yang tetap disimpan', NULL, 1785718232, NULL, 0, 0),
	(4369, 'id', 10, 'automatedmaxkepthelp', 'This specifies the maximum number of recent automated backups to be kept for each course. Older backups will be deleted automatically.', 'Ini menentukan jumlah maksimum cadangan otomatis terbaru yang akan disimpan untuk setiap kursus. Cadangan yang lebih lama akan dihapus secara otomatis.', NULL, 1785718232, NULL, 0, 0),
	(4370, 'id', 10, 'automatedminkept', 'Minimum number of backups kept', 'Jumlah minimum cadangan yang tetap disimpan', NULL, 1785718232, NULL, 0, 0),
	(4371, 'id', 10, 'automatedminkepthelp', 'If backups older than a specified number of days are deleted, it can happen that an inactive course ends up with no backup. To prevent this, a minimum number of backups kept should be specified.', 'Jika cadangan yang lebih lama dari jumlah hari tertentu dihapus, dapat terjadi kursus yang tidak aktif berakhir tanpa cadangan. Untuk mencegah hal ini, jumlah minimum cadangan yang disimpan harus ditentukan.', NULL, 1785718232, NULL, 0, 0),
	(4372, 'id', 10, 'automatedsetup', 'Automated backup setup', 'Setel pencadangan otomatis', NULL, 1785718232, NULL, 0, 0),
	(4373, 'id', 10, 'automatedsettings', 'Automated backup settings', 'Setelan pencadangan otomatis', NULL, 1785718232, NULL, 0, 0),
