	(4376, 'id', 10, 'backupactivity', 'Backup activity: {$a}', 'Aktivitas pencadangan: {$a}', NULL, 1785718232, NULL, 0, 0),
	(4377, 'id', 10, 'backupautoactivitiesdescription', 'Sets the default for including activities in a backup. For the recycle bin to work, this setting must be enabled.', 'Setel bawaan untuk menyertakan aktivitas dalam pencadangan. Agar keranjang sampah berfungsi, setelan ini harus diaktifkan.', NULL, 1785718232, NULL, 0, 0),
