	(4414, 'id', 10, 'cannotfindassignablerole', 'The {$a} role in the backup file cannot be mapped to any of the roles that you are allowed to assign.', 'Peran {$a} dalam berkas cadangan tidak dapat dipetakan ke peran apa pun yang diizinkan untuk Anda tetapkan.', NULL, 1785718232, NULL, 0, 0),
