	(4423, 'id', 10, 'config_keep_groups_and_groupings', 'By default keep current groups and groupings.', 'Secara bawaan, pertahankan grup dan pengelompokan saat ini.', NULL, 1785718232, NULL, 0, 0),
	(4424, 'id', 10, 'config_keep_roles_and_enrolments', 'By default keep current roles and enrolments.', 'Secara bawaan, pertahankan peran dan pendaftaran saat ini.', NULL, 1785718232, NULL, 0, 0),
	(4425, 'id', 10, 'config_overwrite_conf', 'Allows user to overwrite the current course configuration', 'Memungkinkan pengguna untuk menimpa konfigurasi kursus saat ini', NULL, 1785718232, NULL, 0, 0),
	(4426, 'id', 10, 'config_overwrite_course_fullname', 'By default overwrite course full name with the one from the backup file. This requires "Overwrite course configuration" to be checked and current user to have the capability to change course full name (moodle/course:changefullname)', 'Secara bawaan timpa nama lengkap kursus dengan nama dari berkas cadangan. Ini membutuhkan "Timpa konfigurasi kursus" untuk diperiksa dan pengguna saat ini memiliki kemampuan untuk mengubah nama lengkap kursus (moodle/course:changefullname)', NULL, 1785718232, NULL, 0, 0),
	(4427, 'id', 10, 'config_overwrite_course_shortname', 'By default overwrite course short name with the one from the backup file. This requires "Overwrite course configuration" to be checked and current user to have the capability to change course short name (moodle/course:changeshortname)', 'Secara bawaan, timpa nama singkat kursus dengan nama yang ada di berkas cadangan. Ini membutuhkan "Timpa konfigurasi kursus" untuk diperiksa dan pengguna saat ini memiliki kemampuan untuk mengubah nama singkat kursus (moodle/course:changeshortname)', NULL, 1785718232, NULL, 0, 0),
	(4428, 'id', 10, 'config_overwrite_course_startdate', 'By default overwrite course start date with the one from the backup file. This requires "Overwrite course configuration" to be checked and current user to have the capability to roll course dates on restore (moodle/restore:rolldates)', 'Secara bawaan, timpa tanggal mulai kursus dengan tanggal dari berkas cadangan. Hal ini memerlukan "Timpa konfigurasi kursus" untuk diperiksa dan pengguna saat ini memiliki kemampuan untuk memutar tanggal kursus saat pemulihan (moodle/restore:rolldates)', NULL, 1785718232, NULL, 0, 0),
	(4429, 'id', 10, 'configgeneralactivities', 'Sets the default for including activities in a backup.', 'Setel bawaan untuk menyertakan aktivitas dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4430, 'id', 10, 'configgeneralbadges', 'Sets the default for including badges in a backup.', 'Setel bawaan untuk menyertakan lencana dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4431, 'id', 10, 'configgeneralanonymize', 'If enabled all information pertaining to users will be anonymised by default.', 'JIka diaktifkan semua informasi yang berkaitan dengan pengguna akan dibuat anonim secara bawaan.', NULL, 1785718232, NULL, 0, 0),
	(4432, 'id', 10, 'configgeneralblocks', 'Sets the default for including blocks in a backup.', 'Setel bawaan untuk menyertakan blok dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4433, 'id', 10, 'configgeneralcalendarevents', 'Sets the default for including calendar events in a backup.', 'Setel bawaan untuk menyertakan acara kalender dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4434, 'id', 10, 'configgeneralcomments', 'Sets the default for including comments in a backup.', 'Setel bawaan untuk menyertakan komentar dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4435, 'id', 10, 'configgeneralcompetencies', 'Sets the default for including competencies in a backup.', 'Setel bawaan untuk menyertakan kompetensi dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4436, 'id', 10, 'configgeneralcontentbankcontent', 'Sets the default for including content bank content in a backup.', 'Setel bawaan untuk menyertakan isi bank konten dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4437, 'id', 10, 'configgeneralcustomfield', 'Sets the default for including custom fields in a backup.', 'Menetapkan setelan bawaan untuk menyertakan kolom custom dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4438, 'id', 10, 'configgeneralfiles', 'Sets the default for including files in a backup. Please note: Disabling this setting will result in a backup which only includes references to files. This is not a problem if the backup is restored on the same site and the files have not been deleted according to the setting \'Clean up trash pool files\' (filescleanupperiod).', 'Setel bawaan untuk menyertakan berkas dalam cadangan. Harap diperhatikan: Menonaktifkan setelan ini akan menghasilkan cadangan yang hanya menyertakan referensi ke berkas. Ini bukan masalah jika cadangan dipulihkan di situs yang sama dan berkas belum dihapus sesuai dengan setelan \'Bersihkan berkas kumpulan sampah\' (filescleanupperiod).', NULL, 1785718232, NULL, 0, 0),
	(4439, 'id', 10, 'configgeneralfilters', 'Sets the default for including filters in a backup.', 'Setel bawaan untuk menyertakan filter dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4440, 'id', 10, 'configgeneralhistories', 'Sets the default for including user history within a backup.', 'Setel bawaan untuk menyertakan riwayat pengguna dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4441, 'id', 10, 'configgenerallogs', 'If enabled logs will be included in backups by default.', 'Jika log yang diaktifkan akan dimasukkan dalam cadangan secara bawaan.', NULL, 1785718232, NULL, 0, 0),
	(4442, 'id', 10, 'configgeneralquestionbank', 'If enabled the question bank will be included in backups by default. PLEASE NOTE: Disabling this setting will disable the backup of activities which use the question bank, such as the quiz.', 'Jika diaktifkan, bank soal akan disertakan dalam cadangan secara bawaan. PERHATIKAN: Menonaktifkan setelan ini akan menonaktifkan cadangan aktivitas yang menggunakan bank soal, seperti kuis.', NULL, 1785718232, NULL, 0, 0),
	(4443, 'id', 10, 'configgeneralgroups', 'Sets the default for including groups and groupings in a backup.', 'Setel bawaan untuk menyertakan grup dan pengelompokan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4444, 'id', 10, 'configgeneralroleassignments', 'If enabled by default roles assignments will also be backed up.', 'Jika diaktifkan secara bawaan, penugasan peran juga akan dicadangkan.', NULL, 1785718232, NULL, 0, 0),
	(4445, 'id', 10, 'configgeneralpermissions', 'If enabled the role permissions will be imported. This may override existing permissions for enrolled users.', 'Jika diaktifkan, izin peran akan diimpor. Ini dapat menggantikan izin yang ada untuk pengguna terdaftar.', NULL, 1785718232, NULL, 0, 0),
	(4446, 'id', 10, 'configgeneraluserscompletion', 'If enabled user completion information will be included in backups by default.', 'Jika diaktifkan, informasi penyelesaian pengguna akan disertakan dalam cadangan secara bawaan.', NULL, 1785718232, NULL, 0, 0),
	(4447, 'id', 10, 'configgeneralusers', 'Sets the default for whether to include users in backups.', 'Setel bawaan apakah akan memasukkan pengguna atau tidak dalam pencadangan.', NULL, 1785718232, NULL, 0, 0),
	(4448, 'id', 10, 'configgeneralxapistate', 'Sets the default for including the user\'s state in content such as H5P activities in a backup.', 'Menyetel bawaan untuk menyertakan status pengguna dalam konten seperti aktivitas H5P dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4449, 'id', 10, 'configlegacyfiles', 'Sets the default for including legacy course files in a backup. Legacy course files are from versions of Moodle prior to 2.0.', 'Setel bawaan untuk menyertakan berkas kursus lama dalam cadangan. Berkas kursus lama berasal dari versi Moodle sebelum 2.0.', NULL, 1785718232, NULL, 0, 0),
	(4450, 'id', 10, 'configloglifetime', 'This specifies the length of time you want to keep backup logs information. Logs that are older than this age are automatically deleted. It is recommended to keep this value small, because backup logged information can be huge.', 'Ini menentukan lama waktu Anda ingin menyimpan informasi log cadangan. Log yang lebih tua dari usia ini secara otomatis dihapus. Disarankan untuk menjaga nilai ini kecil, karena informasi yang dicatat dapat sangat besar.', NULL, 1785718232, NULL, 0, 0),
	(4451, 'id', 10, 'configrestoreactivities', 'Sets the default for restoring activities.', 'Setel bawaan untuk memulihkan aktivitas.', NULL, 1785718232, NULL, 0, 0),
	(4452, 'id', 10, 'configrestorebadges', 'Sets the default for restoring badges.', 'Setel bawaan untuk memulihkan lencana.', NULL, 1785718232, NULL, 0, 0),
	(4453, 'id', 10, 'configrestoreblocks', 'Sets the default for restoring blocks.', 'Setel bawaan untuk memulihkan blok.', NULL, 1785718232, NULL, 0, 0),
	(4454, 'id', 10, 'configrestorecalendarevents', 'Sets the default for restoring calendar events.', 'Setel bawaan untuk memulihkan acara kalender.', NULL, 1785718232, NULL, 0, 0),
	(4455, 'id', 10, 'configrestorecomments', 'Sets the default for restoring comments.', 'Setel bawaan untuk memulihkan komentar.', NULL, 1785718232, NULL, 0, 0),
	(4456, 'id', 10, 'configrestorecompetencies', 'Sets the default for restoring competencies.', 'Setel bawaan untuk memulihkan kompetensi.', NULL, 1785718232, NULL, 0, 0),
	(4457, 'id', 10, 'configrestorecontentbankcontent', 'Sets the default for restoring content bank content.', 'Setel bawaan untuk memulihkan konten bank konten.', NULL, 1785718232, NULL, 0, 0),
	(4458, 'id', 10, 'configrestorecustomfield', 'Sets the default for restoring custom fields.', 'Menetapkan setelan bawaan untuk memulihkan kolom kustom.', NULL, 1785718232, NULL, 0, 0),
	(4459, 'id', 10, 'configrestoreenrolments', 'Sets the default for restoring enrolment methods.', 'Setel bawaan untuk memulihkan metode pendaftaran.', NULL, 1785718232, NULL, 0, 0),
	(4460, 'id', 10, 'configrestorefilters', 'Sets the default for restoring filters.', 'Setel bawaan untuk memulihkan filter.', NULL, 1785718232, NULL, 0, 0),
	(4461, 'id', 10, 'configrestorehistories', 'Sets the default for restoring user history if it was included in the backup.', 'Setel bawaan untuk memulihkan riwayat pengguna jika itu termasuk dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4462, 'id', 10, 'configrestorelogs', 'If enabled logs will be restored by default if they were included in the backup.', 'Jika diaktifkan, log akan dipulihkan secara bawaan jika disertakan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4463, 'id', 10, 'configrestoregroups', 'Sets the default for restoring groups and groupings if they were included in the backup.', 'Setel bawaan untuk memulihkan grup dan pengelompokan jika disertakan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4464, 'id', 10, 'configrestoreroleassignments', 'If enabled by default roles assignments will be restored if they were included in the backup.', 'Jika diaktifkan secara bawaan, tugas peran akan dipulihkan jika disertakan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4465, 'id', 10, 'configrestorepermissions', 'If enabled the role permissions will be restored. This may override existing permissions for enrolled users.', 'Jika diaktifkan, izin peran akan dipulihkan. Ini dapat mengesampingkan izin yang ada untuk pengguna terdaftar.', NULL, 1785718232, NULL, 0, 0),
	(4466, 'id', 10, 'configrestoreuserscompletion', 'If enabled user completion information will be restored by default if it was included in the backup.', 'Jika diaktifkan, informasi penyelesaian pengguna akan dipulihkan secara bawaan jika disertakan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4467, 'id', 10, 'configrestoreusers', 'Sets the default for whether to restore users if they were included in the backup.', 'Setel bawaan apakah akan memulihkan pengguna jika mereka disertakan dalam cadangan.', NULL, 1785718232, NULL, 0, 0),
	(4468, 'id', 10, 'configrestorexapistate', 'Sets the default for restoring the user\'s state in content such as H5P activities.', 'Menyetel bawaan untuk memulihkan status pengguna dalam konten seperti aktivitas H5P.', NULL, 1785718232, NULL, 0, 0),
