	(4475, 'id', 10, 'confirmnewcoursecontinue', 'New course warning', 'Peringatan kursus baru', NULL, 1785718232, NULL, 0, 0),
	(4476, 'id', 10, 'confirmnewcoursecontinuequestion', 'A temporary (hidden) course will be created by the course restoration process. To abort restoration click cancel. Do not close the browser while restoring.', 'Kursus sementara (tersembunyi) akan dibuat oleh proses pemulihan kursus. Untuk membatalkan pemulihan klik batal. Jangan tutup peramban saat memulihkan.', NULL, 1785718232, NULL, 0, 0),
	(4477, 'id', 10, 'copiesinprogress', 'This course has copies in progress. <a href="{$a}">View in progress copies.</a>', 'Salinan kursus ini sedang dalam proses. <a href="{$a}"> Lihat salinan yang sedang diproses. </a>', NULL, 1785718232, NULL, 0, 0),
	(4478, 'id', 10, 'copycoursedesc', 'Create a copy of this course in any course category.', 'Buat salinan kursus ini di kategori kursus mana pun.', NULL, 1785718232, NULL, 0, 0),
