	(4501, 'id', 10, 'enableasyncbackup', 'Enable asynchronous backups', 'Aktifkan pencadangan asinkron', NULL, 1785718232, NULL, 0, 0),
	(4502, 'id', 10, 'enableasyncbackup_help', 'If enabled, backup and restore operations will be done asynchronously. This provides a better user experience allowing users to do other operations while a backup or restore is in progress. This does not affect imports and exports.', 'Jika diaktifkan, semua operasi pencadangan dan pemulihan akan dilakukan secara asinkron. Hal ini memberikan pengalaman pengguna yang lebih baik yang memungkinkan pengguna melakukan operasi lain saat pencadangan atau pemulihan sedang berlangsung. Hal ini tidak mempengaruhi impor dan ekspor.', NULL, 1785718232, NULL, 0, 0),
	(4503, 'id', 10, 'enterasearch', 'Enter a search', 'Masukkan pencarian', NULL, 1785718232, NULL, 0, 0),
	(4504, 'id', 10, 'error_block_for_module_not_found', 'Orphan block instance (id: {$a->bid}) for course module (id: {$a->mid}) found. This block will not be backed up', 'Ditemukan model blok yatim piatu (id: {$a->bid}) untuk modul kursus (id: {$a->mid}). Blok ini tidak akan dicadangkan', NULL, 1785718232, NULL, 0, 0),
	(4505, 'id', 10, 'error_course_module_not_found', 'Orphan course module (id: {$a}) found. This module will not be backed up.', 'Modul kursus yatim piatu (id: {$a}) ditemukan. Modul ini tidak akan dicadangkan.', NULL, 1785718232, NULL, 0, 0),
	(4506, 'id', 10, 'error_delegate_section_not_found', 'Missing delegate section form course module (ID {$a}). The section will not be backed up.', 'Modul kursus formulir bagian delegasi tidak ada (ID {$a}). Bagian tersebut tidak akan dicadangkan.', NULL, 1785718232, NULL, 0, 0),
	(4507, 'id', 10, 'errorcopyingbackupfile', 'Failed to copy the backup file to the temporary folder before restoring.', 'Gagal menyalin berkas cadangan ke folder sementara sebelum memulihkan.', NULL, 1785718232, NULL, 0, 0),
	(4508, 'id', 10, 'errorfilenamerequired', 'You must enter a valid filename for this backup', 'Anda harus memasukkan nama berkas yang valid untuk cadangan ini', NULL, 1785718232, NULL, 0, 0),
	(4509, 'id', 10, 'errorfilenametoolong', 'The filename must be less than 255 characters in length.', 'Panjang nama berkas harus kurang dari 255 karakter.', NULL, 1785718232, NULL, 0, 0),
	(4510, 'id', 10, 'errorfilenamemustbezip', 'The filename you enter must be a ZIP file and have the .mbz extension', 'Nama file yang Anda masukkan harus berupa file ZIP dan memiliki ekstensi .mbz', NULL, 1785718232, NULL, 0, 0),
	(4511, 'id', 10, 'errorminbackup20version', 'This backup file has been created with one development version of Moodle backup ({$a->backup}). Minimum required is {$a->min}. Cannot be restored.', 'Berkas cadangan ini telah dibuat dengan satu versi pengembangan cadangan Moodle\n ({$a->backup}). Minimum yang dibutuhkan adalah {$a->min}. Tidak dapat dipulihkan.', NULL, 1785718232, NULL, 0, 0),
