	(4513, 'id', 10, 'errorinvalidformatinfo', 'The selected file is not a valid Moodle backup file and can\'t be restored.', 'Berkas yang dipilih bukan berkas cadangan Moodle yang valid dan tidak dapat dipulihkan.', NULL, 1785718232, NULL, 0, 0),
	(4514, 'id', 10, 'errorrestorefrontpagebackup', 'You can only restore site home backups on the site home', 'Anda hanya dapat memulihkan cadangan beranda situs di beranda situs', NULL, 1785718232, NULL, 0, 0),
	(4515, 'id', 10, 'executionsuccess', 'The backup file was successfully created.', 'Berkas cadangan berhasil dibuat.', NULL, 1785718232, NULL, 0, 0),
