	(4805, 'id', 11, 'backpackconnected', 'Backpack is connected', 'Ransel terhubung', NULL, 1785718233, NULL, 0, 0),
	(4806, 'id', 11, 'backpackconnection', 'Connect to a backpack', 'Terhubung ke ransel', NULL, 1785718233, NULL, 0, 0),
	(4807, 'id', 11, 'backpackconnection_help', 'Store and share your badges from this site and display public badges from other websites on your user profile.', 'Simpan dan bagikan lencana Anda dari situs ini dan tampilkan lencana publik dari situs web lain di profil pengguna Anda.', NULL, 1785718233, NULL, 0, 0),
	(4808, 'id', 11, 'backpackconnection_connected', 'Your backpack', 'Ransel Anda', NULL, 1785718233, NULL, 0, 0),
	(4809, 'id', 11, 'backpackconnectioncancelattempt', 'Connect using a different email address', 'Tersambung menggunakan alamat surel yang lain', NULL, 1785718233, NULL, 0, 0),
	(4810, 'id', 11, 'backpackconnectionconnect', 'Connect to backpack', 'Tersambung ke ransel', NULL, 1785718233, NULL, 0, 0),
	(4811, 'id', 11, 'backpackconnectionresendemail', 'Resend verification email', 'Kirim ulang surel verifikasi', NULL, 1785718233, NULL, 0, 0),
	(4812, 'id', 11, 'backpackconnectionunexpectedresult', 'There was a problem connecting to your backpack. Your backpack provider is sending this message: \'{$a}\'.', 'Galat ketika menghubungkan ke ransel Anda. Penyedia ransel Anda mengirimkan pesan ini: \'{$a}\'.', NULL, 1785718233, NULL, 0, 0),
	(4813, 'id', 11, 'backpackconnectionunexpectedmessage', 'The backpack returned the error: "{$a}".', 'Ransel itu mengembalikan kesalahan: "{$a}".', NULL, 1785718233, NULL, 0, 0),
	(4814, 'id', 11, 'backpackdetails', 'Backpack settings', 'Setelan ransel', NULL, 1785718233, NULL, 0, 0),
	(4815, 'id', 11, 'backpackdisconnected', 'Backpack is disconnected', 'Ransel terputus', NULL, 1785718233, NULL, 0, 0),
	(4816, 'id', 11, 'backpackemail_required', 'Email address can\'t be blank', 'Alamat surel tidak boleh kosong', NULL, 1785718233, NULL, 0, 0),
	(4817, 'id', 11, 'backpackemailverificationpending', 'Verification pending', 'Verifikasi tertunda', NULL, 1785718233, NULL, 0, 0),
	(4818, 'id', 11, 'backpackemailverifyemailbody', 'Hi {$a->userfirstname},\n\nYou\'re almost done connecting to your badges backpack on \'{$a->sitename}\'.\n\nTo finish connecting to your backpack, verify your email address through the following button:\n\n{$a->buttonlink}\n\nIf the button doesn\'t work, you can copy and paste the following URL into your browser:\n{$a->link}\n\n\nIf you didn\'t try to connect to your badges backpack, you can safely ignore this email.\n\nFor any extra help, please contact your site support,\n\n{$a->admin}', 'Halo {$a->userfirstname},\n\nAnda hampir selesai terhubung ke ransel lencana Anda di \'{$a->sitename}\'.\n\nUntuk menyelesaikan menghubungkan ke ransel Anda, verifikasi alamat surel Anda melalui tombol berikut:\n\n{$a->buttonlink}\n\nJika tombol tidak berfungsi, Anda dapat menyalin dan menempelkan URL berikut ke peramban Anda:\n{$a->link}\n\nJika Anda tidak mencoba terhubung ke ransel lencana Anda, Anda dapat mengabaikan surel ini dengan aman.\n\nUntuk bantuan tambahan, silakan hubungi dukungan situs Anda,\n\n{$a->admin}', NULL, 1785718233, NULL, 0, 0),
	(4819, 'id', 11, 'backpackemailverifyemailsubject', '{$a}: Badges backpack email verification', '{$a}: Verifikasi surel ransel lencana', NULL, 1785718233, NULL, 0, 0),
	(4820, 'id', 11, 'backpackemailverifypending', 'We have sent an email to <strong>{$a}</strong>. Click on the verification link in the email to activate your backpack connection.', 'Surel verifikasi telah dikirim ke <strong> {$a} </strong>. Klik tautan verifikasi di surel untuk mengaktifkan koneksi ransel Anda.', NULL, 1785718233, NULL, 0, 0),
	(4821, 'id', 11, 'backpackemailverifysuccess', 'You\'re now connected to your backpack.', 'Anda sekarang terhubung ke ransel Anda.', NULL, 1785718233, NULL, 0, 0),
	(4822, 'id', 11, 'backpackemailverifytokenmismatch', 'The token in the link you clicked does not match the stored token. Make sure you clicked the link in most recent email you received.', 'Token di tautan yang Anda klik tidak cocok dengan token yang disimpan. Pastikan Anda mengklik tautan di surel terbaru yang Anda terima.', NULL, 1785718233, NULL, 0, 0),
	(4823, 'id', 11, 'backpackexporterror', 'Can\'t export the badge to backpack', 'Tidak dapat mengekspor lencana ke ransel', NULL, 1785718233, NULL, 0, 0),
	(4824, 'id', 11, 'backpackexporterrorwithinfo', 'Can\'t export the badge "{$a->badgename}" to backpack. Error: {$a->error}', 'Tidak dapat mengekspor lencana "{$a->badgename}" ke ransel. Kesalahan: {$a->error}', NULL, 1785718233, NULL, 0, 0),
	(4825, 'id', 11, 'backpackimport', 'Badge import settings', 'Setelan impor lencana', NULL, 1785718233, NULL, 0, 0),
	(4826, 'id', 11, 'backpackimport_help', 'After the backpack connection is successfully established, badges from your backpack can be displayed on your badges page and your profile page.\n\nIn this area, you can select collections of badges from your backpack that you would like to display in your profile.', 'Setelah koneksi ransel berhasil dibuat, lencana dari ransel Anda dapat ditampilkan di halaman lencana dan halaman profil Anda. Di area ini, Anda dapat memilih koleksi lencana dari ransel Anda yang ingin Anda tampilkan di profil Anda.', NULL, 1785718233, NULL, 0, 0),
	(4827, 'id', 11, 'backpacksettings', 'Backpack settings', 'Setelan ransel', NULL, 1785718233, NULL, 0, 0),
	(4828, 'id', 11, 'backpackapiurl', 'Backpack API URL', 'URL API Ransel', NULL, 1785718233, NULL, 0, 0),
