	(4889, 'id', 11, 'createbutton', 'Create badge', 'Buat lencana', NULL, 1785718233, NULL, 0, 0),
	(4890, 'id', 11, 'creatorbody', '<p>{$a->user} has completed all badge requirements and has been awarded the badge. View issued badge at {$a->link} </p>', '<p> {$a->user} telah menyelesaikan semua persyaratan lencana dan mendapatkan lencana. Lihat lencana yang diterbitkan di {$a->link} </p>', NULL, 1785718233, NULL, 0, 0),
