	(4925, 'id', 11, 'criteria_descr_1', '<strong>{$a}</strong> of the following activities are completed:', '<strong> {$a} </strong> dari aktivitas berikut telah diselesaikan:', NULL, 1785718233, NULL, 0, 0),
	(4926, 'id', 11, 'criteria_descr_2', 'This badge has to be awarded by the users with <strong>{$a}</strong> of the following roles:', 'Lencana ini telah diberikan oleh pengguna dengan  <strong>{$a}</strong> dari peran berikut:', NULL, 1785718233, NULL, 0, 0),
