	(4928, 'id', 11, 'criteria_descr_5', '<strong>{$a}</strong> of the following courses have to be completed:', '<strong> {$a} </strong> dari kursus berikut harus diselesaikan:', NULL, 1785718233, NULL, 0, 0),
	(4929, 'id', 11, 'criteria_descr_6', '<strong>{$a}</strong> of the following user profile fields have to be completed:', '<strong> {$a} </strong> dari ruas profil pengguna berikut harus dilengkapi:', NULL, 1785718233, NULL, 0, 0),
	(4930, 'id', 11, 'criteria_descr_7', '<strong>{$a}</strong> of the following badges have to be earned:', '<strong> {$a} </strong> dari lencana berikut harus diperoleh:', NULL, 1785718233, NULL, 0, 0),
	(4931, 'id', 11, 'criteria_descr_8', 'Membership in <strong>{$a}</strong> of the following cohorts is required:', 'Keanggotaan dalam <strong> {$a} </strong> dari kohor berikut diperlukan:', NULL, 1785718233, NULL, 0, 0),
	(4932, 'id', 11, 'criteria_descr_9', '<strong>{$a}</strong> of the following competencies have to be completed:', '<strong>{$a}</strong> kompetensi berikut harus diselesaikan:', NULL, 1785718233, NULL, 0, 0),
	(4933, 'id', 11, 'criteria_0', 'This badge is awarded when...', 'Lencana ini diberikan ketika...', NULL, 1785718233, NULL, 0, 0),
	(4934, 'id', 11, 'criteria_1', 'Activity completion', 'Penyelesaian aktivitas', NULL, 1785718233, NULL, 0, 0),
	(4935, 'id', 11, 'criteria_1_help', 'Allows a badge to be awarded to users based on the completion of a set of activities within a course.', 'Mengizinkan lencana diberikan kepada pengguna berdasarkan penyelesaian serangkaian aktivitas dalam suatu kursus.', NULL, 1785718233, NULL, 0, 0),
	(4936, 'id', 11, 'criteria_2', 'Manual issue by role', 'Terbitkan manual berdasarkan peran', NULL, 1785718233, NULL, 0, 0),
	(4937, 'id', 11, 'criteria_2_help', 'Allows a badge to be awarded manually by users who have a particular role within the site or course.', 'Mengizinkan lencana diberikan secara manual oleh pengguna yang memiliki peran tertentu dalam situs atau kursus.', NULL, 1785718233, NULL, 0, 0),
	(4938, 'id', 11, 'criteria_3', 'Social participation', 'Partisipasi sosial', NULL, 1785718233, NULL, 0, 0),
	(4939, 'id', 11, 'criteria_3_help', 'Social', 'Sosial', NULL, 1785718233, NULL, 0, 0),
	(4940, 'id', 11, 'criteria_4', 'Course completion', 'Penyelesaian kursus', NULL, 1785718233, NULL, 0, 0),
	(4941, 'id', 11, 'criteria_4_help', 'Allows a badge to be awarded to users who have completed the course. This criterion can have additional parameters such as minimum grade and date of course completion.', 'Mengizinkan lencana diberikan kepada pengguna yang telah menyelesaikan kursus. Kriteria ini dapat memiliki parameter tambahan seperti nilai minimum dan tanggal penyelesaian kursus.', NULL, 1785718233, NULL, 0, 0),
	(4942, 'id', 11, 'criteria_5', 'Completing a set of courses', 'Menyelesaikan sekumpulan kursus', NULL, 1785718233, NULL, 0, 0),
	(4943, 'id', 11, 'criteria_5_help', 'Allows a badge to be awarded to users who have completed a set of courses. Each course can have additional parameters such as minimum grade and date of course completion. ', 'Mengizinkan lencana diberikan kepada pengguna yang telah menyelesaikan serangkaian kursus. Setiap kursus dapat memiliki parameter tambahan seperti nilai minimum dan tanggal penyelesaian kursus.', NULL, 1785718233, NULL, 0, 0),
	(4944, 'id', 11, 'criteria_6', 'Profile completion', 'Penyelesaian profil', NULL, 1785718233, NULL, 0, 0),
	(4945, 'id', 11, 'criteria_6_help', 'Allows a badge to be awarded to users for completing certain fields in their profile. You can select from default and custom profile fields that are available to users. ', 'Mengizinkan lencana diberikan kepada pengguna karena menyelesaikan bidang tertentu di profil mereka. Anda dapat memilih dari bidang profil bawaan dan kursus yang tersedia untuk pengguna.', NULL, 1785718233, NULL, 0, 0),
	(4946, 'id', 11, 'criteria_7', 'Awarded badges', 'Lencana yang diberikan', NULL, 1785718233, NULL, 0, 0),
	(4947, 'id', 11, 'criteria_7_help', 'Allows a badge to be awarded to users based on other badges they have earned.', 'Mengizinkan lencana diberikan kepada pengguna berdasarkan lencana lain yang telah mereka peroleh.', NULL, 1785718233, NULL, 0, 0),
	(4948, 'id', 11, 'criteria_8', 'Cohort membership', 'Keanggotaan kohor', NULL, 1785718233, NULL, 0, 0),
	(4949, 'id', 11, 'criteria_8_help', 'Allows a badge to be awarded to users based on cohort membership.', 'Memungkinkan lencana diberikan kepada pengguna berdasarkan keanggotaan kohor.', NULL, 1785718233, NULL, 0, 0),
	(4950, 'id', 11, 'criteria_9', 'Competencies', 'Kompetensi', NULL, 1785718233, NULL, 0, 0),
	(4951, 'id', 11, 'criteria_9_help', 'Allows a badge to be awarded to users based on the competencies they have completed.', 'Memungkinkan lencana diberikan kepada pengguna berdasarkan kompetensi yang telah mereka selesaikan.', NULL, 1785718233, NULL, 0, 0),
	(4952, 'id', 11, 'criterror', 'Current parameters issues', 'Masalah parameter saat ini', NULL, 1785718233, NULL, 0, 0),
	(4953, 'id', 11, 'criterror_help', 'This fieldset shows all parameters that were initially added to this badge requirement but are no longer available. It is recommended that you un-check such parameters to make sure that users can earn this badge in the future.', 'Kumpulan ruas ini menunjukkan semua parameter yang awalnya ditambahkan ke persyaratan lencana ini tetapi tidak lagi tersedia. Sebaiknya hapus centang pada parameter tersebut untuk memastikan bahwa pengguna dapat memperoleh lencana ini di masa mendatang.', NULL, 1785718233, NULL, 0, 0),
	(4954, 'id', 11, 'currentimage', 'Current image', 'Gambar sekarang', NULL, 1785718233, NULL, 0, 0),
	(4955, 'id', 11, 'currentstatus', 'Current status: ', 'Status terkini:', NULL, 1785718233, NULL, 0, 0),
	(4956, 'id', 11, 'dateawarded', 'Date issued', 'Tanggal terbit', NULL, 1785718233, NULL, 0, 0),
	(4957, 'id', 11, 'dateearned', 'Date: {$a}', 'Tanggal: {$a}', NULL, 1785718233, NULL, 0, 0),
	(4958, 'id', 11, 'day', 'Day(s)', 'Hari', NULL, 1785718233, NULL, 0, 0),
	(4959, 'id', 11, 'deactivate', 'Disable access', 'Nonaktifkan akses', NULL, 1785718233, NULL, 0, 0),
	(4960, 'id', 11, 'deactivatesuccess', 'Access to badge \'{$a}\' disabled.', 'Akses ke lencana \'{$a}\' dinonaktifkan.', NULL, 1785718233, NULL, 0, 0),
	(4961, 'id', 11, 'defaultissuercontact', 'Badge issuer email address', 'Alamat surel penerbit lencana', NULL, 1785718233, NULL, 0, 0),
	(4962, 'id', 11, 'defaultissuercontact_desc', 'An email address associated with the badge issuer. For an Open Badges v2.0 backpack, this is used for authentication when publishing badges to a backpack.', 'Alamat surel yang terkait dengan penerbit lencana. Untuk ransel Open Badges v2.0, ini digunakan untuk otentikasi saat menerbitkan lencana ke ransel.', NULL, 1785718233, NULL, 0, 0),
	(4963, 'id', 11, 'defaultissuerpassword', 'Badge issuer password', 'Kata sandi penerbit lencana', NULL, 1785718233, NULL, 0, 0),
	(4964, 'id', 11, 'defaultissuerpassword_help', 'An account is required on the backpack site with email address as specified in the badge issuer email address setting in Site administration / Badges / Badges settings. The password for the account should be entered here.', 'Akun diperlukan di situs ransel dengan alamat surel seperti yang ditentukan dalam setelan alamat surel penerbit lencana di administrasi Situs/Lencana/Setelan Lencana. Kata sandi untuk akun tersebut harus dimasukkan di sini.', NULL, 1785718233, NULL, 0, 0),
	(4965, 'id', 11, 'defaultissuername', 'Badge issuer name', 'Nama penerbit lencana', NULL, 1785718233, NULL, 0, 0),
	(4966, 'id', 11, 'defaultissuername_desc', 'Name of the issuing agent or authority.', 'Nama agen atau otoritas penerbit.', NULL, 1785718233, NULL, 0, 0),
	(4967, 'id', 11, 'delbadge', 'Would you like to delete badge \'{$a}\' and remove all existing issued badges?', 'Apakah Anda ingin menghapus lencana \'{$a}\' dan menghapus semua lencana yang diterbitkan?', NULL, 1785718233, NULL, 0, 0),
	(4968, 'id', 11, 'delexternalbackpack', 'Delete site backpack', 'Hapus situs ransel', NULL, 1785718233, NULL, 0, 0),
	(4969, 'id', 11, 'delexternalbackpackconfirm', 'Delete site backpack \'{$a}\'?', 'Hapus situs ransel \'{$a}\'?', NULL, 1785718233, NULL, 0, 0),
	(4970, 'id', 11, 'delconfirm', 'Delete and remove existing issued badges', 'Hapus dan hapus lencana yang sudah ada', NULL, 1785718233, NULL, 0, 0),
	(4971, 'id', 11, 'deletehelp', '<p>Fully deleting a badge means that all its information and criteria records will be permanently removed. Users who have earned this badge will no longer be able to access it and display it on their profile pages.</p>\n<p>Note: Users who have earned this badge and have already pushed it to their external backpack, will still have this badge in their external backpack. However, they will not be able to access criteria and evidence pages linking back to this web site.</p>', '<p> Menghapus lencana sepenuhnya berarti semua informasi dan catatan kriterianya akan dihapus secara permanen. Pengguna yang mendapatkan lencana ini tidak dapat lagi mengaksesnya dan menampilkannya di halaman profil mereka. </p> <p> Catatan: Pengguna yang telah mendapatkan lencana ini dan telah memasukkannya ke ransel eksternal mereka, masih akan memiliki lencana ini di ransel luar mereka. Namun, mereka tidak akan dapat mengakses kriteria dan halaman bukti yang menautkan kembali ke situs web ini. </p>', NULL, 1785718233, NULL, 0, 0),
	(4972, 'id', 11, 'delcritconfirm', 'Are you sure that you want to delete this criterion?', 'Apakah Anda yakin ingin menghapus kriteria ini?', NULL, 1785718233, NULL, 0, 0),
	(4973, 'id', 11, 'delparamconfirm', 'Are you sure that you want to delete this parameter?', 'Anda yakin ingin menghapus parameter ini?', NULL, 1785718233, NULL, 0, 0),
	(4974, 'id', 11, 'description', 'Description', 'Deskripsi', NULL, 1785718233, NULL, 0, 0),
	(4975, 'id', 11, 'disconnect', 'Disconnect', 'Putuskan', NULL, 1785718233, NULL, 0, 0),
	(4976, 'id', 11, 'donotaward', 'Currently, this badge is not active, so it cannot be awarded to users. If you would like to award this badge, please set its status to active.', 'Saat ini, lencana ini tidak aktif, sehingga tidak dapat diberikan kepada pengguna. Jika Anda ingin memberikan lencana ini, atur statusnya menjadi aktif.', NULL, 1785718233, NULL, 0, 0),
	(4977, 'id', 11, 'enablebadges', 'Enable badges', 'Aktifkan lencana', NULL, 1785718233, NULL, 0, 0),
	(4978, 'id', 11, 'endorsement', 'Endorsement', 'Pengesahan', NULL, 1785718233, NULL, 0, 0),
	(4979, 'id', 11, 'error:backpackdatainvalid', 'The data return from the backpack was invalid.', 'Data yang dikembalikan dari ransel tidak valid.', NULL, 1785718233, NULL, 0, 0),
	(4980, 'id', 11, 'error:backpackemailnotfound', 'The email \'{$a}\' is not associated with a backpack. You need to <a href="http://backpack.openbadges.org">create a backpack</a> for that account or sign in with another email address.', 'Surel \'{$a}\' tidak terkait dengan ransel. Anda perlu <a href="http://backpack.openbadges.org">membuat ransel</a> untuk akun tersebut atau masuk dengan alamat surel lain.', NULL, 1785718233, NULL, 0, 0),
	(4981, 'id', 11, 'error:badgeawardnotfound', 'Cannot verify this awarded badge.  This badge may have been revoked.', 'Tidak dapat memverifikasi lencana yang diberikan ini. Lencana ini mungkin telah dicabut.', NULL, 1785718233, NULL, 0, 0),
	(4982, 'id', 11, 'error:badgenotfound', 'Badge not found', 'Lencana tidak ditemukan', NULL, 1785718233, NULL, 0, 0),
	(4983, 'id', 11, 'error:cannotawardbadge', 'Cannot award badge to a user.', 'Tidak dapat memberikan lencana kepada pengguna.', NULL, 1785718233, NULL, 0, 0),
	(4984, 'id', 11, 'error:cannotrevokebadge', 'Cannot revoke badge from a user.', 'Tidak dapat mencabut lencana dari pengguna.', NULL, 1785718233, NULL, 0, 0),
	(4985, 'id', 11, 'error:cannotdeletecriterion', 'This criterion cannot be deleted. ', 'Kriteria ini tidak dapat dihapus.', NULL, 1785718233, NULL, 0, 0),
	(4986, 'id', 11, 'error:cannotsendtobackpack', '<strong>Can\'t add badge to backpack</strong><br />\nYour backpack provider is sending this message: \'{$a}\'.<br /><br />\nYou can try downloading the badge and adding it manually to your backpack, or try again later.', '<strong>Tidak dapat menambahkan lencana ke ransel</strong><br />\nPenyedia ransel Anda mengirimkan pesan ini: \'{$a}\'.<br /><br />\nAnda dapat mencoba mengunduh lencana dan menambahkannya secara manual ke ransel Anda, atau coba lagi nanti.', NULL, 1785718233, NULL, 0, 0),
	(4987, 'id', 11, 'error:connectionunknownreason', 'The connection was unsuccessful but no reason was given.', 'Koneksi tidak berhasil tetapi tidak ada alasan yang diberikan.', NULL, 1785718233, NULL, 0, 0),
	(4988, 'id', 11, 'error:clone', 'Cannot clone the badge.', 'Tidak dapat mengkloning lencana.', NULL, 1785718233, NULL, 0, 0),
	(4989, 'id', 11, 'error:externalbadgedoesntexist', 'Badge not found', 'Lencana tidak ditemukan', NULL, 1785718233, NULL, 0, 0),
	(4990, 'id', 11, 'error:guestuseraccess', 'You are currently using guest access. To see badges you need to log in with your user account.', 'Anda sedang menggunakan akses tamu. Untuk melihat lencana, Anda harus masuk dengan akun pengguna Anda.', NULL, 1785718233, NULL, 0, 0),
	(4991, 'id', 11, 'error:invalidcriteriatype', 'Invalid criteria type.', 'Jenis kriteria tidak valid.', NULL, 1785718233, NULL, 0, 0),
	(4992, 'id', 11, 'error:invalidexpiredate', 'Expiry date has to be in the future.', 'Tanggal kedaluwarsa harus di waktu di akan datang.', NULL, 1785718233, NULL, 0, 0);
INSERT INTO `mdl_tool_customlang` (`id`, `lang`, `componentid`, `stringid`, `original`, `master`, `local`, `timemodified`, `timecustomized`, `outdated`, `modified`) VALUES
	(4993, 'id', 11, 'error:invalidexpireperiod', 'Expiry period cannot be negative or equal 0.', 'Periode kedaluwarsa tidak boleh negatif atau sama dengan 0.', NULL, 1785718233, NULL, 0, 0),
	(4994, 'id', 11, 'error:invalidparambadge', 'Badge does not exist. ', 'Lencana tidak ada.', NULL, 1785718233, NULL, 0, 0),
	(4995, 'id', 11, 'error:noactivities', 'There are no activities with completion criteria enabled in this course.', 'Tidak ada aktivitas dengan kriteria penyelesaian yang diaktifkan dalam kursus ini.', NULL, 1785718233, NULL, 0, 0),
	(4996, 'id', 11, 'error:nobadges', 'There are currently no badges with access enabled to be added as criteria. A site badge can only have other site badges as criteria. A course badge can have other course badges or site badges as criteria.', 'Tidak ada lencana kursus atau situs dengan akses yang diaktifkan untuk ditambahkan sebagai kriteria.', NULL, 1785718233, NULL, 0, 0),
	(4997, 'id', 11, 'error:invalidparamcohort', 'Cohort does not exist. ', 'Kohor tidak ada.', NULL, 1785718233, NULL, 0, 0),
	(4998, 'id', 11, 'error:nocohorts', 'No cohorts', 'Tak ada kohor', NULL, 1785718233, NULL, 0, 0),
	(4999, 'id', 11, 'error:nocourses', 'Course completion is not enabled for any of the courses in this site, so none can be displayed. Course completion may be enabled in the course settings.', 'Penyelesaian kursus tidak diaktifkan untuk kursus mana pun di situs ini, jadi tidak ada yang dapat ditampilkan. Penyelesaian kursus dapat diaktifkan di setelan kursus.', NULL, 1785718233, NULL, 0, 0),
	(5000, 'id', 11, 'error:nogroupssummary', '<p>There are no public collections of badges available in your backpack. </p>', '<p>Tidak ada koleksi lencana publik yang tersedia di ransel Anda. </p>', NULL, 1785718233, NULL, 0, 0),
	(5001, 'id', 11, 'error:nogroupslink', '<p>Only public collections are shown. <a href="{$a}" target="_blank" rel="nofollow">Visit your backpack</a> to create some public collections.</p>', '<p> Hanya koleksi publik yang ditampilkan. <a href="{$a}" target="_blank" rel="nofollow"> Kunjungi ransel Anda </a> untuk membuat beberapa koleksi publik. </p>', NULL, 1785718233, NULL, 0, 0),
	(5002, 'id', 11, 'error:nopermissiontoview', 'You have no permissions to view badge recipients', 'Anda tidak diizinkan melihat penerima lencana', NULL, 1785718233, NULL, 0, 0),
	(5003, 'id', 11, 'error:nosuchbadge', 'Badge with id {$a} does not exist.', 'Lencana dengan id {$a} tidak ada.', NULL, 1785718233, NULL, 0, 0),
	(5004, 'id', 11, 'error:nosuchcohort', 'Warning: This cohort is no longer available.', 'Peringatan: Kohor ini tidak lagi tersedia.', NULL, 1785718233, NULL, 0, 0),
	(5005, 'id', 11, 'error:nosuchcourse', 'Warning: This course is no longer available.', 'Peringatan: kursus ini tidak lagi tersedia.', NULL, 1785718233, NULL, 0, 0),
	(5006, 'id', 11, 'error:nosuchfield', 'Warning: This user profile field is no longer available.', 'Peringatan: Ruas profil pengguna ini tidak lagi tersedia.', NULL, 1785718233, NULL, 0, 0),
	(5007, 'id', 11, 'error:nosuchmod', 'Warning: This activity is no longer available.', 'Peringatan: Aktivitas ini tidak lagi tersedia.', NULL, 1785718233, NULL, 0, 0),
	(5008, 'id', 11, 'error:nosuchrole', 'Warning: This role is no longer available.', 'Peringatan: Peran ini tidak lagi tersedia.', NULL, 1785718233, NULL, 0, 0),
	(5009, 'id', 11, 'error:nosuchuser', 'User with this email address does not have an account with the current backpack provider.', 'Pengguna dengan alamat surel ini tidak memiliki akun di penyedia ransel saat ini.', NULL, 1785718233, NULL, 0, 0),
