	(5056, 'id', 11, 'includeauthdetails_desc', 'Enter your badge issuer credentials to connect to your backpack provider.', 'Masukkan kredensial penerbit lencana Anda untuk terhubung ke penyedia tas ransel Anda.', NULL, 1785718233, NULL, 0, 0),
	(5057, 'id', 11, 'includeauthdetails_help', 'Sends your issuer credentials with each badge exported to this backpack.', 'Mengirimkan kredensial penerbit Anda dengan setiap lencana yang diekspor ke ransel ini.', NULL, 1785718233, NULL, 0, 0),
	(5058, 'id', 11, 'includeauthdetailscanvas', 'Connect to a Canvas Credentials issuer account', 'Hubungkan ke akun penerbit Canvas Credentials', NULL, 1785718233, NULL, 0, 0),
	(5059, 'id', 11, 'includeauthdetailscanvas_desc', 'Enter your Canvas Credentials details to connect your issuer account.', 'Masukkan rincian Canvas Credentials Anda untuk menghubungkan akun penerbit Anda.', NULL, 1785718233, NULL, 0, 0),
	(5060, 'id', 11, 'includeauthdetailscanvas_help', 'Badges exported to Canvas Credentials will show your organisation as the issuer. This also lets you track who received badges, and manage updates.', 'Lencana yang diekspor ke Canvas Credentials akan menampilkan organisasi Anda sebagai penerbit. Ini juga memungkinkan Anda melacak siapa yang menerima lencana dan mengelola pembaruan.', NULL, 1785718233, NULL, 0, 0),
	(5061, 'id', 11, 'includeauthdetailscanvas_subtitle', '(Requires a Canvas Credentials paid plan)', '(Memerlukan paket Canvas Credentials berbayar)', NULL, 1785718233, NULL, 0, 0),
	(5062, 'id', 11, 'imageauthoremail_help', 'If specified, the email address of the badge image author is displayed on the badge page.', 'Jika ditentukan, alamat surel dari pembuat gambar lencana ditampilkan di halaman lencana.', NULL, 1785718233, NULL, 0, 0),
