	(5090, 'id', 11, 'makeprivate', 'Make private', 'Jadikan pribadi', NULL, 1785718233, NULL, 0, 0),
	(5091, 'id', 11, 'makepublic', 'Make public', 'Jadikan publik', NULL, 1785718233, NULL, 0, 0),
	(5092, 'id', 11, 'managebadges', 'Manage badges', 'Kelola lencana', NULL, 1785718233, NULL, 0, 0),
	(5093, 'id', 11, 'managebackpacks', 'Manage backpacks', 'Kelola ransel', NULL, 1785718233, NULL, 0, 0),
	(5094, 'id', 11, 'message', 'Message body', 'Tubuh pesan', NULL, 1785718233, NULL, 0, 0),
	(5095, 'id', 11, 'messagebody', '<p>You have been awarded the badge "%badgename%"!</p>\n<p>More information about this badge can be found on the %badgelink% badge information page.</p>\n<p>You can manage and download the badge from your {$a} page.</p>', '<p> Anda telah diberikan lencana "%badgename%"! </p> <p> Informasi lebih lanjut tentang lencana ini dapat ditemukan di halaman%badgelink% informasi lencana. </p> <p> Anda dapat mengelola dan unduh lencananya dari laman {$a} Anda. </p>', NULL, 1785718233, NULL, 0, 0),
	(5096, 'id', 11, 'messagesubject', 'Congratulations! You just earned a badge!', 'Selamat! Anda baru saja mendapatkan lencana!', NULL, 1785718233, NULL, 0, 0),
