	(5118, 'id', 11, 'nomatchingbadges', 'There are no matching badges available for users to earn.', 'Tidak ada lencana yang cocok yang tersedia untuk diperoleh pengguna.', NULL, 1785718233, NULL, 0, 0),
	(5119, 'id', 11, 'nocompetencies', 'No competencies selected.', 'Tidak ada kompetensi yang dipilih.', NULL, 1785718233, NULL, 0, 0),
