	(6853, 'id', 24, 'coursecommunication_desc', 'The default communication service for new courses. Existing courses will not have any provider selected by default.', 'Layanan komunikasi bawaan untuk kursus baru. Kursus yang ada tidak akan memilih penyedia mana pun secara bawaan.', NULL, 1785718236, NULL, 0, 0),
	(6854, 'id', 24, 'coursecontentnotification', 'Send content change notification', 'Kirim pemberitahuan perubahan konten', NULL, 1785718236, NULL, 0, 0),
	(6855, 'id', 24, 'coursecontentnotifnew', '{$a->coursename} new content', '{$a->coursename} konten baru', NULL, 1785718236, NULL, 0, 0),
	(6856, 'id', 24, 'coursecontentnotifnewbody', '<p>{$a->moduletypename} <a href="{$a->link}">{$a->modulename}</a> is new in the course <a href="{$a->courselink}">{$a->coursename}</a>.</p><p><a href="{$a->notificationpreferenceslink}">Change your notification preferences</a></p>', '<p>{$a->moduletypename} <a href="{$a->link}">{$a->modulename}</a> baru dalam kursus <a href="{$a->courselink}">{$a->coursename}</a>.</p><p><a href="{$a->notificationpreferenceslink}">Ubah preferensi notifikasi Anda</a></p>', NULL, 1785718236, NULL, 0, 0),
	(6857, 'id', 24, 'coursecontentnotifupdate', '{$a->coursename} content change', '{$a->coursename} perubahan konten', NULL, 1785718236, NULL, 0, 0),
	(6858, 'id', 24, 'coursecontentnotifupdatebody', '<p>{$a->moduletypename} <a href="{$a->link}">{$a->modulename}</a> has been changed in the course <a href="{$a->courselink}">{$a->coursename}</a>.</p><p><a href="{$a->notificationpreferenceslink}">Change your notification preferences</a></p>', '<p>{$a->moduletypename} <a href="{$a->link}">{$a->modulename}</a> telah diubah dalam kursus <a href="{$a->courselink}">{$a->coursename}</a>.</p><p><a href="{$a->notificationpreferenceslink}">Ubah preferensi notifikasi Anda </a></p>', NULL, 1785718236, NULL, 0, 0),
	(6859, 'id', 24, 'coursecontentnotification_help', 'Tick the box to notify course participants about this new or changed activity or resource. Only users who can access the activity or resource will receive the notification.', 'Centang kotak untuk memberi tahu peserta kursus tentang aktivitas atau sumber daya baru atau yang diubah ini. Hanya pengguna yang dapat mengakses aktivitas atau sumber yang akan menerima notifikasi.', NULL, 1785718236, NULL, 0, 0),
