	(6896, 'id', 24, 'norecentaccessesinfomessage', 'Hi {$a->userfirstname},\n<p>A number of students in {$a->coursename} have not accessed the course recently.</p>', 'Hai {$a->userfirstname},\n<p>Sejumlah siswa di {$a->coursename} belum mengakses kursus akhir-akhir ini.</p>', NULL, 1785718236, NULL, 0, 0),
