	(6919, 'id', 24, 'studentsatriskinfomessage', 'Hi {$a->userfirstname},\n<p>Students in the {$a->coursename} course have been identified as being at risk.</p>', 'Hai {$a->userfirstname},\n<p>Siswa di kursus {$a->coursename} teridentifikasi dalam risiko.</p>', NULL, 1785718236, NULL, 0, 0),
	(6920, 'id', 24, 'target:coursecompletion', 'Students at risk of not meeting the course completion conditions', 'Siswa berisiko tidak memenuhi persyaratan penyelesaian kursus', NULL, 1785718236, NULL, 0, 0),
	(6921, 'id', 24, 'target:coursecompletion_help', 'This target describes whether the student is considered at risk of not meeting the course completion conditions.', 'Target ini menjelaskan apakah siswa dianggap berisiko tidak memenuhi ketentuan penyelesaian kursus.', NULL, 1785718236, NULL, 0, 0),
	(6922, 'id', 24, 'target:coursecompetencies', 'Students at risk of not achieving the competencies assigned to a course', 'Siswa berisiko tidak mencapai kompetensi yang ditugaskan pada satu kursus', NULL, 1785718236, NULL, 0, 0),
	(6923, 'id', 24, 'target:coursecompetencies_help', 'This target describes whether a student is at risk of not achieving the competencies assigned to a course. This target considers that all competencies assigned to the course must be achieved by the end of the course.', 'Target ini menggambarkan apakah seorang siswa berisiko tidak mencapai kompetensi yang ditugaskan pada suatu kursus. Target ini menganggap bahwa semua kompetensi yang diberikan pada kursus tersebut harus dicapai pada akhir kursus.', NULL, 1785718236, NULL, 0, 0),
	(6924, 'id', 24, 'target:coursedropout', 'Students at risk of dropping out', 'Siswa dalam risiko keluar', NULL, 1785718236, NULL, 0, 0),
	(6925, 'id', 24, 'target:coursedropout_help', 'This target describes whether the student is considered at risk of dropping out.', 'Sasaran ini menggambarkan apakah siswa tersebut dianggap berisiko putus sekolah.', NULL, 1785718236, NULL, 0, 0),
