	(8222, 'id', 33, 'dbconnectionfailed', '<p>Error: Database connection failed</p>\n<p>It is possible that the database is overloaded or otherwise not running properly.</p>\n<p>The site administrator should also check that the database details have been correctly specified in config.php</p>', '<p> Galat: Koneksi basis data gagal </p> <p> Ada kemungkinan basis data kelebihan beban atau sebaliknya tidak berjalan dengan baik. </p> <p> Administrator situs juga harus memeriksa bahwa detail basis data telah ditentukan dengan benar di config.php </p>', NULL, 1785718238, NULL, 0, 0),
	(8223, 'id', 33, 'dbdriverproblem', '<p>Error: database driver problem detected</p>\n<p>The site administrator should verify server configuration</p><p>{$a}</p>', '<p> Galat: masalah pengandar basis data terdeteksi </p> <p> Administrator situs harus memverifikasi konfigurasi server </p> <p> {$a} </p>', NULL, 1785718238, NULL, 0, 0),
	(8224, 'id', 33, 'dbsessionbroken', 'Serious database session problem detected.<br /><br />Please notify server administrator.', 'Masalah sesi basis data yang serius terdeteksi. <br /> <br /> Harap beri tahu administrator server.', NULL, 1785718238, NULL, 0, 0),
	(8225, 'id', 33, 'dbsessionhandlerproblem', 'Setting up of database session failed. Please notify the server administrator.', 'Gagal menyiapkan sesi basis data. Harap beri tahu administrator server.', NULL, 1785718238, NULL, 0, 0),
	(8226, 'id', 33, 'dbsessionmysqlpacketsize', 'A serious session error was detected. Please notify the site administrator. The problem is most probably caused by small value in max_allowed_packet MySQL setting.', 'Kesalahan sesi yang serius terdeteksi. Harap beri tahu administrator situs. Masalahnya kemungkinan besar disebabkan oleh nilai kecil dalam setelan MySQL max_allowed_packet.', NULL, 1785718238, NULL, 0, 0),
