	(8228, 'id', 33, 'ddldependencyerror', '{$a->targettype} "{$a->targetname}" cannot be modified. Dependency found with {$a->offendingtype} "{$a->offendingname}"', '{$a->targettype} "{$a->targetname}" tidak dapat dimodifikasi.\n Ketergantungan ditemukan dengan\n {$a->offendingtype} "{$a->offendingname}"', NULL, 1785718238, NULL, 0, 0),
