	(8508, 'id', 33, 'oauth1accesstoken', 'OAuth 1.0 error: We did not obtain the access token.', 'Galat OAuth 1.0: Kami tidak mendapatkan token akses.', NULL, 1785718238, NULL, 0, 0),
	(8509, 'id', 33, 'oauth1requesttoken', 'OAuth 1.0 error: We did not obtain the request token - the service provider may be temporarily down.', 'Galat OAuth 1.0: Kami tidak mendapatkan token permintaan - penyedia layanan mungkin sedang tidak aktif untuk sementara.', NULL, 1785718238, NULL, 0, 0),
	(8510, 'id', 33, 'oauth2upgradetokenerror', 'Could not upgrade OAuth 2 token. HTTP status for remote endpoint: {$a}', 'Tidak dapat meningkatkan token OAuth 2. Status HTTP untuk titik akhir jarak jauh: {$a}', NULL, 1785718238, NULL, 0, 0),
	(8511, 'id', 33, 'oauth2refreshtokenerror', 'Could not refresh OAuth 2 token. HTTP status for remote endpoint: {$a}', 'Tidak dapat menyegarkan token OAuth 2. Status HTTP untuk titik akhir jarak jauh: {$a}', NULL, 1785718238, NULL, 0, 0),
	(8512, 'id', 33, 'oauth2refreshtokentaskerror', 'Could not refresh OAuth 2 token for one or more issuers. View task output for details.', 'Tidak dapat menyegarkan token OAuth 2 untuk satu atau beberapa penerbit. Lihat keluaran tugas untuk mengetahui detailnya.', NULL, 1785718238, NULL, 0, 0),
	(8513, 'id', 33, 'onlyadmins', 'Only administrators can do that', 'Hanya administrator yang dapat melakukannya', NULL, 1785718238, NULL, 0, 0),
	(8514, 'id', 33, 'onlyeditingteachers', 'Only editing teachers can do that', 'Hanya pengajar yang mengedit yang dapat melakukannya', NULL, 1785718238, NULL, 0, 0),
	(8515, 'id', 33, 'onlyeditown', 'You can only edit your own information', 'Anda hanya dapat mengedit informasi Anda sendiri', NULL, 1785718238, NULL, 0, 0),
	(8516, 'id', 33, 'orderidnotfound', 'Order ID {$a} not found', 'ID pesanan {$a} tidak ditemukan', NULL, 1785718238, NULL, 0, 0),
	(8517, 'id', 33, 'opensslsignerror', 'OpenSSL unable to sign data', 'OpenSSL tidak dapat menandatangani data', NULL, 1785718238, NULL, 0, 0),
	(8518, 'id', 33, 'opensslsealerror', 'OpenSSL unable to seal data', 'OpenSSL tidak dapat menyegel data', NULL, 1785718238, NULL, 0, 0),
	(8519, 'id', 33, 'pagenotexisttitle', '404 Error: File not found', 'GALAT 404: Berkas tidak ditemukan', NULL, 1785718238, NULL, 0, 0),
	(8520, 'id', 33, 'pagenotexist', '<p>An unusual error occurred trying to view a page that does not exist:</p>{$a}', '<p> Galat yang tidak biasa saat mencoba melihat halaman yang tidak ada: </p> {$a}', NULL, 1785718238, NULL, 0, 0),
	(8521, 'id', 33, 'passwordexceeded', 'The password can\'t be more than {$a} characters.', 'Kata sandi tidak boleh lebih dari {$a} karakter.', NULL, 1785718238, NULL, 0, 0),
	(8522, 'id', 33, 'pathdoesnotstartslash', 'No valid arguments supplied, path does not start with slash!', 'Tidak ada argumen valid yang diberikan, jalur tidak dimulai dengan garis miring!', NULL, 1785718238, NULL, 0, 0),
	(8523, 'id', 33, 'pleasereport', 'If you have time, please let us know what you were trying to do when the error occurred:', 'Jika Anda punya waktu, beri tahu kami apa yang Anda coba lakukan saat kesalahan terjadi:', NULL, 1785718238, NULL, 0, 0),
	(8524, 'id', 33, 'pluginnotexist', '{$a} plugin doesn\'t exist', 'Pengaya {$a} tidak ada', NULL, 1785718238, NULL, 0, 0),
	(8525, 'id', 33, 'pluginrequirementsnotmet', 'Plugin "{$a->pluginname}" ({$a->pluginversion}) could not be installed.  It requires a newer version of Moodle (currently you are using {$a->currentmoodle}, you need {$a->requiremoodle}).', 'Pengaya "{$a->pluginname}" ({$a->pluginversion}) tidak dapat dipasang. Ini membutuhkan versi Moodle yang lebih baru (saat ini Anda menggunakan {$a->currentmoodle}, Anda memerlukan {$a->requiremoodle}).', NULL, 1785718238, NULL, 0, 0),
	(8526, 'id', 33, 'pluginunsupported', 'Plugin "{$a->pluginname}" {$a->pluginversion} does not support this version of Moodle {$a->moodleversion}. Seek plugin information to find supported versions.', 'Pengaya "{$a->pluginname}" {$a->pluginversion} tidak mendukung versi Moodle ini {$a->moodleversion}. Cari informasi pengaya untuk menemukan versi yang didukung.', NULL, 1785718238, NULL, 0, 0),
	(8527, 'id', 33, 'prefixcannotbeempty', '<p>Error: database table prefix cannot be empty ({$a})</p>\n<p>The site administrator must fix this problem.</p>', '<p> GALAT: prefiks tabel basis data tidak boleh kosong ({$a}) </p> <p> Administrator situs harus memperbaiki masalah ini. </p>', NULL, 1785718238, NULL, 0, 0),
	(8528, 'id', 33, 'privatefilesupload', 'Uploading directly to user private files area is no longer supported. Upload to a draft area and then move the files with core_user::add_user_private_files', 'Mengunggah langsung ke area berkas pribadi pengguna tidak lagi didukung. Unggah ke area draf dan kemudian pindahkan berkas dengan\ncore_user::add_user_private_files', NULL, 1785718238, NULL, 0, 0),
	(8529, 'id', 33, 'processingstops', 'Processing stops here. Remaining records ignored.', 'Pemrosesan berhenti di sini. Rekaman yang tersisa diabaikan.', NULL, 1785718238, NULL, 0, 0),
	(8530, 'id', 33, 'querystringcannotbeempty', 'The query string cannot be empty.', 'String kueri tidak boleh kosong.', NULL, 1785718238, NULL, 0, 0),
	(8531, 'id', 33, 'redirecterrordetected', 'Unsupported redirect detected, script execution terminated', 'Pengalihan yang tidak didukung terdeteksi, eksekusi skrip dihentikan', NULL, 1785718238, NULL, 0, 0),
	(8532, 'id', 33, 'redissessionhandlerproblem', 'Setting up of redis session failed. Please notify the server administrator.', 'Penyiapan sesi redis gagal. Harap beri tahu administrator server.', NULL, 1785718238, NULL, 0, 0),
	(8533, 'id', 33, 'refoundto', 'Can be refunded to {$a}', 'Dapat dikembalikan ke {$a}', NULL, 1785718238, NULL, 0, 0),
	(8534, 'id', 33, 'refoundtoorigi', 'Refunded to original amount: {$a}', 'Dikembalikan ke jumlah awal: {$a}', NULL, 1785718238, NULL, 0, 0),
	(8535, 'id', 33, 'registrationdisabled', 'Registration is disabled on this site', 'Pendaftaran dinonaktifkan di situs ini', NULL, 1785718238, NULL, 0, 0),
	(8536, 'id', 33, 'remotedownloaderror', '<p>The download of the component to your server failed. Please verify proxy settings; the PHP cURL extension is highly recommended.</p>\n<p>You must download the <a href="{$a->url}">{$a->url}</a> file manually, copy it to "{$a->dest}" in your server and unzip it there.</p>', '<p> Pengunduhan komponen ke server Anda gagal. Harap verifikasi setelan proksi; ekstensi PHP cURL sangat direkomendasikan. </p> <p> Anda harus mengunduh berkas <a href="{$a->url} ">{$a->url} </a> secara manual, menyalinnya ke"{$a->dest} "di server Anda dan uraikan di sana. </p>', NULL, 1785718238, NULL, 0, 0),
	(8537, 'id', 33, 'remotedownloadnotallowed', 'Download of components to your server isn\'t allowed (allow_url_fopen is disabled).<br /><br />You must download the <a href="{$a->url}">{$a->url}</a> file manually, copy it to "{$a->dest}" in your server and unzip it there.', 'Pengunduhan komponen ke server Anda tidak diperbolehkan (allow_url_fopen dinonaktifkan). <br /> <br /> Anda harus mengunduh <a href="{$a->url} "> {$a->url} < / a> file secara manual, salin ke "{$a->dest}" di server Anda dan uraikan di sana.', NULL, 1785718238, NULL, 0, 0),
	(8538, 'id', 33, 'reportnotavailable', 'This type of report is only available for the site course', 'Jenis laporan ini hanya tersedia untuk situs kursus', NULL, 1785718238, NULL, 0, 0),
	(8539, 'id', 33, 'requirecorrectaccess', 'Invalid url or port.', 'URL atau porta tidak valid.', NULL, 1785718238, NULL, 0, 0),
	(8540, 'id', 33, 'requireloginerror', 'Course or activity not accessible.', 'kursus atau aktivitas tidak dapat diakses.', NULL, 1785718238, NULL, 0, 0),
	(8541, 'id', 33, 'restorechecksumfailed', 'Some problem happened with the restore information stored in your session. Please check your PHP memory/DB package size limits. Restore stopped.', 'Beberapa masalah terjadi dengan informasi pemulihan yang disimpan dalam sesi Anda. Harap periksa batas ukuran paket memori / DB Anda. Pemulihan dihentikan.', NULL, 1785718238, NULL, 0, 0),
	(8542, 'id', 33, 'restore_path_element_missingmethod', 'Restore method {$a} is missing. It must be defined by a developer.', 'Metode pemulihan {$a} hilang. Ini harus ditentukan oleh pengembang.', NULL, 1785718238, NULL, 0, 0),
	(8543, 'id', 33, 'restore_path_element_noobject', 'Restore object {$a} is not an object.', 'Pulihkan objek {$a} bukan objek.', NULL, 1785718238, NULL, 0, 0),
	(8544, 'id', 33, 'restrictedcontextexception', 'Sorry, execution of external function violates context restriction.', 'Maaf, pelaksanaan fungsi eksternal melanggar batasan konteks.', NULL, 1785718238, NULL, 0, 0),
	(8545, 'id', 33, 'restricteduser', 'Sorry, but your current account "{$a}" is restricted from doing that', 'Maaf, tapi akun Anda saat ini "{$a}" dilarang melakukannya', NULL, 1785718238, NULL, 0, 0),
	(8546, 'id', 33, 'reverseproxyabused', 'Reverse proxy enabled so the server cannot be accessed directly.<br />Please contact the server administrator.', 'Proksi terbalik diaktifkan, server tidak dapat diakses secara langsung, maaf. <br /> Harap hubungi administrator server.', NULL, 1785718238, NULL, 0, 0),
	(8547, 'id', 33, 'rpcerror', 'Ooops! Your MNET communication has failed! Here\'s that error message to pass on to your administrator: {$a}', 'Ups! Komunikasi MNET Anda gagal! Berikut pesan kesalahan untuk diteruskan ke administrator Anda: {$a}', NULL, 1785718238, NULL, 0, 0),
	(8548, 'id', 33, 'secretalreadyused', 'Change password confirmation link was already used, password was not changed', 'Tautan konfirmasi perubahan kata sandi sudah digunakan, kata sandi tidak diubah', NULL, 1785718238, NULL, 0, 0),
	(8549, 'id', 33, 'sectioncantbefound', '<p><strong>This content can\'t be found.</strong></p><p>It may have been deleted, or the URL may be incorrect.</p>', '<p><strong>Konten ini tidak dapat ditemukan</strong></p><p>Mungkin telah dihapus, atau URL-nya mungkin salah.</p>', NULL, 1785718238, NULL, 0, 0),
	(8550, 'id', 33, 'sectionnotexist', 'This section does not exist', 'Bagian ini tidak ada', NULL, 1785718238, NULL, 0, 0),
	(8551, 'id', 33, 'sendmessage', 'Send message', 'Kirim pesan', NULL, 1785718238, NULL, 0, 0),
	(8552, 'id', 33, 'sendmessagesent', 'Thanks for your feedback about:<br>{$a}', 'Terima kasih atas umpan balik Anda tentang: <br> {$a}', NULL, 1785718238, NULL, 0, 0),
	(8553, 'id', 33, 'serverconnection', 'Error connecting to the server', 'Gagal tersambung ke server', NULL, 1785718238, NULL, 0, 0),
	(8554, 'id', 33, 'servicedonotexist', 'The service does not exist', 'Layanan tidak ada', NULL, 1785718238, NULL, 0, 0),
	(8555, 'id', 33, 'sessionwaiterr', 'Timed out while waiting for session lock.<br />Wait for your current requests to finish and try again later.', 'Waktu habis saat menunggu kunci sesi. <br /> Tunggu permintaan Anda saat ini selesai dan coba lagi nanti.', NULL, 1785718238, NULL, 0, 0),
	(8556, 'id', 33, 'sessionexpired', 'Session expired', 'Sesi berakhir', NULL, 1785718238, NULL, 0, 0),
	(8557, 'id', 33, 'sessioncookiesdisable', 'Incorrect use of require_key_login() - session cookies must be disabled!', 'Penggunaan yang salah dari require_key_login() - kuki sesi harus dinonaktifkan!', NULL, 1785718238, NULL, 0, 0),
	(8558, 'id', 33, 'sessiondiskfull', 'The session partition is full. It is not possible to log in at this time. Please notify the server administrator.', 'Partisi sesi penuh. Tidak mungkin untuk masuk saat ini. Harap beri tahu administrator server.', NULL, 1785718238, NULL, 0, 0),
	(8559, 'id', 33, 'sessionhandlerproblem', 'Session handler is misconfigured', 'Penangan sesi salah dikonfigurasi', NULL, 1785718238, NULL, 0, 0),
	(8560, 'id', 33, 'sessionerroruser', 'Your session has timed out. Please log in again.', 'Sesi Anda telah habis. Silakan masuk lagi.', NULL, 1785718238, NULL, 0, 0),
	(8561, 'id', 33, 'sessionerroruser2', 'A server error that affects your login session was detected. Please log in again or restart your browser.', 'Kesalahan server yang mempengaruhi sesi masuk Anda terdeteksi. Silakan masuk lagi atau mulai ulang peramban Anda.', NULL, 1785718238, NULL, 0, 0),
	(8562, 'id', 33, 'sessionipnomatch', 'Sorry, but your IP number seems to have changed from when you first logged in.  This security feature prevents crackers stealing your identity while logged in to this site.  Normal users should not be seeing this message - please ask the site administrator for help.', 'Maaf, tetapi nomor IP Anda sepertinya telah berubah dari saat Anda pertama kali masuk. Fitur keamanan ini mencegah peretas jahat mencuri identitas Anda saat masuk ke situs ini. Pengguna biasa seharusnya tidak melihat pesan ini - silakan minta bantuan administrator situs.', NULL, 1785718238, NULL, 0, 0),
	(8563, 'id', 33, 'sessionipnomatch2', '<p>Sorry, but your IP number seems to have changed from when you first logged in. This security feature prevents crackers stealing your identity while logged in to this site. You may see this error if you use wireless networks or if you are roaming between different networks. Please ask the site administrator for more help.</p>\n<p>If you want to continue please press F5 key to refresh this page.</p>', '<p> Maaf, tetapi nomor IP Anda tampaknya telah berubah dari saat Anda pertama kali masuk. Fitur keamanan ini mencegah peretas jahat mencuri identitas Anda saat masuk ke situs ini. Anda mungkin melihat kesalahan ini jika Anda menggunakan jaringan nirkabel atau jika Anda roaming di antara jaringan yang berbeda. Silakan tanyakan kepada administrator situs untuk bantuan lebih lanjut. </p> <p> Jika Anda ingin melanjutkan, tekan tombol F5 untuk menyegarkan halaman ini. </p>', NULL, 1785718238, NULL, 0, 0),
	(8564, 'id', 33, 'sessioncannotobtainlock', '<p>Unable to obtain lock for session id {$a->id} within {$a->acquiretimeout}.</p>\n<p>It is likely that another page ({$a->whohaslock}) is still running in another browser tab, or it did not release the lock due to an error.</p>\n<p>You can wait until the session lock timeout ({$a->lockexpire}) or you can restart your browser session. If this error persists, please notify the server administrator.</p>', '<p>Tidak dapat memperoleh kunci untuk id sesi {$a->id} dalam {$a->acquiretimeout}.</p> <p>Kemungkinan halaman lain ({$a->whohaslock}) masih berjalan di tab peramban lain, atau tidak membuka kunci karena kesalahan.</p> <p>Anda dapat menunggu hingga batas waktu penguncian sesi ({$a->lockexpire}) atau Anda dapat memulai kembali sesi peramban Anda. Jika kesalahan ini berlanjut, harap beri tahu administrator server.</p>', NULL, 1785718238, NULL, 0, 0),
	(8565, 'id', 33, 'sessionstarterror', 'Couldn\'t start session. Please try again later.', 'Sesi tidak dapat dimulai. Silakan coba lagi nanti.', NULL, 1785718238, NULL, 0, 0),
	(8566, 'id', 33, 'shortnametaken', 'Short name is already used for another course ({$a})', 'Nama singkat sudah digunakan untuk kursus lain ({$a})', NULL, 1785718238, NULL, 0, 0),
	(8567, 'id', 33, 'sitepolicynotagreed', 'Site policy not agreed: <a href="{$a}">Click here to open the site policy.</a>', 'Kebijakan situs tidak disetujui: <a href="{$a}"> Klik di sini untuk membuka kebijakan situs. </a>', NULL, 1785718238, NULL, 0, 0),
	(8568, 'id', 33, 'scheduledbackupsdisabled', 'Scheduled backups have been disabled by the server admin', 'Pencadangan terjadwal telah dinonaktifkan oleh admin server', NULL, 1785718238, NULL, 0, 0),
	(8569, 'id', 33, 'socksnotsupported', 'SOCKS5 proxy is not supported in PHP4', 'Proksi SOCKS5 tidak didukung di PHP4', NULL, 1785718238, NULL, 0, 0),
	(8570, 'id', 33, 'spellcheckernotconf', 'Spellchecker not configured', 'Pemeriksa ejaan tidak dikonfigurasi', NULL, 1785718238, NULL, 0, 0),
	(8571, 'id', 33, 'sslonlyaccess', 'For security reasons only https connections are allowed, sorry.', 'Untuk alasan keamanan, hanya koneksi https yang diperbolehkan, maaf.', NULL, 1785718238, NULL, 0, 0),
	(8572, 'id', 33, 'statscatchupmode', 'Statistics is currently in catchup mode. So far {$a->daysdone} day(s) have been processed and {$a->dayspending} are pending. Check back soon!', 'Statistik saat ini dalam mode mengejar ketinggalan. Sejauh ini {$a->daysdone} hari telah diproses dan {$a->dayspending} sedang menunggu keputusan. Periksa kembali nanti!', NULL, 1785718238, NULL, 0, 0),
	(8573, 'id', 33, 'statsdisable', 'Statistics are not enabled.', 'Statistik belum diaktifkan.', NULL, 1785718238, NULL, 0, 0),
	(8574, 'id', 33, 'statsnodata', 'There is no available data for that combination of course and time period', 'Tidak ada data yang tersedia untuk kombinasi kursus dan periode waktu tersebut', NULL, 1785718238, NULL, 0, 0),
	(8575, 'id', 33, 'storedfilecannotcreatefile', 'Cannot create local file pool file. Please verify permissions in dataroot and available disk space.', 'Tidak dapat membuat berkas kumpulan berkas lokal, harap verifikasi izin di dataroot dan ruang diska yang tersedia.', NULL, 1785718238, NULL, 0, 0),
	(8576, 'id', 33, 'storedfilecannotcreatefiledirs', 'Cannot create local file pool directories. Please verify permissions in dataroot.', 'Tidak dapat membuat direktori kumpulan berkas lokal, harap verifikasi izin di dataroot.', NULL, 1785718238, NULL, 0, 0),
	(8577, 'id', 33, 'storedfilecannotread', 'Cannot read file. Either the file does not exist or there is a permission problem.', 'Tidak dapat membaca berkas. Mungkin berkas tidak ada atau ada masalah izin.', NULL, 1785718238, NULL, 0, 0),
	(8578, 'id', 33, 'storedfilecannotreadfile', 'Cannot read file \'{$a}\'. Either the file does not exist or there is a permission problem.', 'Tidak dapat membaca berkas \'{$a}\'. Mungkin berkas tidak ada atau ada masalah izin.', NULL, 1785718238, NULL, 0, 0),
	(8579, 'id', 33, 'storedfilenotcreated', 'Cannot create file {$a->contextid}/{$a->component}/{$a->filearea}/{$a->itemid}{$a->filepath}{$a->filename}', 'Tidak dapat membuat berkas "{$a->contextid} / {$a->component}/{$a->filearea}/{$a->itemid}{$a->filepath}{$a->filename}"', NULL, 1785718238, NULL, 0, 0),
	(8580, 'id', 33, 'storedfileproblem', 'Unknown exception related to local files ({$a})', 'Pengecualian tidak diketahui terkait dengan berkas lokal ({$a})', NULL, 1785718238, NULL, 0, 0),
	(8581, 'id', 33, 'tagdisabled', 'Tags are disabled!', 'Tag dinonaktifkan!', NULL, 1785718238, NULL, 0, 0),
	(8582, 'id', 33, 'tagnotfound', 'The specified tag was not found in the database', 'Tag yang ditentukan tidak ditemukan dalam basis data', NULL, 1785718238, NULL, 0, 0),
	(8583, 'id', 33, 'targetdatabasenotempty', 'The target database is not empty. Transfer aborted for safety reasons.', 'Basis data target tidak kosong. Transfer dibatalkan untuk alasan keamanan.', NULL, 1785718238, NULL, 0, 0),
	(8584, 'id', 33, 'textconditionsnotallowed', 'Comparisons of text column conditions are not allowed. Please use sql_compare_text() in your query.', 'Perbandingan kondisi kolom teks tidak diperbolehkan. Harap gunakan sql_compare_text() dalam kueri Anda.', NULL, 1785718238, NULL, 0, 0),
	(8585, 'id', 33, 'themenotinstall', 'This theme is not installed!', 'Tema ini belum dipasang!', NULL, 1785718238, NULL, 0, 0),
	(8586, 'id', 33, 'TODO', 'TODO', 'TODO', NULL, 1785718238, NULL, 0, 0),
	(8587, 'id', 33, 'tokengenerationfailed', 'Cannot generate a new token.', 'Tidak dapat membuat token baru.', NULL, 1785718238, NULL, 0, 0),
	(8588, 'id', 33, 'transactionvoid', 'Transaction cannot be voided because it has already been voided', 'Transaksi tidak dapat dibatalkan karena telah dibatalkan', NULL, 1785718238, NULL, 0, 0),
	(8589, 'id', 33, 'unenrolerror', 'An error occurred while trying to unenrol that person', 'Galat saat mencoba membatalkan pendaftaran orang itu', NULL, 1785718238, NULL, 0, 0),
	(8590, 'id', 33, 'unicodeupgradeerror', 'Sorry, but your database is not already in Unicode, and this version of Moodle is not able to migrate your database to Unicode.  Please upgrade to Moodle 1.7.x first and perform the Unicode migration from the Admin page.  After that is done you should be able to migrate to Moodle {$a}', 'Maaf, basis data Anda belum ada di Unicode, dan versi Moodle ini tidak dapat memindahkan basis data Anda ke Unicode. Harap tingkatkan ke Moodle 1.7.x terlebih dahulu dan lakukan migrasi Unicode dari halaman Admin. Setelah itu selesai, Anda seharusnya bisa bermigrasi ke Moodle {$a}', NULL, 1785718238, NULL, 0, 0),
	(8591, 'id', 33, 'unknowaction', 'Unknown action!', 'Tindakan tidak diketahui!', NULL, 1785718238, NULL, 0, 0),
	(8592, 'id', 33, 'unknowcategory', 'Category not known!', 'Kategori tidak diketahui!', NULL, 1785718238, NULL, 0, 0),
	(8593, 'id', 33, 'unknowcontext', 'This is an unknown context ({$a}) in get_child_contexts!', 'Ini adalah konteks yang tidak diketahui ({$a}) di get_child_contexts!', NULL, 1785718238, NULL, 0, 0),
	(8594, 'id', 33, 'unknowformat', 'Format not known ({$a})', 'Format tidak diketahui ({$a})', NULL, 1785718238, NULL, 0, 0),
	(8595, 'id', 33, 'unknownbackupexporterror', 'Unknown error preparing information for import', 'Galat yang tidak diketahui saat menyiapkan informasi untuk diimpor', NULL, 1785718238, NULL, 0, 0),
	(8596, 'id', 33, 'unknownblockregion', 'The block region \'{$a}\' is not recognised on this page.', 'Wilayah blok \'{$a}\' tidak dikenali di halaman ini.', NULL, 1785718238, NULL, 0, 0),
	(8597, 'id', 33, 'unknowncategory', 'Unknown category with category ID number "{$a}"', 'Kategori tidak dikenal dengan nomor kategori ID "{$a}"', NULL, 1785718238, NULL, 0, 0),
	(8598, 'id', 33, 'unknowncontext', 'This is an unknown context.', 'Ini adalah konteks yang tidak diketahui.', NULL, 1785718238, NULL, 0, 0),
	(8599, 'id', 33, 'unknowncourse', 'Unknown course named "{$a}"', 'Nama kursus "{$a}" tidak diketahui', NULL, 1785718238, NULL, 0, 0),
	(8600, 'id', 33, 'unknowncourseidnumber', 'Unknown course ID "{$a}"', 'ID kursus "{$a}" tidak diketahui', NULL, 1785718238, NULL, 0, 0),
	(8601, 'id', 33, 'unknowncoursesection', 'Unknown course section in course "{$a}"', 'Topik kursus tidak diketahui pada kursus "{$a}"', NULL, 1785718238, NULL, 0, 0),
