	(8920, 'id', 41, 'allusers', 'All users', 'Semua pengguna', NULL, 1785718239, NULL, 0, 0),
	(8921, 'id', 41, 'autosort', 'Auto-sort', 'Urutkan otomatis', NULL, 1785718239, NULL, 0, 0),
	(8922, 'id', 41, 'availableidnumbers', 'Available ID numbers', 'Nomor ID yang tersedia', NULL, 1785718239, NULL, 0, 0),
	(8923, 'id', 41, 'average', 'Average', 'Rata-rata', NULL, 1785718239, NULL, 0, 0),
	(8924, 'id', 41, 'averagesdecimalpoints', 'Decimals in column averages', 'Desimal pada kolom rata-rata', NULL, 1785718239, NULL, 0, 0),
	(8925, 'id', 41, 'averagesdecimalpoints_help', 'This setting determines the number of decimal places to display for each average or whether the overall decimal places setting for the category or grade item is used (inherit).', 'Setelan ini menentukan jumlah desimal yang ditampilkan untuk setiap rata-rata atau mengetahui apakah setelan keseluruhan mengenai desimal untuk kategori atau item nilai telah digunakan atau belum (turunan).', NULL, 1785718239, NULL, 0, 0),
	(8926, 'id', 41, 'averagesdisplaytype', 'Column averages display type', 'Tipe tampilan kolom rata-rata', NULL, 1785718239, NULL, 0, 0),
	(8927, 'id', 41, 'averagesdisplaytype_help', 'This setting determines whether the average (mean) is displayed as real grades, percentages or letters, or whether the display type for the category or grade item is used (inherit).', 'Setelan ini menentukan apakah rata-rata ditampilkan sebagai nilai riil, persentase atau huruf, atau untuk mengetahui apakah tipe tampilan untuk kategori atau item nilai telah digunakan atau belum (turunan).', NULL, 1785718239, NULL, 0, 0),
	(8928, 'id', 41, 'backupwithoutgradebook', 'Backup does not contain gradebook configuration', 'Tidak terdapat setelan buku nilai pada cadangan', NULL, 1785718239, NULL, 0, 0),
	(8929, 'id', 41, 'badgrade', 'Supplied grade is invalid', 'Nilai yang dimasukkan tidak benar', NULL, 1785718239, NULL, 0, 0),
	(8930, 'id', 41, 'badlyformattedscale', 'Please enter a comma-separated list of values (at least two values required).', 'Silakan masukkan daftar bilangan yang dipisahkan dengan koma (setidaknya diperlukan dua bilangan).', NULL, 1785718239, NULL, 0, 0),
	(8931, 'id', 41, 'baduser', 'Supplied user is invalid', 'Pengguna yang dimasukkan tidak benar', NULL, 1785718239, NULL, 0, 0),
	(8932, 'id', 41, 'bonuspoints', 'Bonus points', 'Poin bonus', NULL, 1785718239, NULL, 0, 0),
	(8933, 'id', 41, 'bulkcheckboxes', 'Bulk checkboxes', 'Kotak pilihan massal', NULL, 1785718239, NULL, 0, 0),
	(8934, 'id', 41, 'calculatedgrade', 'Calculated grade', 'Nilai terhitung', NULL, 1785718239, NULL, 0, 0),
	(8935, 'id', 41, 'calculation', 'Calculation', 'Penghitungan', NULL, 1785718239, NULL, 0, 0),
	(8936, 'id', 41, 'calculation_help', 'A grade calculation is a formula used to determine grades. The formula should start with an equal (=) sign and may use common mathematical operators, such as max, min and sum. If desired, other grade items may be included in the calculation by typing the ID numbers in double square brackets.', 'Penghitungan nilai adalah rumus yang digunakan untuk mementukan nilai. Rumus harus dimulai dengan tanda sama dengan (=) dan kemudian menggunakan tanda-tanda matematis umum, seperti max, min dan sum. Apabila diinginkan, item nilai lainnya dapat dimasukkan kedalam penghitungan dengan mengetikkan nomor-nomor ID nya dalam kurung siku lapis dua.', NULL, 1785718239, NULL, 0, 0),
	(8937, 'id', 41, 'calculation_link', 'grade/calculation', 'nilai/penghitungan', NULL, 1785718239, NULL, 0, 0),
