	(8981, 'id', 41, 'disablegradehistory', 'Disable grade history', 'Nonaktifkan riwayat penilaian', NULL, 1785718239, NULL, 0, 0),
	(8982, 'id', 41, 'disablegradehistory_help', 'Disable history tracking of changes in grades related tables. This may speed up the server a little and conserve space in database.', 'Nonaktifkan pelacakan riwayat perubahan pada tabel yang berhubungan dengan nilai. Hal ini mungkin dapat sedikit mempercepat server dan menghemat ruang pada basis data.', NULL, 1785718239, NULL, 0, 0),
