	(8987, 'id', 41, 'droplow', 'Drop the lowest', 'Drop yang terendah', NULL, 1785718239, NULL, 0, 0),
	(8988, 'id', 41, 'droplow_help', 'This setting enables a specified number of the lowest grades to be excluded from the aggregation.', 'Setelan ini memungkinkan sejumlah nilai terendah yang ditentukan untuk dikecualikan dari agregasi.', NULL, 1785718239, NULL, 0, 0),
	(8989, 'id', 41, 'droplowestvalue', 'Set drop lowest grade value', 'Atur drop bilangan nilai yang terendah', NULL, 1785718239, NULL, 0, 0),
	(8990, 'id', 41, 'dropped', 'Dropped', 'Di-drop', NULL, 1785718239, NULL, 0, 0),
