	(9111, 'id', 41, 'gradeexportdecimalpoints', 'Grade export decimal places', 'Digit desimal ekspor nilai', NULL, 1785718239, NULL, 0, 0),
	(9112, 'id', 41, 'gradeexportdecimalpoints_desc', 'The number of decimal places to display for export. This can be overridden during export.', 'Jumlah digit desimal yang ditampilkan untuk ekspor. Dapat ditimpa ketika ekspor.', NULL, 1785718239, NULL, 0, 0),
	(9113, 'id', 41, 'gradeexportdisplaytype', 'Grade export display type', 'Tipe tampilan ekspor nilai', NULL, 1785718239, NULL, 0, 0),
	(9114, 'id', 41, 'gradeexportdisplaytype_desc', 'Grades can be shown as real grades, as percentages (in reference to the minimum and maximum grades) or as letters (A, B, C etc..) during export. This can be overridden during export.', 'Nilai dapat ditampilkan sebagai nilai riil, persentase (dengan merujuk pada nilai minimum dan maksimum) atau nilai huruf (A, B, C dll. . .) ketika ekspor. Dapat ditimpa saat ekspor.', NULL, 1785718239, NULL, 0, 0),
	(9115, 'id', 41, 'gradeexportdisplaytypes', 'Grade export display types', 'Tipe tampilan ekspor nilai', NULL, 1785718239, NULL, 0, 0),
