	(9136, 'id', 41, 'gradeletter', 'Grade letter', 'Huruf Nilai', NULL, 1785718239, NULL, 0, 0),
	(9137, 'id', 41, 'gradeletter_help', 'Grade letters are letters, A, B, C, ..., or words, for example Distinction, Merit, Pass, ..., used to represent a range of grades.', 'Huruf nilai adalah huruf, A, B, C, ..., atau kata-kata seperti Luar Biasa, Sempurna, Lulus, ..., yang digunakan untuk merepresentasikan rentang nilai.', NULL, 1785718239, NULL, 0, 0),
	(9138, 'id', 41, 'gradeletternote', 'To delete a grade letter just empty any of the<br /> three text areas for that letter and click submit.', 'Untuk menghapus huruf nilai, kosongkan tiga area teks untuk huruf tersebut dan tekan "kirim"', NULL, 1785718239, NULL, 0, 0),
