	(9258, 'id', 41, 'itemsedit', 'Edit grade item', 'Edit item penilaian', NULL, 1785718239, NULL, 0, 0),
	(9259, 'id', 41, 'keephigh', 'Keep the highest', 'Simpan yang tertinggi', NULL, 1785718239, NULL, 0, 0),
	(9260, 'id', 41, 'keephighestvalues', 'Keep the {$a} highest values', 'Simpan {$a} bilangan tertinggi', NULL, 1785718239, NULL, 0, 0),
	(9261, 'id', 41, 'keephigh_help', 'If set, this option will only keep the X highest grades, X being the selected value for this option.', 'Apabila diaktifkan, opsi ini hanya akan menyimpan X nilai tertinggi, dengan X adalah bilangan yang dipilih pada opsi ini.', NULL, 1785718239, NULL, 0, 0),
	(9262, 'id', 41, 'keymanager', 'Key manager', 'Manajer kunci', NULL, 1785718239, NULL, 0, 0),
	(9263, 'id', 41, 'lessthanmin', 'The grade entered for {$a->itemname} for {$a->username} is less than the minimum allowed', 'Nilai yang dimasukkan pada {$a->itemname} untuk {$a->username} di bawah bilangan minimum yang ditetapkan', NULL, 1785718239, NULL, 0, 0),
	(9264, 'id', 41, 'letter', 'Letter', 'Huruf', NULL, 1785718239, NULL, 0, 0),
	(9265, 'id', 41, 'lettergrade', 'Letter grade', 'Nilai huruf', NULL, 1785718239, NULL, 0, 0),
	(9266, 'id', 41, 'lettergradenonnumber', 'Low and/or High grade were non-numeric for', 'Nilai rendah dan/atau tinggi bukan numerik', NULL, 1785718239, NULL, 0, 0),
	(9267, 'id', 41, 'letterpercentage', 'Letter (percentage)', 'Huruf (persentase)', NULL, 1785718239, NULL, 0, 0),
	(9268, 'id', 41, 'letterreal', 'Letter (real)', 'Huruf (riil)', NULL, 1785718239, NULL, 0, 0),
	(9269, 'id', 41, 'letters', 'Letters', 'Nilai Huruf', NULL, 1785718239, NULL, 0, 0),
	(9270, 'id', 41, 'linkedactivity', 'Linked activity', 'Aktivitas tertaut', NULL, 1785718239, NULL, 0, 0),
	(9271, 'id', 41, 'linkedactivity_help', 'This setting specifies an activity to which this outcome item is linked. This may be used to measure student performance on criteria not assessed by the activity grade.', 'Setelan ini menentukan aktivitas yang ditautkan ke item capaian ini. Ini dapat digunakan untuk mengukur kinerja siswa pada kriteria yang tidak dinilai oleh penilaian aktivitas.', NULL, 1785718239, NULL, 0, 0),
	(9272, 'id', 41, 'linktoactivity', '{$a->name} activity {$a->title}', 'Aktivitas {$a->name} {$a->title}', NULL, 1785718239, NULL, 0, 0),
	(9273, 'id', 41, 'lock', 'Lock', 'Kunci', NULL, 1785718239, NULL, 0, 0),
