	(9284, 'id', 41, 'mapfrom_help', 'Select the column in the spreadsheet containing data for identifying the user, such as username, user ID or email address.', 'Pilih kolom pada lembar kerja yang berisikan data untuk mengidentifikasi pengguna, seperti nama pengguna, ID pengguna atau alamat surel.', NULL, 1785718239, NULL, 0, 0),
	(9285, 'id', 41, 'mappings', 'Grade item mappings', 'Pemetaan item penilaian', NULL, 1785718239, NULL, 0, 0),
	(9286, 'id', 41, 'mappings_help', 'For each column of grades in the spreadsheet, select the corresponding grade item to import the grades into.', 'Pilih item nilai yang cocok untuk mengimpor nilai ke dalamnya untuk setiap kolom pada lembar kerja.', NULL, 1785718239, NULL, 0, 0),
	(9287, 'id', 41, 'mapto', 'Map to', 'Petakan ke', NULL, 1785718239, NULL, 0, 0),
	(9288, 'id', 41, 'mapto_help', 'Select the same identifying data as selected for \'Map from\'.', 'Pilih data pengindentifikasi yang sama dengan yang dipilih untuk \'Petakan dari\'.', NULL, 1785718239, NULL, 0, 0),
	(9289, 'id', 41, 'max', 'Highest', 'Tertinggi', NULL, 1785718239, NULL, 0, 0),
