	(9362, 'id', 41, 'nonunhideableverbose', 'To unhide this grade, you need to unhide {$a->itemname}.', 'Untuk memperlihatkan nilai ini, Anda perlu memperlihatkan {$a->itemname}.', NULL, 1785718239, NULL, 0, 0),
