	(9579, 'id', 41, 'showrank_help', 'Whether to show the position of the student in relation to the rest of the class for each grade item.', 'Apakah akan menunjukkan posisi siswa dalam kaitannya dengan kelas lainnya untuk setiap item nilai.', NULL, 1785718239, NULL, 0, 0),
	(9580, 'id', 41, 'showuserimage', 'Show user profile images', 'Tampilkan gambar profil pengguna', NULL, 1785718239, NULL, 0, 0),
