	(9633, 'id', 41, 'userfields_show_help', 'Show additional user fields like email address on the grader report. The specific fields displayed are controlled by the site setting showuseridentity', 'Tampilkan bidang pengguna tambahan seperti alamat surel pada laporan penilai. Bidang yang ditampilkan dikontrol oleh setelan situs howuseridentity', NULL, 1785718240, NULL, 0, 0),
	(9634, 'id', 41, 'usergrade', 'User {$a->fullname} ({$a->useridnumber}) on item {$a->gradeidnumber}', 'Pengguna {$a->fullname} ({$a->useridnumber}) pada item {$a->gradeidnumber}', NULL, 1785718240, NULL, 0, 0),
