	(9731, 'id', 42, 'privacy:metadata:grading_definitions:timemodified', 'The time when the grading definition was last modified.', 'Waktu saat definisi penilaian terakhir diubah.', NULL, 1785718240, NULL, 0, 0),
	(9732, 'id', 42, 'privacy:metadata:grading_definitions:usercreated', 'The ID of the user who created the grading definition.', 'ID pengguna yang membuat definisi penilaian.', NULL, 1785718240, NULL, 0, 0),
	(9733, 'id', 42, 'privacy:metadata:grading_definitions:usermodified', 'The ID of the user who last modified the grading definition.', 'ID pengguna yang terakhir mengubah definisi penilaian.', NULL, 1785718240, NULL, 0, 0),
	(9734, 'id', 42, 'privacy:metadata:grading_instances', 'Assessment record for one gradable item assessed by one rater.', 'Rekaman penilaian untuk satu item yang dapat dinilai, dinilai oleh satu penilai.', NULL, 1785718240, NULL, 0, 0),
	(9735, 'id', 42, 'privacy:metadata:grading_instances:feedback', 'The feedback given by the user.', 'Umpan balik yang diberikan oleh pengguna.', NULL, 1785718240, NULL, 0, 0),
