	(9803, 'id', 43, 'erroraddtogroup', 'Invalid value for addtogroup. It should be 0 for no group mode or 1 for a new group to be created.', 'Nilai tidak valid untuk tambahkan ke grup. Nilainya harusnya 0 untuk tidak ada mode grup atau 1 untuk grup baru yang akan dibuat.', NULL, 1785718240, NULL, 0, 0),
