	(10067, 'id', 44, 'invalidlanguagefile2', 'Invalid language file {$a->%languageFile} has been included in the library {$a->%name}', 'File bahasa yang tidak valid {$a->%languageFile} telah disertakan di perpustakaan {$a->%name}', NULL, 1785718240, NULL, 0, 0),
