	(10069, 'id', 44, 'invalidlibrarydataboolean', 'Invalid data provided for {$a->%property} in {$a->%library}. Boolean expected.', 'Data tidak valid diberikan untuk {$a->%property} di {$a->%library}. Boolean diharapkan.', NULL, 1785718240, NULL, 0, 0),
