	(10079, 'id', 44, 'invalidsemanticstype', 'H5P internal error: unknown content type "{$a->@type}" in semantics. Removing content!', 'Kesalahan internal H5P: jenis konten tidak dikenal "{$a->@type}" dalam semantik. Menghapus konten!', NULL, 1785718240, NULL, 0, 0),
	(10080, 'id', 44, 'invalidstring', 'Provided string is not valid according to regexp in semantics. (value: "{$a->%value}", regexp: "{$a->%regexp}")', 'String yang diberikan tidak valid menurut regexp dalam semantik. (nilai: "{$a->%nilai}", regexp: "{$a->%regexp}")', NULL, 1785718240, NULL, 0, 0),
