	(10118, 'id', 44, 'missingcoreversion', 'The system was unable to install the {$a->%component} component from the package, as it requires a newer version of the H5P plugin. This site is currently running version {$a->%current}, whereas the required version is {$a->%required} or higher. Please upgrade and then try again.', 'Sistem tidak dapat menginstal komponen {$a->%component} dari paket, karena memerlukan versi server H5P yang lebih baru. Situs ini saat ini menjalankan versi {$a->%current}, sedangkan versi yang diperlukan adalah {$a->%required} atau lebih tinggi. Harap tingkatkan dan coba lagi.', NULL, 1785718240, NULL, 0, 0),
	(10119, 'id', 44, 'missingdependency', 'Missing dependency {$a->@dep} required by {$a->@lib}.', 'Ketergantungan {$a->@dep} tidak ada yang diperlukan oleh {$a->@lib}.', NULL, 1785718240, NULL, 0, 0),
