	(10122, 'id', 44, 'missinglibraryfile', 'The file "{$a->%file}" is missing from library: "{$a->%name}"', 'Berkas "{$a->%file}" hilang dari pustaka: "{$a->%name}"', NULL, 1785718240, NULL, 0, 0),
	(10123, 'id', 44, 'missinglibraryjson', 'Could not find library.json file with valid json format for library {$a->%name}', 'Tidak dapat menemukan berkas library.json dengan format json yang valid untuk pustaka {$a->%name}', NULL, 1785718240, NULL, 0, 0),
	(10124, 'id', 44, 'missinglibraryproperty', 'The required property {$a->%property} is missing from {$a->%library}', 'Properti wajib {$a->%property} tidak ada di {$a->%library}', NULL, 1785718240, NULL, 0, 0),
	(10125, 'id', 44, 'missingmbstring', 'The mbstring PHP extension is not loaded. It is required for H5P to function properly.', 'Ekstensi PHP mbstring tidak dimuat. Diperlukan agar H5P berfungsi dengan baik.', NULL, 1785718240, NULL, 0, 0),
	(10126, 'id', 44, 'missinguploadpermissions', 'Note that the libraries may exist in the file you uploaded, but you\'re not allowed to upload new libraries. Please contact your administrator.', 'Perhatikan bahwa pustaka mungkin ada di berkas yang Anda unggah, tetapi Anda tidak diizinkan untuk mengunggah pustaka baru. Silakan hubungi administrator Anda.', NULL, 1785718240, NULL, 0, 0),
