	(10324, 'id', 46, 'sitecommnews_help', 'You have the option of subscribing to our Moodle newsletter. You may unsubscribe at any time.', 'Anda memiliki pilihan untuk berlangganan buletin Moodle kami. Anda dapat berhenti berlangganan kapan saja.', NULL, 1785718240, NULL, 0, 0),
	(10325, 'id', 46, 'sitecommnewsyes', 'Yes, I would like to receive the Moodle newsletter', 'Ya, saya ingin menerima buletin Moodle', NULL, 1785718240, NULL, 0, 0),
