	(10427, 'id', 48, 'clitablesexist', 'Database tables already present; CLI installation cannot continue.', 'Tabel basis data sudah ada; Instalasi CLI tidak dapat dilanjutkan.', NULL, 1785718241, NULL, 0, 0),
	(10428, 'id', 48, 'compatibilitysettings', 'Checking your PHP settings ...', 'Pengecekan setelan PHP...', NULL, 1785718241, NULL, 0, 0),
	(10429, 'id', 48, 'compatibilitysettingshead', 'Checking your PHP settings ...', 'Pengecekan setelan PHP...', NULL, 1785718241, NULL, 0, 0),
	(10430, 'id', 48, 'compatibilitysettingssub', 'Your server should pass all these tests to make Moodle run properly', 'Server Anda harus berhasil menjalankan semua tes ini agar Moodle berjalan dengan baik', NULL, 1785718241, NULL, 0, 0),
	(10431, 'id', 48, 'configfilenotwritten', 'The installer script was not able to automatically create a config.php file containing your chosen settings, probably because the Moodle directory is not writeable. You can manually copy the following code into a file named config.php within the root directory of Moodle.', 'Skrip pemasang tidak dapat secara otomatis membuat berkas config.php yang berisi setelan yang Anda pilih, mungkin karena direktori Moodle tidak dapat ditulisi. Anda dapat menyalin kode berikut secara manual ke berkas bernama config.php dalam direktori root Moodle.', NULL, 1785718241, NULL, 0, 0),
	(10432, 'id', 48, 'configfilewritten', 'config.php has been successfully created', 'berkas config.php berhasil dibuat', NULL, 1785718241, NULL, 0, 0),
