	(11570, 'id', 56, 'couldnotgetcert', 'No certificate found at <br />{$a}. <br />The host may be down or incorrectly configured.', 'Tidak ada sertifikat yang ditemukan di <br />{$a}. <br />Host mungkin sedang down atau salah konfigurasi.', NULL, 1785718242, NULL, 0, 0),
