	(11618, 'id', 56, 'hostnamehelp', 'The fully-qualified domain name of the remote host, e.g. www.example.com', 'Nama domain yang sepenuhnya memenuhi syarat dari host jarak jauh, mis. www.example.com', NULL, 1785718242, NULL, 0, 0),
	(11619, 'id', 56, 'hostnotconfiguredforsso', 'This server is not configured for remote login.', 'Server ini tidak dikonfigurasi untuk login jarak jauh.', NULL, 1785718242, NULL, 0, 0),
	(11620, 'id', 56, 'hostsettings', 'Host settings', 'Setelan hos', NULL, 1785718242, NULL, 0, 0),
	(11621, 'id', 56, 'http_self_signed_help', 'Permit connections using a self-signed DIY SSL certificate on the remote host.', 'Izinkan koneksi menggunakan sertifikat SSL DIY yang ditandatangani sendiri di host jarak jauh.', NULL, 1785718242, NULL, 0, 0),
	(11622, 'id', 56, 'https_self_signed_help', 'Permit connections using a self-signed DIY SSL in PHP on the remote host over http.', 'Izinkan koneksi menggunakan SSL DIY yang ditandatangani sendiri di PHP pada host jarak jauh melalui http.', NULL, 1785718242, NULL, 0, 0),
	(11623, 'id', 56, 'https_verified_help', 'Permit connections using a verified SSL certificate on the remote host.', 'Izinkan koneksi menggunakan sertifikat SSL terverifikasi pada host jarak jauh.', NULL, 1785718242, NULL, 0, 0),
	(11624, 'id', 56, 'http_verified_help', 'Permit connections using a verified SSL certificate in PHP on the remote host, but over http (not https).', 'Izinkan koneksi menggunakan sertifikat SSL terverifikasi di PHP pada host jarak jauh, tetapi melalui http (bukan https).', NULL, 1785718242, NULL, 0, 0),
