	(11629, 'id', 56, 'installnosuchfunction', 'Coding error! Something is trying to install a mnet xmlrpc function ({$a->method}) from a file ({$a->file}) and it can\'t be found!', 'Kesalahan pengkodean! Sesuatu mencoba menginstal fungsi mnet xmlrpc ({$a->method}) dari berkas ({$a->file}) dan tidak dapat ditemukan!', NULL, 1785718242, NULL, 0, 0),
	(11630, 'id', 56, 'installnosuchmethod', 'Coding error! Something is trying to install a mnet xmlrpc method ({$a->method}) on a class ({$a->class}) and it can\'t be found!', 'Kesalahan pengkodean! Sesuatu sedang mencoba menginstal metode mnet xmlrpc ({$a->method}) di kelas ({$a->class}) dan tidak dapat ditemukan!', NULL, 1785718242, NULL, 0, 0),
	(11631, 'id', 56, 'installreflectionclasserror', 'Coding error! MNet introspection failed for method \'{$a->method}\' in class \'{$a->class}\'.  The original error message, in case it helps, is: \'{$a->error}\'', 'Kesalahan pengkodean! Introspeksi MNet gagal untuk metode \'{$a->method}\' di kelas \'{$a->class}\'. Pesan kesalahan asli, jika membantu, adalah: \'{$a->error}\'', NULL, 1785718242, NULL, 0, 0),
	(11632, 'id', 56, 'installreflectionfunctionerror', 'Coding error! MNet introspection failed for function \'{$a->method}\' in file \'{$a->file}\'.  The original error message, in case it helps, is: \'{$a->error}\'', 'Kesalahan pengkodean! Introspeksi MNet gagal untuk fungsi \'{$a->method}\' di berkas \'{$a->file}\'. Pesan kesalahan asli, jika membantu, adalah: \'{$a->error}\'', NULL, 1785718242, NULL, 0, 0),
