	(11684, 'id', 56, 'nosuchmodule', 'The function was incorrectly addressed and could not be located. Please use the\nmod/modulename/lib/functionname format.', 'Fungsi tersebut salah ditangani dan tidak dapat ditemukan. Silakan gunakan format mod/modulename/lib/functionname.', NULL, 1785718242, NULL, 0, 0),
	(11685, 'id', 56, 'nosuchpublickey', 'Unable to obtain public key for signature verification.', 'Tidak dapat memperoleh kunci publik untuk verifikasi tanda tangan.', NULL, 1785718242, NULL, 0, 0),
	(11686, 'id', 56, 'nosuchservice', 'The RPC service is not running on this host.', 'Layanan RPC tidak berjalan di hos ini.', NULL, 1785718242, NULL, 0, 0),
