	(11688, 'id', 56, 'notBASE64', 'This string is not in base64 encoded format. It cannot be a valid key.', 'String ini tidak dalam format yang disandikan base64. Itu tidak bisa menjadi kunci yang valid.', NULL, 1785718242, NULL, 0, 0),
	(11689, 'id', 56, 'notenoughidpinfo', 'Your identity provider is not giving us enough information to create or update your account locally. Sorry!', 'Penyedia identitas Anda tidak memberi kami informasi yang cukup untuk membuat atau memperbarui akun Anda secara lokal. Maaf!', NULL, 1785718242, NULL, 0, 0),
	(11690, 'id', 56, 'not_in_range', 'The IP address <code>{$a}</code> does not represent a valid trusted host.', 'Alamat IP <code>{$a}</code> tidak mewakili hos tepercaya yang valid.', NULL, 1785718242, NULL, 0, 0),
	(11691, 'id', 56, 'notinxmlrpcserver', 'Attempt to access the MNet remote client, not during XMLRPC server execution', 'Mencoba mengakses klien jarak jauh MNet, bukan selama eksekusi server XMLRPC', NULL, 1785718242, NULL, 0, 0),
	(11692, 'id', 56, 'notmoodleapplication', 'WARNING: This is not a Moodle application, so some of the inspection methods may not work properly.', 'PERINGATAN: Ini bukan aplikasi Moodle, jadi beberapa metode pemeriksaan mungkin tidak bekerja dengan benar.', NULL, 1785718242, NULL, 0, 0),
	(11693, 'id', 56, 'notPEM', 'This key is not in PEM format. It will not work.', 'Kunci ini tidak dalam format PEM. Itu tidak akan bekerja.', NULL, 1785718242, NULL, 0, 0),
	(11694, 'id', 56, 'notpermittedtojump', 'You do not have permission to begin a remote session from this Moodle server.', 'Anda tidak memiliki izin untuk memulai sesi jarak jauh dari server Moodle ini.', NULL, 1785718242, NULL, 0, 0),
	(11695, 'id', 56, 'notpermittedtojumpas', 'You can\'t begin a remote session while you are logged in as another user.', 'Anda tidak dapat memulai sesi jarak jauh saat Anda masuk sebagai pengguna lain.', NULL, 1785718242, NULL, 0, 0),
	(11696, 'id', 56, 'notpermittedtoland', 'You do not have permission to begin a remote session.', 'Anda tidak memiliki izin untuk memulai sesi jarak jauh.', NULL, 1785718242, NULL, 0, 0),
