	(11772, 'id', 56, 'userchangepasswordlink', '<br /> You may be able to change your password at your <a href="{$a->wwwroot}/login/change_password.php">{$a->description}</a> provider.', '<br /> Anda mungkin dapat mengubah sandi Anda di penyedia <a href="{$a->wwwroot}/login/change_password.php "> {$a->description} </a>.', NULL, 1785718243, NULL, 0, 0),
	(11773, 'id', 56, 'usernotfullysetup', 'Your user account is incomplete.  You need to go <a href="{$a}">back to your provider</a> and ensure your profile is completed there.  You may need to log out and in again for this to take effect.', 'Akun pengguna Anda tidak lengkap. Anda harus <a href="{$a}">kembali ke penyedia Anda</a> dan memastikan profil Anda selesai di sana. Anda mungkin perlu keluar dan masuk lagi agar ini berlaku.', NULL, 1785718243, NULL, 0, 0),
	(11774, 'id', 56, 'usersareonline', 'Warning: {$a} users from that server are currently logged on to your site.', 'Peringatan: {$a} pengguna dari server itu saat ini masuk ke situs Anda.', NULL, 1785718243, NULL, 0, 0),
