	(12168, 'id', 63, 'validationmsg_onedir', 'Invalid structure of the ZIP package.', 'Struktur paket ZIP tidak valid.', NULL, 1785718243, NULL, 0, 0),
	(12169, 'id', 63, 'validationmsg_onedir_help', 'The ZIP package must contain just one root directory that holds the plugin code. The name of that root directory must match the name of the plugin.', 'Paket ZIP hanya boleh berisi satu direktori root yang menyimpan kode pengaya. Nama direktori root tersebut harus sama dengan nama pengaya.', NULL, 1785718243, NULL, 0, 0),
