	(12219, 'id', 64, 'enabled', 'Enable portfolios', 'Aktifkan portofolio', NULL, 1785718243, NULL, 0, 0),
	(12220, 'id', 64, 'enableddesc', 'If enabled, users can export content, such as forum posts and assignment submissions, to external portfolios or HTML pages.', 'Jika diaktifkan, pengguna dapat mengekspor konten, seperti kiriman forum dan pengajuan tugas, ke portofolio eksternal atau halaman HTML.', NULL, 1785718243, NULL, 0, 0),
	(12221, 'id', 64, 'err_uniquename', 'Portfolio name must be unique (per plugin)', 'Nama portofolio harus unik (per pengaya)', NULL, 1785718243, NULL, 0, 0),
	(12222, 'id', 64, 'exportalreadyfinished', 'Portfolio export complete!', 'Ekspor portofolio selesai!', NULL, 1785718243, NULL, 0, 0),
