	(12225, 'id', 64, 'exportedpreviously', 'Previous exports', 'Ekspor sebelumnya', NULL, 1785718243, NULL, 0, 0),
	(12226, 'id', 64, 'exportexceptionnoexporter', 'A portfolio_export_exception was thrown with an active session but no exporter object', 'portfolio_export_exception dilempar dengan sesi aktif tetapi tidak ada objek eksportir', NULL, 1785718243, NULL, 0, 0),
	(12227, 'id', 64, 'exportexpired', 'Portfolio export expired', 'Ekspor portofolio kedaluwarsa', NULL, 1785718243, NULL, 0, 0),
	(12228, 'id', 64, 'exportexpireddesc', 'You tried to repeat the export of some information, or start an empty export. To do that properly you should go back to the original location and start again. This sometimes happens if you use the back button after an export has completed, or by bookmarking an invalid url.', 'Anda mencoba mengulangi ekspor beberapa informasi, atau memulai ekspor kosong. Untuk melakukannya dengan benar, Anda harus kembali ke lokasi semula dan mulai lagi. Ini terkadang terjadi jika Anda menggunakan tombol kembali setelah ekspor selesai, atau dengan memarkahi url yang tidak valid.', NULL, 1785718243, NULL, 0, 0),
	(12229, 'id', 64, 'exporting', 'Exporting to portfolio', 'Mengekspor ke portofolio', NULL, 1785718243, NULL, 0, 0),
