	(12272, 'id', 64, 'invalidpreparepackagefile', 'Invalid call to prepare_package_file - either single or multifiles must be set', 'Panggilan tidak valid ke prepared_package_file - baik tunggal maupun multifiles harus disetel', NULL, 1785718243, NULL, 0, 0),
	(12273, 'id', 64, 'invalidproperty', 'Could not find that property ({$a->property} of {$a->class})', 'Tidak dapat menemukan properti ({$a->property} dari {$a->class})', NULL, 1785718243, NULL, 0, 0),
	(12274, 'id', 64, 'invalidsha1file', 'Invalid call to get_sha1_file - either single or multifiles must be set', 'Panggilan tidak valid ke get_sha1_file - baik tunggal maupun multifiles harus disetel', NULL, 1785718243, NULL, 0, 0),
