	(12524, 'id', 66, 'changepublishstatuscat', '<a href="{$a->caturl}">Category "{$a->name}"</a> in course "{$a->coursename}" will have its sharing status changed from {$a->changefrom} to {$a->changeto}.', '<a href="{$a->caturl}">Kategori "{$a->name}"</a> dalam kursus "{$a->coursename}" akan diubah status berbaginya dari {$a- >changfrom} menjadi {$a->changeto}.', NULL, 1785718244, NULL, 0, 0),
	(12525, 'id', 66, 'chooseqtypetoadd', 'Choose a question type to add', 'Pilih jenis soal yang akan ditambahkan', NULL, 1785718244, NULL, 0, 0),
	(12526, 'id', 66, 'editquestions', 'Edit questions', 'Edit soal', NULL, 1785718244, NULL, 0, 0),
	(12527, 'id', 66, 'idnumber', 'ID number', 'Nomor ID', NULL, 1785718244, NULL, 0, 0),
	(12528, 'id', 66, 'idnumber_help', 'If used, the ID number must be unique within each question category. It provides another way of identifying a question which is sometimes useful, but can usually be left blank.', 'Jika digunakan, nomor ID harus unik dalam setiap kategori soal. Ini memberikan cara lain untuk mengidentifikasi soal yang terkadang berguna, tetapi biasanya dapat dibiarkan kosong.', NULL, 1785718244, NULL, 0, 0),
	(12529, 'id', 66, 'ignorebroken', 'Ignore broken links', 'Abaikan tautan rusak', NULL, 1785718244, NULL, 0, 0),
	(12530, 'id', 66, 'impossiblechar', 'Impossible character {$a} detected as parenthesis character', 'Karakter yang tidak dimungkinkan {$a} terdeteksi pada karakter tanda kurung', NULL, 1785718244, NULL, 0, 0),
	(12531, 'id', 66, 'import', 'Import', 'Impor', NULL, 1785718244, NULL, 0, 0),
	(12532, 'id', 66, 'importcategory', 'Import category', 'Impor kategori', NULL, 1785718244, NULL, 0, 0),
	(12533, 'id', 66, 'importcategory_help', 'This setting determines the category into which the imported questions will go.\n\nCertain import formats, such as GIFT and Moodle XML, may include category and context data in the import file. To make use of this data, rather than the selected category, the appropriate checkboxes should be ticked. If categories specified in the import file do not exist, they will be created.', 'Setelan ini menentukan kategori ke mana pertanyaan yang diimpor akan masuk. Format impor tertentu, seperti GIFT dan Moodle XML, dapat menyertakan data kategori dan konteks dalam berkas impor. Untuk menggunakan data ini, daripada kategori yang dipilih, kotak centang yang sesuai harus dicentang. Jika kategori yang ditentukan dalam berkas impor tidak ada, kategori tersebut akan dibuat.', NULL, 1785718244, NULL, 0, 0),
	(12534, 'id', 66, 'importerror', 'An error occurred during import processing', 'Terjadi galat ketika proses impor', NULL, 1785718244, NULL, 0, 0),
	(12535, 'id', 66, 'importerrorquestion', 'Error importing question', 'Galat ketika mengimpor soal', NULL, 1785718244, NULL, 0, 0),
	(12536, 'id', 66, 'importingquestions', 'Importing {$a} questions from file', 'Mengimpor {$a} soal dari berkas', NULL, 1785718244, NULL, 0, 0),
	(12537, 'id', 66, 'importparseerror', 'Error(s) found parsing the import file. No questions have been imported. To import any good questions try again setting \'Stop on error\' to \'No\'', 'Galat ditemukan menguraikan kalimat berkas impor. Tidak ada soal diimpor. Untuk mengimpor soal, coba lagi dengan setel \'Berhenti ketika galat\' ke \'Tidak\'', NULL, 1785718244, NULL, 0, 0),
	(12538, 'id', 66, 'importquestions', 'Import questions from file', 'Impor soal dari berkas', NULL, 1785718244, NULL, 0, 0),
	(12539, 'id', 66, 'importquestions_help', 'This function enables questions in a variety of formats to be imported via text file. Note that the file must use UTF-8 encoding.', 'Fungsi ini memungkinkan soal dari bermacam format diimpor melalui berkas teks. Perhatikan bahwa berkas harus menggunakan pengodean UTF-8', NULL, 1785718244, NULL, 0, 0),
	(12540, 'id', 66, 'importquestions_link', 'question/import', 'soal/impor', NULL, 1785718244, NULL, 0, 0),
	(12541, 'id', 66, 'importwrongfileencoding', 'The file you selected does not use UTF-8 character encoding. {$a} files must use UTF-8.', 'Berkas yang Anda pilih tidak menggunakan pengkodean karakter UTF-8. Berkas {$a} harus menggunakan UTF-8.', NULL, 1785718244, NULL, 0, 0),
	(12542, 'id', 66, 'importwrongfiletype', 'The type of the file you selected ({$a->actualtype}) does not match the type expected by this import format ({$a->expectedtype}).', 'Tipe berkas yang anda pilih ({$a->actualtype}) tidak cocok dengan tipe yang diperlukan oleh format impor ({$a->expectedtype}).', NULL, 1785718244, NULL, 0, 0),
	(12543, 'id', 66, 'invalidarg', 'No valid arguments supplied or incorrect server configuration', 'Tidak ada argumen sah yang disuplai atau setelan server tidak benar', NULL, 1785718244, NULL, 0, 0),
	(12544, 'id', 66, 'invalidcategoryidforparent', 'Invalid category id for parent!', 'ID kategori tidak valid untuk induk!', NULL, 1785718244, NULL, 0, 0),
	(12545, 'id', 66, 'invalidcategoryidtomove', 'Invalid category id to move!', 'Id kategori tidak valid untuk dipindahkan!', NULL, 1785718244, NULL, 0, 0),
	(12546, 'id', 66, 'invalidconfirm', 'Confirmation string was incorrect', 'String konfirmasi salah', NULL, 1785718244, NULL, 0, 0),
	(12547, 'id', 66, 'invalidcontextinhasanyquestions', 'Invalid context passed to question_context_has_any_questions.', 'Konteks yang tidak valid diteruskan ke question_context_has_any_questions.', NULL, 1785718244, NULL, 0, 0),
	(12548, 'id', 66, 'invalidgrade', 'Grades ({$a}) do not match grade options - question skipped.', 'Nilai ({$a}) tidak cocok dengan opsi nilai - soal dilewati.', NULL, 1785718244, NULL, 0, 0),
	(12549, 'id', 66, 'invalidgradequestion', 'Grades ({$a->grades}) do not match grade options - question \'{$a->question}\' skipped.', 'Nilai ({$a->grades}) tidak cocok dengan opsi nilai - soal \'{$a->question}\' dilewati.', NULL, 1785718244, NULL, 0, 0),
