	(12569, 'id', 66, 'movedquestionsandcategories', 'Moved questions and question categories from {$a->oldplace} to {$a->newplace}.', 'Soal dan kategori soal dipindahkan dari {$a->oldplace} ke {$a->newplace}.', NULL, 1785718244, NULL, 0, 0),
	(12570, 'id', 66, 'movelinksonly', 'Just change where links point to, do not move or copy files.', 'Ubah saja ke mana tautan mengarah, jangan pindahkan atau salin file.', NULL, 1785718244, NULL, 0, 0),
