	(12574, 'id', 66, 'movingcategory', 'Moving category', 'Memindahkan kategori', NULL, 1785718244, NULL, 0, 0),
	(12575, 'id', 66, 'movingcategoryandfiles', 'Are you sure you want to move category {$a->name} and all child categories to context for "{$a->contextto}"?<br /> We have detected {$a->urlcount} files linked from questions in {$a->fromareaname}, would you like to copy or move these to {$a->toareaname}?', 'Anda yakin ingin memindahkan kategori {$a->name} dan semua kategori turunan ke konteks untuk "{$a->contextto}"?<br /> Kami telah mendeteksi berkas {$a->urlcount} yang ditautkan dari soal di {$a->fromareaname}, apakah Anda ingin menyalin atau memindahkan ini ke {$a->toareaname}?', NULL, 1785718244, NULL, 0, 0),
	(12576, 'id', 66, 'movingcategorynofiles', 'Are you sure you want to move category "{$a->name}" and all child categories to context for "{$a->contextto}"?', 'Yakin ingin memindahkan kategori "{$a->name}" dan semua kategori turunan ke konteks untuk "{$a->contextto}"?', NULL, 1785718244, NULL, 0, 0),
	(12577, 'id', 66, 'movingquestions', 'Moving questions and any files', 'Memindahkan setiap soal dan berkas', NULL, 1785718244, NULL, 0, 0),
	(12578, 'id', 66, 'movingquestionsandfiles', 'Are you sure you want to move question(s) {$a->questions} to context for <strong>"{$a->tocontext}"</strong>?<br /> We have detected <strong>{$a->urlcount} files</strong> linked from these question(s) in {$a->fromareaname}, would you like to copy or move these to {$a->toareaname}?', 'Anda yakin ingin memindahkan soal {$a->questions} ke konteks untuk <strong>"{$a->tocontext}"</strong>?<br /> Kami telah mendeteksi <strong>{$a->urlcount} berkas</strong> yang ditautkan dari soal ini di {$a->fromareaname}, apakah Anda ingin menyalin atau memindahkannya ke {$a->toareaname}?', NULL, 1785718244, NULL, 0, 0),
	(12579, 'id', 66, 'movingquestionsnofiles', 'Are you sure you want to move question(s) {$a->questions} to context for <strong>"{$a->tocontext}"</strong>?<br /> There are <strong>no files</strong> linked from these question(s) in {$a->fromareaname}.', 'Anda yakin ingin memindahkan soal {$a->questions} ke konteks untuk <strong>"{$a->tocontext}"</strong>?<br /> Tidak ada <strong>tidak ada berkas< /strong> ditautkan dari soal ini di {$a->fromareaname}.', NULL, 1785718244, NULL, 0, 0),
	(12580, 'id', 66, 'needtochoosecat', 'You need to choose a category to move this question to or press \'cancel\'.', 'Anda harus memilih kategori tujuan untuk memindahkan soal ini atau tekan \'batalkan\'.', NULL, 1785718244, NULL, 0, 0),
	(12581, 'id', 66, 'nocate', 'No such category {$a}!', 'Tidak ada kategori semacam itu {$a}!', NULL, 1785718244, NULL, 0, 0),
	(12582, 'id', 66, 'nopermissionadd', 'You don\'t have permission to add questions here.', 'Anda tidak diizinkan menambah soal.', NULL, 1785718244, NULL, 0, 0),
	(12583, 'id', 66, 'nopermissionedit', 'You don\'t have permission to edit questions from here.', 'Anda tidak memiliki izin untuk mengedit pertanyaan dari sini.', NULL, 1785718244, NULL, 0, 0),
	(12584, 'id', 66, 'noprobs', 'No problems found in your question database.', 'Tidak ada masalah ditemukan pada basis data soal Anda.', NULL, 1785718244, NULL, 0, 0),
	(12585, 'id', 66, 'noquestions', 'No questions were found that could be exported. Make sure that you have selected a category to export that contains questions.', 'Tidak ditemukan soal yang dapat diekspor. Pastikan Anda telah memilih kategori yang akan diekspor yang berisi soal.', NULL, 1785718244, NULL, 0, 0),
	(12586, 'id', 66, 'noquestionsinfile', 'There are no questions in the import file', 'Tidak ada soal pada berkas impor', NULL, 1785718244, NULL, 0, 0),
	(12587, 'id', 66, 'notagfiltersapplied', 'No tag filters applied', 'Tidak ada filter label yang diterapkan', NULL, 1785718244, NULL, 0, 0),
	(12588, 'id', 66, 'notenoughanswers', 'This type of question requires at least {$a} answers', 'Tipe soal ini membutuhkan setidaknya {$a} jawaban', NULL, 1785718244, NULL, 0, 0),
	(12589, 'id', 66, 'notenoughdatatoeditaquestion', 'Neither a question id, nor a category id and question type, was specified.', 'Tidak ada id soal, id kategori dan tipe soal yang dispesifikasikan.', NULL, 1785718244, NULL, 0, 0),
	(12590, 'id', 66, 'notenoughdatatomovequestions', 'You need to provide the question ids of questions you want to move.', 'Anda harus menyediakan ID soal untuk soal yang mau anda pindahkan.', NULL, 1785718244, NULL, 0, 0),
