	(12595, 'id', 66, 'page-question-x', 'Any question page', 'Setiap halaman soal', NULL, 1785718244, NULL, 0, 0),
	(12596, 'id', 66, 'page-question-edit', 'Question editing page', 'Halaman penyunting soal', NULL, 1785718244, NULL, 0, 0),
