	(14908, 'id', 80, 'restrictedusers_help', 'This setting determines whether all users with the permission to create a web services token can generate a token for this service via their security keys page or whether only authorised users can do so.', 'Setelan ini menentukan apakah semua pengguna dengan izin untuk membuat token layanan web dapat menghasilkan token untuk layanan ini melalui halaman kunci keamanan mereka atau apakah pengguna hanya berwenang dapat melakukannya.', NULL, 1785718247, NULL, 0, 0),
	(14909, 'id', 80, 'restoredaccountresetpassword', 'Restored account need to reset password before getting a token.', 'Untuk mengembalikan akun harus mereset kata sandi sebelum mendapatkan token.', NULL, 1785718247, NULL, 0, 0),
