	(14948, 'id', 80, 'tokennameprefix', 'Webservice-{$a}', 'Webservice-{$a}', NULL, 1785718247, NULL, 0, 0),
	(14949, 'id', 80, 'tokennewmessage', 'Copy the token now. It won\'t be shown again once you leave this page.', 'Salin token sekarang. Itu tidak akan ditampilkan lagi setelah Anda meninggalkan halaman ini.', NULL, 1785718247, NULL, 0, 0),
