	(15410, 'id', 96, 'formerror_droprequired', 'You must define at least one drop zone for this question.', 'Anda harus menentukan setidaknya satu zona penurunan untuk pertanyaan ini.', NULL, 1785718248, NULL, 0, 0),
	(15411, 'id', 96, 'formerror_noallowedtags', 'HTML tags are not allowed in this text which is the alt text for a draggable image.', 'Tag HTML tidak diperbolehkan dalam teks ini yang merupakan teks alternatif untuk gambar yang dapat diseret.', NULL, 1785718248, NULL, 0, 0),
	(15412, 'id', 96, 'formerror_noytop', 'You must provide a value for the y coordinate for the top left corner of this drop area. You can drag and drop the drop area above to set the coordinates or enter them manually here.', 'Anda harus memberikan nilai untuk koordinat y untuk sudut kiri atas area penurunan ini. Anda dapat menarik dan melepas area di atas untuk mengatur koordinat atau memasukkannya secara manual di sini.', NULL, 1785718248, NULL, 0, 0),
	(15413, 'id', 96, 'formerror_noxleft', 'You must provide a value for the x coordinate for the top left corner of this drop area. You can drag and drop the drop area above to set the coordinates or enter them manually here.', 'Anda harus memberikan nilai untuk koordinat x untuk sudut kiri atas area penurunan ini. Anda dapat menarik dan melepas area di atas untuk mengatur koordinat atau memasukkannya secara manual di sini.', NULL, 1785718248, NULL, 0, 0),
	(15414, 'id', 96, 'formerror_nofile', 'You need to upload or select a file to use here.', 'Anda perlu mengunggah atau memilih berkas untuk digunakan di sini.', NULL, 1785718248, NULL, 0, 0),
	(15415, 'id', 96, 'formerror_nofile3', 'You need to select an image file here, or delete the associated label and uncheck the unlimited checkbox.', 'Anda perlu memilih berkas gambar di sini, atau menghapus label terkait dan hapus centang pada kotak centang tak terbatas.', NULL, 1785718248, NULL, 0, 0),
	(15416, 'id', 96, 'formerror_notintytop', 'The y coordinate must be an integer.', 'Koordinat y harus berupa bilangan bulat.', NULL, 1785718248, NULL, 0, 0),
	(15417, 'id', 96, 'formerror_notintxleft', 'The x coordinate must be an integer.', 'Koordinat x harus berupa bilangan bulat.', NULL, 1785718248, NULL, 0, 0),
	(15418, 'id', 96, 'formerror_multipledraginstance', 'You have selected this image {$a} more than once as the correct choice for a drop zone but it is not marked as being an unlimited drag item.', 'Anda telah memilih gambar ini {$a} lebih dari sekali sebagai pilihan yang tepat untuk zona lepas tetapi tidak ditandai sebagai item tarik tak terbatas.', NULL, 1785718248, NULL, 0, 0),
	(15419, 'id', 96, 'formerror_multipledraginstance2', 'You have selected this image more than once as the correct choice for a drop zone but it is not marked as being an unlimited drag item.', 'Anda telah memilih gambar ini lebih dari sekali sebagai pilihan yang tepat untuk zona lepas tetapi tidak ditandai sebagai item seret tak terbatas.', NULL, 1785718248, NULL, 0, 0),
	(15420, 'id', 96, 'formerror_noimageselected', 'You need to select a drag item to be the correct choice for this drop zone.', 'Anda harus memilih item yang dapat diseret  untuk menjadi pilihan yang tepat untuk zona lepas ini.', NULL, 1785718248, NULL, 0, 0),
	(15421, 'id', 96, 'formerror_nobgimage', 'You need to select an image to use as the background for the drag and drop area.', 'Anda perlu memilih gambar untuk digunakan sebagai latar belakang untuk area seret and lepas.', NULL, 1785718248, NULL, 0, 0),
	(15422, 'id', 96, 'infinite', 'Unlimited', 'Tak terbatas', NULL, 1785718248, NULL, 0, 0),
