	(15501, 'id', 97, 'shape_circle_coords', 'x,y;r (where x,y are the coordinates of the centre of the circle and r is the radius)', 'x,y;r (di mana x,y adalah koordinat pusat lingkaran dan r adalah jari-jarinya)', NULL, 1785718248, NULL, 0, 0),
	(15502, 'id', 97, 'shape_rectangle', 'Rectangle', 'Persegi panjang', NULL, 1785718248, NULL, 0, 0),
