	(15504, 'id', 97, 'shape_rectangle_coords', 'x,y;w,h (where x,y are the coordinates of the top left corner of the rectangle and w and h are the width and height of the rectangle)', 'x,y;w,h (di mana x,y adalah koordinat sudut kiri atas persegi panjang dan w dan h adalah lebar dan tinggi persegi panjang)', NULL, 1785718248, NULL, 0, 0),
	(15505, 'id', 97, 'shape_polygon', 'Polygon', 'Poligon', NULL, 1785718248, NULL, 0, 0),
