	(15548, 'id', 100, 'attachmentsrequired_help', 'This option specifies the minimum number of attachments required for a response to be considered gradable.', 'Opsi ini menentukan jumlah minimum lampiran yang diperlukan agar jawaban dipertimbangkan secara gradual.', NULL, 1785718248, NULL, 0, 0),
	(15549, 'id', 100, 'err_maxminmismatch', 'Maximum word limit must be greater than minimum word limit', 'Batas kata maksimum harus lebih besar dari batas kata minimum', NULL, 1785718248, NULL, 0, 0),
	(15550, 'id', 100, 'err_maxwordlimit', 'Maximum word limit is enabled but is not set', 'Batas kata maksimum dinonaktifkan tetapi tidak disetel', NULL, 1785718248, NULL, 0, 0),
