	(15566, 'id', 100, 'minwordlimit_help', 'If the response requires that students enter text, this is the minimum number of words that each student will be allowed to submit.', 'Jika jawaban mengharuskan siswa memasukkan teks, ini adalah jumlah minimum kata yang boleh dikirim oleh setiap siswa.', NULL, 1785718248, NULL, 0, 0),
	(15567, 'id', 100, 'minwordlimitboundary', 'This question requires a response of at least {$a->limit} words and you are attempting to submit {$a->count} words. Please expand your response and try again.', 'Soal ini membutuhkan jawaban minimal {$a->limit} kata dan Anda mencoba mengirimkan {$a->count} kata. Perluas jawaban Anda dan coba lagi.', NULL, 1785718248, NULL, 0, 0),
	(15568, 'id', 100, 'mustattach', 'When "No online text" is selected, or responses are optional, you must allow at least one attachment.', 'Ketika "Tidak ada teks daring" dipilih, atau jawaban bersifat opsional, Anda harus mengizinkan setidaknya satu lampiran.', NULL, 1785718248, NULL, 0, 0),
	(15569, 'id', 100, 'mustrequire', 'When "No online text" is selected, or responses are optional, you must require at least one attachment.', 'Ketika "Tidak ada teks daring" dipilih, atau jawaban bersifat opsional, Anda harus mengizinkan setidaknya satu lampiran.', NULL, 1785718248, NULL, 0, 0),
	(15570, 'id', 100, 'mustrequirefewer', 'You cannot require more attachments than you allow.', 'Anda tidak dapat meminta lebih banyak lampiran daripada yang Anda izinkan.', NULL, 1785718248, NULL, 0, 0),
