	(15573, 'id', 100, 'pluginname', 'Essay', 'Essay', NULL, 1785718248, NULL, 0, 0),
	(15574, 'id', 100, 'pluginname_help', 'In response to a question, the respondent may upload one or more files and/or enter text online. A response template may be provided. Responses must be graded manually.', 'Menanggapi soal, responden dapat mengunggah satu atau lebih file dan / atau memasukkan teks secara daring. Templat jawaban mungkin disediakan. Jawaban harus dinilai secara manual.', NULL, 1785718248, NULL, 0, 0),
	(15575, 'id', 100, 'pluginname_link', 'question/type/essay', 'question/type/essay', NULL, 1785718249, NULL, 0, 0),
