	(16037, 'id', 112, 'assignfeedback', 'Feedback plugin', 'PEngaya umpan balik', NULL, 1785718249, NULL, 0, 0),
	(16038, 'id', 112, 'assignfeedbackpluginname', 'Feedback plugin', 'Pengaya umpan balik', NULL, 1785718249, NULL, 0, 0),
	(16039, 'id', 112, 'assignmentduedigesthtml', '<p>Hi {$a->firstname},</p>\n<p>The following assignments are due on <strong>{$a->duedate}</strong>.</p>\n{$a->digest}', '<p>Hai {$a->firstname},</p>\n<p>Tugas berikut harus dikumpulkan pada <strong>{$a->duedate}</strong>.</p>\n{$a->digest}', NULL, 1785718249, NULL, 0, 0),
	(16040, 'id', 112, 'assignmentduedigestitem', '<strong>{$a->assignmentname}</strong> in course {$a->coursename}<br/>\n<strong>Due: {$a->duetime}</strong><br/>\n<a href="{$a->url}" aria-label="Go to {$a->assignmentname}">Go to activity</a>', '<strong>{$a->assignmentname}</strong> pada kursus {$a->coursename}<br/>\n<strong>Jatuh tempo: {$a->duetime}</strong><br/>\n<a href="{$a->url}" aria-label="Go to {$a->assignmentname}">Menuju Aktivitas</a>', NULL, 1785718249, NULL, 0, 0),
	(16041, 'id', 112, 'assignmentduedigestsubject', 'You have assignments due in 7 days', 'Anda memiliki penugasan yang harus diselesaikan dalam 7 hari', NULL, 1785718249, NULL, 0, 0),
	(16042, 'id', 112, 'assignmentduesoonhtml', '<p>Hi {$a->firstname},</p>\n<p>The assignment <strong>{$a->assignmentname}</strong> in course {$a->coursename} is due soon.</p>\n<p><strong>Due: {$a->duedate}</strong></p>\n<p><a href="{$a->url}">Go to activity</a></p>', '<p>Hai {$a->firstname},</p>\n<p>Penugasan <strong>{$a->assignmentname}</strong> dalam kursus {$a->coursename} akan segera selesai.</p>\n <p><strong>Batas waktu: {$a->duedate}</strong></p>\n<p><a href="{$a->url}">Buka aktivitas</a></p>', NULL, 1785718249, NULL, 0, 0),
	(16043, 'id', 112, 'assignmentoverduehtml', '<p>Hi {$a->firstname},</p>\n<p><strong>{$a->assignmentname}</strong> in course {$a->coursename} was due on <strong>{$a->duedate}</strong>.</p>\n<p>You might still be able to submit your assignment{$a->cutoffsnippet}, but your submission will be marked as late.</p>\n<p><a href="{$a->url}">Go to activity</a></p>', '<p>Hai {$a->firstname},</p> <p><strong>{$a->assignmentname</strong> dalam kursus\n{$a->coursename} harus diselesaikan pada <strong>{$a->duedate</strong>.</p>\n<p>Anda mungkin masih dapat mengirimkan tugas Anda{$a->cutoffsnippet}, namun kiriman Anda akan ditandai terlambat.</p> <p><a href="{$a->url}">Buka aktivitas</a></p>', NULL, 1785718249, NULL, 0, 0),
	(16044, 'id', 112, 'assignmentoverduehtmlcutoffsnippet', ' <strong>by {$a->cutoffdate}</strong>', '<strong>selambat-lambatnya pada {$a->cutoffdate}</strong>', NULL, 1785718249, NULL, 0, 0),
	(16045, 'id', 112, 'assignmentduesoonsubject', 'Due on {$a->duedate}: {$a->assignmentname}', 'Jatuh tempo pada {$a->duedate}: {$a->assignmentname}', NULL, 1785718249, NULL, 0, 0),
	(16046, 'id', 112, 'assignmentoverduesubject', 'Overdue: {$a->assignmentname}', 'Terlambat: {$a->assignmentname}', NULL, 1785718249, NULL, 0, 0),
	(16047, 'id', 112, 'assignmentisdue', 'Assignment is due', 'Penugasan jatuh tempo', NULL, 1785718249, NULL, 0, 0),
	(16048, 'id', 112, 'assignmentmail', '{$a->grader} has posted some feedback on your\nassignment submission for \'{$a->assignment}\'\n\nYou can see it appended to your assignment submission:\n\n    {$a->url}', '{$a->grader} telah mengirim beberapa umpan balik pada pengajuan tugas Anda untuk \'{$a->assignment}\'\n\nAnda dapat melihatnya ditambahkan ke ajuan tugas Anda:\n\n{$a->url}', NULL, 1785718249, NULL, 0, 0),
	(16049, 'id', 112, 'assignmentmailhtml', '<p>{$a->grader} has posted some feedback on your\nassignment submission for \'<i>{$a->assignment}</i>\'.</p>\n<p>You can see it appended to your <a href="{$a->url}">assignment submission</a>.</p>', '<p> {$a->grader} telah mengirim beberapa umpan balik pada pengajuan tugas Anda untuk \'<i> {$a->assignment} </i>\'. </ p> <p> Anda dapat melihatnya ditambahkan ke <a href="{$a->url} "> ajuan tugas </a>. </p>', NULL, 1785718249, NULL, 0, 0),
	(16050, 'id', 112, 'assignmentmailsmall', '{$a->grader} has posted some feedback on your\nassignment submission for \'{$a->assignment}\' You can see it appended to your submission', '{$a->grader} telah mengirim beberapa umpan balik tentang pengajuan tugas Anda untuk \'{$a->assignment}\' Anda dapat melihatnya ditambahkan ke pengajuan Anda', NULL, 1785718249, NULL, 0, 0),
