	(16131, 'id', 112, 'cutoffdate_help', 'If set, submissions will not be accepted after this date without an extension. If not set, submissions will always be accepted.', 'Jika ditetapkan, kiriman tidak akan diterima setelah tanggal ini tanpa perpanjangan. Jika tidak disetel, kiriman akan selalu diterima.', NULL, 1785718249, NULL, 0, 0),
	(16132, 'id', 112, 'cutoffdatevalidation', 'Cut-off date cannot be earlier than the due date.', 'Tanggal batas akhir tidak boleh lebih awal dari tanggal jatuh tempo.', NULL, 1785718249, NULL, 0, 0),
