	(16276, 'id', 112, 'inactiveoverridehelp', '* This override is inactive because the user\'s access to the activity is restricted. This can be due to group or role assignments, other access restrictions, or the activity being hidden.', '* Penyampingaan ini tidak aktif karena akses pengguna ke aktivitas dibatasi. Hal ini dapat terjadi karena penetapan grup atau peran, pembatasan akses lainnya, atau aktivitas disembunyikan.', NULL, 1785718250, NULL, 0, 0),
	(16277, 'id', 112, 'includesuspendedparticipants', 'Include suspended participants', 'Sertakan peserta yang ditangguhkan', NULL, 1785718250, NULL, 0, 0),
