	(16440, 'id', 112, 'removesubmissionconfirmforstudentwithtimelimit', 'Are you sure you want to remove the submission for {$a}? Please note that this will not reset the student\'s time limit. You can give more time by adding a time limit user override.', 'Anda yakin ingin menghapus pengajuan untuk {$a}? Harap dicatat bahwa ini tidak akan mengatur ulang batas waktu siswa. Anda dapat memberikan lebih banyak waktu dengan menambahkan batas waktu penggantian pengguna.', NULL, 1785718250, NULL, 0, 0),
	(16441, 'id', 112, 'removesubmissionconfirmwithtimelimit', 'Are you sure you want to remove your submission? Please note that this will not reset your time limit.', 'Anda yakin ingin menghapus ajuan Anda? Harap dicatat bahwa ini tidak akan mengatur ulang batas waktu Anda.', NULL, 1785718250, NULL, 0, 0),
