	(16485, 'id', 112, 'submissionattachments_help', 'Tick the box to only show files on the submission page. Otherwise, files will be shown on both the assignment and submission pages.', 'Centang kotak untuk hanya menampilkan berkas di halaman pengajuan. Jika tidak, file akan ditampilkan pada halaman tugas dan pengajuan.', NULL, 1785718250, NULL, 0, 0),
	(16486, 'id', 112, 'confirmstart', 'You have {$a} to complete this assignment. When you begin, the timer will start to count down and can\'t be paused.', 'Anda memiliki {$a} untuk menyelesaikan tugas ini. Saat Anda mulai, penghitung waktu akan mulai menghitung mundur dan tidak dapat dijeda.', NULL, 1785718250, NULL, 0, 0),
	(16487, 'id', 112, 'submissioncopiedtext', 'You have made a copy of your previous\nassignment submission for \'{$a->assignment}\'\n\nYou can see the status of your assignment submission:\n\n    {$a->url}', 'Anda telah berhasil membuat salinan pengajuan tugas untuk \'{$a->assignment}\'\n\nAnda dapat melihat status pengajuan tugas Anda:\n\n    {$a->url}', NULL, 1785718250, NULL, 0, 0),
	(16488, 'id', 112, 'submissioncopiedhtml', '<p>You have made a copy of your previous\nassignment submission for \'<i>{$a->assignment}</i>\'.</p>\n<p>You can see the status of your <a href="{$a->url}">assignment submission</a>.</p>', '<p>Anda telah berhasil membuat salinan pengajuan tugas untuk \'<i>{$a->assignment}</i>\'.</p> <p>Anda dapat melihat status <a href="{$a->url}">pengajuan tugas</a> Anda.</p>', NULL, 1785718250, NULL, 0, 0),
	(16489, 'id', 112, 'submissioncopiedsmall', 'You have copied your previous assignment submission for {$a->assignment}', 'Anda telah menyalin ajuan tugas Anda sebelumnya untuk {$a->assignment}', NULL, 1785718250, NULL, 0, 0),
