	(16502, 'id', 112, 'submissionreceiptotherhtml', 'Your assignment submission for\n\'<i>{$a->assignment}</i>\' has been submitted.<br /><br />\nYou can see the status of your <a href="{$a->url}">assignment submission</a>.', 'Pengajuan tugas untuk  \'<i>{$a->assignment}</i>\' telah tersampaikan.<br /><br /> Anda dapat melihat status <a href="{$a->url}">ajuan tugas</a>.', NULL, 1785718250, NULL, 0, 0),
