	(16703, 'id', 113, 'config_general', 'General settings', 'Setelan umum', NULL, 1785718250, NULL, 0, 0),
	(16704, 'id', 113, 'config_general_description', 'To set up BigBlueButton, you can either use your own BigBlueButton server and credentials, or obtain credentials through the <a href="https://registration-portal.blindsidenetworks.com/" target="_blank">Blindside Networks Registration Portal (opens in a new window)</a>.', 'Untuk menyiapkan BigBlueButton, Anda dapat menggunakan peladen dan kredensial BigBlueButton Anda sendiri, atau mendapatkan kredensial melalui <a href="https://registration-portal.blindsidenetworks.com/" target="_blank">Portal Pendaftaran Jaringan Blindside ( terbuka di jendela baru)</a>.', NULL, 1785718250, NULL, 0, 0),
	(16705, 'id', 113, 'config_profile_picture_enabled', 'Show profile pictures', 'Tampilkan gambar profil', NULL, 1785718250, NULL, 0, 0),
	(16706, 'id', 113, 'config_profile_picture_enabled_description', 'Should profile pictures of participants be shown in BigBlueButton sessions?', 'Haruskah foto profil peserta ditampilkan di sesi BigBlueButton?', NULL, 1785718250, NULL, 0, 0),
	(16707, 'id', 113, 'config_server_url', 'BigBlueButton server URL', 'URL Server BigBlueButton', NULL, 1785718250, NULL, 0, 0),
	(16708, 'id', 113, 'config_server_url_description', 'The URL of your BigBlueButton server.', 'URL server server BigBlueButton Anda', NULL, 1785718250, NULL, 0, 0),
	(16709, 'id', 113, 'config_shared_secret', 'BigBlueButton shared secret', 'Kode rahasia bersama BigBlueButton', NULL, 1785718250, NULL, 0, 0),
	(16710, 'id', 113, 'config_shared_secret_description', 'The security secret of your BigBlueButton server.', 'Rahasia keamanan server BigBlueButton Anda.', NULL, 1785718250, NULL, 0, 0),
	(16711, 'id', 113, 'config_checksum_algorithm', 'BigBlueButton server checksum algorithm', 'Algoritma checksum server BigBlueButton', NULL, 1785718250, NULL, 0, 0),
	(16712, 'id', 113, 'config_checksum_algorithm_description', 'SHA1 is compatible with older servers. SHA256 and SHA512 are more secure. SHA512 is FIPS 140-2 compliant.', 'SHA1 kompatibel dengan server lama. SHA256 dan SHA512 lebih aman. SHA512 sesuai dengan FIPS 140-2.', NULL, 1785718250, NULL, 0, 0),
	(16713, 'id', 113, 'config_recording', 'Recording', 'Merekam', NULL, 1785718250, NULL, 0, 0),
