	(16715, 'id', 113, 'config_recording_default', 'Recording enabled by default', 'Fitur rekam diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16716, 'id', 113, 'config_recording_default_description', 'Should the setting \'Session can be recorded\' be enabled by default when adding a new BigBlueButton room?', 'Haruskah setelan \'Sesi dapat direkam\' diaktifkan secara bawaan saat menambahkan ruang BigBlueButton baru?', NULL, 1785718250, NULL, 0, 0),
	(16717, 'id', 113, 'config_recording_editable', 'Session can be recorded editable', 'Sesi dapat direkam dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16718, 'id', 113, 'config_recording_editable_description', 'Should \'Session can be recorded\' be editable in the BigBlueButton activity settings?', 'Haruskah \'Sesi dapat direkam\' dapat diedit di setelan aktivitas BigBlueButton?', NULL, 1785718250, NULL, 0, 0),
	(16719, 'id', 113, 'config_recording_protect_editable', 'Protected recordings state can be edited', 'Status rekaman yang dilindungi dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16720, 'id', 113, 'config_recording_protect_editable_description', 'If checked the interface includes an option for protecting/unprotecting recordings.', 'Jika dicentang, antarmuka menyertakan opsi untuk melindungi/membuka proteksi rekaman.', NULL, 1785718250, NULL, 0, 0),
	(16721, 'id', 113, 'config_recording_all_from_start_default', 'Start recording from the beginning', 'Rekam semua dari awal', NULL, 1785718250, NULL, 0, 0),
	(16722, 'id', 113, 'config_recording_all_from_start_default_description', 'Should the setting \'Start recording from the beginning\' be enabled by default when adding a new BigBlueButton room?', 'Haruskah setelan \'Mulai merekam dari awal\' diaktifkan secara bawaan saat menambahkan ruang BigBlueButton baru?', NULL, 1785718250, NULL, 0, 0),
	(16723, 'id', 113, 'config_recording_all_from_start_editable', 'Start recording from the beginning editable', 'Mulai merekam dari awal yang dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16724, 'id', 113, 'config_recording_all_from_start_editable_description', 'Should \'Start recording from the beginning\' be editable in the BigBlueButton activity settings?', 'Haruskah \'Mulai merekam dari awal\' dapat diedit di setelan aktivitas BigBlueButton?', NULL, 1785718250, NULL, 0, 0),
	(16725, 'id', 113, 'config_recording_hide_button_default', 'Hide recording button', 'Sembunyikan tombol rekam', NULL, 1785718250, NULL, 0, 0),
	(16726, 'id', 113, 'config_recording_hide_button_default_description', 'If checked the button for record will be hidden', 'Jika dicentang, tombol untuk merekam akan disembunyikan', NULL, 1785718250, NULL, 0, 0),
	(16727, 'id', 113, 'config_recording_hide_button_editable', 'Hide recording button editable', 'Sembunyikan tombol rekam dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16728, 'id', 113, 'config_recording_hide_button_editable_description', 'Should \'Hide recording button\' be editable in the BigBlueButton activity settings?', 'Haruskah \'Sembunyikan tombol perekaman\' dapat diedit di setelan aktivitas BigBlueButton?', NULL, 1785718250, NULL, 0, 0),
	(16729, 'id', 113, 'config_recording_refresh_period', 'Recording refresh period (in seconds)', 'Periode penyegaran perekaman (dalam detik)', NULL, 1785718250, NULL, 0, 0),
	(16730, 'id', 113, 'config_recording_refresh_period_description', 'How often should the BigBlueButton server be queried to refresh remote information for a recording?', 'Seberapa sering server BigBlueButton harus melakukan kueri untuk menyegarkan informasi jarak jauh untuk rekaman?', NULL, 1785718250, NULL, 0, 0),
	(16731, 'id', 113, 'config_recordings', 'Show recordings', 'Tampilkan rekaman', NULL, 1785718250, NULL, 0, 0),
	(16732, 'id', 113, 'config_recordings_description', 'These settings are feature specific', 'Setelan ini khusus untuk fitur', NULL, 1785718250, NULL, 0, 0),
	(16733, 'id', 113, 'config_recordings_general', 'Show recording settings', 'Tampilkan setelan rekam', NULL, 1785718250, NULL, 0, 0),
	(16734, 'id', 113, 'config_recordings_general_description', 'These settings are used only when showing recordings', 'Setelan ini hanya digunakan saat menampilkan rekaman', NULL, 1785718250, NULL, 0, 0),
	(16735, 'id', 113, 'config_recordings_deleted_default', 'Include recordings from deleted activities enabled by default', 'Sertakan rekaman dari aktivitas yang dihapus yang diaktifkan secara bawaan.', NULL, 1785718250, NULL, 0, 0),
	(16736, 'id', 113, 'config_recordings_deleted_default_description', 'If enabled, the recording table will include recordings of any activities which have since been deleted.', 'Jika diaktifkan, tabel perekaman akan menyertakan rekaman milik aktivitas yang dihapus jika ada.', NULL, 1785718250, NULL, 0, 0),
	(16737, 'id', 113, 'config_recordings_deleted_editable', 'Include recordings from deleted activities feature can be edited', 'Sertakan rekaman dari fitur aktivitas yang dihapus dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16738, 'id', 113, 'config_recordings_deleted_editable_description', 'Include recordings from deleted activities by default can be edited when the instance is added or updated.', 'Menyertakan rekaman dari aktivitas yang dihapus secara bawaan dapat diedit saat model ditambahkan atau diperbarui.', NULL, 1785718250, NULL, 0, 0),
	(16739, 'id', 113, 'config_recordings_imported_default', 'Show only imported links enabled by default', 'Tampilkan hanya tautan yang diimpor yang diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16740, 'id', 113, 'config_recordings_imported_default_description', 'If enabled the recording table will include only the imported links to recordings.', 'Jika diaktifkan, tabel perekaman hanya akan menyertakan tautan yang diimpor ke rekaman.', NULL, 1785718250, NULL, 0, 0),
	(16741, 'id', 113, 'config_recordings_imported_editable', 'Show only imported links feature can be edited', 'Tampilkan hanya fitur tautan yang diimpor yang dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16742, 'id', 113, 'config_recordings_imported_editable_description', 'Show only imported links by default can be edited when the instance is added or updated.', 'Tampilkan hanya tautan yang diimpor secara bawaan yang dapat diedit saat model ditambahkan atau diperbarui.', NULL, 1785718250, NULL, 0, 0),
	(16743, 'id', 113, 'config_recordings_preview_default', 'Preview is enabled by default', 'Pratinjau diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16744, 'id', 113, 'config_recordings_preview_default_description', 'If enabled the table includes a preview of the presentation.', 'Jika diaktifkan, tabel menyertakan pratinjau presentasi.', NULL, 1785718250, NULL, 0, 0),
	(16745, 'id', 113, 'config_recordings_preview_editable', 'Preview feature can be edited', 'Fitur pratinjau dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16746, 'id', 113, 'config_recordings_preview_editable_description', 'Preview feature can be edited when the instance is added or updated.', 'Fitur pratinjau dapat diedit saat model ditambahkan atau diperbarui.', NULL, 1785718250, NULL, 0, 0),
	(16747, 'id', 113, 'config_recordings_asc_sort', 'List recordings in chronological order', 'Daftar rekaman dalam urutan kronologis', NULL, 1785718250, NULL, 0, 0),
	(16748, 'id', 113, 'config_recordings_asc_sort_description', 'Recordings are ordered by date, either chronological or reverse chronological order (most recent recording first).', 'Rekaman diurutkan berdasarkan tanggal, baik urutan kronologis atau urutan kronologis terbalik (rekaman terbaru terlebih dahulu).', NULL, 1785718250, NULL, 0, 0),
	(16749, 'id', 113, 'config_recording_safe_formats', 'Recording formats viewable by everyone', 'Format rekaman dapat dilihat oleh semua orang', NULL, 1785718250, NULL, 0, 0),
	(16750, 'id', 113, 'config_recording_safe_formats_description', 'Select the formats which are viewable by everyone.\nAll other formats are only viewable by teachers and other users with the mod/bigbluebuttonbn:viewallrecordingformats and\n mod/bigbluebuttonbn:managerecordings capabilities.', 'Pilih format yang dapat dilihat oleh semua orang. Semua format lain hanya dapat dilihat oleh pengajar dan pengguna lain dengan mod/bigbluebuttonbn:viewallrecordingformats dan mod/bigbluebuttonbn: kelola kemampuan rekaman.', NULL, 1785718250, NULL, 0, 0),
	(16751, 'id', 113, 'config_importrecordings', 'Import recordings', 'Impor rekaman', NULL, 1785718250, NULL, 0, 0),
	(16752, 'id', 113, 'config_importrecordings_description', 'These settings are feature specific.', 'Setelan ini untuk fitur khusus.', NULL, 1785718250, NULL, 0, 0),
	(16753, 'id', 113, 'config_importrecordings_enabled', 'Import recordings enabled', 'Impor rekaman diaktifkan', NULL, 1785718250, NULL, 0, 0),
	(16754, 'id', 113, 'config_importrecordings_enabled_description', 'When this and the recording feature are enabled, it is possible to import recordings from different courses into an activity.', 'Ketika fitur ini dan fitur rekam diaktifkan, dimungkinkan untuk mengimpor rekaman dari kursus yang berbeda ke dalam suatu aktivitas.', NULL, 1785718250, NULL, 0, 0),
	(16755, 'id', 113, 'config_importrecordings_from_deleted_enabled', 'Import recordings from deleted activities enabled', 'Impor rekaman dari aktivitas yang dihapus diaktifkan', NULL, 1785718250, NULL, 0, 0),
	(16756, 'id', 113, 'config_importrecordings_from_deleted_enabled_description', 'When this and the import recording feature are enabled, it is possible to import recordings from activities that are no longer in the course.', 'Ketika fitur ini dan impor rekam diaktifkan, dimungkinkan untuk mengimpor rekaman dari aktivitas yang tidak lagi ada dalam kursus.', NULL, 1785718250, NULL, 0, 0),
	(16757, 'id', 113, 'config_waitformoderator', 'Wait for moderator', 'Tunggu moderator', NULL, 1785718250, NULL, 0, 0),
	(16758, 'id', 113, 'config_waitformoderator_description', 'These settings are feature specific', 'Setelan ini khusus untuk fitur', NULL, 1785718250, NULL, 0, 0),
	(16759, 'id', 113, 'config_waitformoderator_default', 'Wait for moderator enabled by default', 'Tunggu moderator diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16760, 'id', 113, 'config_waitformoderator_default_description', 'Should the setting \'Wait for moderator\' be enabled by default when adding a new BigBlueButton room?', 'Apakah setelan \'Tunggu moderator\' diaktifkan secara bawaan ketika ruang atau konferensi baru ditambahkan.', NULL, 1785718250, NULL, 0, 0),
	(16761, 'id', 113, 'config_waitformoderator_editable', 'Wait for moderator editable', 'Fitur tunggu moderator dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16762, 'id', 113, 'config_waitformoderator_editable_description', 'Should \'Wait for moderator\' be editable in the BigBlueButton activity settings?', 'Haruskah \'Tunggu moderator\' dapat diedit di setelan aktivitas BigBlueButton?', NULL, 1785718250, NULL, 0, 0),
	(16763, 'id', 113, 'config_waitformoderator_ping_interval', 'Wait for moderator ping (seconds)', 'Ping tunggu moderator (detik)', NULL, 1785718250, NULL, 0, 0),
	(16764, 'id', 113, 'config_waitformoderator_ping_interval_description', 'How often should the server be pinged to check if the moderator has entered the room?', 'Seberapa sering server harus di-ping untuk memeriksa apakah moderator telah memasuki ruangan?', NULL, 1785718250, NULL, 0, 0),
	(16765, 'id', 113, 'config_waitformoderator_cache_ttl', 'Wait for moderator cache TTL (seconds)', 'Singgahan tunggu  moderator TTL (detik)', NULL, 1785718250, NULL, 0, 0),
	(16766, 'id', 113, 'config_waitformoderator_cache_ttl_description', 'To support a heavy load of clients this plugin makes use of a cache. This parameter defines the time the cache will be kept before the next request is sent to the BigBlueButton server.', 'Untuk mendukung banyak klien, pengaya ini menggunakan singgahan. Parameter ini menentukan waktu singgahan akan disimpan sebelum permintaan berikutnya dikirim ke server BigBlueButton.', NULL, 1785718250, NULL, 0, 0),
	(16767, 'id', 113, 'config_voicebridge', 'Voice bridge', 'Jembatan suara', NULL, 1785718250, NULL, 0, 0),
	(16768, 'id', 113, 'config_voicebridge_description', 'These settings enable or disable options in the UI and also define default values for these options.', 'Setelan ini mengaktifkan atau menonaktifkan opsi di UI dan juga menentukan nilai bawaan untuk opsi ini.', NULL, 1785718250, NULL, 0, 0),
	(16769, 'id', 113, 'config_voicebridge_editable', 'Conference voice bridge can be edited', 'Jembatan suara konferensi dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16770, 'id', 113, 'config_voicebridge_editable_description', 'A conference voice bridge number can be permanently assigned to a room. When assigned, the number cannot be used for any other room.', 'Nomor penghubung suara konferensi dapat ditetapkan secara permanen ke sebuah ruang. Saat ditetapkan, nomor tersebut tidak dapat digunakan untuk ruang lain mana pun.', NULL, 1785718250, NULL, 0, 0),
	(16771, 'id', 113, 'config_preuploadpresentation', 'Presentation file', 'Berkas presentasi', NULL, 1785718250, NULL, 0, 0),
	(16772, 'id', 113, 'config_preuploadpresentation_description', 'These settings enable or disable options in the UI and also define default values for these options. The feature works only if the Moodle server is accessible to BigBlueButton.', 'Setelan ini mengaktifkan atau menonaktifkan opsi di UI dan juga menentukan nilai bawaan untuk opsi ini. Fitur ini hanya berfungsi jika server Moodle dapat diakses oleh BigBlueButton..', NULL, 1785718250, NULL, 0, 0),
	(16773, 'id', 113, 'config_preuploadpresentation_editable', 'Presentation file on activity page', 'Berkas presentasi di halaman aktivitas', NULL, 1785718250, NULL, 0, 0),
	(16774, 'id', 113, 'config_preuploadpresentation_editable_description', 'Option in activity settings to upload presentation file to show on activity page.', 'Pilihan dalam setelan aktivitas untuk mengunggah berkas presentasi untuk ditampilkan di halaman aktivitas.', NULL, 1785718250, NULL, 0, 0),
	(16775, 'id', 113, 'config_presentation_default', 'Default presentation file', 'Berkas presentasi bawaan', NULL, 1785718250, NULL, 0, 0),
	(16776, 'id', 113, 'config_presentation_default_description', 'A file may be provided for use in all rooms.', 'Berkas dapat disediakan untuk digunakan di semua ruang.', NULL, 1785718250, NULL, 0, 0),
	(16777, 'id', 113, 'config_showpresentation_default', 'Show presentation file on activity page', 'Tampilkan berkas presentasi di halaman aktivitas', NULL, 1785718250, NULL, 0, 0),
	(16778, 'id', 113, 'config_showpresentation_default_description', 'Should students have access to the presentation file before the session? This setting has no effect on users with the capability \'Always see presentation file on activity page\' .', 'Haruskah siswa memiliki akses ke berkas presentasi sebelum sesi? Setelan ini tidak berpengaruh pada pengguna dengan kapabilitas \'Selalu melihat berkas presentasi di halaman aktivitas\'.', NULL, 1785718250, NULL, 0, 0),
	(16779, 'id', 113, 'config_showpresentation_editable', '\'Show presentation file on activity page\' option', 'Opsi \'Tampilkan berkas presentasi di halaman aktivitas\'', NULL, 1785718250, NULL, 0, 0),
	(16780, 'id', 113, 'config_showpresentation_editable_description', 'Option in activity settings for teachers to choose whether to show the presentation file to students.', 'Opsi dalam setelan aktivitas bagi pengajar untuk memilih apakah akan menampilkan berkas presentasi kepada siswa.', NULL, 1785718250, NULL, 0, 0),
	(16781, 'id', 113, 'config_participant', 'Participants', 'Peserta', NULL, 1785718250, NULL, 0, 0),
	(16782, 'id', 113, 'config_participant_description', 'These settings define the default role for participants.', 'Setelan ini menentukan peran bawaan untuk peserta.', NULL, 1785718250, NULL, 0, 0),
	(16783, 'id', 113, 'config_participant_moderator_default', 'Moderator', 'Moderator', NULL, 1785718250, NULL, 0, 0),
	(16784, 'id', 113, 'config_participant_moderator_default_description', 'This rule is used by default when a new room is added.', 'Aturan ini digunakan secara bawaan ketika ruangan baru ditambahkan.', NULL, 1785718250, NULL, 0, 0),
	(16785, 'id', 113, 'config_poll_interval', 'Poll interval (in seconds) to refresh the room\'s status', 'Interval jajak pendapat (dalam detik) untuk menyegarkan status ruangan', NULL, 1785718250, NULL, 0, 0),
	(16786, 'id', 113, 'config_poll_interval_description', 'The poll interval must be at least 2 seconds. If necessary, you can lower the load on the remote server by increasing the interval.', 'Interval jejak pendapat minimal harus 2 detik. Jika perlu, Anda dapat menurunkan beban di server jarak jauh dengan menambah interval.', NULL, 1785718250, NULL, 0, 0),
	(16787, 'id', 113, 'config_userlimit', 'User limit', 'Batas pengguna', NULL, 1785718250, NULL, 0, 0),
	(16788, 'id', 113, 'config_userlimit_description', 'These settings enable or disable options in the UI and also define default values for these options.', 'Setelan ini mengaktifkan atau menonaktifkan opsi di UI dan juga menentukan nilai bawaan untuk opsi ini.', NULL, 1785718250, NULL, 0, 0),
	(16789, 'id', 113, 'config_userlimit_default', 'User limit enabled by default', 'Batas pengguna diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16790, 'id', 113, 'config_userlimit_default_description', 'The number of users allowed in a session by default when a new room is added. Set to 0 to allow an unlimited number of users.', 'Jumlah pengguna yang diizinkan dalam satu sesi secara bawaan saat ruang baru ditambahkan. Setel ke 0 untuk mengizinkan jumlah pengguna yang tidak terbatas.', NULL, 1785718250, NULL, 0, 0),
	(16791, 'id', 113, 'config_userlimit_editable', 'User limit feature can be edited', 'Fitur batas pengguna dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16792, 'id', 113, 'config_userlimit_editable_description', 'User limit value by default can be edited when the room or conference is added or updated.', 'Nilai batas pengguna secara bawaan dapat diedit ketika ruangan atau konferensi ditambahkan atau diperbarui.', NULL, 1785718250, NULL, 0, 0),
	(16793, 'id', 113, 'config_scheduled', 'Scheduled sessions', 'Sesi terjadwal', NULL, 1785718250, NULL, 0, 0),
	(16794, 'id', 113, 'config_scheduled_description', 'These settings define default behaviour for scheduled sessions.', 'Setelan ini menentukan beberapa perilaku secara bawa untuk sesi terjadwal.', NULL, 1785718250, NULL, 0, 0),
	(16795, 'id', 113, 'config_scheduled_pre_opening', 'Accessible before opening time', 'Dapat diakses sebelum jam buka', NULL, 1785718250, NULL, 0, 0),
	(16796, 'id', 113, 'config_scheduled_pre_opening_description', 'The time in minutes that the room is open for prior to the scheduled opening time.', 'Waktu dalam menit saat ruangan dibuka sebelum waktu buka yang dijadwalkan.', NULL, 1785718250, NULL, 0, 0),
	(16797, 'id', 113, 'config_extended_capabilities', 'Extended capabilities', 'Kemampuan yang diperluas', NULL, 1785718250, NULL, 0, 0),
	(16798, 'id', 113, 'config_extended_capabilities_description', 'Configuration for extended capabilities when the BigBlueButton server offers them.', 'Konfigurasi untuk kemampuan yang diperluas saat server BigBlueButton menawarkannya.', NULL, 1785718250, NULL, 0, 0),
	(16799, 'id', 113, 'config_uidelegation_enabled', 'UI delegation is enabled', 'Delegasi UI diaktifkan', NULL, 1785718250, NULL, 0, 0),
	(16800, 'id', 113, 'config_uidelegation_enabled_description', 'These settings enable or disable the UI delegation to the BigBlueButton server.', 'Setelan ini mengaktifkan atau menonaktifkan delegasi UI ke server BigBlueButton.', NULL, 1785718250, NULL, 0, 0),
	(16801, 'id', 113, 'config_recordingready_enabled', 'Send recording available notification', 'Kirim pemberitahuan rekaman yang tersedia', NULL, 1785718250, NULL, 0, 0),
	(16802, 'id', 113, 'config_recordingready_enabled_description', 'If enabled, a notification will be sent when a recording link is available. This feature requires the script post_publish_recording_ready_callback to be enabled on the BigBlueButton server.', 'Jika diaktifkan, pemberitahuan akan dikirim saat tautan rekaman tersedia. Fitur ini mengharuskan skrip post_publish_recording_ready_callback diaktifkan di server BigBlueButton.', NULL, 1785718250, NULL, 0, 0),
	(16803, 'id', 113, 'config_meetingevents_enabled', 'Register live sessions', 'Daftarkan acara langsung', NULL, 1785718250, NULL, 0, 0),
	(16804, 'id', 113, 'config_meetingevents_enabled_description', 'If enabled, live sessions will be processed after the session ends. This feature is required for Activity completion and will only work if the BigBlueButton server is capable of processing post_events scripts.', 'Jika diaktifkan, sesi langsung akan diproses setelah sesi berakhir. Fitur ini diperlukan untuk penyelesaian Aktivitas dan hanya akan berfungsi jika server BigBlueButton mampu memproses skrip post_events.', NULL, 1785718250, NULL, 0, 0),
	(16805, 'id', 113, 'config_warning_curl_not_installed', 'This feature requires the CURL extension for php installed and enabled. The settings will be accessible only if this condition is fulfilled.', 'Fitur ini memerlukan ekstensi CURL yang diaktifkan pada php terpasang. Setelan akan dapat diakses hanya jika kondisi ini terpenuhi.', NULL, 1785718250, NULL, 0, 0),
	(16806, 'id', 113, 'config_warning_bigbluebuttonbn_cfg_deprecated', 'BigBlueButton makes use of config.php with a global variable that has been deprecated. Please convert the file as it will not be supported in future versions.', 'BigBlueButton memanfaatkan config.php dengan variabel global yang sudah tidak digunakan lagi. Harap konversi berkas karena tidak akan didukung di versi mendatang.', NULL, 1785718250, NULL, 0, 0),
	(16807, 'id', 113, 'config_muteonstart', 'Mute on start', 'Bisukan saat Mulai', NULL, 1785718250, NULL, 0, 0),
	(16808, 'id', 113, 'config_muteonstart_description', 'These settings enable or disable options in the UI and also define default values for these options.', 'Setelan ini mengaktifkan atau menonaktifkan opsi di UI dan juga menentukan nilai bawaan untuk opsi ini.', NULL, 1785718250, NULL, 0, 0),
	(16809, 'id', 113, 'config_muteonstart_default', 'Mute on start enabled by default', 'Bisukan saat mulai diaktifkan secara bawaan', NULL, 1785718250, NULL, 0, 0),
	(16810, 'id', 113, 'config_muteonstart_default_description', 'If enabled the session will be muted on start.', 'Jika diaktifkan, sesi akan dibisukan saat mulai.', NULL, 1785718250, NULL, 0, 0),
	(16811, 'id', 113, 'config_muteonstart_editable', 'Mute on start can be edited', 'Bisukan saat mulai dapat diedit', NULL, 1785718250, NULL, 0, 0),
	(16812, 'id', 113, 'config_muteonstart_editable_description', 'Mute on start by default can be edited when the instance is added or updated.', 'Bisukan saat mulai secara bawaan dapat diedit saat model ditambahkan atau diperbarui.', NULL, 1785718250, NULL, 0, 0),
	(16813, 'id', 113, 'config_welcome_default', 'Default welcome message', 'Pesan selamat datang bawaan', NULL, 1785718250, NULL, 0, 0),
	(16814, 'id', 113, 'config_welcome_default_description', 'The welcome message is displayed when participants enter the room. If the field is left blank, the language string \'mod_form_field_welcome_default\' is used.', 'Pesan selamat datang ditampilkan saat peserta memasuki ruangan. Jika kolom dibiarkan kosong, string bahasa \'mod_form_field_welcome_default\' akan digunakan.', NULL, 1785718250, NULL, 0, 0),
	(16815, 'id', 113, 'config_welcome_editable', 'Default welcome message is editable by teachers', 'Pesan selamat datang bawaan dapat diedit oleh pengajar', NULL, 1785718250, NULL, 0, 0),
	(16816, 'id', 113, 'config_welcome_editable_description', 'Welcome message can be edited when the instance is added or updated', 'Pesan selamat datang dapat diedit ketika model ditambahkan atau diperbarui', NULL, 1785718250, NULL, 0, 0),
	(16817, 'id', 113, 'config_default_messages', 'Default messages', 'Pesan bawaan', NULL, 1785718250, NULL, 0, 0),
