	(16870, 'id', 113, 'guestaccess_invite_failure', 'Error {$a->errors} when inviting {$a->emails}.', 'Galat {$a->errors} saat mengundang {$a->emails}.', NULL, 1785718250, NULL, 0, 0),
	(16871, 'id', 113, 'guestaccess_join_meeting', 'Join meeting', 'Gabung rapat', NULL, 1785718250, NULL, 0, 0),
	(16872, 'id', 113, 'guest_invitation_subject', 'Invitation: {$a->name} session in {$a->course_fullname}', 'Undangan: sesi {$a->name} di {$a->course_fullname}', NULL, 1785718250, NULL, 0, 0),
	(16873, 'id', 113, 'guest_invitation_small_message', 'Hi,\n\nYou are invited to a BigBlueButton session {$a->name} in the course {$a->course_fullname}.\n\nLink: {$a->guestjoinurl}\nPassword: {$a->guestpassword}\n\nIf you need help, please contact {$a->sender}.', 'Hai,\n\nAnda diundang ke sesi BigBlueButton {$a->name} dalam kursus {$a->course_fullname}.\n\nTautan: {$a->guestjoinurl}\nKata sandi: {$a->guestpassword}\n\nJika Anda butuh bantuan, silakan hubungi {$a->sender}.', NULL, 1785718250, NULL, 0, 0),
	(16874, 'id', 113, 'guest_invitation_full_message', 'Hi,\n<p>You are invited to a BigBlueButton session <strong>{$a->name}</strong> in the course {$a->course_fullname}.</p>\n<p>Link: {$a->guestjoinurl}<br/>\n<p>Password: {$a->guestpassword}</p>\n<p>If you need help, please contact {$a->sender}.</p>', 'Hai,\n<p>Anda diundang ke sesi BigBlueButton <strong>{$a->name}</strong> dalam kursus {$a->course_fullname}.</p>\n<p>Tautan: {$a->guestjoinurl}<br/>\n<p>Kata sandi: {$a->kata sandi tamu}</p>\n<p>Jika Anda butuh bantuan, harap hubungi {$a->sender}.</p>', NULL, 1785718250, NULL, 0, 0),
	(16875, 'id', 113, 'index_confirm_end', 'Do you want to end the session?', 'Apakah Anda ingin mengakhiri sesi?', NULL, 1785718250, NULL, 0, 0),
