	(17193, 'id', 114, 'chapterandsubchaptersdeleted', 'Chapter "{$a->title}" and its {$a->subchapters} subchapters were deleted', 'Bab "{$a->title}" dan {$a->subchapters} subbabnya telah dihapus', NULL, 1785718251, NULL, 0, 0),
	(17194, 'id', 114, 'chapterdeleted', 'Chapter "{$a->title}" was deleted', 'Bab "{$a->title}" telah dihapus', NULL, 1785718251, NULL, 0, 0),
	(17195, 'id', 114, 'customtitles', 'Custom titles', 'Judul kustom', NULL, 1785718251, NULL, 0, 0),
	(17196, 'id', 114, 'customtitles_help', 'Normally the chapter title is displayed in the table of contents (TOC) AND as a heading above the content.\n\nIf the custom titles checkbox is ticked, the chapter title is NOT displayed as a heading above the content. A different title (perhaps longer than the chapter title) may be entered as part of the content.', 'Biasanya judul bab ditampilkan dalam daftar isi (TOC) DAN sebagai judul di atas konten.\n\nJika kotak centang judul kustom dicentang, judul bab TIDAK ditampilkan sebagai judul di atas konten. Judul yang berbeda (mungkin lebih panjang dari judul bab) dapat dimasukkan sebagai bagian dari konten.', NULL, 1785718251, NULL, 0, 0),
