	(17445, 'id', 116, 'indicator:cognitivedepth_help', 'This indicator is based on the cognitive depth reached by the student in a Choice activity.', 'Indikator ini didasarkan pada kedalaman kognitif yang dicapai siswa dalam suatu aktivitas Pemilihan.', NULL, 1785718251, NULL, 0, 0),
	(17446, 'id', 116, 'indicator:cognitivedepthdef', 'Choice cognitive', 'Pemilihan kognitif', NULL, 1785718251, NULL, 0, 0),
	(17447, 'id', 116, 'indicator:cognitivedepthdef_help', 'The participant has reached this percentage of the cognitive engagement offered by the Choice activities during this analysis interval (Levels = No view, View, Submit, View feedback)', 'Peserta telah mencapai persentase keterlibatan kognitif yang ditawarkan oleh aktivitas Pemilihan selama interval analisis ini (Tingkat = Tidak ada tampilan, Lihat, Kirim, Lihat umpan balik)', NULL, 1785718251, NULL, 0, 0),
	(17448, 'id', 116, 'indicator:cognitivedepthdef_link', 'Learning_analytics_indicators#Cognitive_depth', 'Learning_analytics_indicators#Cognitive_depth', NULL, 1785718251, NULL, 0, 0),
