	(18009, 'id', 118, 'emailteachermailhtml', '<p>{$a->username} has completed feedback activity : <i>\'{$a->feedback}\'</i>.</p>\n<p>It is <a href="{$a->url}">available on the site</a>.</p>', '<p>{$a->username} telah menyelesaikan aktivitas umpan balik : <i>\'{$a->feedback}\'</i>.</p> <p>Ini <a href="{$a- >url}">tersedia di situs</a>.</p>', NULL, 1785718252, NULL, 0, 0),
