	(18616, 'id', 120, 'messageinboundattachmentdisallowed', 'Unable to post your reply, since it includes an attachment and the forum doesn\'t allow attachments.', 'Tidak dapat mengeposkan balasan Anda, karena di dalamnya terdapat lampiran dan forum tidak mengizinkan lampiran.', NULL, 1785718253, NULL, 0, 0),
	(18617, 'id', 120, 'messageinboundfilecountexceeded', 'Unable to post your reply, since it includes more than the maximum number of attachments allowed for the forum ({$a->forum->maxattachments}).', 'Tidak dapat kirimkan balasan Anda, karena ini mencakup lebih dari jumlah maksimum lampiran yang diizinkan untuk forum\n({$a>forum->maxattachments}).', NULL, 1785718253, NULL, 0, 0),
