	(18868, 'id', 120, 'subscribestop', 'I don\'t want to be notified of new posts in this forum', 'Jangan beritahu saya jika terdapat kiriman baru di forum ini', NULL, 1785718253, NULL, 0, 0),
	(18869, 'id', 120, 'subscription', 'Subscription', 'Berlanggganan', NULL, 1785718253, NULL, 0, 0),
	(18870, 'id', 120, 'subscription_help', 'If you are subscribed to a forum it means you will receive notification of new forum posts. Usually you can choose whether you wish to be subscribed, though sometimes subscription is forced so that everyone receives notifications.', 'Jika Anda berlangganan forum, itu artinya Anda akan menerima pemberitahuan jika terdapat kirimanbaru pada forum. Biasanya Anda dapat memilih apakah Anda ingin berlangganan, meskipun terkadang berlangganan dipaksakan agar semua orang menerima pemberitahuan.', NULL, 1785718253, NULL, 0, 0),
	(18871, 'id', 120, 'subscriptionandtracking', 'Subscription and tracking', 'Berlangganan dan pelacakan', NULL, 1785718253, NULL, 0, 0),
	(18872, 'id', 120, 'subscriptionmode', 'Subscription mode', 'Mode berlangganan', NULL, 1785718253, NULL, 0, 0),
	(18873, 'id', 120, 'subscriptionmodeconfirm', 'Are you sure you want to change the subscription mode to {$a}?', 'Yakin ingin mengubah mode berlangganan ke {$a}?', NULL, 1785718253, NULL, 0, 0),
	(18874, 'id', 120, 'subscriptionmode_help', 'When a participant is subscribed to a forum it means they will receive forum post notifications. There are 4 subscription mode options:\n\n* Optional subscription - Participants can choose whether to be subscribed\n* Forced subscription - Everyone is subscribed and cannot unsubscribe\n* Auto subscription - Everyone is subscribed initially but can choose to unsubscribe at any time\n* Subscription disabled - Subscriptions are not allowed', 'Ketika seorang peserta berlangganan ke forum, itu artinya mereka akan menerima pemberitahuan kiriman forum. Ada 4 opsi mode langganan: * Berlangganan opsional - Peserta dapat memilih apakah akan berlangganan * Berlangganan paksa - Semua orang berlangganan dan tidak dapat berhenti berlangganan * Berlangganan otomatis - Semua orang pada awalnya berlangganan tetapi dapat memilih untuk berhenti berlangganan kapan saja * Langganan dinonaktifkan - Langganan tersedia tidak diperbolehkan', NULL, 1785718253, NULL, 0, 0),
	(18875, 'id', 120, 'subscriptionoptional', 'Optional subscription', 'Berlangganan opsional', NULL, 1785718253, NULL, 0, 0),
	(18876, 'id', 120, 'subscriptionforced', 'Forced subscription', 'Berlangganan dipaksakan', NULL, 1785718253, NULL, 0, 0),
	(18877, 'id', 120, 'subscriptionauto', 'Auto subscription', 'Berlangganan otomatis', NULL, 1785718253, NULL, 0, 0),
	(18878, 'id', 120, 'subscriptiondisabled', 'Subscription disabled', 'Berlangganan dinonaktifkan', NULL, 1785718253, NULL, 0, 0),
