	(19127, 'id', 121, 'filtername', 'Glossary auto-linking', 'Tautan otomatis glosarium', NULL, 1785718254, NULL, 0, 0),
	(19128, 'id', 121, 'fullmatch', 'Match whole words only', 'Cocokkan seluruh kata saja', NULL, 1785718254, NULL, 0, 0),
	(19129, 'id', 121, 'fullmatch_help', 'This setting specifies whether only whole words will be linked, for example, a glossary entry named "construct" will not create a link inside the word "constructivism".', 'Setelan ini menentukan apakah hanya seluruh kata yang akan ditautkan, misalnya, entri glosarium bernama "construct" tidak akan membuat tautan di dalam kata "constructivism".', NULL, 1785718254, NULL, 0, 0),
