	(19157, 'id', 121, 'indicator:cognitivedepth', 'Glossary cognitive', 'Glosarium kognitif', NULL, 1785718254, NULL, 0, 0),
	(19158, 'id', 121, 'indicator:cognitivedepth_help', 'This indicator is based on the cognitive depth reached by the student in a Glossary activity.', 'Indikator ini didasarkan pada kedalaman kognitif yang dicapai siswa dalam aktivitas Glosarium.', NULL, 1785718254, NULL, 0, 0),
	(19159, 'id', 121, 'indicator:cognitivedepthdef', 'Glossary cognitive', 'Glosarium kognitif', NULL, 1785718254, NULL, 0, 0),
	(19160, 'id', 121, 'indicator:cognitivedepthdef_help', 'The participant has reached this percentage of the cognitive engagement offered by the Glossary activities during this analysis interval (Levels = No view, View, Submit)', 'Peserta telah mencapai persentase keterlibatan kognitif yang ditawarkan oleh aktivitas Daftar Istilah selama interval analisis ini (Tingkat = Tidak ada tampilan, Lihat, Kirim)', NULL, 1785718254, NULL, 0, 0),
	(19161, 'id', 121, 'indicator:cognitivedepthdef_link', 'Learning_analytics_indicators#Cognitive_depth', 'Learning_analytics_indicators#Cognitive_depth', NULL, 1785718254, NULL, 0, 0),
	(19162, 'id', 121, 'indicator:socialbreadth', 'Glossary social', 'Glosarium sosial', NULL, 1785718254, NULL, 0, 0),
	(19163, 'id', 121, 'indicator:socialbreadth_help', 'This indicator is based on the social breadth reached by the student in a Glossary activity.', 'Indikator ini didasarkan pada keluasan sosial yang dicapai siswa dalam kegiatan Glosarium.', NULL, 1785718254, NULL, 0, 0),
	(19164, 'id', 121, 'indicator:socialbreadthdef', 'Glossary social', 'Glosarium sosial', NULL, 1785718254, NULL, 0, 0),
	(19165, 'id', 121, 'indicator:socialbreadthdef_help', 'The participant has reached this percentage of the social engagement offered by the Glossary activities during this analysis interval (Levels = No participation, Participant alone)', 'Peserta telah mencapai persentase keterlibatan sosial yang ditawarkan oleh kegiatan Daftar Istilah selama interval analisis ini (Tingkat = Tidak ada partisipasi, Peserta saja)', NULL, 1785718254, NULL, 0, 0),
	(19166, 'id', 121, 'indicator:socialbreadthdef_link', 'Learning_analytics_indicators#Social_breadth', 'Learning_analytics_indicators#Social_breadth', NULL, 1785718254, NULL, 0, 0),
	(19167, 'id', 121, 'isglobal', 'Is this glossary global?', 'Apakah glosarium ini bersifat global?', NULL, 1785718254, NULL, 0, 0),
	(19168, 'id', 121, 'isglobal_help', 'A global glossary has entries which are linked to from throughout the site, rather than only in the course that the glossary is in. Only administrators can set a glossary as global.', 'Glosarium global memiliki entri yang ditautkan dari seluruh situs, bukan hanya di jalur glosarium tersebut. Hanya administrator yang dapat menetapkan glosarium sebagai global.', NULL, 1785718254, NULL, 0, 0),
	(19169, 'id', 121, 'letter', 'letter', 'surat', NULL, 1785718254, NULL, 0, 0),
	(19170, 'id', 121, 'linkcategory', 'Automatically link this category', 'Tautkan kategori ini secara otomatis', NULL, 1785718254, NULL, 0, 0),
	(19171, 'id', 121, 'linkcategory_help', 'If glossary auto-linking has been enabled and this setting is enabled, the category name will be automatically linked wherever it appears throughout the rest of the course. When a participant follows a category name link, they will be taken to the "Browse by category" page of the glossary.', 'Jika penautan otomatis glosarium telah diaktifkan dan setelan ini diaktifkan, nama kategori akan ditautkan secara otomatis di mana pun ia muncul di sepanjang sisa kursus. Ketika seorang peserta mengikuti tautan nama kategori, mereka akan dibawa ke halaman "Jelajahi menurut kategori" dari glosarium.', NULL, 1785718254, NULL, 0, 0),
	(19172, 'id', 121, 'linking', 'Auto-linking', 'Tautan otomatis', NULL, 1785718254, NULL, 0, 0),
