	(19535, 'id', 125, 'configslideshowbgcolor', 'Background colour for the slideshow if it is enabled', 'Warna latar belakang untuk tayangan salindia jika diaktifkan', NULL, 1785718254, NULL, 0, 0),
	(19536, 'id', 125, 'configslideshowheight', 'Sets the height of the slideshow if it is enabled', 'Setel ketinggian tayangan salindia jika diaktifkan', NULL, 1785718254, NULL, 0, 0),
