	(19614, 'id', 125, 'eolstudentoutoftimenoanswers', 'You did not answer any questions.  You have received a 0 for this lesson.', 'Anda tidak menjawab soal apapun. Nilai Anda 0 untuk pelajaran ini.', NULL, 1785718254, NULL, 0, 0),
	(19615, 'id', 125, 'essay', 'Essay', 'Essai', NULL, 1785718254, NULL, 0, 0),
	(19616, 'id', 125, 'essayemailmessage2', '<p>Essay prompt: {$a->question}</p><p>Your response: <em>{$a->response}</em></p><p>Grader\'s comments: <em>{$a->comment}</em></p><p>You have received {$a->earned} out of {$a->outof} for this essay question.</p><p>Your grade for the {$a->lesson} lesson has been changed to {$a->newgrade}&#37;.</p>', '<p>Permintaan esai: {$a->question}</p><p>Tanggapan Anda: <em>{$a->response}</em></p><p>Komentar siswa: <em> {$a->comment}</em></p><p>Anda telah menerima {$a->earned} dari {$a->outof} untuk pertanyaan esai ini.</p><p>Anda nilai untuk pelajaran {$a->lesson} telah diubah menjadi {$a->newgrade}%.</p>', NULL, 1785718254, NULL, 0, 0),
	(19617, 'id', 125, 'essayemailmessagesmall', '<p>You have received {$a->earned} out of {$a->outof} for this essay question.</p><p>Your grade for the {$a->lesson} lesson has been changed to {$a->newgrade}&#37;.</p>', '<p>Anda telah menerima {$a->earned} dari {$a->outof} untuk pertanyaan esai ini.</p><p>Nilai Anda untuk pelajaran {$a->lesson} telah diubah menjadi {$a->newgrade}%.</p>', NULL, 1785718254, NULL, 0, 0),
