	(19741, 'id', 125, 'minimumnumberofquestions', 'Minimum number of questions', 'Jumllah minimum soal', NULL, 1785718254, NULL, 0, 0),
	(19742, 'id', 125, 'minimumnumberofquestions_help', 'This setting specifies the minimum number of questions that will be used to calculate a grade for the activity.', 'Setelan ini menentukan jumlah soal minimum yang akan digunakan untuk menghitung nilai aktivitas.', NULL, 1785718254, NULL, 0, 0),
