	(19793, 'id', 125, 'notenoughtimespent', 'You completed this lesson in {$a->timespent}, which is less than the required time of {$a->timerequired}. You might need to attempt the lesson again.', 'Anda menyelesaikan pelajaran ini dalam {$a->timespent}, yang kurang dari waktu yang dibutuhkan {$a->timerequired}. Anda mungkin perlu mengerjakan pelajaran lagi.', NULL, 1785718254, NULL, 0, 0),
