	(20065, 'id', 126, 'contentitem_deeplinking', 'Supports Deep Linking (Content-Item Message)', 'Mendukung Deep Linking (Pesan Konten-Item)', NULL, 1785718255, NULL, 0, 0),
	(20066, 'id', 126, 'contentitem_deeplinking_help', 'If ticked, the option \'Select content\' will be available when adding an external tool.', 'Jika dicentang, opsi \'Pilih konten\' akan tersedia saat menambahkan alat eksternal.', NULL, 1785718255, NULL, 0, 0),
