	(20110, 'id', 126, 'dynreg_update_text', 'There are existing tools attached to the registration\'s domain. Do you want to update an already installed\nexternal tool or create a new external tool?', 'Ada alat yang sudah ada yang melekat pada domain pendaftaran. Apakah Anda ingin memperbarui alat eksternal yang sudah diinstal atau membuat alat eksternal baru?', NULL, 1785718255, NULL, 0, 0),
	(20111, 'id', 126, 'dynreg_update_warn_dupdomain', 'It is not recommended to have multiple external tools under the same domain.', 'Tidak disarankan untuk memiliki beberapa alat eksternal di bawah domain yang sama.', NULL, 1785718255, NULL, 0, 0),
	(20112, 'id', 126, 'dynreg_update_name', 'Tool name', 'Nama alat', NULL, 1785718255, NULL, 0, 0),
