	(20557, 'id', 128, 'attempttitle', '{$a}', '{$a}', NULL, 1785718256, NULL, 0, 0),
	(20558, 'id', 128, 'attempttitlepaged', '{$a->name} (page {$a->currentpage} of {$a->totalpages})', '{$a->name} (page {$a->currentpage} of {$a->totalpages})', NULL, 1785718256, NULL, 0, 0),
	(20559, 'id', 128, 'autosaveperiod', 'Auto-save delay', 'Jeda penyimpanan otomatis', NULL, 1785718256, NULL, 0, 0),
	(20560, 'id', 128, 'autosaveperiod_desc', 'Responses can be saved automatically during quiz attempts. The responses are saved whenever one is changed, and then after this delay. There is a trade-off: a shorter delay increases the server load, but reduces the chance that students lose their work. If you are going to make this delay much shorter, you should change the value gradually and monitor the server load. If the load gets too high, make the delay longer again. Setting the delay to 0 turns off auto-saving.', 'Jawaban disimpan secara otomatis ketika mengerjakan kuis. Jawaban tersimpan setiap kali ada perubahan,  dan kemudian setelah penundaan ini. Ada pertukaran: penundaan yang lebih singkat meningkatkan beban server, tetapi mengurangi kemungkinan siswa kehilangan pekerjaan mereka. Jika Anda ingin membuat penundaan ini lebih pendek, Anda harus mengubah nilainya secara bertahap dan memonitor beban server. Jika beban terlalu tinggi, buat penundaan lebih lama lagi. Mengatur penundaan ke 0 mematikan penyimpanan otomatis.', NULL, 1785718256, NULL, 0, 0),
	(20561, 'id', 128, 'back', 'Back to preview question', 'Kembali ke soal pratinjau', NULL, 1785718256, NULL, 0, 0),
	(20562, 'id', 128, 'backtocourse', 'Back to the course', 'Kembali ke kursus', NULL, 1785718256, NULL, 0, 0),
	(20563, 'id', 128, 'backtoquestionlist', 'Back to question list', 'Kembali ke daftar soal', NULL, 1785718256, NULL, 0, 0),
	(20564, 'id', 128, 'backtoquiz', 'Back to quiz editing', 'Kembali mengedit kuis', NULL, 1785718256, NULL, 0, 0),
	(20565, 'id', 128, 'bestgrade', 'Best grade', 'Nilai terbaik', NULL, 1785718256, NULL, 0, 0),
	(20566, 'id', 128, 'bothattempts', 'Show students with and without attempts', 'Tampilkan siswa yang sudah mengerjakan atau pun belum', NULL, 1785718256, NULL, 0, 0),
	(20567, 'id', 128, 'browsersecurity', 'Browser security', 'Keamanan peramban web', NULL, 1785718256, NULL, 0, 0),
	(20568, 'id', 128, 'browsersecurity_help', 'If "Full screen pop-up with some JavaScript security" is selected,\n\n* The quiz will only start if the student has a JavaScript-enabled web-browser\n* The quiz appears in a full screen popup window that covers all the other windows and has no navigation controls\n* Students are prevented, as far as is possible, from using facilities like copy and paste', 'Jika "Layar penuh sembulan dengan beberapa keamanan JavaScript" dipilih, * Kuis hanya akan dimulai jika siswa memiliki peramban web yang mengaktifkan JavaScript * Kuis muncul di jendela sembulan layar penuh yang mencakup semua jendela lain dan memiliki tidak ada kontrol navigasi * Sedapat mungkin siswa dilarang menggunakan fasilitas seperti salin dan tempel', NULL, 1785718256, NULL, 0, 0),
	(20569, 'id', 128, 'cachedef_overrides', 'User and group override information', 'Informasi penyampingan pengguna dan grup', NULL, 1785718256, NULL, 0, 0),
	(20570, 'id', 128, 'calculated', 'Calculated', 'Perhitungan', NULL, 1785718256, NULL, 0, 0),
	(20571, 'id', 128, 'calculatedquestion', 'Calculated question not supported at line {$a}. The question will be ignored', 'Soal perhitungan pada baris {$a} tidak didukung. Soal akan diabaikan', NULL, 1785718256, NULL, 0, 0),
	(20572, 'id', 128, 'cannotcreatepath', 'Path cannot be created ({$a})', 'Jalur tidak dapat dibuat ({$a})', NULL, 1785718256, NULL, 0, 0),
	(20573, 'id', 128, 'cannoteditafterattempts', 'You cannot add or remove questions because this quiz has been attempted. ({$a})', 'Anda tidak dapat menambah atau menghapus soal yang telah dikerjakan ({$a})', NULL, 1785718256, NULL, 0, 0),
	(20574, 'id', 128, 'cannotfindprevattempt', 'Cannot find previous attempt to build on.', 'Hasil pengerjaan kuis sebelumnya tidak ditemukan.', NULL, 1785718256, NULL, 0, 0),
	(20575, 'id', 128, 'cannotfindquestionregard', 'Failed to get questions for regrading!', 'Gagal mendapatkan soal untuk dinilai ulang!', NULL, 1785718256, NULL, 0, 0),
	(20576, 'id', 128, 'cannotinsert', 'Cannot insert question', 'Tidak dapat menyisipkan soal', NULL, 1785718256, NULL, 0, 0),
	(20577, 'id', 128, 'cannotinsertrandomquestion', 'Could not insert new random question!', 'Tidak dapat memasukkan soal acak', NULL, 1785718256, NULL, 0, 0),
	(20578, 'id', 128, 'cannotloadquestion', 'Could not load question options', 'Tidak dapat memuat opsi soal', NULL, 1785718256, NULL, 0, 0),
	(20579, 'id', 128, 'cannotloadtypeinfo', 'Unable to load questiontype specific question information', 'Tidak dapat memuat informasi khusus mengenai jenis soal', NULL, 1785718256, NULL, 0, 0),
	(20580, 'id', 128, 'cannotopen', 'Cannot open export file ({$a})', 'Tidak dapat membuka berkas ekspor ({$a})', NULL, 1785718256, NULL, 0, 0),
	(20581, 'id', 128, 'cannotremoveallsectionslots', 'You have selected all questions under the \'{$a}\' section heading. It is not allowed to remove all questions under a section heading.', 'Anda telah memilih semua soal di bawah judul bagian \'{$a}\'. Tidak diperbolehkan untuk menghapus semua soal di bawah judul bagian.', NULL, 1785718256, NULL, 0, 0),
	(20582, 'id', 128, 'cannotremoveslots', 'Cannot remove questions', 'Tidak dapat menghapus soal', NULL, 1785718256, NULL, 0, 0),
	(20583, 'id', 128, 'cannotrestore', 'Could not restore question sessions', 'Tidak dapat memulihkan sesi soal', NULL, 1785718256, NULL, 0, 0),
	(20584, 'id', 128, 'cannotreviewopen', 'You cannot review this attempt, it is still open.', 'Anda tidak dapat mereviu pengerjaan kuis ini karena masih dikerjakan.', NULL, 1785718256, NULL, 0, 0),
	(20585, 'id', 128, 'cannotsavelayout', 'Could not save layout', 'Tidak dapat menyimpan tata letak', NULL, 1785718256, NULL, 0, 0),
	(20586, 'id', 128, 'cannotsavenumberofquestion', 'Could not save number of questions per page', 'Tidak dapat menyimpan jumlah soal per halaman', NULL, 1785718256, NULL, 0, 0),
	(20587, 'id', 128, 'cannotsavequestion', 'Cannot save question list', 'Tidak dapat menyimpan daftar soal', NULL, 1785718256, NULL, 0, 0),
	(20588, 'id', 128, 'cannotsetgrade', 'Could not set a new maximum grade for the quiz', 'Tidak dapat menyetel nilai maksimum baru untuk kuis', NULL, 1785718256, NULL, 0, 0),
	(20589, 'id', 128, 'cannotsetsumgrades', 'Failed to set sumgrades', 'gagal untuk menyetel jumlah', NULL, 1785718256, NULL, 0, 0),
	(20590, 'id', 128, 'cannotstartgradesmismatch', 'Cannot start an attempt at this quiz. The quiz is set to be graded out of {$a->grade}, but none of the questions in the quiz have a grade. This can be fixed on the \'Edit quiz\' page.', 'Tidak dapat mulai mengerjakan kuis ini. Kuis disetel untuk dinilai dari {$a->grade}, tetapi tidak ada soal dalam kuis yang memiliki nilai. Ini dapat diperbaiki pada halaman \'Edit kuis\'.', NULL, 1785718256, NULL, 0, 0),
	(20591, 'id', 128, 'cannotstartmissingquestion', 'Cannot start an attempt at this quiz. The quiz definition includes a question that does not exist.', 'Tidak dapat mulai mengerjakan kuis ini. Definisi kuis mencakup soal yang tidak ada.', NULL, 1785718256, NULL, 0, 0),
	(20592, 'id', 128, 'cannotstartnoquestions', 'Cannot start an attempt at this quiz. The quiz has not been set up yet. No questions have been added.', 'Tidak dapat mulai mengerjakan kuis ini. Kuis belum disiapkan. Belum ada soal.', NULL, 1785718256, NULL, 0, 0),
	(20593, 'id', 128, 'cannotwrite', 'Cannot write to export file ({$a})', 'Tidak dapat menulis untuk mengekspor berkas ({$a})', NULL, 1785718256, NULL, 0, 0),
	(20594, 'id', 128, 'canredoquestions', 'Allow redo within an attempt', 'Izinkan mengulang ketika mengerjakan', NULL, 1785718256, NULL, 0, 0),
	(20595, 'id', 128, 'canredoquestions_desc', 'If enabled, after finishing attempting a question, a \'Try another question like this one\' button is displayed. This allows for a similar question (selected randomly) to be attempted, or the same question again, without the entire quiz attempt having to be submitted and another attempt started. This option is useful for practice quizzes.\n\nThis setting only affects questions and behaviours (such as immediate feedback or interactive with multiple tries) where it is possible to finish a question before the attempt is submitted.', 'Jika diaktifkan, setelah selesai mengerjakan soal, tombol \'Coba soal lain seperti ini\' akan ditampilkan. Hal ini memungkinkan soal serupa (dipilih secara acak) mengerjakan kembali soal tanpa harus mengawali dari awal kuis. Opsi ini berguna untuk latihan kuis. Setelan ini hanya memengaruhi soal dan perilaku (seperti umpan balik langsung atau interaktif dengan beberapa upaya pengerjaan kuis) di mana dimungkinkan untuk menyelesaikan soal sebelum hasil pengerjaan kuis diserahkan.', NULL, 1785718256, NULL, 0, 0),
	(20596, 'id', 128, 'canredoquestions_help', 'If enabled, after finishing attempting a question, a \'Try another question like this one\' button is displayed. This allows for a similar question (selected randomly) to be attempted, or the same question again, without the entire quiz attempt having to be submitted and another attempt started. This option is useful for practice quizzes.\n\nThis setting only affects questions and behaviours (such as immediate feedback or interactive with multiple tries) where it is possible to finish a question before the attempt is submitted.', 'Jika diaktifkan, setelah selesai mengerjakan soal, tombol \'Coba soal lain seperti ini\' akan ditampilkan. Hal ini memungkinkan soal serupa (dipilih secara acak) mengerjakan kembali soal tanpa harus mengawali dari awal kuis. Opsi ini berguna untuk latihan kuis. Setelan ini hanya memengaruhi soal dan perilaku (seperti umpan balik langsung atau interaktif dengan beberapa upaya pengerjaan kuis) di mana dimungkinkan untuk menyelesaikan soal sebelum hasil pengerjaan kuis diserahkan.', NULL, 1785718256, NULL, 0, 0),
	(20597, 'id', 128, 'canredoquestionsyes', 'Yes, provide the option to try another question', 'Ya, berikan opsi untuk mencoba soal lain', NULL, 1785718256, NULL, 0, 0),
	(20598, 'id', 128, 'caseno', 'No, case is unimportant', 'Tidak, huruf besar/kecil tidak masalah', NULL, 1785718256, NULL, 0, 0),
	(20599, 'id', 128, 'casesensitive', 'Case sensitivity', 'Penulisan huruf besar/kecil berpengaruh', NULL, 1785718256, NULL, 0, 0),
	(20600, 'id', 128, 'caseyes', 'Yes, case must match', 'Ya, huruf besar/kecil harus cocok', NULL, 1785718256, NULL, 0, 0),
	(20601, 'id', 128, 'categoryadded', 'The category \'{$a}\' was added', 'Kategori \'{$a}\' telah ditambahkan', NULL, 1785718256, NULL, 0, 0),
	(20602, 'id', 128, 'categorydeleted', 'The category \'{$a}\' was deleted', 'Kategori \'{$a}\' telah dihapus', NULL, 1785718256, NULL, 0, 0),
	(20603, 'id', 128, 'categorynoedit', 'You do not have editing privileges in the category \'{$a}\'.', 'Anda tidak memiliki hak mengedit kategori \'{$a}\'.', NULL, 1785718256, NULL, 0, 0),
	(20604, 'id', 128, 'categoryupdated', 'The category was successfully updated', 'Kategori berhasil diperbarui', NULL, 1785718256, NULL, 0, 0),
	(20605, 'id', 128, 'close', 'Close window', 'Tutup jendela', NULL, 1785718256, NULL, 0, 0),
	(20606, 'id', 128, 'closed', 'Closed', 'Ditutup', NULL, 1785718256, NULL, 0, 0),
	(20607, 'id', 128, 'closebeforeopen', 'The close date must be after the open date.', 'Tanggal penutupan harus setelah tanggal pembukaan.', NULL, 1785718256, NULL, 0, 0),
	(20608, 'id', 128, 'closepreview', 'Close preview', 'Tutup pratinjau', NULL, 1785718256, NULL, 0, 0),
