	(20684, 'id', 128, 'decimalplaces_help', 'This setting specifies the number of digits shown after the decimal point when displaying grades. It only affects the display of grades, not the grades stored in the database, nor the internal calculations, which are carried out to full accuracy.', 'Setelan ini menentukan jumlah digit ditampilkan setelah titik desimal ketika menampilkan nilai. Hanya mempengaruhi tampilan nilai, bukan nilai yang disimpan dalam basis data, maupun perhitungan internal, yang dilakukan untuk akurasi penuh.', NULL, 1785718256, NULL, 0, 0),
	(20685, 'id', 128, 'decimalplacesquestion', 'Decimal places in marks for questions', 'Jumlah digit desimal soal', NULL, 1785718256, NULL, 0, 0),
	(20686, 'id', 128, 'decimalplacesquestion_help', 'The number of digits shown after the decimal point when displaying the marks for individual questions.', 'Jumlah digit yang ditampilkan setelah titik desimal saat menampilkan tanda untuk masing-masing soal.', NULL, 1785718256, NULL, 0, 0),
