	(20691, 'id', 128, 'delaylater', 'Enforced delay between later attempts', 'Penundaan paksa antara pengerjaan kuis selanjutnya', NULL, 1785718256, NULL, 0, 0),
	(20692, 'id', 128, 'delaylater_help', 'If enabled, a student must wait for the specified time to elapse before attempting the quiz a third time and any subsequent times.', 'Jika diaktifkan, siswa harus menunggu waktu yang ditentukan berlalu sebelum mengerjakan kuis untuk ketiga kalinya dan berikutnya.', NULL, 1785718256, NULL, 0, 0),
