	(20865, 'id', 128, 'guestsno', 'Sorry, guests cannot see or attempt quizzes', 'Maaf, tamu tidak diperbolehkan menjawab kuis', NULL, 1785718256, NULL, 0, 0),
	(20866, 'id', 128, 'hidebreaks', 'Hide page breaks', 'Sembunyikan jeda halaman', NULL, 1785718256, NULL, 0, 0),
