	(20963, 'id', 128, 'navnojswarning', 'Warning: these links will not save your answers. Use the next button at the bottom of the page.', 'Peringatan: tautan ini tidak akan menyimpan jawaban Anda. Gunakan tombol berikutnya di bagian bawah halaman.', NULL, 1785718256, NULL, 0, 0),
	(20964, 'id', 128, 'neverallononepage', 'Never, all questions on one page', 'Tidak pernah, semua soal dalam satu halaman', NULL, 1785718256, NULL, 0, 0),
