	(21019, 'id', 128, 'openafterclose', 'Could not update the quiz. You have specified an open date after the close date.', 'Tidak dapat memperbarui kuis. Anda telah menentukan tanggal buka setelah tanggal tutup.', NULL, 1785718256, NULL, 0, 0),
