	(21560, 'id', 129, 'selectmainfile', 'Please select the main file by clicking the icon next to file name.', 'Silakan pilih berkas utama dengan mengklik ikon di sebelah nama berkas.', NULL, 1785718257, NULL, 0, 0),
	(21561, 'id', 129, 'showdate', 'Show upload/modified date', 'Tampilkan tanggal unggah/modifikasi', NULL, 1785718257, NULL, 0, 0),
	(21562, 'id', 129, 'showdate_desc', 'Display upload/modified date on course page?', 'Tampilkan tanggal unggah/modifikasi pada halaman kursus?', NULL, 1785718257, NULL, 0, 0),
	(21563, 'id', 129, 'showdate_help', 'Displays the upload/modified date beside links to the file.\n\nIf there are multiple files in this resource, the start file upload/modified date is displayed.', 'Menampilkan tanggal unggah/modifikasi di samping tautan ke berkas.\n\nJika ada beberapa berkas dalam sumber ini, tanggal mulai upload/modifikasi berkas akan ditampilkan.', NULL, 1785718257, NULL, 0, 0),
	(21564, 'id', 129, 'showsize', 'Show size', 'Tampilkan ukuran', NULL, 1785718257, NULL, 0, 0),
	(21565, 'id', 129, 'showsize_help', 'Displays the file size, such as \'3.1 MB\', beside links to the file.\n\nIf there are multiple files in this resource, the total size of all files is displayed.', 'Menampilkan ukuran berkas, seperti \'3.1 MB\', di samping tautan ke berkas.\n\nJika ada beberapa berkas dalam sumber ini, ukuran total semua berkas akan ditampilkan.', NULL, 1785718257, NULL, 0, 0),
	(21566, 'id', 129, 'showsize_desc', 'Display file size on course page?', 'Tampilkan ukuran berkas di halaman kursus?', NULL, 1785718257, NULL, 0, 0),
	(21567, 'id', 129, 'showtype', 'Show type', 'Tampilkan jenis', NULL, 1785718257, NULL, 0, 0),
	(21568, 'id', 129, 'showtype_desc', 'Display file type (e.g. \'Word document\') on course page?', 'Tampilkan jenis berkas (mis. \'Dokumen Word\') di halaman kursus?', NULL, 1785718257, NULL, 0, 0),
	(21569, 'id', 129, 'showtype_help', 'Displays the type of the file, such as \'Word document\', beside links to the file.\n\nIf there are multiple files in this resource, the start file type is displayed.\n\nIf the file type is not known to the system, it will not display.', 'Menampilkan jenis berkas, seperti \'dokumen Word\', di samping tautan ke berkas.\n\nJika ada beberapa berkas dalam sumber ini, jenis berkas awal akan ditampilkan.\n\nJika jenis berkas tidak diketahui oleh sistem, itu tidak akan ditampilkan.', NULL, 1785718257, NULL, 0, 0),
	(21570, 'id', 129, 'uploadeddate', 'Uploaded {$a}', 'Diunggah {$a}', NULL, 1785718257, NULL, 0, 0),
