	(21573, 'id', 130, 'aicchacptimeout', 'AICC HACP timeout', 'Batas waktu AICC HACP', NULL, 1785718257, NULL, 0, 0),
	(21574, 'id', 130, 'aicchacptimeout_desc', 'Length of time in minutes that an external AICC HACP session can remain open', 'Durasi waktu dalam menit agar sesi HACP AICC eksternal dapat tetap terbuka', NULL, 1785718257, NULL, 0, 0),
	(21575, 'id', 130, 'aicchacpkeepsessiondata', 'AICC HACP session data', 'Data sesi AICC HACP', NULL, 1785718257, NULL, 0, 0),
	(21576, 'id', 130, 'aicchacpkeepsessiondata_desc', 'Length of time in days to keep the external AICC HACP session data (a high setting will fill up the table with old data but may be useful when debugging)', 'Lamanya waktu dalam hari untuk menyimpan data sesi AICC HACP eksternal (setelan tinggi akan mengisi tabel dengan data lama tetapi mungkin berguna saat awakutu)', NULL, 1785718257, NULL, 0, 0),
	(21577, 'id', 130, 'aiccuserid', 'AICC pass numeric user id', 'ID pengguna AICC', NULL, 1785718257, NULL, 0, 0),
	(21578, 'id', 130, 'aiccuserid_desc', 'The AICC standard for usernames is very restrictive compared with Moodle, and allows for alphanumeric characters, dash and underscore only. Periods, spaces and the @ symbol are not permitted. If enabled, user ID numbers are passed to the AICC package instead of usernames.', 'Standar AICC untuk nama pengguna sangat ketat dibandingkan dengan Moodle, dan memungkinkan karakter alfanumerik, tanda hubung, dan garis bawah saja. Titik, spasi, dan simbol @ tidak diizinkan. Jika diaktifkan, nomor ID pengguna diteruskan ke paket AICC alih-alih nama pengguna.', NULL, 1785718257, NULL, 0, 0),
	(21579, 'id', 130, 'activation', 'Activation', 'Aktivasi', NULL, 1785718257, NULL, 0, 0),
	(21580, 'id', 130, 'activityloading', 'You will be automatically redirected to the activity in', 'Anda akan secara otomatis dialihkan ke dalam aktivitas', NULL, 1785718257, NULL, 0, 0),
