	(21588, 'id', 130, 'allowtypeexternal', 'Enable external package type', 'Aktifkan jenis paket eksternal', NULL, 1785718257, NULL, 0, 0),
	(21589, 'id', 130, 'allowtypeexternalaicc', 'Enable direct AICC URL', 'Aktifkan URL AICC langsung', NULL, 1785718257, NULL, 0, 0),
	(21590, 'id', 130, 'allowtypeexternalaicc_desc', 'If enabled this allows a direct url to a simple AICC package', 'Jika diaktifkan, ini memungkinkan url langsung ke paket AICC sederhana', NULL, 1785718257, NULL, 0, 0),
	(21591, 'id', 130, 'allowtypelocalsync', 'Enable downloaded package type', 'Aktifkan jenis paket yang diunduh', NULL, 1785718257, NULL, 0, 0),
