	(21608, 'id', 130, 'autocommit', 'Auto-commit', 'Auto-commit', NULL, 1785718257, NULL, 0, 0),
	(21609, 'id', 130, 'autocommit_help', 'If enabled, SCORM data is automatically saved to the database. This is useful for SCORM objects which do not save their data regularly.', 'Jika diaktifkan, data SCORM akan otomatis tersimpan ke dalam basis data. Hal ini berguna untuk objek SCORM yang tidak menyimpan datanya secara berkala.', NULL, 1785718257, NULL, 0, 0),
	(21610, 'id', 130, 'autocommitdesc', 'Automatically save SCORM data if the SCORM package does not save it.', 'Secara otomatis menyimpan data SCORM jika paket SCORM tidak menyimpannya.', NULL, 1785718257, NULL, 0, 0),
	(21611, 'id', 130, 'autocontinue', 'Auto-continue', 'Melanjutkan otomatis', NULL, 1785718257, NULL, 0, 0),
	(21612, 'id', 130, 'autocontinue_help', 'If enabled, subsequent learning objects are launched automatically, otherwise the Continue button must be used.', 'Jika diaktifkan, objek pembelajaran berikutnya diluncurkan secara otomatis, jika tidak, tombol Lanjutkan harus digunakan.', NULL, 1785718257, NULL, 0, 0),
	(21613, 'id', 130, 'autocontinuedesc', 'If enabled, subsequent learning objects are launched automatically, otherwise the Continue button must be used.', 'Jika diaktifkan, objek pembelajaran berikutnya diluncurkan secara otomatis, jika tidak, tombol Lanjutkan harus digunakan.', NULL, 1785718257, NULL, 0, 0),
