	(21718, 'id', 130, 'gradeaverage', 'Average grade', 'Nilai rata-rata', NULL, 1785718257, NULL, 0, 0),
	(21719, 'id', 130, 'gradeforattempt', 'Grade for attempt', 'Nilai untuk upaya', NULL, 1785718257, NULL, 0, 0),
	(21720, 'id', 130, 'gradehighest', 'Highest grade', 'Nilai tertinggi', NULL, 1785718257, NULL, 0, 0),
	(21721, 'id', 130, 'grademethod', 'Grading method', 'Metode penilaian', NULL, 1785718257, NULL, 0, 0),
	(21722, 'id', 130, 'grademethod_help', 'The grading method defines how the grade for a single attempt of the activity is determined.\n\nThere are 4 grading methods:\n\n* Learning objects - The number of completed/passed learning objects\n* Highest grade - The highest score obtained in all passed learning objects\n* Average grade - The mean of all the scores\n* Sum grade - The sum of all the scores', 'Metode penilaian menentukan bagaimana nilai untuk satu upaya aktivitas ditentukan.\n\nAda 4 metode penilaian:\n\n* Objek pembelajaran - Jumlah objek pembelajaran yang diselesaikan/lulus\n* Nilai tertinggi - Nilai tertinggi yang diperoleh pada semua objek pembelajaran yang lulus\n* Nilai rata-rata - Rata-rata semua nilai * Jumlah nilai - Jumlah semua skor', NULL, 1785718257, NULL, 0, 0),
	(21723, 'id', 130, 'grademethoddesc', 'The grading method defines how the grade for a single attempt of the activity is determined.', 'Metode penilaian menentukan bagaimana nilai untuk satu upaya aktivitas ditentukan.', NULL, 1785718257, NULL, 0, 0),
	(21724, 'id', 130, 'gradereported', 'Grade reported', 'Nilai yang dilaporkan', NULL, 1785718257, NULL, 0, 0),
	(21725, 'id', 130, 'gradesettings', 'Grade settings', 'Setelan nilai', NULL, 1785718257, NULL, 0, 0),
	(21726, 'id', 130, 'gradescoes', 'Learning objects', 'Objek belajar', NULL, 1785718257, NULL, 0, 0),
	(21727, 'id', 130, 'gradesum', 'Sum grade', 'Jumlah nilai', NULL, 1785718257, NULL, 0, 0),
	(21728, 'id', 130, 'height', 'Height', 'Tinggi', NULL, 1785718257, NULL, 0, 0),
	(21729, 'id', 130, 'hidden', 'Hidden', 'Tersembunyi', NULL, 1785718257, NULL, 0, 0),
	(21730, 'id', 130, 'hidebrowse', 'Disable preview mode', 'Nonaktifkan mode pratinjau', NULL, 1785718257, NULL, 0, 0),
	(21731, 'id', 130, 'hidebrowse_help', 'Preview mode allows a student to browse an activity before attempting it. If preview mode is disabled, the preview button is hidden.', 'Mode pratinjau memungkinkan siswa menelusuri aktivitas sebelum mencobanya. Jika mode pratinjau dinonaktifkan, tombol pratinjau disembunyikan.', NULL, 1785718257, NULL, 0, 0),
	(21732, 'id', 130, 'hidebrowsedesc', 'Preview mode allows a student to browse an activity before attempting it.', 'Mode pratinjau memungkinkan siswa menelusuri aktivitas sebelum mencobanya.', NULL, 1785718257, NULL, 0, 0),
