	(21736, 'id', 130, 'hidetoc_help', 'How the table of contents is displayed in the SCORM player', 'Bagaimana daftar isi ditampilkan di pemutar SCORM', NULL, 1785718257, NULL, 0, 0),
	(21737, 'id', 130, 'hidetocdesc', 'This setting specifies how the table of contents is displayed in the SCORM player.', 'Setelan ini menentukan bagaimana daftar isi ditampilkan di pemutar SCORM.', NULL, 1785718257, NULL, 0, 0),
