	(21741, 'id', 130, 'incomplete', 'Incomplete', 'Belum selesai', NULL, 1785718257, NULL, 0, 0),
	(21742, 'id', 130, 'indicator:cognitivedepth', 'SCORM cognitive', 'Kognitif SCORM', NULL, 1785718257, NULL, 0, 0),
	(21743, 'id', 130, 'indicator:cognitivedepth_help', 'This indicator is based on the cognitive depth reached by the student in a SCORM activity.', 'Indikator ini didasarkan pada kedalaman kognitif yang dicapai siswa dalam kegiatan SCORM.', NULL, 1785718257, NULL, 0, 0),
	(21744, 'id', 130, 'indicator:cognitivedepthdef', 'SCORM cognitive', 'Kognitif SCORM', NULL, 1785718257, NULL, 0, 0),
	(21745, 'id', 130, 'indicator:cognitivedepthdef_help', 'The participant has reached this percentage of the cognitive engagement offered by the SCORM activities during this analysis interval (Levels = No view, View, Submit, View feedback)', 'Peserta telah mencapai persentase keterlibatan kognitif yang ditawarkan oleh aktivitas SCORM selama interval analisis ini (Tingkat = Tidak ada tampilan, Lihat, Kirim, Lihat umpan balik)', NULL, 1785718257, NULL, 0, 0),
	(21746, 'id', 130, 'indicator:cognitivedepthdef_link', 'Learning_analytics_indicators#Cognitive_depth', 'Learning_analytics_indicators#Cognitive_depth', NULL, 1785718257, NULL, 0, 0),
	(21747, 'id', 130, 'indicator:socialbreadth', 'SCORM social', 'SCORM sosial', NULL, 1785718257, NULL, 0, 0),
	(21748, 'id', 130, 'indicator:socialbreadth_help', 'This indicator is based on the social breadth reached by the student in a SCORM activity.', 'Indikator ini didasarkan pada keluasan sosial yang dicapai siswa dalam kegiatan SCORM.', NULL, 1785718257, NULL, 0, 0),
	(21749, 'id', 130, 'indicator:socialbreadthdef', 'SCORM social', 'SCORM sosial', NULL, 1785718257, NULL, 0, 0),
	(21750, 'id', 130, 'indicator:socialbreadthdef_help', 'The participant has reached this percentage of the social engagement offered by the SCORM activities during this analysis interval (Levels = No participation, Participant alone)', 'Peserta telah mencapai persentase keterlibatan sosial yang ditawarkan oleh kegiatan SCORM selama interval analisis ini (Tingkat = Tidak ada partisipasi, Peserta saja)', NULL, 1785718257, NULL, 0, 0),
	(21751, 'id', 130, 'indicator:socialbreadthdef_link', 'Learning_analytics_indicators#Social_breadth', 'Learning_analytics_indicators#Social_breadth', NULL, 1785718257, NULL, 0, 0),
	(21752, 'id', 130, 'interactions', 'Interactions', 'Interaksi', NULL, 1785718257, NULL, 0, 0),
	(21753, 'id', 130, 'largetrackupgrade', 'This next upgrade step may take some time to complete, your site has {$a} SCORM track records that need to be migrated to the new table structure, please be patient as a progress bar is not able to be displayed.', 'Langkah pemutakhiran berikutnya ini mungkin membutuhkan waktu untuk diselesaikan, situs Anda memiliki {$a} rekam jejak SCORM yang perlu dipindahkan ke struktur tabel baru, harap bersabar karena bilah progres tidak dapat ditampilkan.', NULL, 1785718257, NULL, 0, 0),
	(21754, 'id', 130, 'masteryoverride', 'Mastery score overrides status', 'Skor penguasaan mengesampingkan status', NULL, 1785718257, NULL, 0, 0),
	(21755, 'id', 130, 'masteryoverride_help', 'If enabled and a mastery score is provided, when LMSFinish is called and a raw score has been set, status will be recalculated using the raw score and mastery score and any status provided by the SCORM (including "incomplete") will be overridden.', 'Jika diaktifkan dan skor penguasaan diberikan, ketika LMSFinish dipanggil dan skor mentah telah ditetapkan, status akan dihitung ulang menggunakan skor mentah dan skor penguasaan dan status apa pun yang disediakan oleh SCORM (termasuk "tidak lengkap") akan diganti.', NULL, 1785718257, NULL, 0, 0),
	(21756, 'id', 130, 'masteryoverridedesc', 'This preference sets the default for the mastery score override setting', 'Preferensi ini menetapkan bawaan untuk setelan penggantian skor penguasaan', NULL, 1785718257, NULL, 0, 0),
	(21757, 'id', 130, 'myattempts', 'My attempts', 'Upayaku', NULL, 1785718257, NULL, 0, 0),
	(21758, 'id', 130, 'myaiccsessions', 'My AICC sessions', 'Sesi AICC-ku', NULL, 1785718257, NULL, 0, 0),
	(21759, 'id', 130, 'repositorynotsupported', 'This repository does not support linking directly to an imsmanifest.xml file.', 'Repositori ini tidak mendukung penautan langsung ke berkas imsmanifest.xml.', NULL, 1785718257, NULL, 0, 0),
	(21760, 'id', 130, 'trackid', 'ID', 'ID', NULL, 1785718257, NULL, 0, 0),
	(21761, 'id', 130, 'trackid_help', 'This is the identifier set by your SCORM package for this question, the SCORM specification doesn\'t allow the full question text to be provided.', 'Ini adalah pengenal yang ditetapkan oleh paket SCORM Anda untuk soal ini, spesifikasi SCORM tidak mengizinkan teks soal lengkap disediakan.', NULL, 1785718257, NULL, 0, 0),
	(21762, 'id', 130, 'trackcorrectcount', 'Correct count', 'Hitungan benar', NULL, 1785718257, NULL, 0, 0),
	(21763, 'id', 130, 'trackcorrectcount_help', 'Number of correct results for the question', 'Jumlah hasil yang benar untuk soal', NULL, 1785718257, NULL, 0, 0),
	(21764, 'id', 130, 'trackpattern', 'Pattern', 'Pola', NULL, 1785718257, NULL, 0, 0),
	(21765, 'id', 130, 'trackpattern_help', 'This is what a correct response to this question would be, it does not show the learners response.', 'Ini adalah jawaban yang benar untuk soal ini, itu tidak menunjukkan jawaban peserta didik.', NULL, 1785718257, NULL, 0, 0),
	(21766, 'id', 130, 'tracklatency', 'Latency', 'Latensi', NULL, 1785718257, NULL, 0, 0),
	(21767, 'id', 130, 'tracklatency_help', 'The time elapsed between the time the question was made available to the learner for a response and the time of the first response.', 'Waktu berlalu antara waktu soal itu dibuat tersedia untuk pelajar untuk jawaban dan waktu jawaban pertama.', NULL, 1785718258, NULL, 0, 0),
	(21768, 'id', 130, 'trackresponse', 'Response', 'Jawaban', NULL, 1785718258, NULL, 0, 0),
	(21769, 'id', 130, 'trackresponse_help', 'This is the response made by the learner for this question', 'Ini adalah jawaban yang dibuat oleh siswa untuk soal ini', NULL, 1785718258, NULL, 0, 0),
	(21770, 'id', 130, 'trackresult', 'Result', 'Hasil', NULL, 1785718258, NULL, 0, 0),
	(21771, 'id', 130, 'trackresult_help', 'Shows if the learner entered a correct response.', 'Menunjukkan jika siswa memasukkan jawaban yang benar.', NULL, 1785718258, NULL, 0, 0),
	(21772, 'id', 130, 'trackscoremin', 'Minimum score', 'Skor minimum', NULL, 1785718258, NULL, 0, 0),
	(21773, 'id', 130, 'trackscoremin_help', 'Minimum value that can be assigned for the raw score', 'Nilai minimum yang dapat diberikan untuk skor mentah', NULL, 1785718258, NULL, 0, 0),
	(21774, 'id', 130, 'trackscoremax', 'Maximum score', 'Skor maksimum', NULL, 1785718258, NULL, 0, 0),
	(21775, 'id', 130, 'trackscoremax_help', 'Maximum value that can be assigned for the raw score', 'Nilai maksimum yang dapat diberikan untuk skor mentah', NULL, 1785718258, NULL, 0, 0),
	(21776, 'id', 130, 'trackscoreraw', 'Raw score', 'Skor mentah', NULL, 1785718258, NULL, 0, 0),
	(21777, 'id', 130, 'trackscoreraw_help', 'Number that reflects the performance of the learner relative to the range bounded by the values of min and max', 'Angka yang mencerminkan kinerja pelajar relatif terhadap rentang yang dibatasi oleh nilai min dan maks', NULL, 1785718258, NULL, 0, 0),
	(21778, 'id', 130, 'tracksuspenddata', 'Suspend data', 'Tangguhkan data', NULL, 1785718258, NULL, 0, 0),
	(21779, 'id', 130, 'tracksuspenddata_help', 'Provides space to store and retrieve data between learner sessions', 'Menyediakan ruang untuk menyimpan dan mengambil data di antara sesi pelajar', NULL, 1785718258, NULL, 0, 0),
	(21780, 'id', 130, 'tracktime', 'Time', 'Waktu', NULL, 1785718258, NULL, 0, 0),
