	(21782, 'id', 130, 'tracktype', 'Type', 'Jenis', NULL, 1785718258, NULL, 0, 0),
	(21783, 'id', 130, 'tracktype_help', 'Type of the question, for example "choice" or "shortanswer".', 'Jenis pertanyaan, misalnya "pilihan" atau "jawaban singkat".', NULL, 1785718258, NULL, 0, 0),
	(21784, 'id', 130, 'trackweight', 'Weight', 'Bobot', NULL, 1785718258, NULL, 0, 0),
