	(21790, 'id', 130, 'invalidurlhttpcheck', 'Invalid URL specified. Debug message:<pre>{$a->cmsg}</pre>', 'URL yang ditentukan tidak valid. Pesan awakutu: <pre> {$a->cmsg} </pre>', NULL, 1785718258, NULL, 0, 0),
