	(21801, 'id', 130, 'maximumattempts', 'Number of attempts', 'Jumlah upaya', NULL, 1785718258, NULL, 0, 0),
	(21802, 'id', 130, 'maximumattempts_help', 'This setting enables the number of attempts to be restricted. It is only applicable for SCORM 1.2 and AICC packages.', 'Setelan ini memungkinkan jumlah upaya untuk dibatasi. Ini hanya berlaku untuk paket SCORM 1.2 dan AICC.', NULL, 1785718258, NULL, 0, 0),
	(21803, 'id', 130, 'maximumattemptsdesc', 'This preference sets the default maximum attempts for an activity', 'Preferensi ini menetapkan setelan standar upaya maksimum  untuk suatu aktivitas.', NULL, 1785718258, NULL, 0, 0),
