	(21924, 'id', 130, 'skipview', 'Student skip content structure page', 'Siswa melewatkan halaman struktur konten', NULL, 1785718258, NULL, 0, 0),
	(21925, 'id', 130, 'skipview_help', 'This setting specifies whether the content structure page should ever be skipped (not displayed). If the package contains only one learning object, the content structure page can always be skipped.', 'Setelan ini menentukan apakah halaman struktur konten harus dilewati (tidak ditampilkan). Jika paket hanya berisi satu objek pembelajaran, halaman struktur konten selalu dapat dilewati.', NULL, 1785718258, NULL, 0, 0),
