	(22854, 'id', 135, 'submissiondeleteconfirm', 'Are you sure you want to delete the following submission?', 'Apakah Anda yakin ingin menghapus ajuan berikut?', NULL, 1785718263, NULL, 0, 0),
	(22855, 'id', 135, 'submissiondeleteconfirmassess', 'Are you sure you want to delete the following submission? Note this will also delete {$a->count} assessments associated with this submission, which may affect the reviewers\' grades.', 'Apakah Anda yakin ingin menghapus ajuan berikut? Perhatikan bahwa ini juga akan menghapus {$a->count} penilaian yang terkait dengan ajuan ini, yang dapat memengaruhi nilai peninjau.', NULL, 1785718263, NULL, 0, 0),
	(22856, 'id', 135, 'submissionend', 'Submissions deadline', 'Batas waktu pengajuan', NULL, 1785718263, NULL, 0, 0),
	(22857, 'id', 135, 'submissionendbeforestart', 'Submissions deadline can not be specified before the open for submissions date', 'Batas waktu pengajuan tidak dapat ditentukan sebelum tanggal terbuka untuk pengajuan', NULL, 1785718263, NULL, 0, 0),
	(22858, 'id', 135, 'submissionendevent', '{$a} deadline for submissions', '{$a} batas waktu pengajuan', NULL, 1785718263, NULL, 0, 0),
	(22859, 'id', 135, 'submissionenddatetime', 'Submissions deadline: {$a->daydatetime} ({$a->distanceday})', 'Batas waktu pengajuan: {$a->daydatetime} ({$a->distanceday})', NULL, 1785718263, NULL, 0, 0),
	(22860, 'id', 135, 'submissionendswitch', 'Switch to the next phase after the submissions deadline', 'Beralih ke fase berikutnya setelah batas waktu pengajuan.', NULL, 1785718263, NULL, 0, 0),
	(22861, 'id', 135, 'submissionendswitch_help', 'If the submissions deadline is specified and this box is checked, the workshop will automatically switch to the assessment phase after the submissions deadline.\n\nIf you enable this feature, it is recommended to set up the scheduled allocation method, too. If the submissions are not allocated, no assessment can be done even if the workshop itself is in the assessment phase.', 'Jika batas waktu pengajuan ditentukan dan kotak ini dicentang, lokakarya akan secara otomatis beralih ke tahap penilaian setelah batas waktu pengajuan. Jika Anda mengaktifkan fitur ini, disarankan untuk mengatur metode alokasi terjadwal juga. Jika pengajuan tidak dialokasikan, penilaian tidak dapat dilakukan meskipun lokakarya itu sendiri dalam tahap penilaian.', NULL, 1785718263, NULL, 0, 0),
	(22862, 'id', 135, 'submissiongrade', 'Grade for submission', 'Nilai ajuan', NULL, 1785718263, NULL, 0, 0),
	(22863, 'id', 135, 'submissiongrade_help', 'This setting specifies the maximum grade that may be obtained for submitted work.', 'Setelan ini menentukan nilai maksimum yang dapat diperoleh untuk pekerjaan yang diajukan.', NULL, 1785718263, NULL, 0, 0),
	(22864, 'id', 135, 'submissiongradeof', 'Grade for submission (of {$a})', 'Nilai untuk pengajuan (dari {$a})', NULL, 1785718263, NULL, 0, 0),
