	(22887, 'id', 135, 'switchingphase', 'Switching phase', 'Beralih fase', NULL, 1785718263, NULL, 0, 0),
	(22888, 'id', 135, 'switchphase', 'Switch phase', 'Beralih fase', NULL, 1785718263, NULL, 0, 0),
	(22889, 'id', 135, 'switchphaseauto', 'Switching has been scheduled', 'Peralihan telah terjadwal', NULL, 1785718263, NULL, 0, 0),
	(22890, 'id', 135, 'switchphasenext', 'Switch to the next phase', 'Beralih ke fase selanjutnya', NULL, 1785718263, NULL, 0, 0),
	(22891, 'id', 135, 'switchphase10', 'Switch to the setup phase', 'Beralih ke Fase Persiapan', NULL, 1785718263, NULL, 0, 0),
	(22892, 'id', 135, 'switchphase10info', 'You are about to switch the workshop into the <strong>Setup phase</strong>. In this phase, users cannot modify their submissions or their assessments. Teachers may use this phase to change workshop settings, modify the grading strategy or tweak assessment forms.', 'Anda akan mengalihkan lokakarya ke <strong>Fase Penyiapan</strong>. Pada fase ini, pengguna tidak dapat mengubah ajuan atau penilaian mereka. Pengajar dapat menggunakan fase ini untuk mengubah setelan lokakarya, memodifikasi strategi penilaian atau mengubah formulir penilaian.', NULL, 1785718263, NULL, 0, 0),
	(22893, 'id', 135, 'switchphase20', 'Switch to the submission phase', 'Beralih ke Fase Pengajuan', NULL, 1785718263, NULL, 0, 0),
	(22894, 'id', 135, 'switchphase20info', 'You are about to switch the workshop into the <strong>Submission phase</strong>. Students may submit their work during this phase (within the submission access control dates, if set). Teachers may allocate submissions for peer review.', 'Anda akan mengalihkan lokakarya ke <strong>Fase Pengajuan</strong>. Siswa dapat mengajukan pekerjaan mereka selama fase ini (dalam tanggal kontrol akses pengajuan, jika ditetapkan). Pengajar dapat mengalokasikan kiriman untuk ulasan rekan sejawat.', NULL, 1785718263, NULL, 0, 0),
	(22895, 'id', 135, 'switchphase30', 'Switch to the assessment phase', 'Beralih ke Fase Pengajuan', NULL, 1785718263, NULL, 0, 0),
	(22896, 'id', 135, 'switchphase30auto', 'Workshop will automatically switch into the assessment phase after {$a->daydatetime} ({$a->distanceday})', 'Lokakarya akan secara otomatis beralih ke fase penilaian setelah {$a->daydatetime} ({$a->distanceday})', NULL, 1785718263, NULL, 0, 0),
	(22897, 'id', 135, 'switchphase30info', 'You are about to switch the workshop into the <strong>Assessment phase</strong>. In this phase, reviewers may assess the submissions they have been allocated (within the assessment access control dates, if set).', 'Anda akan mengalihkan lokakarya ke <strong>Fase Penilaian</strong>. Pada fase ini, peninjau dapat menilai ajuan yang telah dialokasikan (dalam tanggal kontrol akses penilaian, jika ditetapkan).', NULL, 1785718263, NULL, 0, 0),
	(22898, 'id', 135, 'switchphase40', 'Switch to the evaluation phase', 'Beralih ke Fase Evaluasi', NULL, 1785718263, NULL, 0, 0),
	(22899, 'id', 135, 'switchphase40info', 'You are about to switch the workshop into the <strong>Grading evaluation phase</strong>. In this phase, users cannot modify their submissions or their assessments. Teachers may use the grading evaluation tools to calculate final grades and provide feedback for reviewers.', 'Anda akan mengalihkan lokakarya ke <strong>fase Evaluasi penilaian</strong>. Pada fase ini, pengguna tidak dapat mengubah ajuan atau penilaian mereka. Pengajar dapat menggunakan alat evaluasi penilaian untuk menghitung nilai akhir dan memberikan umpan balik untuk pengulas.', NULL, 1785718263, NULL, 0, 0),
	(22900, 'id', 135, 'switchphase50', 'Close workshop', 'Tutup lokakarya', NULL, 1785718263, NULL, 0, 0),
	(22901, 'id', 135, 'switchphase50info', 'You are about to close the workshop. This will result in the calculated grades appearing in the gradebook. Students may view their submissions and their submission assessments.', 'Anda akan menutup lokakarya. Ini akan menghasilkan nilai yang dihitung muncul di buku nilai. Siswa dapat melihat ajuan mereka dan penilaian ajuan mereka.', NULL, 1785718263, NULL, 0, 0),
