	(22915, 'id', 135, 'undersetup', 'The workshop is currently being set up. Please wait until it is switched to the next phase.', 'Saat ini lokakarya sedang disiapkan. Harap tunggu sampai beralih ke fase berikutnya.', NULL, 1785718263, NULL, 0, 0),
	(22916, 'id', 135, 'useexamples', 'Use examples', 'Gunakan contoh', NULL, 1785718263, NULL, 0, 0),
	(22917, 'id', 135, 'useexamples_desc', 'Example submissions are provided for practice in assessing', 'Ajukan karyamu', NULL, 1785718263, NULL, 0, 0),
	(22918, 'id', 135, 'useexamples_help', 'If enabled, users can try assessing one or more example submissions and compare their assessment with a reference assessment. The grade is not counted in the grade for assessment.', 'Jika diaktifkan, pengguna dapat mencoba menilai satu atau beberapa contoh ajuan dan membandingkan penilaian mereka dengan penilaian referensi. Nilai tidak dihitung dalam nilai untuk penilaian.', NULL, 1785718263, NULL, 0, 0),
	(22919, 'id', 135, 'usepeerassessment', 'Use peer assessment', 'Gunakan penilaian rekan sejawat', NULL, 1785718263, NULL, 0, 0),
	(22920, 'id', 135, 'usepeerassessment_desc', 'Students may assess the work of others', 'Siswa boleh menilai karya orang lain', NULL, 1785718263, NULL, 0, 0),
	(22921, 'id', 135, 'usepeerassessment_help', 'If enabled, a user may be allocated submissions from other users to assess and will receive a grade for assessment in addition to a grade for their own submission.', 'Jika diaktifkan, pengguna dapat dialokasikan ajuan dari pengguna lain untuk dinilai dan akan mendapatkan nilai untuk penilaian selain nilai untuk ajuan mereka sendiri.', NULL, 1785718263, NULL, 0, 0),
	(22922, 'id', 135, 'userdatecreated', 'submitted on <span>{$a}</span>', 'diajukan pada <span>{$a}</span>', NULL, 1785718263, NULL, 0, 0),
	(22923, 'id', 135, 'userdatemodified', 'modified on <span>{$a}</span>', 'dimodifikasi pada <span>{$a}</span>', NULL, 1785718263, NULL, 0, 0),
	(22924, 'id', 135, 'userplan', 'Workshop planner', 'Perencana lokakarya', NULL, 1785718263, NULL, 0, 0),
	(22925, 'id', 135, 'userplancurrentphase', 'Current phase', 'Fase sekarang', NULL, 1785718263, NULL, 0, 0),
	(22926, 'id', 135, 'userplan_help', 'The workshop planner displays all phases of the activity and lists the tasks for each phase. The current phase is highlighted and task completion is indicated with a tick.', 'Perencana lokakarya menampilkan semua tahapan kegiatan dan membuat daftar tugas untuk setiap tahapan. Fase saat ini disorot dan penyelesaian tugas ditunjukkan dengan tanda centang.', NULL, 1785718263, NULL, 0, 0),
	(22927, 'id', 135, 'userplanaccessibilityskip', 'Skip to current tasks', 'Lewati ke tugas saat ini', NULL, 1785718263, NULL, 0, 0),
	(22928, 'id', 135, 'userplanaccessibilitytitle', 'Workshop timeline with {$a} phases', 'Lini masa lokakarya dengan {$a} fase', NULL, 1785718263, NULL, 0, 0),
	(22929, 'id', 135, 'useselfassessment', 'Use self-assessment', 'Gunakan penilaian mandiri', NULL, 1785718263, NULL, 0, 0),
	(22930, 'id', 135, 'useselfassessment_help', 'If enabled, a user may be allocated their own submission to assess and will receive a grade for assessment in addition to a grade for their submission.', 'Jika diaktifkan, pengguna dapat mengalokasikan kiriman mereka sendiri untuk dinilai dan akan mendapatkan nilai untuk penilaian selain nilai untuk kiriman mereka.', NULL, 1785718263, NULL, 0, 0),
