	(22973, 'id', 136, 'auth_cas_certificate_path', 'Path of the CA chain file (PEM Format) to validate the server certificate', 'Jalur file rantai CA (Format PEM) untuk memvalidasi sertifikat server', NULL, 1785718264, NULL, 0, 0),
	(22974, 'id', 136, 'auth_cas_certificate_path_key', 'Certificate path', 'Jalur sertifikat', NULL, 1785718264, NULL, 0, 0),
	(22975, 'id', 136, 'auth_cas_create_user', 'Turn this on if you want to insert CAS-authenticated users in Moodle database. If not then only users who already exist in the Moodle database can log in.', 'Aktifkan ini jika Anda ingin memasukkan pengguna yang diautentikasi CAS dalam basis data Moodle. Jika tidak maka hanya pengguna yang sudah ada di basis data Moodle yang bisa masuk.', NULL, 1785718264, NULL, 0, 0),
	(22976, 'id', 136, 'auth_cas_create_user_key', 'Create user', 'Buat pengguna', NULL, 1785718264, NULL, 0, 0),
	(22977, 'id', 136, 'auth_cas_curl_ssl_version', 'The SSL version (2 or 3) to use. By default PHP will try to determine this itself, although in some cases this must be set manually.', 'Versi SSL (2 atau 3) yang akan digunakan. Secara bawaan PHP akan mencoba menentukan ini sendiri, meskipun dalam beberapa kasus ini harus diatur secara manual.', NULL, 1785718264, NULL, 0, 0),
	(22978, 'id', 136, 'auth_cas_curl_ssl_version_default', 'Default', 'Bawaan', NULL, 1785718264, NULL, 0, 0),
	(22979, 'id', 136, 'auth_cas_curl_ssl_version_key', 'cURL SSL Version', 'Versi cURL SSL', NULL, 1785718264, NULL, 0, 0),
	(22980, 'id', 136, 'auth_cas_curl_ssl_version_SSLv2', 'SSLv2', 'SSLv2', NULL, 1785718264, NULL, 0, 0),
	(22981, 'id', 136, 'auth_cas_curl_ssl_version_SSLv3', 'SSLv3', 'SSLv3', NULL, 1785718264, NULL, 0, 0),
