	(22991, 'id', 136, 'auth_cas_invalidcaslogin', 'Sorry, your login has failed - you could not be authorised', 'Maaf, login Anda gagal - Anda tidak dapat diotorisasi', NULL, 1785718264, NULL, 0, 0),
	(22992, 'id', 136, 'auth_cas_language', 'Select language for authentication pages', 'Pilih bahasa untuk halaman otentikasi', NULL, 1785718264, NULL, 0, 0),
