	(22995, 'id', 136, 'auth_cas_logout_return_url_key', 'Alternative logout return URL', 'URL pengembalian log keluar alternatif', NULL, 1785718264, NULL, 0, 0),
	(22996, 'id', 136, 'auth_cas_logout_return_url', 'Provide the URL that CAS users shall be redirected to after logging out.<br />If left empty, users will be redirected to the location that moodle will redirect users to', 'Berikan URL tujuan pengalihan pengguna CAS setelah keluar.<br />Jika dibiarkan kosong, pengguna akan diarahkan ke lokasi yang akan diarahkan oleh Moodle', NULL, 1785718264, NULL, 0, 0),
	(22997, 'id', 136, 'auth_cas_logoutcas', 'Select \'yes\' if you want to logout from CAS when you disconnect from Moodle', 'Pilih \'ya\' jika Anda ingin keluar dari CAS saat Anda memutuskan sambungan dari Moodle', NULL, 1785718264, NULL, 0, 0),
