	(22999, 'id', 136, 'auth_cas_multiauth', 'Select \'yes\' if you want to have multi-authentication (CAS + other authentication)', 'Pilih \'ya\' jika Anda ingin memiliki multi-otentikasi (CAS + otentikasi lainnya)', NULL, 1785718264, NULL, 0, 0),
