	(23200, 'id', 139, 'start_tls', 'Use regular LDAP service (port 389) with TLS encryption', 'Gunakan layanan LDAP biasa (port 389) dengan enkripsi TLS', NULL, 1785718265, NULL, 0, 0),
	(23201, 'id', 139, 'start_tls_key', 'Use TLS', 'Gunakan TLS', NULL, 1785718265, NULL, 0, 0),
	(23202, 'id', 139, 'updateremfail', 'Error updating LDAP record. Error code: {$a->errno}; Error string: {$a->errstring}<br/>Key ({$a->key}) - old moodle value: \'{$a->ouvalue}\' new value: \'{$a->nuvalue}\'', 'Galat saat memperbarui data LDAP. Kode kesalahan: {$a-> errno}; String kesalahan: {$a-> errstring} <br/> Kunci ({$a-> key}) - nilai moodle lama: \'{$a-> ouvalue}\' nilai baru: \'{$a-> nuvalue}\'', NULL, 1785718265, NULL, 0, 0),
	(23203, 'id', 139, 'updateremfailamb', 'Failed to update LDAP with ambiguous field {$a->key}; old moodle value: \'{$a->ouvalue}\', new value: \'{$a->nuvalue}\'', 'Gagal memperbarui LDAP dengan ruas ambigu {$a->key}; nilai moodle lama: \'{$a->ouvalue}\', nilai baru: \'{$a->nuvalue}\'', NULL, 1785718265, NULL, 0, 0),
	(23204, 'id', 139, 'updatepasserror', 'Error in user_update_password(). Error code: {$a->errno}; Error string: {$a->errstring}', 'Galat pada user_update_password(). Kode kesalahan: {$a->errno}; String kesalahan: {$a->errstring}', NULL, 1785718265, NULL, 0, 0),
	(23205, 'id', 139, 'updatepasserrorexpire', 'Error in user_update_password() when reading password expiry time. Error code: {$a->errno}; Error string: {$a->errstring}', 'Galat pada user_update_password() saat membaca kata sandi kedaluwarsa. Kode kesalahan: {$a-> errno}; String kesalahan: {$a->errstring}', NULL, 1785718265, NULL, 0, 0),
	(23206, 'id', 139, 'updatepasserrorexpiregrace', 'Error in user_update_password() when modifying expiry time and/or grace logins. Error code: {$a->errno}; Error string: {$a->errstring}', 'Galat pada user_update_password() saat mengubah waktu kedaluwarsa dan/atau masa masuk masa tenggang. Kode kesalahan: {$a->errno}; String kesalahan: {$a->errstring}', NULL, 1785718265, NULL, 0, 0),
	(23207, 'id', 139, 'updateusernotfound', 'Could not find user while updating externally. Details follow: search base: \'{$a->userdn}\'; search filter: \'(objectClass=*)\'; search attributes: {$a->attribs}', 'Tidak dapat menemukan pengguna saat memperbarui secara eksternal. Detailnya mengikuti: basis pencarian: \'{$a->userdn}\'; filter pencarian: \'(objectClass=*)\'; atribut pencarian: {$a->attribs}', NULL, 1785718265, NULL, 0, 0),
	(23208, 'id', 139, 'user_activatenotsupportusertype', 'auth: ldap user_activate() does not support selected usertype: {$a}', 'auth: ldap user_activate() tidak mendukung tipe pengguna yang dipilih: {$a}', NULL, 1785718265, NULL, 0, 0),
	(23209, 'id', 139, 'user_disablenotsupportusertype', 'auth: ldap user_disable() does not support selected usertype: {$a}', 'auth: ldap user_disable() tidak mendukung tipe pengguna yang dipilih: {$a}', NULL, 1785718265, NULL, 0, 0),
