	(23216, 'id', 139, 'diag_genericerror', 'LDAP error {$a->code} reading {$a->subject}: {$a->message}.', 'Kesalahan LDAP {$a-> code} membaca {$a-> subject}: {$a-> message}.', NULL, 1785718265, NULL, 0, 0),
	(23217, 'id', 139, 'diag_toooldversion', 'It is very unlikely a modern LDAP server uses LDAPv2 protocol. Wrong settings can corrupt values in user fields. Check with your LDAP administrator.', 'Sangat tidak mungkin server LDAP modern menggunakan protokol LDAP v2. Setelan yang salah dapat merusak nilai di bidang pengguna. Hubungi administrator LDAP Anda.', NULL, 1785718265, NULL, 0, 0),
