	(23220, 'id', 139, 'diag_rolegroupnotfound', 'Group {$a->group} for role {$a->localname} doesn\'t exist or can\'t be read by bind DN.', 'Grup {$a->group} untuk peran {$a->localname} tidak ada atau tidak bisa dibaca oleh bind DN.', NULL, 1785718265, NULL, 0, 0),
	(23221, 'id', 139, 'privacy:metadata', 'The LDAP server authentication plugin does not store any personal data.', 'Pengaya autentikasi server LDAP tidak menyimpan data pribadi apa pun.', NULL, 1785718265, NULL, 0, 0),
	(23222, 'id', 140, 'accountcreatedsuccess', 'Your account has been created and is now ready to use.', 'Akun Anda telah dibuat dan sekarang siap digunakan.', NULL, 1785718265, NULL, 0, 0),
