	(23238, 'id', 140, 'privacy:metadata:auth_lti:issuer', 'The issuer URL identifying the platform to which the linked user belongs.', 'URL penerbit yang mengidentifikasi platform tempat pengguna tertaut berada.', NULL, 1785718265, NULL, 0, 0),
