	(23241, 'id', 140, 'privacy:metadata:auth_lti:sub256', 'The SHA256 hash of the subject string identifying the user on the issuer.', 'Hash SHA256 dari string subjek yang mengidentifikasi pengguna pada penerbit.', NULL, 1785718265, NULL, 0, 0),
