	(23243, 'id', 140, 'privacy:metadata:auth_lti:timecreated', 'The timestamp when the user account was linked to the LTI login.', 'Stempel waktu saat akun pengguna ditautkan ke login LTI.', NULL, 1785718265, NULL, 0, 0),
