	(23250, 'id', 140, 'welcome', 'Welcome!', 'Selamat datang!', NULL, 1785718265, NULL, 0, 0),
	(23251, 'id', 140, 'firstlaunchnoauthnotice', 'To link your existing account you must be logged in to the site. Please log in to the site in a new tab/window and then relaunch the tool here. For further information, see the documentation <a href="{$a}" target="_blank">Publish as LTI tool</a>.', 'Untuk menautkan akun Anda yang ada, Anda harus masuk ke situs. Harap masuk ke situs di tab/jendela baru, lalu luncurkan kembali alat di sini. Untuk informasi lebih lanjut, lihat dokumentasi <a href="{$a}" target="_blank">Publikasikan sebagai alat LTI</a>.', NULL, 1785718265, NULL, 0, 0),
	(23252, 'id', 141, 'auth_manualdescription', 'This method removes any way for users to create their own accounts.  All accounts must be manually created by the admin user.', 'Metode ini menghilangkan segala cara untuk seorang pengguna untuk membuat keanggotaan mereka sendiri. Semua keanggotaan harus secara manual dibuat oleh pengguna Admin.', NULL, 1785718265, NULL, 0, 0),
	(23253, 'id', 141, 'expiration', 'Enable password expiry', 'Aktifkan kedaluwarsa kata sandi', NULL, 1785718265, NULL, 0, 0),
	(23254, 'id', 141, 'expiration_desc', 'Allow passwords to expire after a specified time.', 'Izinkan kata sandi untuk kedaluwarsa setelah waktu yang ditentukan.', NULL, 1785718265, NULL, 0, 0),
	(23255, 'id', 141, 'expiration_warning', 'Notification threshold', 'Ambang notifikasi', NULL, 1785718265, NULL, 0, 0),
	(23256, 'id', 141, 'expiration_warning_desc', 'Number of days before password expiry that a notification is issued.', 'Jumlah hari sebelum kata sandi kedaluwarsa bahwa pemberitahuan dikeluarkan.', NULL, 1785718265, NULL, 0, 0),
	(23257, 'id', 141, 'passwdexpiretime', 'Password duration', 'Durasi kata sandi', NULL, 1785718265, NULL, 0, 0),
	(23258, 'id', 141, 'passwdexpiretime_desc', 'Length of time for which a password is valid.', 'Lama waktu untuk kata sandi valid.', NULL, 1785718265, NULL, 0, 0),
	(23259, 'id', 141, 'pluginname', 'Manual accounts', 'Akun manual', NULL, 1785718265, NULL, 0, 0),
	(23260, 'id', 141, 'passwdexpire_settings', 'Password expiry settings', 'Setelan masa berlaku kata sandi', NULL, 1785718265, NULL, 0, 0),
	(23261, 'id', 141, 'privacy:metadata:preference:passwordupdatetime', 'The date of the last password change.', 'Tanggal perubahan kata sandi terakhir.', NULL, 1785718265, NULL, 0, 0),
	(23262, 'id', 142, 'auth_mnet_auto_add_remote_users', 'When set to Yes, a local user record is auto-created when a remote user logs in for the first time.', 'Jika diatur ke Ya, catatan pengguna lokal dibuat secara otomatis saat pengguna jarak jauh masuk untuk pertama kalinya.', NULL, 1785718265, NULL, 0, 0),
	(23263, 'id', 142, 'auth_mnetdescription', 'Users are authenticated according to the web of trust defined in your Moodle Network settings.', 'Pengguna diautentikasi sesuai dengan web kepercayaan yang ditentukan dalam setelan Jaringan Moodle Anda.', NULL, 1785718265, NULL, 0, 0),
	(23264, 'id', 142, 'auth_mnet_roamin', 'These host\'s users can roam in to your site', 'Pengguna hos ini dapat menjelajah ke situs Anda', NULL, 1785718265, NULL, 0, 0),
	(23265, 'id', 142, 'auth_mnet_roamout', 'Your users can roam out to these hosts', 'Pengguna Anda dapat menjelajah ke hos berikut', NULL, 1785718265, NULL, 0, 0),
	(23266, 'id', 142, 'auth_mnet_rpc_negotiation_timeout', 'The timeout in seconds for authentication over the XMLRPC transport.', 'Batas waktu dalam detik untuk autentikasi melalui pengangkutan XMLRPC.', NULL, 1785718265, NULL, 0, 0),
	(23267, 'id', 142, 'auto_add_remote_users', 'Auto add remote users', 'Tambahkan pengguna jarak jauh secara otomatis', NULL, 1785718265, NULL, 0, 0),
	(23268, 'id', 142, 'crontask', 'Background processing for MNET authentication', 'Pemrosesan latar belakang untuk autentikasi MNET', NULL, 1785718265, NULL, 0, 0),
	(23269, 'id', 142, 'rpc_negotiation_timeout', 'RPC negotiation timeout', 'Batas waktu negosiasi RPC', NULL, 1785718265, NULL, 0, 0),
	(23270, 'id', 142, 'sso_idp_description', 'Publish this service to allow your users to roam to the {$a} site without having to re-login there. <ul><li><em>Dependency</em>: You must also <strong>subscribe</strong> to the SSO (Service Provider) service on {$a}.</li></ul><br />Subscribe to this service to allow authenticated users from {$a} to access your site without having to re-login. <ul><li><em>Dependency</em>: You must also <strong>publish</strong> the SSO (Service Provider) service to {$a}.</li></ul><br />', 'Publikasikan layanan ini untuk memungkinkan pengguna Anda menjelajah ke situs {$a} tanpa harus masuk kembali ke sana. <ul><li><em>Ketergantungan</em>: Anda juga harus <strong>berlangganan</strong> ke layanan SSO (Penyedia Layanan) di {$a}.</li></ul><br />Berlangganan ke layanan ini untuk mengizinkan pengguna yang diautentikasi dari {$a} mengakses situs Anda tanpa harus masuk kembali. <ul><li><em>Ketergantungan</em>: Anda juga harus <strong>memublikasikan</strong> layanan SSO (Penyedia Layanan) ke {$a}.</li></ul><br / >', NULL, 1785718265, NULL, 0, 0),
	(23271, 'id', 142, 'sso_idp_name', 'SSO  (Identity Provider)', 'SSO (Penyedia Identitas)', NULL, 1785718265, NULL, 0, 0),
	(23272, 'id', 142, 'sso_mnet_login_refused', 'Username {$a->user} is not permitted to login from {$a->host}.', 'Nama pengguna {$a->user} tidak diizinkan untuk masuk dari {$a->host}.', NULL, 1785718265, NULL, 0, 0),
	(23273, 'id', 142, 'sso_sp_description', 'Publish  this service to allow authenticated users from {$a} to access your site without having to re-login. <ul><li><em>Dependency</em>: You must also <strong>subscribe</strong> to the SSO (Identity Provider) service on {$a}.</li></ul><br />Subscribe to this service to allow your users to roam to the {$a} site without having to re-login there. <ul><li><em>Dependency</em>: You must also <strong>publish</strong> the SSO (Identity Provider) service to {$a}.</li></ul><br />', 'Publikasikan layanan ini untuk memungkinkan pengguna yang diautentikasi dari {$a} mengakses situs Anda tanpa harus masuk kembali. <ul><li><em>Ketergantungan</em>: Anda juga harus <strong>berlangganan</strong> ke layanan SSO (Penyedia Identitas) di {$a}.</li></ul><br />Berlangganan ke layanan ini agar pengguna Anda dapat menjelajahi situs {$a} tanpa harus log masuk ulang di sana. <ul><li><em>Ketergantungan</em>: Anda juga harus <strong>memublikasikan</strong> layanan SSO (Penyedia Identitas) ke {$a}.</li></ul><br / >', NULL, 1785718265, NULL, 0, 0),
