	(23307, 'id', 142, 'privacy:metadata:mnet_external:policyagreed', 'A flag to determine if the user has agreed to the site policy.', 'Sebuah bendera untuk menentukan apakah pengguna telah menyetujui kebijakan situs.', NULL, 1785718265, NULL, 0, 0),
	(23308, 'id', 142, 'privacy:metadata:mnet_external:suspended', 'A flag to show if the user has been suspended on this system.', 'Sebuah bendera untuk menunjukkan jika pengguna telah ditangguhkan di sistem ini.', NULL, 1785718265, NULL, 0, 0),
