	(23316, 'id', 142, 'privacy:metadata:mnet_log:course', 'Remote system course ID where the action occurred.', 'ID kursus sistem jarak jauh ketika aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23317, 'id', 142, 'privacy:metadata:mnet_log:coursename', 'Remote system course full name where the action occurred.', 'Nama lengkap kursus sistem jarak jauh dimana aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23318, 'id', 142, 'privacy:metadata:mnet_log:hostid', 'Remote system MNet ID.', 'ID MNet sistem jarak jauh.', NULL, 1785718265, NULL, 0, 0),
	(23319, 'id', 142, 'privacy:metadata:mnet_log:info', 'Additional information about the action.', 'Informasi tambahan mengenai aksi tersebut.', NULL, 1785718265, NULL, 0, 0),
	(23320, 'id', 142, 'privacy:metadata:mnet_log:ip', 'The IP address used at the time of the action occurred.', 'Alamat IP yang digunakan saat aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23321, 'id', 142, 'privacy:metadata:mnet_log:module', 'Remote system module where the action occurred.', 'Modul sistem jarak jauh tempat aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23322, 'id', 142, 'privacy:metadata:mnet_log:remoteid', 'Remote ID of the user who carried out the action in the remote system.', 'ID jarak jauh dari pengguna yang melakukan aksi di sistem jarak jauh.', NULL, 1785718265, NULL, 0, 0),
	(23323, 'id', 142, 'privacy:metadata:mnet_log:time', 'Time when the action occurred.', 'Waktu saat aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23324, 'id', 142, 'privacy:metadata:mnet_log:url', 'Remote system URL where the action occurred.', 'URL sistem jarak jauh dimana aksi terjadi.', NULL, 1785718265, NULL, 0, 0),
	(23325, 'id', 142, 'privacy:metadata:mnet_log:userid', 'Local ID of the user who carried out the action in the remote system.', 'ID lokal pengguna yang melakukan aksi di sistem jarak jauh.', NULL, 1785718265, NULL, 0, 0),
	(23326, 'id', 142, 'privacy:metadata:mnet_session', 'The details of each MNet user session in a remote system. The data is stored temporarily.', 'Detail dari setiap sesi pengguna MNet dalam sistem jarak jauh. Data disimpan sementara.', NULL, 1785718265, NULL, 0, 0),
	(23327, 'id', 142, 'privacy:metadata:mnet_session:expires', 'Time when the session expires.', 'Waktu sesi berakhir.', NULL, 1785718265, NULL, 0, 0),
	(23328, 'id', 142, 'privacy:metadata:mnet_session:mnethostid', 'Remote system MNet ID.', 'ID MNet sistem jarak jauh.', NULL, 1785718265, NULL, 0, 0),
	(23329, 'id', 142, 'privacy:metadata:mnet_session:token', 'Unique session identifier', 'Pengenal sesi unik', NULL, 1785718265, NULL, 0, 0),
	(23330, 'id', 142, 'privacy:metadata:mnet_session:useragent', 'User agent used to access the remote system', 'Agen pengguna yang digunakan untuk mengakses sistem jarak jauh', NULL, 1785718265, NULL, 0, 0),
	(23331, 'id', 142, 'privacy:metadata:mnet_session:userid', 'ID of the user jumping to remote system.', 'ID pengguna melompat ke sistem jarak jauh.', NULL, 1785718266, NULL, 0, 0),
	(23332, 'id', 142, 'privacy:metadata:mnet_session:username', 'Username of the user jumping to remote system.', 'Nama pengguna pengguna beralih ke sistem jarak jauh.', NULL, 1785718266, NULL, 0, 0),
	(23333, 'id', 142, 'unknownhost', 'Unknown host', 'Hos yang tidak diketahui', NULL, 1785718266, NULL, 0, 0),
	(23334, 'id', 143, 'auth_nologindescription', 'Auxiliary plugin that prevents user to login into system and also discards any mail sent to the user. Can be used to <em>suspend</em> user accounts.', 'Pengaya bantu yang mencegah pengguna untuk masuk ke sistem dan juga membuang semua surel yang dikirim ke pengguna. Dapat digunakan untuk <em>menangguhkan</em> akun pengguna.', NULL, 1785718266, NULL, 0, 0),
	(23335, 'id', 143, 'pluginname', 'No login', 'Tidak ada log masuk', NULL, 1785718266, NULL, 0, 0),
	(23336, 'id', 143, 'privacy:metadata', 'The No login authentication plugin does not store any personal data.', 'Pengaya Tanpa autentikasi log masuk tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23337, 'id', 144, 'auth_nonedescription', 'Users can sign in and create valid accounts immediately, with no authentication against an external server and no confirmation via email.  Be careful using this option - think of the security and administration problems this could cause.', 'Pengguna dapat mendaftar dan membuat keanggotaan yang sah segera, tanpa autentikasi pada server eksternal dan tidak ada konfirmasi melalui surel.  Berhati-hatilah untuk menggunakan pilihan ini - pikirkan mengenai keamanan dan problem administrasi yang dapat disebabkan oleh ini.', NULL, 1785718266, NULL, 0, 0),
	(23338, 'id', 144, 'pluginname', 'No authentication', 'Tidak ada autentikasi', NULL, 1785718266, NULL, 0, 0),
	(23339, 'id', 144, 'privacy:metadata', 'The No authentication plugin does not store any personal data.', 'Pengaya Tanpa autentikasi tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23340, 'id', 144, 'checknoauthdetails', '<p>The <em>No authentication</em> plugin is not intended for production sites. Please disable it unless this is a development test site.</p>', '<p>Pengaya <em>Tanpa autentikasi</em> tidak ditujukan untuk situs produksi. Harap nonaktifkan kecuali ini adalah situs uji pengembangan.</p>', NULL, 1785718266, NULL, 0, 0),
	(23341, 'id', 144, 'checknoautherror', 'The No authentication plugin cannot be used on production sites.', 'Pengaya Tanpa autentikasi tidak dapat digunakan di situs produksi.', NULL, 1785718266, NULL, 0, 0),
	(23342, 'id', 144, 'checknoauth', 'No authentication', 'Tidak ada autentikasi', NULL, 1785718266, NULL, 0, 0),
	(23343, 'id', 144, 'checknoauthok', 'The no authentication plugin is disabled.', 'Pengaya tanpa autentikasi dinonaktifkan.', NULL, 1785718266, NULL, 0, 0),
	(23344, 'id', 145, 'accountexists', 'A user already exists on this site with this username. If this is your account, log in by entering your username and password and add it as a linked login via your preferences page.', 'Seorang pengguna sudah ada di situs ini dengan nama pengguna ini. Jika ini adalah akun Anda, masuk dengan memasukkan nama pengguna dan kata sandi Anda dan tambahkan sebagai log masuk yang ditautkan melalui halaman preferensi Anda.', NULL, 1785718266, NULL, 0, 0),
	(23345, 'id', 145, 'auth_oauth2description', 'OAuth 2 standards based authentication', 'Autentikasi berbasis standar OAuth 2', NULL, 1785718266, NULL, 0, 0),
	(23346, 'id', 145, 'auth_oauth2settings', 'OAuth 2 authentication settings.', 'Setelan autentikasi OAuth 2.', NULL, 1785718266, NULL, 0, 0),
	(23347, 'id', 145, 'confirmaccountemail', 'Hi {$a->firstname},\n\nA new account has been requested at \'{$a->sitename}\' using your email address.\n\nTo confirm your new account, please click the link below:\n\n<a href="{$a->link}">Confirm your account</a>\n\n\nIf you need help, please contact the site administrator.\n{$a->admin}\n\nIf you did not do this, someone else could be trying to compromise your account.\nPlease contact the site administrator immediately.', 'Hai {$a->firstname},\n\nAkun baru telah diminta di \'{$a->sitename}\' menggunakan alamat surel Anda.\n\nUntuk mengonfirmasikan akun baru Anda, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Konfirmasikan akun Anda</a>\n\n\nJika Anda membutuhkan bantuan, silakan hubungi administrator situs.\n{$a->admin}\n\nJika Anda tidak melakukan ini, orang lain mungkin mencoba untuk membobol akun Anda.\nSilakan hubungi administrator situs segera.', NULL, 1785718266, NULL, 0, 0),
	(23348, 'id', 145, 'confirmaccountemailsubject', '{$a}: account confirmation', '{$a}: konfirmasi akun', NULL, 1785718266, NULL, 0, 0),
	(23349, 'id', 145, 'confirmationinvalid', 'The confirmation link is either invalid, or has expired. Please start the login process again to generate a new confirmation email.', 'Tautan konfirmasi tidak valid, atau telah kedaluwarsa. Silakan mulai proses log masuk lagi untuk menghasilkan surel konfirmasi baru.', NULL, 1785718266, NULL, 0, 0),
	(23350, 'id', 145, 'confirmationpending', 'This account is pending email confirmation.', 'Akun ini sedang menunggu konfirmasi surel.', NULL, 1785718266, NULL, 0, 0),
	(23351, 'id', 145, 'confirmlinkedloginemail', 'Hi {$a->firstname},\n\nA request has been made to link the {$a->issuername} login\n{$a->linkedemail} to your account at \'{$a->sitename}\'\nusing your email address.\n\nTo confirm this request and link these logins, please click the link below:\n\n<a href="{$a->link}">Link your accounts</a>\n\n\nIf you need help, please contact the site administrator.\n{$a->admin}\n\nIf you did not do this, someone else could be trying to compromise your account.\nPlease contact the site administrator immediately.', 'Hai {$a->firstname},\n\nPermintaan telah dibuat untuk menghubungkan masuk {$a->issuername}\n{$a->linkedemail} ke akun Anda di \'{$a->sitename}\'\nmenggunakan alamat surel Anda.\n\nUntuk mengonfirmasikan permintaan ini dan menghubungkan masuk ini, silakan klik tautan di bawah ini:\n\n<a href="{$a->link}">Hubungkan akun Anda</a>\n\n\nJika Anda membutuhkan bantuan, silakan hubungi administrator situs.\n{$a->admin}\n\nJika Anda tidak melakukan ini, orang lain mungkin mencoba untuk membahayakan akun Anda.\nSilakan hubungi administrator situs segera.', NULL, 1785718266, NULL, 0, 0),
	(23352, 'id', 145, 'confirmlinkedloginemailsubject', '{$a}: linked login confirmation', '{$a}: konfirmasi log masuk tertaut', NULL, 1785718266, NULL, 0, 0),
	(23353, 'id', 145, 'createaccountswarning', 'This authentication plugin allows users to create accounts on your site. You may want to enable the setting "authpreventaccountcreation" if you use this plugin.', 'Pengaya autentikasi ini memungkinkan pengguna untuk membuat akun di situs Anda. Anda mungkin ingin mengaktifkan setelan "authpreventaccountcreation" jika Anda menggunakan pengaya ini.', NULL, 1785718266, NULL, 0, 0),
	(23354, 'id', 145, 'createnewlinkedlogin', 'Link a new account ({$a})', 'Tautkan akun baru ({$a})', NULL, 1785718266, NULL, 0, 0),
	(23355, 'id', 145, 'emailconfirmlink', 'Link your accounts', 'Tautkan akun Anda', NULL, 1785718266, NULL, 0, 0),
	(23356, 'id', 145, 'emailconfirmlinksent', '<p>An existing account was found with this email address but it is not linked yet.</p>\n   <p>The accounts must be linked before you can log in.</p>\n   <p>An email should have been sent to your address at <b>{$a}</b>.</p>\n   <p>It contains easy instructions to link your accounts.</p>\n   <p>If you have any difficulty, contact the site administrator.</p>', '<p>Akun yang ada ditemukan dengan alamat surel ini tetapi belum ditautkan.</p>\n    <p>Akun harus ditautkan sebelum Anda dapat masuk.</p>\n    <p>Seharusnya surel telah dikirim ke alamat Anda di <b>{$a}</b>.</p>\n    <p>Berisi petunjuk mudah untuk menautkan akun Anda.</p>', NULL, 1785718266, NULL, 0, 0),
	(23357, 'id', 145, 'emailpasswordchangeinfo', 'Hi {$a->firstname},\n\nSomeone (probably you) has requested a new password for your account on \'{$a->sitename}\'.\n\nHowever your password cannot be reset because you are using your account on another site to log in.\n\nPlease log in as before, using the link on the login page.\n{$a->admin}', 'Halo {$a->firstname},\n\nSeseorang (mungkin Anda) telah meminta sandi baru untuk akun Anda di \'{$a->sitename}\'.\n\nNamun kata sandi Anda tidak dapat diatur ulang karena Anda menggunakan akun Anda di situs lain untuk masuk.\n\nSilakan masuk seperti sebelumnya, menggunakan tautan di halaman log masuk.\n{$a->admin}', NULL, 1785718266, NULL, 0, 0),
	(23358, 'id', 145, 'emailpasswordchangeinfosubject', '{$a}: Change password information', '{$a}: Informasi ubah kata sandi', NULL, 1785718266, NULL, 0, 0),
	(23359, 'id', 145, 'info', 'External account', 'Akun eksternal', NULL, 1785718266, NULL, 0, 0),
	(23360, 'id', 145, 'issuer', 'OAuth 2 service', 'Layanan OAuth 2', NULL, 1785718266, NULL, 0, 0),
	(23361, 'id', 145, 'issuernologin', 'This issuer can not be used to log in.', 'Penerbit ini tidak dapat digunakan untuk masuk.', NULL, 1785718266, NULL, 0, 0),
	(23362, 'id', 145, 'key', 'Key', 'Kunci', NULL, 1785718266, NULL, 0, 0),
	(23363, 'id', 145, 'linkedlogins', 'Linked logins', 'Log masuk yang ditautkan', NULL, 1785718266, NULL, 0, 0),
	(23364, 'id', 145, 'linkedloginshelp', 'Help with linked logins', 'Bantuan dengan log masuk yang ditautkan', NULL, 1785718266, NULL, 0, 0),
	(23365, 'id', 145, 'loggedin', 'User successfully authenticated with provider.', 'Pengguna berhasil diautentikasi dengan penyedia.', NULL, 1785718266, NULL, 0, 0),
	(23366, 'id', 145, 'loginerror_userincomplete', 'The user information returned did not contain a username and email address. The OAuth 2 service may be configured incorrectly.', 'Informasi pengguna yang dikembalikan tidak berisi nama pengguna dan alamat surel. Layanan OAuth 2 mungkin tidak dikonfigurasi dengan benar.', NULL, 1785718266, NULL, 0, 0),
	(23367, 'id', 145, 'loginerror_nouserinfo', 'No user information was returned. The OAuth 2 service may be configured incorrectly.', 'Tidak ada informasi pengguna yang dikembalikan. Layanan OAuth 2 mungkin tidak dikonfigurasi dengan benar.', NULL, 1785718266, NULL, 0, 0),
	(23368, 'id', 145, 'loginerror_invaliddomain', 'The email address is not allowed at this site.', 'Alamat surel tidak diperbolehkan di situs ini.', NULL, 1785718266, NULL, 0, 0),
	(23369, 'id', 145, 'loginerror_authenticationfailed', 'The authentication process failed.', 'Proses autentikasi gagal.', NULL, 1785718266, NULL, 0, 0),
	(23370, 'id', 145, 'loginerror_cannotcreateaccounts', 'An account with your email address could not be found.', 'Akun dengan alamat surel Anda tidak dapat ditemukan.', NULL, 1785718266, NULL, 0, 0),
	(23371, 'id', 145, 'noconfiguredidps', 'There are no configured OAuth2 providers.', 'Pengguna berhasil diautentikasi dengan penyedia.', NULL, 1785718266, NULL, 0, 0),
	(23372, 'id', 145, 'noissuersavailable', 'None of the configured OAuth 2 services allow you to link login accounts.', 'Tak satu pun dari layanan OAuth2 yang dikonfigurasi memungkinkan Anda menautkan akun masuk.', NULL, 1785718266, NULL, 0, 0),
	(23373, 'id', 145, 'notloggedindebug', 'The login attempt failed. Reason: {$a}', 'Upaya log masuk gagal. Alasan: {$a}', NULL, 1785718266, NULL, 0, 0),
	(23374, 'id', 145, 'notwhileloggedinas', 'Linked logins cannot be managed while logged in as another user.', 'Log masuk tertaut tidak dapat dikelola saat masuk sebagai pengguna lain.', NULL, 1785718266, NULL, 0, 0),
	(23375, 'id', 145, 'oauth2:managelinkedlogins', 'Manage own linked login accounts', 'Kelola akun masuk tertaut sendiri', NULL, 1785718266, NULL, 0, 0),
	(23376, 'id', 145, 'notenabled', 'Sorry, OAuth 2 authentication plugin is not enabled', 'Maaf, pengaya autentikasi OAuth 2 tidak diaktifkan', NULL, 1785718266, NULL, 0, 0),
	(23377, 'id', 145, 'plugindescription', 'This authentication plugin displays a list of the configured identity providers on the login page. Selecting an identity provider allows users to login with their credentials from an OAuth 2 provider.', 'Pengaya autentikasi ini menampilkan daftar penyedia identitas yang dikonfigurasi di halaman log masuk. Memilih penyedia identitas memungkinkan pengguna untuk masuk dengan kredensial mereka dari penyedia OAuth 2.', NULL, 1785718266, NULL, 0, 0),
	(23378, 'id', 145, 'pluginname', 'OAuth 2', 'OAuth 2', NULL, 1785718266, NULL, 0, 0),
	(23379, 'id', 145, 'alreadylinked', 'This external account is already linked to an account on this site', 'Akun eksternal ini sudah ditautkan ke akun di situs ini', NULL, 1785718266, NULL, 0, 0),
	(23380, 'id', 145, 'privacy:metadata:auth_oauth2', 'OAuth 2 authentication', 'Autentikasi OAuth 2', NULL, 1785718266, NULL, 0, 0),
	(23381, 'id', 145, 'privacy:metadata:auth_oauth2:authsubsystem', 'This plugin is connected to the authentication subsystem.', 'Pengaya ini terhubung ke subsistem autentikasi.', NULL, 1785718266, NULL, 0, 0),
	(23382, 'id', 145, 'privacy:metadata:auth_oauth2:confirmtoken', 'The confirmation token.', 'Token konfirmasi.', NULL, 1785718266, NULL, 0, 0),
	(23383, 'id', 145, 'privacy:metadata:auth_oauth2:confirmtokenexpires', 'The timestamp when the confirmation token expires.', 'Stempel waktu saat token konfirmasi kedaluwarsa.', NULL, 1785718266, NULL, 0, 0),
	(23384, 'id', 145, 'privacy:metadata:auth_oauth2:email', 'The external email that maps to this account.', 'Surel eksternal yang dipetakan ke akun ini.', NULL, 1785718266, NULL, 0, 0),
	(23385, 'id', 145, 'privacy:metadata:auth_oauth2:issuerid', 'The ID of the OAuth 2 issuer for this OAuth 2 login', 'ID penerbit OAuth 2 untuk login OAuth 2 ini', NULL, 1785718266, NULL, 0, 0),
	(23386, 'id', 145, 'privacy:metadata:auth_oauth2:tableexplanation', 'OAuth 2 accounts linked to a user\'s Moodle account.', 'Akun OAuth 2 ditautkan ke akun Moodle pengguna.', NULL, 1785718266, NULL, 0, 0),
	(23387, 'id', 145, 'privacy:metadata:auth_oauth2:timecreated', 'The timestamp when the user account was linked to the OAuth 2 login.', 'Stempel waktu saat akun pengguna ditautkan ke log masuk OAuth 2.', NULL, 1785718266, NULL, 0, 0),
	(23388, 'id', 145, 'privacy:metadata:auth_oauth2:timemodified', 'The timestamp when this record was modified.', 'Stempel waktu saat rekaman ini diubah.', NULL, 1785718266, NULL, 0, 0),
	(23389, 'id', 145, 'privacy:metadata:auth_oauth2:userid', 'The ID of the user account which the OAuth 2 login is linked to.', 'ID akun pengguna yang ditautkan dengan login OAuth 2.', NULL, 1785718266, NULL, 0, 0),
	(23390, 'id', 145, 'privacy:metadata:auth_oauth2:usermodified', 'The ID of the user who modified this account.', 'ID pengguna yang mengubah akun ini.', NULL, 1785718266, NULL, 0, 0),
	(23391, 'id', 145, 'privacy:metadata:auth_oauth2:username', 'The external username that maps to this account.', 'Nama pengguna eksternal yang memetakan ke akun ini.', NULL, 1785718266, NULL, 0, 0),
	(23392, 'id', 145, 'testidplogin', 'Test login with:', 'Uji login dengan:', NULL, 1785718266, NULL, 0, 0),
	(23393, 'id', 145, 'userinfo', 'User data from provider:', 'Data pengguna dari penyedia:', NULL, 1785718266, NULL, 0, 0),
	(23394, 'id', 145, 'value', 'Value', 'Nilai', NULL, 1785718266, NULL, 0, 0),
	(23395, 'id', 146, 'auth_shib_auth_method', 'Authentication method name', 'Nama metode autentikasi', NULL, 1785718266, NULL, 0, 0),
	(23396, 'id', 146, 'auth_shib_auth_method_description', 'Provide a name for the Shibboleth authentication method that is familiar to your users. This could be the name of your Shibboleth federation, e.g. <tt>SWITCHaai Login</tt> or <tt>InCommon Login</tt> or similar.', 'Berikan nama untuk metode autentikasi Shibboleth yang familiar bagi pengguna Anda. Ini bisa menjadi nama federasi Shibboleth Anda, mis. <tt>Login SWITCHAai</tt> atau <tt>Login Biasa</tt> atau yang serupa.', NULL, 1785718266, NULL, 0, 0),
	(23397, 'id', 146, 'auth_shib_auth_logo', 'Authentication method logo', 'Logo metode autentikasi', NULL, 1785718266, NULL, 0, 0),
	(23398, 'id', 146, 'auth_shib_auth_logo_description', 'Provide a logo for the Shibboleth authentication method that is familiar to your users. This could be the logo of your Shibboleth federation, e.g. <tt>SWITCHaai Login</tt> or <tt>InCommon Login</tt> or similar.', 'Berikan logo untuk metode autentikasi Shibboleth yang familiar bagi pengguna Anda. Ini bisa menjadi logo federasi Shibboleth Anda, mis. <tt>Login SWITCHAai</tt> atau <tt>Login Biasa</tt> atau yang serupa.', NULL, 1785718266, NULL, 0, 0),
	(23399, 'id', 146, 'auth_shib_contact_administrator', 'In case you are not associated with the given organizations and you need access to a course on this server, please contact the <a href="mailto:{$a}">Moodle Administrator</a>.', 'Jika Anda tidak terkait dengan organisasi tertentu dan Anda memerlukan akses ke kursus di server ini, harap hubungi <a href="mailto:{$a}">Administrator Moodle</a>.', NULL, 1785718266, NULL, 0, 0),
	(23400, 'id', 146, 'auth_shibbolethdescription', 'Using this method users are created and authenticated using Shibboleth. For set-up details, see the <a href="{$a}">Shibboleth README</a>.', 'Dengan menggunakan metode ini, pengguna dibuat dan diautentikasi menggunakan Shibboleth. Untuk detail setelan, lihat <a href="{$a}">Shibboleth README</a>.', NULL, 1785718266, NULL, 0, 0),
	(23401, 'id', 146, 'auth_shibboleth_errormsg', 'Please select the organization you are member of!', 'Silakan pilih organisasi tempat Anda menjadi anggota!', NULL, 1785718266, NULL, 0, 0),
	(23402, 'id', 146, 'auth_shibboleth_login', 'Shibboleth login', 'Log masuk shibboleth', NULL, 1785718266, NULL, 0, 0),
	(23403, 'id', 146, 'auth_shibboleth_login_long', 'Log in via Shibboleth', 'Masuk melalui Shibboleth', NULL, 1785718266, NULL, 0, 0),
	(23404, 'id', 146, 'auth_shibboleth_manual_login', 'Manual login', 'Log masuk manual', NULL, 1785718266, NULL, 0, 0),
	(23405, 'id', 146, 'auth_shibboleth_select_member', 'I\'m a member of ...', 'saya anggota...', NULL, 1785718266, NULL, 0, 0),
	(23406, 'id', 146, 'auth_shibboleth_select_organization', 'For authentication via Shibboleth, please select your organisation from the drop-down menu:', 'Untuk otentikasi melalui Shibboleth, silakan pilih organisasi Anda dari menu tarik-turun:', NULL, 1785718266, NULL, 0, 0),
	(23407, 'id', 146, 'auth_shib_convert_data', 'Data modification API', 'API modifikasi data', NULL, 1785718266, NULL, 0, 0),
	(23408, 'id', 146, 'auth_shib_convert_data_description', 'You can use this API to further modify the data provided by Shibboleth. Read the <a href="{$a}">README</a> for further instructions.', 'Anda dapat menggunakan API ini untuk memodifikasi lebih lanjut data yang disediakan oleh Shibboleth. Baca <a href="{$a}">README</a> untuk petunjuk lebih lanjut.', NULL, 1785718266, NULL, 0, 0),
	(23409, 'id', 146, 'auth_shib_convert_data_warning', 'The file does not exist or is not readable by the webserver process!', 'Berkas tidak ada atau tidak dapat dibaca oleh proses server web!', NULL, 1785718266, NULL, 0, 0),
	(23410, 'id', 146, 'auth_shib_convert_data_filepath_warning', 'You cannot use a file that is located within the current site data directory ($CFG->dataroot) as the data modification API.', 'Anda tidak dapat menggunakan berkas yang terletak di dalam direktori data situs saat ini ($CFG->dataroot) sebagai API modifikasi data.', NULL, 1785718266, NULL, 0, 0),
	(23411, 'id', 146, 'auth_shib_changepasswordurl', 'Password-change URL', 'URL perubahan kata sandi', NULL, 1785718266, NULL, 0, 0),
	(23412, 'id', 146, 'auth_shib_idp_list', 'Identity providers', 'Penyedia identitas', NULL, 1785718266, NULL, 0, 0),
	(23413, 'id', 146, 'auth_shib_idp_list_description', 'Provide a list of Identity Provider entityIDs to let the user choose from on the login page.<br />On each line there must be a comma-separated tuple for entityID of the IdP (see the Shibboleth metadata file) and Name of IdP as it shall be displayed in the drop-down list.<br />As an optional third parameter you can add the location of a Shibboleth session initiator that shall be used in case your Moodle installation is part of a multi federation setup.', 'Berikan daftar ID entitas Penyedia Identitas agar pengguna dapat memilih dari halaman login.<br />Di setiap baris harus ada tupel yang dipisahkan koma untuk ID entitas IdP (lihat berkas metadata Shibboleth) dan Nama IdP sebagai itu akan ditampilkan dalam daftar tarik-turun.<br />Sebagai parameter ketiga opsional, Anda dapat menambahkan lokasi inisiator sesi Shibboleth yang akan digunakan jika instalasi Moodle Anda adalah bagian dari setelan multi federasi.', NULL, 1785718266, NULL, 0, 0),
	(23414, 'id', 146, 'auth_shib_instructions', 'Use the <a href="{$a}">Shibboleth login</a> to get access via Shibboleth, if your institution supports it. Otherwise, use the normal login form shown here.', 'Gunakan <a href="{$a}">Log masuk Shibboleth</a> untuk mendapatkan akses melalui Shibboleth, jika institusi Anda mendukungnya. Jika tidak, gunakan formulir log masuk normal yang ditunjukkan di sini.', NULL, 1785718266, NULL, 0, 0),
	(23415, 'id', 146, 'auth_shib_instructions_help', 'Here you should provide custom instructions for your users to explain Shibboleth.  It will be shown on the login page in the instructions section. The instructions must include a link to "<b>{$a}</b>" that users click when they want to log in.', 'Di sini Anda harus memberikan instruksi kustom bagi pengguna Anda untuk menjelaskan Shibboleth. Ini akan ditampilkan pada halaman login di bagian instruksi. Petunjuk harus menyertakan tautan ke "<b>{$a}</b>" yang diklik pengguna saat mereka ingin masuk.', NULL, 1785718266, NULL, 0, 0),
	(23416, 'id', 146, 'auth_shib_instructions_key', 'Login instructions', 'Petunjuk masuk', NULL, 1785718266, NULL, 0, 0),
	(23417, 'id', 146, 'auth_shib_integrated_wayf', 'Moodle WAYF service', 'Layanan Moodle WAYF', NULL, 1785718266, NULL, 0, 0),
	(23418, 'id', 146, 'auth_shib_integrated_wayf_description', 'If you enable this, Moodle will use its own WAYF service instead of the one configured for Shibboleth. Moodle will display a drop-down list on this alternative login page where the user has to select his Identity Provider.', 'Jika Anda mengaktifkan ini, Moodle akan menggunakan layanan WAYF-nya sendiri alih-alih yang dikonfigurasi untuk Shibboleth. Moodle akan menampilkan daftar tari-turun pada halaman log masuk alternatif ini di mana pengguna harus memilih Penyedia Identitasnya.', NULL, 1785718266, NULL, 0, 0),
	(23419, 'id', 146, 'auth_shib_logout_return_url', 'Alternative logout return URL', 'URL pengembalian log keluar alternatif', NULL, 1785718266, NULL, 0, 0),
	(23420, 'id', 146, 'auth_shib_logout_return_url_description', 'Provide the URL that Shibboleth users shall be redirected to after logging out.<br />If left empty, users will be redirected to the location that moodle will redirect users to', 'Berikan URL tujuan pengalihan pengguna Shibboleth setelah keluar.<br />Jika dibiarkan kosong, pengguna akan diarahkan ke lokasi yang akan diarahkan oleh moodle', NULL, 1785718266, NULL, 0, 0),
	(23421, 'id', 146, 'auth_shib_logout_url', 'Shibboleth Service Provider logout handler URL', 'URL pengendali log keluar Penyedia Layanan Shibboeth', NULL, 1785718266, NULL, 0, 0),
	(23422, 'id', 146, 'auth_shib_logout_url_description', 'Provide the URL to the Shibboleth Service Provider logout handler. This typically is <tt>/Shibboleth.sso/Logout</tt>', 'Berikan URL ke pengendali log keluar  URL penangan logout Penyedia Layanan Shibboeth. Ini biasanya <tt>/Shibboleth.sso/Logout</tt>', NULL, 1785718266, NULL, 0, 0),
	(23423, 'id', 146, 'auth_shib_no_organizations_warning', 'If you want to use the integrated WAYF service, you must provide a coma-separated list of Identity Provider entityIDs, their names and optionally a session initiator.', 'Jika Anda ingin menggunakan layanan WAYF terintegrasi, Anda harus memberikan daftar ID entitas Penyedia Identitas yang dipisahkan koma, namanya, dan inisiator sesi secara opsional.', NULL, 1785718266, NULL, 0, 0),
	(23424, 'id', 146, 'auth_shib_only', 'Shibboleth only', 'Hanya Shibboleth', NULL, 1785718266, NULL, 0, 0),
	(23425, 'id', 146, 'auth_shib_only_description', 'Check this option if a Shibboleth authentication shall be enforced', 'Centang opsi ini jika otentikasi Shibboleth harus ditegakkan', NULL, 1785718266, NULL, 0, 0),
	(23426, 'id', 146, 'auth_shib_username_description', 'Name of the webserver Shibboleth environment variable that shall be used as Moodle username', 'Nama variabel lingkungan Shibboleth server web yang akan digunakan sebagai nama pengguna Moodle', NULL, 1785718266, NULL, 0, 0),
	(23427, 'id', 146, 'shib_invalid_account_error', 'You seem to be Shibboleth authenticated but Moodle has no valid account for your username. Your account may not exist or it may have been suspended.', 'Anda tampaknya terautentikasi Shibboleth tetapi Moodle tidak memiliki akun yang valid untuk nama pengguna Anda. Akun Anda mungkin tidak ada atau mungkin telah ditangguhkan.', NULL, 1785718266, NULL, 0, 0),
	(23428, 'id', 146, 'shib_no_attributes_error', 'You seem to be Shibboleth authenticated but Moodle didn\'t receive any user attributes. Please check that your Identity Provider releases the necessary attributes ({$a}) to the Service Provider Moodle is running on or inform the webmaster of this server.', 'Anda tampaknya terautentikasi Shibboleth tetapi Moodle tidak menerima atribut pengguna apa pun. Harap periksa bahwa Penyedia Identitas Anda merilis atribut yang diperlukan ({$a}) ke Penyedia Layanan Moodle yang sedang berjalan atau beri tahu webmaster server ini.', NULL, 1785718266, NULL, 0, 0),
	(23429, 'id', 146, 'shib_not_all_attributes_error', 'Moodle needs certain Shibboleth attributes which are not present in your case. The attributes are: {$a}<br />Please contact the webmaster of this server or your Identity Provider.', 'Moodle membutuhkan atribut Shibboleth tertentu yang tidak ada dalam kasus Anda. Atributnya adalah: {$a}<br />Harap hubungi webmaster server ini atau Penyedia Identitas Anda.', NULL, 1785718266, NULL, 0, 0),
	(23430, 'id', 146, 'shib_not_set_up_error', 'Shibboleth authentication doesn\'t seem to be set up correctly because no Shibboleth environment variables are present for this page. Please consult the <a href="{$a}">README</a> for further instructions on how to set up Shibboleth authentication or contact the webmaster of this Moodle installation.', 'Autentikasi Shibboleth tampaknya tidak diatur dengan benar karena tidak ada variabel lingkungan Shibboleth untuk halaman ini. Silakan baca <a href="{$a}">README</a> untuk instruksi lebih lanjut tentang cara mengatur autentikasi Shibboleth atau hubungi webmaster instalasi Moodle ini.', NULL, 1785718266, NULL, 0, 0),
	(23431, 'id', 146, 'pluginname', 'Shibboleth', 'Shibboleth', NULL, 1785718266, NULL, 0, 0),
	(23432, 'id', 146, 'privacy:metadata', 'The Shibboleth authentication plugin does not store any personal data.', 'Pengaya autentikasi Shibboleth tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23433, 'id', 147, 'auth_webservicedescription', 'This authentication method should be used for accounts that are exclusively for use by web service clients.', 'Metode autentikasi ini harus digunakan untuk akun yang khusus digunakan oleh klien layanan web.', NULL, 1785718266, NULL, 0, 0),
	(23434, 'id', 147, 'pluginname', 'Web services authentication', 'Autentikasi layanan web', NULL, 1785718266, NULL, 0, 0),
	(23435, 'id', 147, 'privacy:metadata', 'The Web services authentication plugin does not store any personal data.', 'Pengaya autentikasi layanan web tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23436, 'id', 148, 'name', 'Gregorian', 'Gregorian', NULL, 1785718266, NULL, 0, 0),
