	(23438, 'id', 148, 'privacy:metadata', 'The Gregorian calendar format plugin does not store any personal data.', 'Pengaya tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23439, 'id', 149, 'cachedef_customlink', 'Custom link data', 'Data tautan kustom', NULL, 1785718266, NULL, 0, 0),
	(23440, 'id', 149, 'customlinkurl', 'Custom link URL', 'URL tautan kustom', NULL, 1785718266, NULL, 0, 0),
	(23441, 'id', 149, 'customlinkurl_help', 'Provide a link to an existing room from any communication service you would like to make available to participants - such as Microsoft Teams, Slack or Matrix.', 'Berikan tautan ke ruang yang ada dari layanan komunikasi apa pun yang ingin Anda sediakan bagi peserta - seperti Microsoft Teams, Slack, atau Matrix.', NULL, 1785718266, NULL, 0, 0),
	(23442, 'id', 149, 'customlinkurlinfo', 'The URL of an existing room already set up for this course.', 'URL ruang yang sudah disiapkan untuk kursus ini.', NULL, 1785718266, NULL, 0, 0),
	(23443, 'id', 149, 'pluginname', 'Custom link', 'Tautan kustom', NULL, 1785718266, NULL, 0, 0),
	(23444, 'id', 149, 'privacy:metadata', 'Custom link communication plugin does not store any personal data.', 'Pengaya komunikasi tautan kustom tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23445, 'id', 150, 'cachedef_serverversions', 'Matrix server version information for running servers', 'Informasi versi server matriks untuk menjalankan server', NULL, 1785718266, NULL, 0, 0),
	(23446, 'id', 150, 'matrixhomeservername', 'Homeserver name', 'Nama Server Rumah', NULL, 1785718266, NULL, 0, 0),
	(23447, 'id', 150, 'matrixhomeservername_desc', 'The part after <code>@user:</code> in your Matrix ID (e.g. <code>example.com</code> in <code>@user:example.com</code>)', 'Bagian setelah <code>@user:</code> di ID Matrix Anda (misalnya <code>example.com</code> di <code>@user:example.com</code>)', NULL, 1785718266, NULL, 0, 0),
	(23448, 'id', 150, 'matrixhomeserverurl', 'Homeserver URL', 'URL homeserver', NULL, 1785718266, NULL, 0, 0),
	(23449, 'id', 150, 'matrixhomeserverurl_desc', 'Server URL for connecting and creating accounts e.g. https://matrix.example.com.', 'URL server untuk menghubungkan dan membuat akun (misalnya, https://matrix.example.com)', NULL, 1785718266, NULL, 0, 0),
	(23450, 'id', 150, 'matrixaccesstoken', 'Access token', 'Token akses', NULL, 1785718266, NULL, 0, 0),
	(23451, 'id', 150, 'matrixaccesstoken_desc', 'Access token for the account which will perform actions on the homeserver.', 'Akses token untuk akun yang akan melakukan aksi di server rumah.', NULL, 1785718266, NULL, 0, 0),
	(23452, 'id', 150, 'matrixelementurl', 'Element web URL', 'Elemen URL web', NULL, 1785718266, NULL, 0, 0),
	(23453, 'id', 150, 'matrixroomtopic', 'Room topic', 'Topik ruangan', NULL, 1785718266, NULL, 0, 0),
	(23454, 'id', 150, 'matrixroomtopic_help', 'A short description of what this room is for.', 'Deskripsi singkat tentang kegunaan ruangan ini.', NULL, 1785718266, NULL, 0, 0),
	(23455, 'id', 150, 'matrixuserid', 'Matrix user ID', 'ID pengguna matriks', NULL, 1785718266, NULL, 0, 0),
	(23456, 'id', 150, 'matrix:moderator', 'Matrix moderator', 'Moderator matriks', NULL, 1785718266, NULL, 0, 0),
	(23457, 'id', 150, 'pluginname', 'Matrix', 'Matriks', NULL, 1785718266, NULL, 0, 0),
	(23458, 'id', 150, 'privacy:metadata', 'The Matrix communication plugin does not store any personal data.', 'Pengaya komunikasi Matrix tidak menyimpan data pribadi apa pun.', NULL, 1785718266, NULL, 0, 0),
	(23459, 'id', 150, 'matrixrefreshtoken', 'Refresh token', 'Segarkan token', NULL, 1785718266, NULL, 0, 0),
	(23460, 'id', 150, 'matrixrefreshtoken_desc', 'Admin refresh token to be associated with the access token.', 'Token penyegaran admin untuk dikaitkan dengan token akses.', NULL, 1785718266, NULL, 0, 0),
	(23461, 'id', 151, 'checkedbydefault', 'Checked by default', 'Secara bawaan sudah dicentang', NULL, 1785718266, NULL, 0, 0),
	(23462, 'id', 151, 'errorconfigunique', 'The checkbox field cannot be defined as unique.', 'Kolom kotak centang tidak dapat didefinisikan sebagai unik.', NULL, 1785718266, NULL, 0, 0),
	(23463, 'id', 151, 'pluginname', 'Checkbox', 'kotak centang', NULL, 1785718266, NULL, 0, 0),
	(23464, 'id', 151, 'privacy:metadata', 'The Checkbox field type plugin doesn\'t store any personal data; it uses tables defined in core.', 'Pengaya jenis kolom Kotak centang tidak menyimpan data pribadi apa pun; itu menggunakan tabel yang didefinisikan dalam inti.', NULL, 1785718266, NULL, 0, 0),
	(23465, 'id', 151, 'specificsettings', 'Checkbox field settings', 'Setelan kolom kotak centang', NULL, 1785718266, NULL, 0, 0),
	(23466, 'id', 152, 'errormaxdate', 'Please enter a date no later than {$a}.', 'Harap masukkan tanggal selambat-lambatnya {$a}.', NULL, 1785718266, NULL, 0, 0),
	(23467, 'id', 152, 'errormindate', 'Please enter a date on or after {$a}.', 'Harap masukkan tanggal pada atau setelah {$a}.', NULL, 1785718266, NULL, 0, 0),
	(23468, 'id', 152, 'includetime', 'Include time', 'Sertakan waktu', NULL, 1785718266, NULL, 0, 0),
