	(23510, 'id', 155, 'errorconfiglinkplaceholder', 'The link must contain a placeholder $$.', 'Tautan harus berisi placeholder $$.', NULL, 1785718267, NULL, 0, 0),
	(23511, 'id', 155, 'errorconfiglinksyntax', 'The link must be a valid URL starting with either http:// or https://.', 'Tautan harus berupa URL valid yang dimulai dengan http:// atau https://.', NULL, 1785718267, NULL, 0, 0),
	(23512, 'id', 155, 'errorconfigmaxlen', 'The maximum number of characters allowed must be between 1 and 1333.', 'Jumlah maksimum karakter yang diperbolehkan harus antara 1 dan 1333.', NULL, 1785718267, NULL, 0, 0),
	(23513, 'id', 155, 'errormaxlength', 'The maximum number of characters allowed in this field is {$a}.', 'Jumlah maksimum karakter yang diperbolehkan dalam bidang ini adalah {$a}.', NULL, 1785718267, NULL, 0, 0),
	(23514, 'id', 155, 'islink', 'Link field', 'Kolom tautan', NULL, 1785718267, NULL, 0, 0),
	(23515, 'id', 155, 'islink_help', 'To transform the text into a link, enter a URL containing $$ as a placeholder, where $$ will be replaced with the text. For example, to transform a Twitter ID to a link, enter https://twitter.com/$$.', 'Untuk mengubah teks menjadi tautan, masukkan URL yang berisi $$ sebagai placeholder, dengan $$ akan diganti dengan teks. Misalnya, untuk mengubah ID Twitter menjadi tautan, masukkan https://twitter.com/$$.', NULL, 1785718267, NULL, 0, 0),
	(23516, 'id', 155, 'ispassword', 'Password field', 'Kolom kata sandi', NULL, 1785718267, NULL, 0, 0),
