	(23551, 'id', 159, 'dbhost', 'Database host', 'Hos basis data', NULL, 1785718267, NULL, 0, 0),
	(23552, 'id', 159, 'dbhost_desc', 'Type database server IP address or host name. Use a system DSN name if using ODBC. Use a PDO DSN if using PDO.', 'Ketik alamat IP server basis data atau nama hos. Gunakan nama DSN sistem jika menggunakan ODBC. Gunakan PDO DSN jika menggunakan PDO.', NULL, 1785718267, NULL, 0, 0),
	(23553, 'id', 159, 'dbname', 'Database name', 'Nama basis data', NULL, 1785718267, NULL, 0, 0),
	(23554, 'id', 159, 'dbname_desc', 'Leave empty if using a DSN name in database host.', 'Biarkan kosong jika menggunakan nama DSN di hos basis data.', NULL, 1785718267, NULL, 0, 0),
	(23555, 'id', 159, 'dbpass', 'Database password', 'Kata sandi basis data', NULL, 1785718267, NULL, 0, 0),
	(23556, 'id', 159, 'dbsetupsql', 'Database setup command', 'Perintah penyiapan basis data', NULL, 1785718267, NULL, 0, 0),
	(23557, 'id', 159, 'dbsetupsql_desc', 'SQL command for special database setup, often used to setup communication encoding - example for MySQL and PostgreSQL: <em>SET NAMES \'utf8\'</em>', 'Perintah SQL untuk setelan basis data khusus, sering digunakan untuk mengatur pengodean komunikasi - contoh untuk MySQL dan PostgreSQL: <em> SET NAMES \'utf8\' </em>', NULL, 1785718267, NULL, 0, 0),
	(23558, 'id', 159, 'dbsybasequoting', 'Use sybase quotes', 'Gunakan kutipan sybase', NULL, 1785718267, NULL, 0, 0),
	(23559, 'id', 159, 'dbsybasequoting_desc', 'Sybase style single quote escaping - needed for Oracle, MS SQL and some other databases. Do not use for MySQL!', 'Sybase style single quote escaping - diperlukan untuk Oracle, MS SQL dan beberapa basis data lainnya. Jangan gunakan untuk MySQL!', NULL, 1785718267, NULL, 0, 0),
	(23560, 'id', 159, 'dbtype', 'Database driver', 'Pengandar basis data', NULL, 1785718267, NULL, 0, 0),
	(23561, 'id', 159, 'dbtype_desc', 'ADOdb database driver name, type of the external database engine.', 'Nama pengandar basis data ADOdb, jenis mesin basis data eksternal.', NULL, 1785718267, NULL, 0, 0),
	(23562, 'id', 159, 'dbuser', 'Database user', 'Pengguna basis data', NULL, 1785718267, NULL, 0, 0),
	(23563, 'id', 159, 'debugdb', 'Debug ADOdb', 'Awakutu ADOdb', NULL, 1785718267, NULL, 0, 0),
	(23564, 'id', 159, 'debugdb_desc', 'Debug ADOdb connection to external database - use when getting empty page during login. Not suitable for production sites!', 'Awakutu koneksi ADOdb ke basis data eksternal - gunakan saat mendapatkan halaman kosong selama login. Tidak cocok untuk situs produksi!', NULL, 1785718267, NULL, 0, 0),
	(23565, 'id', 159, 'defaultcategory', 'Default new course category', 'Kategori kursus baru bawaan', NULL, 1785718267, NULL, 0, 0),
	(23566, 'id', 159, 'defaultcategory_desc', 'The default category for auto-created courses. Used when no new category id specified or not found.', 'Kategori bawaan untuk kursus yang dibuat secara otomatis. Digunakan ketika tidak ada id kategori baru yang ditentukan atau tidak ditemukan.', NULL, 1785718267, NULL, 0, 0),
	(23567, 'id', 159, 'defaultrole', 'Default role', 'Peran bawaan', NULL, 1785718267, NULL, 0, 0),
	(23568, 'id', 159, 'defaultrole_desc', 'The role that will be assigned by default if no other role is specified in external table.', 'Peran yang akan ditetapkan secara bawaan jika tidak ada peran lain yang ditentukan di tabel eksternal.', NULL, 1785718267, NULL, 0, 0),
	(23569, 'id', 159, 'ignorehiddencourses', 'Ignore hidden courses', 'Abaikan kursus tersembunyi', NULL, 1785718267, NULL, 0, 0),
	(23570, 'id', 159, 'ignorehiddencourses_desc', 'If enabled users will not be enrolled on courses that are set to be unavailable to students.', 'Jika diaktifkan, pengguna tidak akan terdaftar di kursus yang disetel untuk tidak tersedia bagi siswa.', NULL, 1785718267, NULL, 0, 0),
	(23571, 'id', 159, 'localcategoryfield', 'Local category field', 'Ruas kategori lokal', NULL, 1785718267, NULL, 0, 0),
	(23572, 'id', 159, 'localcoursefield', 'Local course field', 'Ruas kategori lokal', NULL, 1785718267, NULL, 0, 0),
	(23573, 'id', 159, 'localrolefield', 'Local role field', 'Ruas peran lokal', NULL, 1785718267, NULL, 0, 0),
	(23574, 'id', 159, 'localuserfield', 'Local user field', 'Ruas peran lokal', NULL, 1785718267, NULL, 0, 0),
	(23575, 'id', 159, 'newcourseenddate', 'New course end date field', 'Kolom tanggal akhir kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23576, 'id', 159, 'newcourseenddate_desc', 'Specify a date in the format yyyy-mm-dd or Unix time, or leave blank for the course end date to be calculated from the configured course duration.', 'Tentukan tanggal dalam format yyyy-mm-dd atau waktu Unix, atau biarkan kosong agar tanggal akhir kursus dihitung dari durasi kursus yang dikonfigurasi.', NULL, 1785718267, NULL, 0, 0),
	(23577, 'id', 159, 'newcoursetable', 'Remote new courses table', 'Tabel kursus baru jarak jauh', NULL, 1785718267, NULL, 0, 0),
	(23578, 'id', 159, 'newcoursetable_desc', 'Specify of the name of the table that contains list of courses that should be created automatically. Empty means no courses are created.', 'Tentukan nama tabel yang berisi daftar kursus yang harus dibuat secara otomatis. Kosong berarti tidak ada kursus yang dibuat.', NULL, 1785718267, NULL, 0, 0),
	(23579, 'id', 159, 'newcoursecategory', 'New course category field', 'Ruas kategori kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23580, 'id', 159, 'newcoursefullname', 'New course full name field', 'Ruas nama lengkap kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23581, 'id', 159, 'newcourseidnumber', 'New course ID number field', 'Ruas nomor ID kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23582, 'id', 159, 'newcoursestartdate', 'New course start date field', 'Kolom tanggal mulai kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23583, 'id', 159, 'newcoursestartdate_desc', 'Specify a date in the format yyyy-mm-dd or Unix time, or leave blank for the course start date to be set to the current date.', 'Tentukan tanggal dalam format yyyy-mm-dd atau waktu Unix, atau biarkan kosong agar tanggal mulai kursus ditetapkan ke tanggal saat ini.', NULL, 1785718267, NULL, 0, 0),
	(23584, 'id', 159, 'newcourseshortname', 'New course short name field', 'Ruas nama singkat kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23585, 'id', 159, 'pluginname', 'External database', 'Basis data eksternal', NULL, 1785718267, NULL, 0, 0),
	(23586, 'id', 159, 'pluginname_desc', 'You can use an external database (of nearly any kind) to control your enrolments. It is assumed your external database contains at least a field containing a course ID, and a field containing a user ID. These are compared against fields that you choose in the local course and user tables.', 'Anda dapat menggunakan basis data eksternal (hampir semua jenis) untuk mengontrol pendaftaran Anda. Diasumsikan basis data eksternal Anda berisi setidaknya satu ruas yang berisi ID kursus, dan ruas yang berisi ID pengguna. Ini dibandingkan dengan ruas yang Anda pilih di kursus lokal dan tabel pengguna.', NULL, 1785718267, NULL, 0, 0),
	(23587, 'id', 159, 'remotecoursefield', 'Remote course field', 'Ruas kursus jarak jauh', NULL, 1785718267, NULL, 0, 0),
	(23588, 'id', 159, 'remotecoursefield_desc', 'The name of the field in the remote table that we are using to match entries in the course table.', 'Nama ruas di tabel jarak jauh yang kami gunakan untuk mencocokkan entri di tabel kursus.', NULL, 1785718267, NULL, 0, 0),
	(23589, 'id', 159, 'remoteenroltable', 'Remote user enrolment table', 'Tabel pendaftaran pengguna jarak jauh', NULL, 1785718267, NULL, 0, 0),
	(23590, 'id', 159, 'remoteenroltable_desc', 'Specify the name of the table that contains list of user enrolments. Empty means no user enrolment sync.', 'Tentukan nama tabel yang berisi daftar pendaftaran pengguna. Kosong berarti tidak ada sinkronisasi pendaftaran pengguna.', NULL, 1785718267, NULL, 0, 0),
	(23591, 'id', 159, 'remoteotheruserfield', 'Remote Other User field', 'Ruas Pengguna Lain Jarak Jauh', NULL, 1785718267, NULL, 0, 0),
	(23592, 'id', 159, 'remoteotheruserfield_desc', 'The name of the field in the remote table that we are using to flag "Other User" role assignments.', 'Nama ruas di tabel jarak jauh yang kita gunakan untuk menandai penetapan peran "Pengguna Lain".', NULL, 1785718267, NULL, 0, 0),
	(23593, 'id', 159, 'remoterolefield', 'Remote role field', 'Ruas peran jarak jauh', NULL, 1785718267, NULL, 0, 0),
	(23594, 'id', 159, 'remoterolefield_desc', 'The name of the field in the remote table that we are using to match entries in the roles table.', 'Nama ruas di tabel jarak jauh yang kami gunakan untuk mencocokkan entri di tabel peran.', NULL, 1785718267, NULL, 0, 0),
	(23595, 'id', 159, 'remoteuserfield', 'Remote user field', 'Ruas pengguna jarak jauh', NULL, 1785718267, NULL, 0, 0),
