	(23597, 'id', 159, 'settingsheaderlocal', 'Local field mapping', 'Pemetaan ruas lokal', NULL, 1785718267, NULL, 0, 0),
	(23598, 'id', 159, 'settingsheaderremote', 'Remote enrolment sync', 'Sinkronisasi pendaftaran jarak jauh', NULL, 1785718267, NULL, 0, 0),
	(23599, 'id', 159, 'settingsheadernewcourses', 'Creation of new courses', 'Pembuatan kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23600, 'id', 159, 'syncenrolmentstask', 'Synchronise external database enrolments task', 'Sinkronisasi tugas pendaftaran basis data eksternal', NULL, 1785718267, NULL, 0, 0),
	(23601, 'id', 159, 'remoteuserfield_desc', 'The name of the field in the remote table that we are using to match entries in the user table.', 'Nama ruas di tabel jarak jauh yang kami gunakan untuk mencocokkan entri di tabel pengguna.', NULL, 1785718267, NULL, 0, 0),
	(23602, 'id', 159, 'templatecourse', 'New course template', 'Templat kursus baru', NULL, 1785718267, NULL, 0, 0),
	(23603, 'id', 159, 'templatecourse_desc', 'Optional: auto-created courses can copy their settings from a template course. Type here the shortname of the template course.', 'Opsional: kursus yang dibuat secara otomatis dapat menyalin setelannya dari templat kursus. Ketik di sini nama pendek dari templat kursus.', NULL, 1785718267, NULL, 0, 0),
	(23604, 'id', 159, 'privacy:metadata', 'The External database enrolment plugin does not store any personal data.', 'Pengaya pendaftaran basis data eksternal tidak menyimpan data pribadi apa pun.', NULL, 1785718267, NULL, 0, 0),
