	(23762, 'id', 164, 'bind_settings', 'Bind settings', 'Setelan Bind', NULL, 1785718268, NULL, 0, 0),
	(23763, 'id', 164, 'cannotcreatecourse', 'Cannot create course: missing required data from the LDAP record!', 'Tidak dapat membuat kursus: data yang diperlukan tidak ada dari data LDAP!', NULL, 1785718268, NULL, 0, 0),
	(23764, 'id', 164, 'cannotupdatecourse', 'Cannot update course: missing required data from the LDAP record! Course idnumber: \'{$a->idnumber}\'', 'Tidak dapat memperbarui kursus: data yang diperlukan tidak ada dari data LDAP!  Nomor ID kursus: \'{$a->idnumber}\'', NULL, 1785718268, NULL, 0, 0),
	(23765, 'id', 164, 'cannotupdatecourse_duplicateshortname', 'Cannot update course: Duplicate short name. Skipping course with idnumber \'{$a->idnumber}\'...', 'Tidak dapat memperbarui kursus: Nama singkat duplikat. Lewati kursus dengan Nomor ID \'{$a->idnumber}\' ...', NULL, 1785718268, NULL, 0, 0),
	(23766, 'id', 164, 'courseupdated', 'Course with idnumber \'{$a->idnumber}\' was successfully updated.', 'Kursus dengan nomor ID \'{$a->idnumber}\' berhasil diperbarui.', NULL, 1785718268, NULL, 0, 0),
	(23767, 'id', 164, 'courseupdateskipped', 'Course with idnumber \'{$a->idnumber}\' does not require updating. Skipping...', 'Kursus dengan nomor ID \'{$a->idnumber}\' tidak perlu diperbarui. Lewati ...', NULL, 1785718268, NULL, 0, 0),
	(23768, 'id', 164, 'category', 'The category for auto-created courses', 'Kategori untuk kursus yang dibuat secara otomatis', NULL, 1785718268, NULL, 0, 0),
	(23769, 'id', 164, 'category_key', 'Category', 'Kategori', NULL, 1785718268, NULL, 0, 0),
