	(23772, 'id', 164, 'coursenotexistskip', 'Course \'{$a}\' does not exist and autocreation disabled, skipping\n', 'kursus \'{$a}\' tidak ada dan pembuatan otomatis dinonaktifkan, lewati', NULL, 1785718268, NULL, 0, 0),
