	(23791, 'id', 164, 'createnotcourseextid', 'User enrolled to a non-existing course \'{$a->courseextid}\'', 'Pengguna terdaftar ke kursus yang tidak ada \'{$a->courseextid}\'', NULL, 1785718268, NULL, 0, 0),
