	(23794, 'id', 164, 'editlock', 'Lock value', 'Kunci nilai', NULL, 1785718268, NULL, 0, 0),
	(23795, 'id', 164, 'emptyenrolment', 'Empty enrolment for role \'{$a->role_shortname}\' in course \'{$a->course_shortname}\'\n', 'Kosongkan pendaftaran untuk peran \'{$a->role_shortname}\' dalam  kursus \'{$a->course_shortname}\'', NULL, 1785718268, NULL, 0, 0),
	(23796, 'id', 164, 'enrolname', 'LDAP', 'LDAP', NULL, 1785718268, NULL, 0, 0),
	(23797, 'id', 164, 'enroluser', 'Enrol user \'{$a->user_username}\' into course \'{$a->course_shortname}\' (id {$a->course_id})', 'Daftarkan pengguna \'{$a->user_username}\' ke dalam kursus \'{$a->course_shortname}\' (id {$a->course_id})', NULL, 1785718268, NULL, 0, 0),
	(23798, 'id', 164, 'enroluserenable', 'Enabled enrolment for user \'{$a->user_username}\' in course \'{$a->course_shortname}\' (id {$a->course_id})', 'Pendaftaran diaktifkan untuk pengguna \'{$a->user_username}\' dalam kursus \'{$a->course_shortname}\' (id {$a->course_id})', NULL, 1785718268, NULL, 0, 0),
	(23799, 'id', 164, 'explodegroupusertypenotsupported', 'ldap_explode_group() does not support selected user type: {$a}\n', 'ldap_explode_group() tidak mendukung jenis pengguna yang dipilih: {$a}', NULL, 1785718268, NULL, 0, 0),
