	(23802, 'id', 164, 'extremovedsuspendnoroles', 'Disabled enrolment and removed roles for user \'{$a->user_username}\' in course \'{$a->course_shortname}\' (id {$a->course_id})', 'Pendaftaran dinonaktifkan dan peran pengguna dihapus \'{$a->user_username}\' pada kursus \'{$a->course_shortname}\' (id {$a->course_id})', NULL, 1785718268, NULL, 0, 0),
