	(23977, 'id', 165, 'registerplatformdelete', 'Delete platform registration', 'Hapus pendaftaran platform', NULL, 1785718269, NULL, 0, 0),
	(23978, 'id', 165, 'registerplatformdeleteconfirm', 'Are you sure you want to delete the registration for the platform \'{$a}\'? This will also remove all tool deployments stored against this registration.', 'Yakin ingin menghapus pendaftaran untuk platform \'{$a}\'? Ini juga akan menghapus semua penerapan alat yang disimpan dalam pendaftaran ini.', NULL, 1785718269, NULL, 0, 0),
	(23979, 'id', 165, 'registerplatformdeletenotice', 'Platform registration deleted', 'Pendaftaran platform dihapus', NULL, 1785718269, NULL, 0, 0),
	(23980, 'id', 165, 'registerplatformedit', 'Edit registration', 'Edit registrasi', NULL, 1785718269, NULL, 0, 0),
	(23981, 'id', 165, 'registerplatformeditnotice', 'Platform registration updated', 'Pendaftaran platform diperbarui', NULL, 1785718269, NULL, 0, 0),
	(23982, 'id', 165, 'registration', 'Published tool registration', 'Diterbitkan alat pendaftaran', NULL, 1785718269, NULL, 0, 0),
