	(23985, 'id', 165, 'registrationdynamic', 'Dynamic registration', 'Registrasi dinamis', NULL, 1785718269, NULL, 0, 0),
	(23986, 'id', 165, 'registrationmanual', 'Manual registration', 'Pendaftaran manual', NULL, 1785718269, NULL, 0, 0),
