	(23988, 'id', 165, 'registrationstatusactive', 'Active', 'Aktif', NULL, 1785718269, NULL, 0, 0),
	(23989, 'id', 165, 'registrationstatuspending', 'Pending', 'Ditangguhkan', NULL, 1785718269, NULL, 0, 0),
	(23990, 'id', 165, 'registrationurl', 'Registration URL', 'URL Pendaftaran', NULL, 1785718269, NULL, 0, 0),
	(23991, 'id', 165, 'registrationurlinfomessage', 'If the platform supports dynamic registration, use the registration URL below. For further information on dynamic registration, see the documentation <a href="{$a}">Publish as LTI tool</a>.', 'Jika platform mendukung pendaftaran dinamis, gunakan URL pendaftaran di bawah ini. Untuk informasi lebih lanjut tentang pendaftaran dinamis, lihat dokumentasi <a href="{$a}">Publikasikan sebagai alat LTI</a>.', NULL, 1785718269, NULL, 0, 0),
	(23992, 'id', 165, 'registrationurl_help', 'If a registration URL (also called proxy URL) is used, then the tool is automatically configured.', 'Jika URL pendaftaran (juga disebut URL praksi) digunakan, alat tersebut secara otomatis dikonfigurasi.', NULL, 1785718269, NULL, 0, 0),
