	(23998, 'id', 165, 'rolelearner', 'Role for student', 'Peran siswa', NULL, 1785718269, NULL, 0, 0),
	(23999, 'id', 165, 'rolelearner_help', 'The role assigned in the tool to the remote student.', 'Peran yang diberikan dalam alat kepada siswa jarak jauh.', NULL, 1785718269, NULL, 0, 0),
	(24000, 'id', 165, 'secret', 'Secret', 'Rahasia', NULL, 1785718269, NULL, 0, 0),
	(24001, 'id', 165, 'secret_help', 'A string of characters which is shared with the remote system (LTI consumer) to provide access to the tool.', 'Serangkaian karakter yang dibagikan dengan sistem jarak jauh (konsumen LTI) untuk menyediakan akses ke alat.', NULL, 1785718269, NULL, 0, 0),
