	(24006, 'id', 165, 'tooldetails', 'Tool details', 'Detail alat', NULL, 1785718269, NULL, 0, 0),
	(24007, 'id', 165, 'toolsprovided', 'Published tools', 'Alat yang diterbitkan', NULL, 1785718269, NULL, 0, 0),
	(24008, 'id', 165, 'toolsprovided_help', 'A tool may be shared with another site by providing either launch details or a registration URL.', 'Sebuah alat dapat dibagikan dengan situs lain dengan memberikan detail peluncuran atau URL pendaftaran.', NULL, 1785718269, NULL, 0, 0),
