	(24023, 'id', 166, 'confirmbulkdeleteenrolment', 'Are you sure you want to delete these user enrolments?', 'Anda yakin ingin menghapus pendaftaran pengguna ini?', NULL, 1785718269, NULL, 0, 0),
	(24024, 'id', 166, 'defaultstart', 'Default enrolment start', 'Pendaftaran bawaan dimulai', NULL, 1785718269, NULL, 0, 0),
	(24025, 'id', 166, 'defaultperiod', 'Default enrolment duration', 'Durasi pendaftaran bawaan', NULL, 1785718269, NULL, 0, 0),
	(24026, 'id', 166, 'defaultperiod_desc', 'Default length of time that the enrolment is valid. If set to zero, the enrolment duration will be unlimited by default.', 'Durasi bawaan pendaftaran valid. Jika disetel ke nol, durasi pendaftaran tidak akan terbatas secara bawaan.', NULL, 1785718269, NULL, 0, 0),
	(24027, 'id', 166, 'defaultperiod_help', 'Default length of time that the enrolment is valid, starting with the moment the user is enrolled. If disabled, the enrolment duration will be unlimited by default.', 'Durasi bawaan pendaftaran valid, dimulai dari saat pengguna terdaftar. Jika dinonaktifkan, durasi pendaftaran tidak akan terbatas secara bawaan.', NULL, 1785718269, NULL, 0, 0),
