	(24033, 'id', 166, 'expiredaction', 'Enrolment expiry action', 'Tindakan kedaluwarsa pendaftaran', NULL, 1785718269, NULL, 0, 0),
	(24034, 'id', 166, 'expiredaction_help', 'Select action to carry out when user enrolment expires. Please note that some user data and settings are purged from course during course unenrolment.', 'Pilih tindakan yang akan dilakukan saat pendaftaran pengguna berakhir. Harap dicatat bahwa beberapa data pengguna dan setelan dihapus dari kursus selama pembatalan pendaftaran.', NULL, 1785718269, NULL, 0, 0),
	(24035, 'id', 166, 'expirymessageenrollersubject', 'Enrolment expiry notification', 'Pemberitahuan kedaluwarsa pendaftaran', NULL, 1785718269, NULL, 0, 0),
	(24036, 'id', 166, 'expirymessageenrollerbody', 'Enrolment in the course \'{$a->course}\' will expire within the next {$a->threshold} for the following users:\n\n{$a->users}\n\nTo extend their enrolment, go to {$a->extendurl}', 'Pendaftaran dalam kursus \'{$a->course}\' akan berakhir dalam {$a->threshold} berikutnya untuk pengguna berikut:\n\n{a->users}\n\nUntuk memperpanjang pendaftaran mereka, buka {$a->extendurl}', NULL, 1785718269, NULL, 0, 0),
	(24037, 'id', 166, 'expirymessageenrolledsubject', 'Enrolment expiry notification', 'Pemberitahuan kedaluwarsa pendaftaran', NULL, 1785718269, NULL, 0, 0),
	(24038, 'id', 166, 'expirymessageenrolledbody', 'Dear {$a->user},\n\nThis is a notification that your enrolment in the course \'{$a->course}\' is due to expire on {$a->timeend}.\n\nIf you need help, please contact {$a->enroller}.', 'Halo {$a->user},\n\nIni adalah pemberitahuan bahwa pendaftaran Anda dalam kursus \'{$a->course}\' akan berakhir pada {$a->timeend}.\n\nJika Anda membutuhkan bantuan, silakan hubungi {$a->enroller}.', NULL, 1785718269, NULL, 0, 0),
