	(24052, 'id', 166, 'sendexpirynotificationstask', 'Manual enrolment send expiry notifications task', 'Pendaftaran manual mengirim tugas pemberitahuan kedaluwarsa', NULL, 1785718269, NULL, 0, 0),
	(24053, 'id', 166, 'status', 'Enable manual enrolments', 'Aktifkan pendaftaran manual', NULL, 1785718269, NULL, 0, 0),
	(24054, 'id', 166, 'status_desc', 'Allow course access of internally enrolled users. This should be kept enabled in most cases.', 'Izinkan akses kursus dari pengguna yang terdaftar secara internal. Ini harus tetap diaktifkan dalam banyak kasus.', NULL, 1785718269, NULL, 0, 0),
	(24055, 'id', 166, 'status_help', 'This setting determines whether users can be enrolled manually, via a link in the course administration settings, by a user with appropriate permissions such as a teacher.', 'Setelan ini menentukan apakah pengguna dapat didaftarkan secara manual, melalui tautan dalam setelan administrasi kursus, oleh pengguna dengan izin yang sesuai seperti pengajar.', NULL, 1785718269, NULL, 0, 0),
	(24056, 'id', 166, 'statusenabled', 'Enabled', 'Diaktifkan', NULL, 1785718269, NULL, 0, 0),
	(24057, 'id', 166, 'statusdisabled', 'Disabled', 'Dinonaktifkan', NULL, 1785718269, NULL, 0, 0),
