	(24062, 'id', 166, 'unenroluser', 'Do you really want to unenrol "{$a->user}" from course "{$a->course}"?', 'Anda yakin ingin membatalkan pendaftaran "{$a->user}" dari kursus "{$a->course}"?', NULL, 1785718269, NULL, 0, 0),
	(24063, 'id', 166, 'unenrolusers', 'Unenrol users', 'Keluarkan pengguna', NULL, 1785718269, NULL, 0, 0),
	(24064, 'id', 166, 'wscannotenrol', 'Plugin instance cannot manually enrol a user in the course id = {$a->courseid}', 'Model pengaya tidak dapat mendaftarkan pengguna secara manual di ID kursus = {$a->courseid}', NULL, 1785718269, NULL, 0, 0),
	(24065, 'id', 166, 'wsnoinstance', 'Manual enrolment plugin instance doesn\'t exist or is disabled for the course (id = {$a->courseid})', 'Model pengaya pendaftaran manual tidak ada atau dinonaktifkan untuk kursus (id = {$a->courseid})', NULL, 1785718269, NULL, 0, 0),
	(24066, 'id', 166, 'wsusercannotassign', 'You don\'t have the permission to assign this role ({$a->roleid}) to this user ({$a->userid}) in this course ({$a->courseid}).', 'Anda tidak memiliki izin untuk menetapkan peran ini ({$a->roleid}) kepada pengguna ini ({$a->userid}) dalam kursus ini ({$a->courseid}).', NULL, 1785718269, NULL, 0, 0),
	(24067, 'id', 166, 'manualpluginnotinstalled', 'The "Manual" plugin has not yet been installed', 'Pengaya "Manual" belum terpasang', NULL, 1785718269, NULL, 0, 0),
