	(24104, 'id', 168, 'roleforremoteusers_help', 'What role will the remote users from the selected host get.', 'Peran apa yang akan didapat oleh pengguna jarak jauh dari hos yang dipilih.', NULL, 1785718270, NULL, 0, 0),
	(24105, 'id', 168, 'privacy:metadata', 'The MNet remote enrolments plugin does not store any personal data.', 'Pengaya pendaftaran jarak jauh MNet tidak menyimpan data pribadi apa pun.', NULL, 1785718270, NULL, 0, 0),
