	(24119, 'id', 169, 'enrolperiod_desc', 'Default length of time that the enrolment is valid. If set to zero, the enrolment duration will be unlimited by default.', 'Durasi bawaan pendaftaran valid. Jika disetel ke nol, durasi pendaftaran tidak akan terbatas secara bawaan.', NULL, 1785718270, NULL, 0, 0),
	(24120, 'id', 169, 'enrolperiod_help', 'Length of time that the enrolment is valid, starting with the moment the user is enrolled. If disabled, the enrolment duration will be unlimited.', 'Durasi pendaftaran valid, dimulai dari saat pengguna terdaftar. Jika dinonaktifkan, durasi pendaftaran tidak akan terbatas.', NULL, 1785718270, NULL, 0, 0),
