	(24123, 'id', 169, 'errdisabled', 'The PayPal enrolment plugin is disabled and does not handle payment notifications.', 'Pengaya pendaftaran PayPal dinonaktifkan dan tidak menangani pemberitahuan pembayaran.', NULL, 1785718270, NULL, 0, 0),
