	(24255, 'id', 171, 'airnotifierfielderror', 'Please remove any empty spaces or unnecessary characters from the following field: {$a}', 'Harap hapus spasi kosong atau karakter yang tidak perlu dari ruas berikut: {$a}', NULL, 1785718270, NULL, 0, 0),
