	(24935, 'id', 220, 'donottrack', 'Enable do not track Vimeo links', 'Aktifkan jangan lacak tautan Vimeo', NULL, 1785718274, NULL, 0, 0),
	(24936, 'id', 220, 'donottrack_desc', 'If enabled, the player will not track any session data, including all cookies and analytics.', 'Jika diaktifkan, pemain tidak akan melacak data sesi apa pun, termasuk semua kuki dan analitik.', NULL, 1785718274, NULL, 0, 0),
	(24937, 'id', 221, 'pluginname', 'YouTube', 'YouTube', NULL, 1785718274, NULL, 0, 0),
	(24938, 'id', 221, 'pluginname_help', 'The video-sharing website youtube.com. Video and playlist links are supported.', 'Situs berbagi video youtube.com. Tautan video dan daftar putar didukung.', NULL, 1785718274, NULL, 0, 0),
	(24939, 'id', 221, 'privacy:metadata', 'The Youtube media plugin does not store any personal data.', 'Pengaya media Youtube tidak menyimpan data pribadi apa pun.', NULL, 1785718274, NULL, 0, 0),
	(24940, 'id', 221, 'supportsvideo', 'YouTube videos', 'Video Youtube', NULL, 1785718274, NULL, 0, 0),
	(24941, 'id', 221, 'supportsplaylist', 'YouTube playlists', 'Daftar putar YouTube', NULL, 1785718274, NULL, 0, 0),
	(24942, 'id', 221, 'nocookie', 'Use no cookie domain', 'Tidak menggunakan domain kuki', NULL, 1785718274, NULL, 0, 0),
	(24943, 'id', 221, 'nocookie_desc', 'Use youtube-nocookie.com domain for embedding videos. This reduces the number of third party cookies used in embedding. This domain is also not blocked by some adblockers.', 'Gunakan domain youtube-nocookie.com untuk menyematkan video. Ini mengurangi jumlah kuki pihak ketiga yang digunakan dalam penyematan. Domain ini juga tidak diblokir oleh beberapa adblocker.', NULL, 1785718274, NULL, 0, 0),
	(24944, 'id', 222, 'filtername', 'Activity names auto-linking', 'Nama aktivitas penautan otomatis', NULL, 1785718274, NULL, 0, 0),
	(24945, 'id', 222, 'privacy:metadata', 'The Activity names auto-linking plugin does not store any personal data.', 'Pengaya tautan otomatis nama aktivitas tidak menyimpan data pribadi apa pun.', NULL, 1785718274, NULL, 0, 0),
	(24946, 'id', 223, 'filtername', 'Algebra notation', 'Notasi aljabar', NULL, 1785718274, NULL, 0, 0),
	(24947, 'id', 223, 'algebraicexpression', 'Algebraic expression', 'Ekspresi aljabar', NULL, 1785718274, NULL, 0, 0),
	(24948, 'id', 223, 'privacy:metadata', 'The Algebra notation plugin does not store any personal data.', 'Pengaya notasi Aljabar tidak menyimpan data pribadi apa pun.', NULL, 1785718274, NULL, 0, 0),
	(24949, 'id', 224, 'filtername', 'Code highlighter', 'Penyorot kode', NULL, 1785718274, NULL, 0, 0),
	(24950, 'id', 224, 'privacy:metadata', 'The code highlighter plugin does not store any personal data.', 'Pengaya penyorot kode tidak menyimpan data pribadi apa pun.', NULL, 1785718274, NULL, 0, 0),
	(24951, 'id', 225, 'filtername', 'Database auto-linking', 'Tautan otomatis basis data', NULL, 1785718274, NULL, 0, 0),
	(24952, 'id', 225, 'privacy:metadata', 'The Database auto-linking plugin does not store any personal data.', 'Pengaya tautan otomatis basis data tidak menyimpan data pribadi apa pun.', NULL, 1785718274, NULL, 0, 0),
	(24953, 'id', 226, 'allowedsourceslist', 'Allowed sources', 'Sumber yang diizinkan', NULL, 1785718275, NULL, 0, 0),
	(24954, 'id', 226, 'allowedsourceslistdesc', 'A list of URLs from which users can embed H5P content. If none are specified, all URLs will remain as links and not be displayed as embedded H5P content.\n\n\'[id]\' is a placeholder for the H5P content ID in the external source.\nFor example:\n\n- H5P.com: https://[xxxxxx].h5p.com/content/[id]\n- Wordpress: http://myserver/wp-admin/admin-ajax.php?action=h5p_embed&id=[id]', 'Daftar URL tempat pengguna dapat menyematkan konten H5P. Jika tidak ada yang ditentukan, semua URL akan tetap sebagai tautan dan tidak ditampilkan sebagai konten H5P yang disematkan.\n\n\'[id]\' adalah pengganti untuk ID konten H5P di sumber eksternal.\nSebagai contoh:\n\n- H5P.com: https://[xxxxxx].h5p.com/content/[id]\n- Wordpress: http://myserver/wp-admin/admin-ajax.php?action=h5p_embed&id=[id]', NULL, 1785718275, NULL, 0, 0),
	(24955, 'id', 226, 'filtername', 'Display H5P', 'Tampilan H5P', NULL, 1785718275, NULL, 0, 0),
	(24956, 'id', 226, 'privacy:metadata', 'The display H5P filter does not store any personal data.', 'Filter tampilan H5P tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24957, 'id', 227, 'filtername', 'Email protection', 'Perlindungan surel', NULL, 1785718275, NULL, 0, 0),
	(24958, 'id', 227, 'privacy:metadata', 'The Email protection plugin does not store any personal data.', 'Pengaya pelindung surel tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24959, 'id', 228, 'filtername', 'Display emoticons as images', 'Tampilkan emotikon sebagai gambar', NULL, 1785718275, NULL, 0, 0),
	(24960, 'id', 228, 'settingformats', 'Apply to formats', 'Terapkan ke format', NULL, 1785718275, NULL, 0, 0),
	(24961, 'id', 228, 'settingformats_desc', 'The filter will be applied only if the original text was inserted in one of the selected formats.', 'Filter akan diterapkan hanya jika teks asli disisipkan dalam salah satu format yang dipilih.', NULL, 1785718275, NULL, 0, 0),
	(24962, 'id', 228, 'privacy:metadata', 'The Display emoticons as images plugin does not store any personal data.', 'Pengaya Penampil emotikan sebagai gambar tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24963, 'id', 229, 'glossarycategory', '{$a->glossary}: Category {$a->category}', '{$a->glossary}: Kategori {$a->category}', NULL, 1785718275, NULL, 0, 0),
	(24964, 'id', 229, 'glossaryconcept', '{$a->glossary}: {$a->concept}', '{$a->glossary}: {$a->concept}', NULL, 1785718275, NULL, 0, 0),
	(24965, 'id', 229, 'filtername', 'Glossary auto-linking', 'Tautan otomatis glosarium', NULL, 1785718275, NULL, 0, 0),
	(24966, 'id', 229, 'privacy:metadata', 'The Glossary auto-linking plugin does not store any personal data.', 'Pengaya tautan otomatis glosarium tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24967, 'id', 229, 'attachments', 'Attachments', 'Lampiran', NULL, 1785718275, NULL, 0, 0),
	(24968, 'id', 230, 'filtername', 'MathJax', 'MathJax', NULL, 1785718275, NULL, 0, 0),
	(24969, 'id', 230, 'additionaldelimiters', 'Additional equation delimiters', 'Pembatas persamaan tambahan', NULL, 1785718275, NULL, 0, 0),
	(24970, 'id', 230, 'additionaldelimiters_help', 'MathJax filter parses text for equations contained within delimiter characters.\n\nThe list of recognised delimiter characters can be added to here (e.g. AsciiMath uses `). Delimiters can contain multiple characters and multiple delimiters can be separated with commas.', 'Filter MathJax mem-parsing teks untuk persamaan yang terdapat dalam karakter pembatas.\n\nIni adalah pesan percobaan untuk mengonfirmasi bahwa Anda telah berhasil mengonfigurasi surel keluar situs Anda.', NULL, 1785718275, NULL, 0, 0),
	(24971, 'id', 230, 'httpsurl', 'MathJax URL', 'URL Mathjax', NULL, 1785718275, NULL, 0, 0),
	(24972, 'id', 230, 'httpsurl_help', 'Full URL to MathJax library.', 'URL lengkap ke pustaka MathJax.', NULL, 1785718275, NULL, 0, 0),
	(24973, 'id', 230, 'texfiltercompatibility', 'TeX filter compatibility', 'Kompatibilitas filter TeX', NULL, 1785718275, NULL, 0, 0),
	(24974, 'id', 230, 'texfiltercompatibility_help', 'The MathJax filter can be used as a replacement for the TeX notation filter.\n\nTo support all the delimiters supported by the TeX notation filter, MathJax will be configured to display all equations "inline" with the text.', 'Filter MathJax dapat digunakan sebagai pengganti filter notasi TeX.\n\nUntuk mendukung semua pembatas yang didukung oleh filter notasi TeX, MathJax akan dikonfigurasi untuk menampilkan semua persamaan "sejajar" dengan teks.', NULL, 1785718275, NULL, 0, 0),
	(24975, 'id', 230, 'localinstall', 'Local MathJax installation', 'Instalasi MathJax lokal', NULL, 1785718275, NULL, 0, 0),
	(24976, 'id', 230, 'localinstall_help', 'The default MathJax configuration uses the CDN version of MathJax, but MathJax can be installed locally if required.\n\nThis can be useful to save on bandwidth or because of local proxy restrictions.\n\nTo use a local installation of MathJax, first download the full MathJax library from https://www.mathjax.org/. Then install it on a web server. Finally update the MathJax filter settings httpurl and/or httpsurl to point to the local MathJax.js URL.', 'Konfigurasi MathJax bawaan menggunakan MathJax versi CDN, tetapi MathJax dapat diinstal secara lokal jika diperlukan.\n\nIni dapat berguna untuk menghemat lebar pita atau karena pembatasan proksi lokal.\n\nUntuk menggunakan instalasi lokal MathJax, pertama-tama unduh pustaka MathJax lengkap dari https://www.mathjax.org/. Kemudian instal di server web. Terakhir, perbarui setelan filter MathJax httpurl dan/atau httpsurl untuk menunjuk ke URL MathJax.js lokal.', NULL, 1785718275, NULL, 0, 0),
	(24977, 'id', 230, 'mathjaxsettings', 'MathJax configuration', 'Konfigurasi MathJax', NULL, 1785718275, NULL, 0, 0),
	(24978, 'id', 230, 'mathjaxsettings_desc', 'The default MathJax configuration should be appropriate for most users, but MathJax is highly configurable and any of the standard MathJax configuration options can be added here.', 'Konfigurasi MathJax bawaan harus sesuai untuk sebagian besar pengguna, tetapi MathJax sangat dapat dikonfigurasi dan salah satu opsi konfigurasi MathJax standar dapat ditambahkan di sini.', NULL, 1785718275, NULL, 0, 0),
	(24979, 'id', 230, 'privacy:metadata', 'The MathJax plugin does not store any personal data.', 'Pengaya Mathjax tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24980, 'id', 231, 'fallbackaudio', 'Audio link', 'Tautan audio', NULL, 1785718275, NULL, 0, 0),
	(24981, 'id', 231, 'fallbackvideo', 'Video link', 'Tautan video', NULL, 1785718275, NULL, 0, 0),
	(24982, 'id', 231, 'filtername', 'Multimedia plugins', 'Pengaya multimedia', NULL, 1785718275, NULL, 0, 0),
	(24983, 'id', 231, 'linktomedia', 'The multimedia plugins filter finds a link in text that points to a multimedia resource and replaces the link with an appropriate multimedia player code which can play the resource. It also replaces &lt;video&gt; and &lt;audio&gt; tags with selected video and audio players.\n\n<a href="{$a}">Manage media players</a>', 'Filter plugin multimedia menemukan tautan dalam teks yang menunjuk ke sumber daya multimedia dan mengganti tautan dengan kode pemutar multimedia yang sesuai yang dapat memutar sumber daya. Itu juga menggantikan tag <video> dan <audio> dengan pemutar video dan audio yang dipilih.\n\n<a href="{$a}">Manage media players</a>', NULL, 1785718275, NULL, 0, 0),
	(24984, 'id', 231, 'privacy:metadata', 'The Multimedia plugins plugin does not store any personal data.', 'Pengaya multimedia tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24985, 'id', 232, 'filtername', 'Multi-language content', 'Konten Multi-Bahasa', NULL, 1785718275, NULL, 0, 0),
	(24986, 'id', 232, 'forceoldsyntax', 'Force old syntax', 'Paksa sintaks lama', NULL, 1785718275, NULL, 0, 0),
	(24987, 'id', 232, 'forceoldsyntax_desc', 'Force old multi-language syntax: &lt;span&gt; without the class="multilang" and &lt;lang&gt;.', 'Paksa sintaks multibahasa lama: &lt;span&gt; tanpa class="multilang" dan &lt;lang&gt;', NULL, 1785718275, NULL, 0, 0),
	(24988, 'id', 232, 'privacy:metadata', 'The Multi-language content plugin does not store any personal data.', 'Pengaya Konten Multibahasa tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(24989, 'id', 233, 'configconvertformat', 'If <i>latex</i> and <i>dvips</i> are present in addition to <i>convert</i> or <i>dvisvgm</i>, select the preferred image type (<i>convert</i> produces GIF or PNG; <i>dvisvgm</i> produces SVG). Otherwise <i>mimeTeX</i> will be used to to create GIF images.', 'Jika <i>lateks</i> dan <i>dvips</i> ada selain <i>konversi</i> atau <i>dvisvgm</i>, pilih jenis gambar yang diinginkan (<i> convert</i> menghasilkan GIF atau PNG; <i>dvisvgm</i> menghasilkan SVG). Jika tidak, <i>mimeTeX</i> akan digunakan untuk membuat gambar GIF.', NULL, 1785718275, NULL, 0, 0),
	(24990, 'id', 233, 'convertformat', 'Output image format', 'Format keluaran gambar', NULL, 1785718275, NULL, 0, 0),
	(24991, 'id', 233, 'latexpreamble', 'LaTeX preamble', 'Pembukaan LaTeX', NULL, 1785718275, NULL, 0, 0),
	(24992, 'id', 233, 'latexsettings', 'LaTeX renderer Settings', 'Setelan penyaji LaTeX', NULL, 1785718275, NULL, 0, 0),
	(24993, 'id', 233, 'filtername', 'TeX notation', 'Notasi TeX', NULL, 1785718275, NULL, 0, 0),
	(24994, 'id', 233, 'pathconvert', 'Path of <i>convert</i> binary', 'Jalur <i>konversi</i> biner', NULL, 1785718275, NULL, 0, 0),
	(24995, 'id', 233, 'pathdvips', 'Path of <i>dvips</i> binary', 'Jalur <i> dvip </i> biner', NULL, 1785718275, NULL, 0, 0),
	(24996, 'id', 233, 'pathdvisvgm', 'Path of <i>dvisvgm</i> binary', 'Jalur <i> dvisvgm </i> biner', NULL, 1785718275, NULL, 0, 0),
	(24997, 'id', 233, 'pathlatex', 'Path of <i>latex</i> binary', 'Jalur biner <i>lateks</i>', NULL, 1785718275, NULL, 0, 0),
	(24998, 'id', 233, 'pathmimetex', 'Path of <i>mimetex</i> binary', 'Jalur biner <i>mimetex</i>', NULL, 1785718275, NULL, 0, 0),
	(24999, 'id', 233, 'pathmimetexdesc', 'Moodle will use its own mimetex binary unless another valid path is specified.', 'Moodle akan menggunakan biner mimetexnya sendiri kecuali jika jalur valid lainnya ditentukan.', NULL, 1785718275, NULL, 0, 0),
	(25000, 'id', 233, 'source', 'TeX source', 'Sumber TeX', NULL, 1785718275, NULL, 0, 0),
	(25001, 'id', 233, 'privacy:metadata', 'The TeX notation plugin does not store any personal data.', 'Pengaya notasi TeX tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(25002, 'id', 234, 'embedimages', 'Embed images', 'Sematkan gambar', NULL, 1785718275, NULL, 0, 0),
	(25003, 'id', 234, 'embedimages_desc', 'Replace image urls with images in selected text formats.', 'Ganti URL gambar dengan gambar dalam format teks yang dipilih.', NULL, 1785718275, NULL, 0, 0),
	(25004, 'id', 234, 'filtername', 'Convert URLs into links and images', 'Konversi URL menjadi tautan dan gambar', NULL, 1785718275, NULL, 0, 0),
	(25005, 'id', 234, 'settingformats', 'Apply to formats', 'Terapkan ke format', NULL, 1785718275, NULL, 0, 0),
	(25006, 'id', 234, 'settingformats_desc', 'The filter will be applied only if the original text was inserted in one of the selected formats.', 'Filter akan diterapkan hanya jika teks asli disisipkan dalam salah satu format yang dipilih.', NULL, 1785718275, NULL, 0, 0),
	(25007, 'id', 234, 'privacy:metadata', 'The Convert URLs into links and images plugin does not store any personal data.', 'Pengaya konversi URL ke tautan dan gambar tidak menyimpan data pribadi apa pun.', NULL, 1785718275, NULL, 0, 0),
	(25008, 'id', 235, 'autosavefailed', 'Could not connect to the server. If you submit this page now, your changes may be lost.', 'Tidak dapat terhubung ke server. Jika Anda mengirimkan halaman ini sekarang, perubahan Anda mungkin akan hilang.', NULL, 1785718275, NULL, 0, 0),
	(25009, 'id', 235, 'autosavefrequency', 'Autosave frequency', 'Frekuensi simpan otomatis', NULL, 1785718275, NULL, 0, 0),
	(25010, 'id', 235, 'autosavefrequency_desc', 'This is the number of seconds between auto save attempts. Atto will automatically save the text in the editor according to this setting, so that text can be automatically restored when the same user returns to the same form.', 'Ini adalah jumlah detik antara upaya penyimpanan otomatis. Atto akan secara otomatis menyimpan teks di editor sesuai dengan setelan ini, sehingga teks dapat dipulihkan secara otomatis ketika pengguna yang sama kembali ke formulir yang sama.', NULL, 1785718275, NULL, 0, 0),
	(25011, 'id', 235, 'autosavesucceeded', 'Draft saved.', 'Draf disimpan.', NULL, 1785718275, NULL, 0, 0),
	(25012, 'id', 235, 'errorcannotparseline', 'The line \'{$a}\' is not in the correct format.', 'Baris \'{$a}\' tidak dalam format yang benar.', NULL, 1785718275, NULL, 0, 0),
	(25013, 'id', 235, 'errorgroupisusedtwice', 'The group \'{$a}\' is defined twice; group names must be unique.', 'Grup \'{$a}\' didefinisikan dua kali; nama grup harus unik.', NULL, 1785718275, NULL, 0, 0),
	(25014, 'id', 235, 'errornopluginsorgroupsfound', 'No plugins or groups found; please add some groups and plugins.', 'Tidak ada pengaya atau grup yang ditemukan; silakan tambahkan beberapa grup dan pengaya.', NULL, 1785718275, NULL, 0, 0),
	(25015, 'id', 235, 'errorpluginnotfound', 'The plugin \'{$a}\' cannot be used; it does not appear to be installed.', 'Pengaya \'{$a}\' tidak dapat digunakan; sepertinya tidak terpasang.', NULL, 1785718275, NULL, 0, 0),
	(25016, 'id', 235, 'errorpluginisusedtwice', 'The plugin \'{$a}\' is used twice; plugins can only be defined once.', 'Pengaya \'{$a}\' digunakan dua kali; plugin hanya dapat ditentukan satu kali.', NULL, 1785718275, NULL, 0, 0),
	(25017, 'id', 235, 'errortextrecovery', 'Unfortunately the draft version could not be restored.', 'Sayangnya versi draf tidak dapat dipulihkan.', NULL, 1785718275, NULL, 0, 0),
	(25018, 'id', 235, 'pluginname', 'Atto HTML editor', 'Editor HTML Atto', NULL, 1785718275, NULL, 0, 0),
	(25019, 'id', 235, 'richtexteditor', 'Rich text editor', 'Editor rich teks', NULL, 1785718275, NULL, 0, 0),
	(25020, 'id', 235, 'subplugintype_atto', 'Atto plugin', 'Pengaya Atto', NULL, 1785718275, NULL, 0, 0),
	(25021, 'id', 235, 'subplugintype_atto_plural', 'Atto plugins', 'Pengaya Atto', NULL, 1785718275, NULL, 0, 0),
	(25022, 'id', 235, 'settings', 'Atto toolbar settings', 'Setelan bilah alat Atto', NULL, 1785718275, NULL, 0, 0),
	(25023, 'id', 235, 'taskautosavecleanup', 'Delete expired autosave drafts', 'Hapus draf simpan otomatis yang kedaluwarsa', NULL, 1785718275, NULL, 0, 0),
	(25024, 'id', 235, 'textrecovered', 'A draft version of this text was automatically restored.', 'Versi konsep teks ini dipulihkan secara otomatis.', NULL, 1785718275, NULL, 0, 0),
	(25025, 'id', 235, 'toolbarconfig', 'Toolbar config', 'Konfigurasi bilah alat', NULL, 1785718275, NULL, 0, 0),
	(25026, 'id', 235, 'toolbarconfig_desc', 'The list of plugins and the order they are displayed can be configured here. The configuration consists of groups (one per line) followed by the ordered list of plugins for that group. The group is separated from the plugins with an equals sign and the plugins are separated with commas. The group names must be unique and should indicate what the buttons have in common. Button and group names should not be repeated and may only contain alphanumeric characters.', 'Daftar pengaya dan urutan tampilannya dapat dikonfigurasi di sini. Konfigurasi terdiri dari grup (satu per baris) diikuti oleh daftar plugin yang dipesan untuk grup itu. Grup dipisahkan dari plugin dengan tanda sama dengan dan plugin dipisahkan dengan koma. Nama grup harus unik dan harus menunjukkan kesamaan tombol. Nama tombol dan grup tidak boleh diulang dan hanya boleh berisi karakter alfanumerik.', NULL, 1785718275, NULL, 0, 0),
	(25027, 'id', 235, 'editor_command_keycode', 'Cmd + {$a}', 'Cmd + {$a}', NULL, 1785718275, NULL, 0, 0),
	(25028, 'id', 235, 'editor_control_keycode', 'Ctrl + {$a}', 'Ctrl + {$a}', NULL, 1785718275, NULL, 0, 0),
	(25029, 'id', 235, 'plugin_title_shortcut', '{$a->title} [{$a->shortcut}]', '{$a->title} [{$a->shortcut}]', NULL, 1785718275, NULL, 0, 0),
	(25030, 'id', 235, 'recover', 'Recover', 'Pulihkan', NULL, 1785718275, NULL, 0, 0),
	(25031, 'id', 235, 'infostatus', 'Information', 'Informasi', NULL, 1785718275, NULL, 0, 0),
	(25032, 'id', 235, 'warningstatus', 'Warning', 'Peringatan', NULL, 1785718275, NULL, 0, 0),
	(25033, 'id', 235, 'autosaves', 'Editor autosave information', 'Informasi simpan otomatis editor', NULL, 1785718275, NULL, 0, 0),
	(25034, 'id', 235, 'privacy:metadata:database:atto_autosave', 'Automatically saved text editor drafts.', 'Draf editor teks disimpan secara otomatis.', NULL, 1785718275, NULL, 0, 0),
	(25035, 'id', 235, 'privacy:metadata:database:atto_autosave:userid', 'The ID of the user whose data was saved.', 'ID pengguna yang datanya disimpan.', NULL, 1785718275, NULL, 0, 0),
	(25036, 'id', 235, 'privacy:metadata:database:atto_autosave:drafttext', 'The text which was saved.', 'Teks yang disimpan.', NULL, 1785718275, NULL, 0, 0),
