	(25042, 'id', 237, 'privacy:reason', 'The TinyMCE editor does not store any preferences or user data.', 'Editor TinyMCE tidak menyimpan preferensi atau data pengguna.', NULL, 1785718275, NULL, 0, 0),
	(25043, 'id', 237, 'branding', 'TinyMCE branding', 'Pencitraan merek TinyMCE', NULL, 1785718275, NULL, 0, 0),
	(25044, 'id', 237, 'branding_desc', 'Support TinyMCE by displaying the logo in the bottom corner of the text editor. The logo links to the TinyMCE website.', 'Dukung TinyMCE dengan menampilkan logo di pojok bawah editor teks. Logo tertaut ke situs web TinyMCE.', NULL, 1785718275, NULL, 0, 0),
	(25045, 'id', 237, 'extended_valid_elements', 'Extended valid elements', 'Elemen valid yang diperluas', NULL, 1785718275, NULL, 0, 0),
