	(26055, 'id', 281, 'privacy:metadata:preference:grade_report_aggregationposition', 'Whether the category and course total columns are displayed first or last in the gradebook reports', 'Apakah kategori dan kolom total kursus ditampilkan pertama atau terakhir dalam laporan buku nilai', NULL, 1785718281, NULL, 0, 0),
	(26056, 'id', 281, 'privacy:metadata:preference:grade_report_averagesdecimalpoints', 'The number of decimal places to display for each average or whether the overall decimal places setting for the category or grade item is used (inherit).', 'Jumlah digit desimal yang akan ditampilkan untuk setiap rata-rata atau apakah setelan digit desimal keseluruhan untuk kategori atau item nilai digunakan (mewarisi).', NULL, 1785718281, NULL, 0, 0),
	(26057, 'id', 281, 'privacy:metadata:preference:grade_report_averagesdisplaytype', 'Whether the average (mean) is displayed as real grades, percentages or letters, or whether the display type for the category or grade item is used (inherit).', 'Apakah rata-rata (rata-rata) ditampilkan sebagai nilai nyata, persentase atau huruf, atau apakah jenis tampilan untuk kategori atau item nilai digunakan (mewarisi).', NULL, 1785718281, NULL, 0, 0),
	(26058, 'id', 281, 'privacy:metadata:preference:grade_report_grader_collapsed_categories', 'List of gradebook categories to be collapsed', 'Daftar kategori buku nilai yang akan diciutkan', NULL, 1785718281, NULL, 0, 0),
	(26059, 'id', 281, 'privacy:metadata:preference:grade_report_meanselection', 'Whether cells with no grade should be included when calculating the average (mean) for each category or grade item', 'Apakah sel tanpa nilai harus disertakan saat menghitung rata-rata (rata-rata) untuk setiap kategori atau item nilai', NULL, 1785718281, NULL, 0, 0),
	(26060, 'id', 281, 'privacy:metadata:preference:grade_report_quickgrading', 'Whether to display a text input box for each grade, allowing many grades to be edited at the same time', 'Apakah akan menampilkan kotak input teks untuk setiap nilai, memungkinkan banyak nilai diedit secara bersamaan', NULL, 1785718281, NULL, 0, 0),
	(26061, 'id', 281, 'privacy:metadata:preference:grade_report_rangesdecimalpoints', 'The number of decimal places to display for each range or whether the overall decimal places setting for the category or grade item is used (inherit)', 'Jumlah digit desimal yang akan ditampilkan untuk setiap rentang atau apakah setelan tempat desimal keseluruhan untuk kategori atau item nilai digunakan (mewarisi)', NULL, 1785718281, NULL, 0, 0),
	(26062, 'id', 281, 'privacy:metadata:preference:grade_report_rangesdisplaytype', 'Whether the range is displayed as real grades, percentages or letters, or whether the display type for the category or grade item is used (inherit)', 'Apakah rentang ditampilkan sebagai nilai nyata, persentase, atau huruf, atau apakah jenis tampilan untuk kategori atau item nilai digunakan (mewarisi)', NULL, 1785718281, NULL, 0, 0),
	(26063, 'id', 281, 'privacy:metadata:preference:grade_report_showaverages', 'Whether to display an additional row with the average (mean) for each category and grade item', 'Apakah akan menampilkan baris tambahan dengan rata-rata (rata-rata) untuk setiap kategori dan item nilai', NULL, 1785718281, NULL, 0, 0),
	(26064, 'id', 281, 'privacy:metadata:preference:grade_report_shownumberofgrades', 'Whether to display in brackets after each average the number of grades used when calculating the average', 'Apakah akan ditampilkan dalam tanda kurung setelah setiap rata-rata jumlah nilai yang digunakan saat menghitung rata-rata', NULL, 1785718281, NULL, 0, 0),
	(26065, 'id', 281, 'privacy:metadata:preference:grade_report_showonlyactiveenrol', 'Whether to display only active enrolled users (not suspended) in gradebook report or all the enrolled users', 'Apakah hanya menampilkan pengguna terdaftar aktif (tidak ditangguhkan) dalam laporan buku nilai atau semua pengguna terdaftar', NULL, 1785718281, NULL, 0, 0),
	(26066, 'id', 281, 'privacy:metadata:preference:grade_report_showranges', 'Whether to display an additional row with the range for each category and grade item', 'Apakah akan menampilkan baris tambahan dengan rentang untuk setiap kategori dan item nilai', NULL, 1785718281, NULL, 0, 0),
	(26067, 'id', 281, 'privacy:metadata:preference:grade_report_showuserimage', 'Whether to show the user\'s profile image next to the name', 'Apakah akan menampilkan gambar profil pengguna di sebelah nama', NULL, 1785718281, NULL, 0, 0),
