	(26307, 'id', 289, 'err_scoreformat', 'Number of points for each level must be a valid number', 'Jumlah poin untuk setiap tingkatan harus berupa angka yang valid', NULL, 1785718282, NULL, 0, 0),
	(26308, 'id', 289, 'err_totalscore', 'Maximum number of points possible when graded by the rubric must be more than zero', 'Jumlah poin maksimum yang dimungkinkan ketika dinilai oleh rubrik harus lebih dari nol', NULL, 1785718282, NULL, 0, 0),
