	(26349, 'id', 289, 'sortlevelsasc', 'Sort order for levels:', 'Urutkan urutan untuk tingkatan:', NULL, 1785718282, NULL, 0, 0),
	(26350, 'id', 289, 'sortlevelsasc0', 'Descending by number of points', 'Menurun berdasarkan jumlah poin', NULL, 1785718282, NULL, 0, 0),
