	(26371, 'id', 291, 'pythonpackagenotinstalled', 'The moodlemlbackend Python package is not installed or there is a problem with it. Please execute "{$a}" from command line interface for more info.', 'Paket moodlemlbackend Python tidak diinstal atau ada masalah dengannya. Silakan jalankan "{$a}" dari antarmuka baris perintah untuk info lebih lanjut.', NULL, 1785718283, NULL, 0, 0),
	(26372, 'id', 291, 'pythonpathnotdefined', 'The path to your executable Python binary has not been defined. Please visit "{$a}" to set it.', 'Jalur ke biner Python yang dapat dieksekusi belum ditentukan. Kunjungi "{$a}" untuk menyetelnya.', NULL, 1785718283, NULL, 0, 0),
