	(26483, 'id', 300, 'nosubdir', 'You need to create at least one folder inside the <b>{$a}</b> directory so you can select it here.', 'Anda perlu membuat setidaknya satu folder di dalam direktori <b>{$a}</b> sehingga Anda dapat memilihnya di sini.', NULL, 1785718283, NULL, 0, 0),
