	(26487, 'id', 300, 'enablecourseinstances', 'Allow admins to add a file system repository instance to a course (configurable only by admins)', 'Izinkan admin menambahkan model repositori sistem berkas ke kursus (hanya dapat dikonfigurasi oleh admin)', NULL, 1785718283, NULL, 0, 0),
	(26488, 'id', 300, 'enableuserinstances', 'Allow admins to add a file system repository instance for personal use (configurable only by admins)', 'Izinkan admin menambahkan model repositori sistem berkas untuk penggunaan pribadi (hanya dapat dikonfigurasi oleh admin)', NULL, 1785718283, NULL, 0, 0),
	(26489, 'id', 300, 'privacy:metadata', 'The File system repository plugin does not store or transmit any personal data.', 'Pengaya repositori sistem file tidak menyimpan atau mengirimkan data pribadi apa pun.', NULL, 1785718283, NULL, 0, 0),
	(26490, 'id', 301, 'apikey', 'API key', 'Kunci API', NULL, 1785718283, NULL, 0, 0),
	(26491, 'id', 301, 'callbackurl', 'Callback URL', 'URL Callback', NULL, 1785718283, NULL, 0, 0),
	(26492, 'id', 301, 'callbackurltext', '<ol>\n<li>Visit <a href="http://www.flickr.com/services/api/keys/">Flickr API Keys</a> again.</li>\n<li>Make sure you set the callback URL for this Flickr key as <strong>{$a}</strong></li></ol>', '<ol> <li>Kunjungi <a href="http://www.flickr.com/services/api/keys/">Kunci API Flickr</a> lagi.</li> <li>Pastikan Anda menyetel URL panggilan balik untuk kunci Flickr ini sebagai <strong>{$a}</strong></li></ol>', NULL, 1785718283, NULL, 0, 0),
	(26493, 'id', 301, 'callbackwarning', '<ol>\n<li>Get a <a href="http://www.flickr.com/services/api/keys/">Flickr API Key and Secret</a> from Flickr for this Moodle site.</li>\n<li>Enter those details here, then click Save and then Settings to come back to this page.  You will see that Moodle has generated a callback URL for you.</li>\n<li>Edit your <a href="http://www.flickr.com/services/api/keys/">Flickr</a> key details again and set the callback URL.</li></ol>', '<ol> <li>Dapatkan <a href="http://www.flickr.com/services/api/keys/">Kunci dan Rahasia API Flickr</a> dari Flickr untuk situs Moodle ini.</li > <li>Masukkan detail tersebut di sini, lalu klik Simpan, lalu Setelan untuk kembali ke halaman ini. Anda akan melihat bahwa Moodle telah membuat URL panggilan balik untuk Anda.</li> <li>Edit <a href="http://www.flickr.com/services/api/keys/">Flickr</a> Anda detail kunci lagi dan setel URL panggilan balik.</li></ol>', NULL, 1785718283, NULL, 0, 0),
