	(26608, 'id', 306, 'defaultreturntype', 'Default return type', 'Jenis pengembalian bawaan', NULL, 1785718284, NULL, 0, 0),
	(26609, 'id', 306, 'fileoptions', 'The types and defaults for returned files is configurable here. Note that all files linked externally will be updated so that the owner is the Moodle system account.', 'Jenis dan bawaan untuk berkas yang dikembalikan dapat dikonfigurasi di sini. Perhatikan bahwa semua berkas yang ditautkan secara eksternal akan diperbarui sehingga pemiliknya adalah akun sistem Moodle.', NULL, 1785718284, NULL, 0, 0),
	(26610, 'id', 306, 'configuration_exception', 'An error in the configuration of the OAuth 2 client occurred: {$a}', 'Galat konfigurasi klien OAuth 2: {$a}', NULL, 1785718284, NULL, 0, 0),
	(26611, 'id', 306, 'request_exception', 'A request to {$a->instance} has failed. {$a->errormessage}', 'Permintaan untuk {$a->instance} gagal. {$a->errormessage}', NULL, 1785718284, NULL, 0, 0),
	(26612, 'id', 306, 'requestnotexecuted', 'The request could not be executed. If this happens repeatedly, please contact the site administrator.', 'Permintaan tidak dapat dijalankan. Jika ini terjadi berulang kali, silakan hubungi administrator situs.', NULL, 1785718284, NULL, 0, 0),
	(26613, 'id', 306, 'notauthorized', 'You are not authorised to execute this request. Please ensure you are authenticated with the correct account.', 'Anda tidak berwenang untuk menjalankan permintaan ini. Pastikan Anda diautentikasi dengan akun yang benar.', NULL, 1785718284, NULL, 0, 0),
	(26614, 'id', 306, 'contactadminwith', 'The requested action could not be executed. If this happens repeatedly, please contact the site administrator with the following additional information:<br>"<i>{$a}</i>".', 'Tindakan yang diminta tidak dapat dijalankan. Jika ini terjadi berulang kali, harap hubungi administrator situs dengan informasi tambahan berikut:<br>"<i>{$a}</i>".', NULL, 1785718284, NULL, 0, 0),
	(26615, 'id', 306, 'cannotconnect', 'The user could not be authenticated. Please log in and then upload the file.', 'Pengguna tidak dapat diautentikasi. Silakan masuk dan kemudian unggah berkas.', NULL, 1785718284, NULL, 0, 0),
	(26616, 'id', 306, 'filenotaccessed', 'The requested file could not be accessed. Please check whether you have chosen a valid file and you are authenticated with the right account.', 'Berkas yang diminta tidak dapat diakses. Harap periksa apakah Anda telah memilih berkas yang valid dan Anda diautentikasi dengan akun yang benar.', NULL, 1785718284, NULL, 0, 0),
	(26617, 'id', 306, 'couldnotmove', 'The requested file could not be moved in the {$a} folder.', 'Berkas yang diminta tidak dapat dipindahkan di folder {$a}.', NULL, 1785718284, NULL, 0, 0),
