	(26821, 'id', 321, 'connectionerror', 'The specified Solr server is not available or the specified index does not exist', 'Server Solr yang ditentukan tidak tersedia atau indeks yang ditentukan tidak ada', NULL, 1785718285, NULL, 0, 0),
	(26822, 'id', 321, 'connectionsettings', 'Connection settings', 'Setelan koneksi', NULL, 1785718285, NULL, 0, 0),
	(26823, 'id', 321, 'errorcreatingschema', 'Error creating the Solr schema: {$a}', 'Galat saat membuat skema Solr: {$a}', NULL, 1785718285, NULL, 0, 0),
	(26824, 'id', 321, 'errorvalidatingschema', 'Error validating Solr schema: field {$a->fieldname} does not exist. Please <a href="{$a->setupurl}">follow this link</a> to set up the required fields.', 'Kesalahan memvalidasi skema Solr: bidang {$a->fieldname} tidak ada. Harap <a href="{$a->setupurl}">ikuti tautan ini</a> untuk menyiapkan ruas yang diperlukan.', NULL, 1785718285, NULL, 0, 0),
	(26825, 'id', 321, 'errorsolr', 'The Solr search engine reported an error: {$a}', 'Mesin telusur Solr melaporkan kesalahan: {$a}', NULL, 1785718285, NULL, 0, 0),
	(26826, 'id', 321, 'extensionerror', 'The Apache Solr PHP extension is not installed. Please check the documentation.', 'Ekstensi Apache Solr PHP tidak diinstal. Silakan periksa dokumentasi.', NULL, 1785718285, NULL, 0, 0),
	(26827, 'id', 321, 'fileindexing', 'Enable file indexing', 'Aktifkan pengindeksan berkas', NULL, 1785718285, NULL, 0, 0),
	(26828, 'id', 321, 'fileindexing_help', 'If your Solr install supports it, this feature allows Moodle to send files to be indexed.<br/>\nYou will need to reindex all site contents after enabling this option for all files to be added.', 'Jika instalasi Solr Anda mendukungnya, fitur ini memungkinkan Moodle mengirim berkas untuk diindeks.<br/>\nAnda perlu mengindeks ulang semua konten situs setelah mengaktifkan opsi ini agar semua berkas dapat ditambahkan.', NULL, 1785718285, NULL, 0, 0),
	(26829, 'id', 321, 'fileindexsettings', 'File indexing settings', 'Setelan pengindeksan berkas', NULL, 1785718285, NULL, 0, 0),
	(26830, 'id', 321, 'maxindexfilekb', 'Maximum file size to index (kB)', 'Ukuran berkas maksimum untuk diindeks (kB)', NULL, 1785718285, NULL, 0, 0),
	(26831, 'id', 321, 'maxindexfilekb_help', 'Files larger than this number of kilobytes will not be included in search indexing. If set to zero, files of any size will be indexed.', 'Berkas yang lebih besar dari jumlah kilobyte ini tidak akan disertakan dalam pengindeksan pencarian. Jika disetel ke nol, berkas dengan ukuran berapa pun akan diindeks.', NULL, 1785718285, NULL, 0, 0),
	(26832, 'id', 321, 'minimumsolr4', 'Solr 4.0 is the minimum version required for Moodle', 'Solr 4.0 adalah versi minimum yang diperlukan untuk Moodle', NULL, 1785718285, NULL, 0, 0),
	(26833, 'id', 321, 'missingconfig', 'Your Apache Solr server is not yet configured in Moodle.', 'Server Apache Solr Anda belum dikonfigurasi di Moodle.', NULL, 1785718285, NULL, 0, 0),
	(26834, 'id', 321, 'multivaluedfield', 'Field "{$a}" returned an array instead of a scalar. Please delete the current index, create a new one and run setup_schema.php before indexing data in Solr.', 'Ruas "{$a}" mengembalikan array alih-alih skalar. Harap hapus indeks saat ini, buat yang baru dan jalankan setup_schema.php sebelum mengindeks data di Solr.', NULL, 1785718285, NULL, 0, 0),
	(26835, 'id', 321, 'nodatafromserver', 'No data from server', 'Tidak ada data dari server', NULL, 1785718285, NULL, 0, 0),
	(26836, 'id', 321, 'pluginname', 'Solr', 'Solr', NULL, 1785718285, NULL, 0, 0),
	(26837, 'id', 321, 'privacy:metadata', 'This plugin sends data externally to a linked Solr search engine. It does not store data locally.', 'Pengaya ini mengirimkan data secara eksternal ke mesin pencari Solr yang terhubung. Itu tidak menyimpan data secara lokal.', NULL, 1785718285, NULL, 0, 0),
	(26838, 'id', 321, 'privacy:metadata:data', 'Personal data passed through from the search subsystem.', 'Data pribadi melewati dari subsistem pencarian.', NULL, 1785718285, NULL, 0, 0),
	(26839, 'id', 321, 'schemafieldautocreated', 'Field "{$a}" already exists in Solr schema. You probably forgot to run this script before indexing data and fields were autocreated by Solr. Please delete the current index, create a new one and run setup_schema.php again before indexing data in Solr.', 'Ruas "{$a}" sudah ada di skema Solr. Anda mungkin lupa menjalankan skrip ini sebelum mengindeks data dan bidang dibuat otomatis oleh Solr. Harap hapus indeks saat ini, buat yang baru dan jalankan setup_schema.php lagi sebelum mengindeks data di Solr.', NULL, 1785718285, NULL, 0, 0),
	(26840, 'id', 321, 'schemasetupfromsolr5', 'Your Solr server version is lower than 5.0. This script can only set your schema if your Solr version is 5.0 or higher. You need to manually set the fields in your schema according to \\search_solr\\document::get_default_fields_definition().', 'Versi server Solr Anda lebih rendah dari 5.0. Skrip ini hanya dapat mengatur skema Anda jika versi Solr Anda 5.0 atau lebih tinggi. Anda perlu mengatur ruas dalam skema Anda secara manual sesuai dengan search_solr\\document::get_default_fields_definition().', NULL, 1785718285, NULL, 0, 0),
	(26841, 'id', 321, 'searchinfo', 'Search queries', 'Kueri penelusuran', NULL, 1785718285, NULL, 0, 0),
	(26842, 'id', 321, 'searchinfo_help', 'The field to be searched may be specified by prefixing the search query with \'title:\', \'content:\', \'name:\', or \'intro:\'. For example, searching for \'title:news\' would return results with the word \'news\' in the title.\n\nBoolean operators (\'AND\', \'OR\', \'NOT\') may be used to combine or exclude keywords.\n\nWildcard characters (\'*\' or \'?\' ) may be used to represent characters in the search query.', 'Bidang yang akan ditelusuri dapat ditentukan dengan mengawali kueri penelusuran dengan \'title:\', \'content:\', \'name:\', atau \'intro:\'. Misalnya, mencari \'title:news\' akan mengembalikan hasil dengan kata \'news\' di judulnya.\n\nOperator Boolean (\'AND\', \'OR\', \'NOT\') dapat digunakan untuk menggabungkan atau mengecualikan kata kunci.\n\nKarakter wildcard (\'*\' atau \'?\' ) dapat digunakan untuk mewakili karakter dalam kueri penelusuran.', NULL, 1785718285, NULL, 0, 0),
	(26843, 'id', 321, 'setupok', 'The schema is ready to be used.', 'Skema siap digunakan.', NULL, 1785718285, NULL, 0, 0),
