	(27018, 'id', 341, 'disregardedwithoutpenalty', 'The submission was invalid, and has been disregarded without penalty.', 'Pengajuan itu tidak sah, dan telah diabaikan tanpa penalti.', NULL, 1785718287, NULL, 0, 0),
