	(27020, 'id', 341, 'gradingdetailswithadjustment', 'Marks for this submission: {$a->raw}/{$a->max}. Accounting for previous tries, this gives <strong>{$a->cur}/{$a->max}</strong>.', 'Nilai untuk ajuan ini: {$a->raw}/{$a->max}. Dengan memperhitungkan percobaan sebelumnya, ini memberikan <strong>{$a->cur}/{$a->max}</strong>.', NULL, 1785718287, NULL, 0, 0),
	(27021, 'id', 341, 'gradingdetailswithadjustmentpenalty', 'Marks for this submission: {$a->raw}/{$a->max}. Accounting for previous tries, this gives <strong>{$a->cur}/{$a->max}</strong>. This submission attracted a penalty of {$a->penalty}.', 'Nilai untuk ajuan ini: {$a->raw}/{$a->max}. Dengan memperhitungkan percobaan sebelumnya, ini memberikan <strong>{$a->cur}/{$a->max}</strong>.', NULL, 1785718287, NULL, 0, 0),
	(27022, 'id', 341, 'gradingdetailswithadjustmenttotalpenalty', 'Marks for this submission: {$a->raw}/{$a->max}. Accounting for previous tries, this gives <strong>{$a->cur}/{$a->max}</strong>. This submission attracted a penalty of {$a->penalty}. Total penalties so far: {$a->totalpenalty}.', 'Nilai untuk ajuan ini: {$a->raw}/{$a->max}. Dengan memperhitungkan percobaan sebelumnya, ini memberikan <strong>{$a->cur}/{$a->max}</strong>. Ajuan ini dikenakan penalti {$a->penalty}. Total penalti sejauh ini: {$a->totalpenalty}.', NULL, 1785718287, NULL, 0, 0),
	(27023, 'id', 341, 'gradingdetailswithpenalty', 'Marks for this submission: {$a->raw}/{$a->max}. This submission attracted a penalty of {$a->penalty}.', 'Nilai untuk ajuan ini: {$a->raw}/{$a->max}. Ajuan ini dikenakan penalti {$a->penalty}.', NULL, 1785718287, NULL, 0, 0),
	(27024, 'id', 341, 'gradingdetailswithtotalpenalty', 'Marks for this submission: {$a->raw}/{$a->max}. This submission attracted a penalty of {$a->penalty}. Total penalties so far: {$a->totalpenalty}.', 'Nilai untuk ajuan ini: {$a->raw}/{$a->max}. Ajuan ini dikenakan penalti {$a->penalty}. Total penalti sejauh ini: {$a->totalpenalty}.', NULL, 1785718287, NULL, 0, 0),
