	(27050, 'id', 343, 'certainty2', 'C=2 (Mid: >67%)', 'C=2 (Pertengahan: >67%)', NULL, 1785718287, NULL, 0, 0),
	(27051, 'id', 343, 'certainty3', 'C=3 (Quite sure: >80%)', 'C=3 (Cukup yakin: >80%)', NULL, 1785718287, NULL, 0, 0),
