	(27505, 'id', 363, 'messageprovider:warningcheckid', 'Warning of invalid checkids', 'Peringatan checkid tidak valid', NULL, 1785718289, NULL, 0, 0),
	(27506, 'id', 363, 'warningcheckidbody', 'There is an issue with a Brickfield check\n which is active but not listed in the database. Please investigate.', 'Ada masalah dengan pemeriksaan Brickfield yang aktif tetapi tidak terdaftar dalam basis data. Tolong investigasi.', NULL, 1785718289, NULL, 0, 0),
	(27507, 'id', 363, 'warningcheckidsubject', 'Brickfield Toolkit checkID warning', 'Peringatan checkID Perangkat Brickfield', NULL, 1785718289, NULL, 0, 0),
	(27508, 'id', 363, 'checkdesc:alinksdontopennewwindow', 'Links opening into a new window should warn users in advance.', 'Tautan yang membuka jendela baru harus memperingatkan pengguna sebelumnya.', NULL, 1785718289, NULL, 0, 0),
	(27509, 'id', 363, 'checkdesc:amustcontaintext', 'A link needs to contain text to be perceivable.', 'Tautan harus berisi teks agar dapat dipahami.', NULL, 1785718289, NULL, 0, 0),
	(27510, 'id', 363, 'checkdesc:areadontopennewwindow', 'Areas, used in image maps, opening into a new window should warn users in advance.', 'Area, yang digunakan dalam peta gambar, membuka jendela baru harus memperingatkan pengguna sebelumnya.', NULL, 1785718289, NULL, 0, 0),
	(27511, 'id', 363, 'checkdesc:areahasaltvalue', 'Areas, used in image maps, should not be missing alt (alternative) text, similar to images.', 'Area, yang digunakan dalam peta gambar, tidak boleh melewatkan teks alt (alternatif), mirip dengan gambar.', NULL, 1785718289, NULL, 0, 0),
	(27512, 'id', 363, 'checkdesc:asuspiciouslinktext', 'Link text should be descriptive and provide context about its destination.', 'Teks tautan harus deskriptif dan memberikan konteks tentang tujuannya.', NULL, 1785718289, NULL, 0, 0),
	(27513, 'id', 363, 'checkdesc:basefontisnotused', 'Basefont elements (traditionally used for formatting) are not accessible and should not be used.', 'Elemen Basefont (biasanya digunakan untuk pemformatan) tidak dapat diakses dan tidak boleh digunakan.', NULL, 1785718289, NULL, 0, 0),
	(27514, 'id', 363, 'checkdesc:blinkisnotused', 'Blink elements, which blink on and off, are not accessible and should not be used.', 'Elemen Blink, yang berkedip dan mati, tidak dapat diakses dan tidak boleh digunakan.', NULL, 1785718289, NULL, 0, 0),
	(27515, 'id', 363, 'checkdesc:boldisnotused', 'Bold (b) elements should not be used; "strong" should be used instead.', 'Elemen Bold (b) tidak boleh digunakan; "strong" harus digunakan sebagai gantinya.', NULL, 1785718289, NULL, 0, 0),
	(27516, 'id', 363, 'checkdesc:contenttoolong', 'The overall page content length should not exceed 500 words.', 'Panjang konten halaman keseluruhan tidak boleh melebihi 500 kata.', NULL, 1785718289, NULL, 0, 0),
	(27517, 'id', 363, 'checkdesc:csstexthascontrast', 'The colour contrast between the text and background is too low.', 'Kontras warna antara teks dan latar belakang terlalu rendah.', NULL, 1785718289, NULL, 0, 0),
	(27518, 'id', 363, 'checkdesc:embedhasassociatednoembed', 'Embed elements (for embedding multimedia) should not be missing their corresponding "noembed" elements.', 'Elemen yang disematkan (untuk menyematkan multimedia) tidak boleh kehilangan elemen "noembed" yang sesuai.', NULL, 1785718289, NULL, 0, 0),
	(27519, 'id', 363, 'checkdesc:headerh3', 'Headers following after H3 headers (the editor large header option) should not break the page heading hierarchy.', 'Header yang mengikuti setelah header H3 (opsi editor header besar) tidak boleh merusak hierarki judul halaman.', NULL, 1785718289, NULL, 0, 0),
	(27520, 'id', 363, 'checkdesc:headershavetext', 'A header needs to contain text to be perceivable.', 'Header harus berisi teks agar dapat dipahami.', NULL, 1785718289, NULL, 0, 0),
	(27521, 'id', 363, 'checkdesc:iisnotused', 'Italic (i) elements should not be used; "em" should be used instead.', 'Italic (i) tidak boleh digunakan; "em" harus digunakan sebagai gantinya.', NULL, 1785718289, NULL, 0, 0),
	(27522, 'id', 363, 'checkdesc:imgaltisdifferent', 'Image alt (alternative) text should not be the image filename.', 'Teks alt (alternatif) gambar tidak boleh berupa nama berkas gambar.', NULL, 1785718289, NULL, 0, 0),
	(27523, 'id', 363, 'checkdesc:imgaltistoolong', 'Ensure that the image alt (alternative) text is concise enough to describe the image.', 'Pastikan teks alt (alternatif) gambar cukup ringkas untuk mendeskripsikan gambar.', NULL, 1785718289, NULL, 0, 0),
	(27524, 'id', 363, 'checkdesc:imgaltnotemptyinanchor', 'Image alt (alternative) text should not be empty, especially when the image has a link going elsewhere.', 'Teks alt (alternatif) gambar tidak boleh kosong, terutama jika gambar memiliki tautan ke tempat lain.', NULL, 1785718289, NULL, 0, 0),
	(27525, 'id', 363, 'checkdesc:imgaltnotplaceholder', 'Image alt (alternative) text should not be a simple placeholder text, such as "image".', 'Teks alt (alternatif) gambar tidak boleh berupa teks placeholder sederhana, seperti "gambar".', NULL, 1785718289, NULL, 0, 0),
	(27526, 'id', 363, 'checkdesc:imghasalt', 'Image alt (alternative) text should not be missing for image elements, unless purely decorative with no meaning.', 'Teks alt (alternatif) gambar tidak boleh hilang untuk elemen gambar, kecuali hanya dekoratif tanpa arti.', NULL, 1785718289, NULL, 0, 0),
	(27527, 'id', 363, 'checkdesc:imgwithmaphasusemap', 'Image maps, with clickable areas, need matching "usemap" and "map" elements.', 'Peta gambar, dengan area yang dapat diklik, membutuhkan elemen "usermap" dan "map" yang cocok.', NULL, 1785718290, NULL, 0, 0),
	(27528, 'id', 363, 'checkdesc:legendtextnotempty', 'Legend elements, used for captioning fieldset elements, should contain text.', 'Elemen legenda, digunakan untuk membuat teks pada elemen fieldset, harus berisi teks.', NULL, 1785718290, NULL, 0, 0),
	(27529, 'id', 363, 'checkdesc:marqueeisnotused', 'Marquee (auto-scrolling) elements are not accessible and should not be used.', 'Elemen marquee (pengguliran otomatis) tidak dapat diakses dan tidak boleh digunakan.', NULL, 1785718290, NULL, 0, 0),
	(27530, 'id', 363, 'checkdesc:noheadings', 'No headers makes content less structured and harder to read.', 'Tidak ada header yang membuat konten kurang terstruktur dan lebih sulit dibaca.', NULL, 1785718290, NULL, 0, 0);
INSERT INTO `mdl_tool_customlang` (`id`, `lang`, `componentid`, `stringid`, `original`, `master`, `local`, `timemodified`, `timecustomized`, `outdated`, `modified`) VALUES
	(27531, 'id', 363, 'checkdesc:objectmusthaveembed', 'Object elements (for embedding external resources) should not be missing their corresponding "embed" elements.', 'Elemen objek (untuk menyematkan sumber daya eksternal) tidak boleh kehilangan elemen "embed" yang sesuai.', NULL, 1785718290, NULL, 0, 0),
	(27532, 'id', 363, 'checkdesc:objectmusthavetitle', 'Object elements (for embedding external resources) should not be missing their corresponding "title" descriptions.', 'Elemen objek (untuk menyematkan sumber daya eksternal) tidak boleh kehilangan deskripsi "title" yang sesuai.', NULL, 1785718290, NULL, 0, 0),
	(27533, 'id', 363, 'checkdesc:objectmusthavevalidtitle', 'Object elements (for embedding external resources) should have corresponding "titles" with text.', 'Elemen objek (untuk menyematkan sumber daya eksternal) harus memiliki "titles" yang sesuai dengan teks.', NULL, 1785718290, NULL, 0, 0),
	(27534, 'id', 363, 'checkdesc:strikeisnotused', 'Strike (strike-through) elements should not be used; "del" (deleted) should be used instead.', 'Elemen Strike (strike-through) tidak boleh digunakan; "del" (dihapus) harus digunakan sebagai gantinya.', NULL, 1785718290, NULL, 0, 0),
	(27535, 'id', 363, 'checkdesc:tabledatashouldhaveth', 'Tables ideally should not be missing headers.', 'Tabel idealnya tidak boleh kehilangan header.', NULL, 1785718290, NULL, 0, 0),
	(27536, 'id', 363, 'checkdesc:tablesummarydoesnotduplicatecaption', 'Table summaries and captions should not be identical.', 'Ringkasan tabel dan keterangan gambar tidak boleh identik.', NULL, 1785718290, NULL, 0, 0),
	(27537, 'id', 363, 'checkdesc:tabletdshouldnotmerge', 'Tables ideally should not have any merged cells.', 'Tabel idealnya tidak boleh memiliki sel gabungan.', NULL, 1785718290, NULL, 0, 0),
	(27538, 'id', 363, 'checkdesc:tablethshouldhavescope', 'Table row or column scopes (used to map row and column to each cell) should be declared.', 'Cakupan baris atau kolom tabel (digunakan untuk memetakan baris dan kolom ke setiap sel) harus dideklarasikan.', NULL, 1785718290, NULL, 0, 0),
	(27539, 'id', 363, 'activate', 'Activate', 'Mengaktifkan', NULL, 1785718290, NULL, 0, 0),
	(27540, 'id', 363, 'activated', 'The plugin is activated and ready to use.', 'Pengaya sudah aktif dan siap digunakan.', NULL, 1785718290, NULL, 0, 0),
	(27541, 'id', 363, 'activationform', 'Brickfield registration', 'Pendaftaran Brickfield', NULL, 1785718290, NULL, 0, 0),
	(27542, 'id', 363, 'activationheader', 'Brickfield activation', 'Aktivasi Brickfield', NULL, 1785718290, NULL, 0, 0),
	(27543, 'id', 363, 'activationinfo', '<p>In order to use this plugin, you must provide valid keys for this site in this form.</p><p>Please <a href="{$a}" data-action="send_info" target="_blank">register at the Brickfield Portal (opens in new window)</a> to receive those keys if you do not already have them. </p><p>Once activated, your keys will then be validated via scheduled cron tasks.</p>', '<p> Untuk menggunakan pengaya ini, Anda harus memberikan kunci yang valid untuk situs ini dalam formulir ini. </p> <p> Harap <a href = "{$a}" data-action = "send_info" target = " _blank "> mendaftar di Brickfield Portal (terbuka di jendela baru) </a> untuk menerima kunci tersebut jika Anda belum memilikinya. </p> <p> Setelah diaktifkan, kunci Anda akan divalidasi melalui tugas cron terjadwal. </p>', NULL, 1785718290, NULL, 0, 0),
	(27544, 'id', 363, 'contenttypeerrors', 'Total results of activity content tests per course and per content type.', 'Hasil total tes konten aktivitas per kursus dan per jenis konten.', NULL, 1785718290, NULL, 0, 0),
	(27545, 'id', 363, 'contentyperesults', 'Total passed/failed for content areas per course.', 'Total lulus/gagal untuk area konten per kursus.', NULL, 1785718290, NULL, 0, 0),
	(27546, 'id', 363, 'country', 'Country', 'Negara', NULL, 1785718290, NULL, 0, 0),
	(27547, 'id', 363, 'country_help', 'Country of the site', 'Negara situs', NULL, 1785718290, NULL, 0, 0),
	(27548, 'id', 363, 'hashcorrect', 'The entered code is correct.', 'Kode yang dimasukkan benar.', NULL, 1785718290, NULL, 0, 0),
	(27549, 'id', 363, 'hashincorrect', 'The entered code is incorrect.', 'Kode yang dimasukkan salah.', NULL, 1785718290, NULL, 0, 0),
	(27550, 'id', 363, 'inactive', 'The plugin is inactive and cannot be used. Please enter valid registration keys, and press "Activate".', 'Pengaya tidak aktif dan tidak dapat digunakan. Silakan masukkan kunci registrasi yang valid, dan tekan "Aktifkan".', NULL, 1785718290, NULL, 0, 0),
