	(27565, 'id', 363, 'secretkey', 'API key', 'Kunci API', NULL, 1785718290, NULL, 0, 0),
	(27566, 'id', 363, 'secretkey_help', 'This code is received by email after registration.', 'Kode ini diterima melalui surel setelah pendaftaran.', NULL, 1785718290, NULL, 0, 0),
	(27567, 'id', 363, 'sendfollowinginfo', '<p>The following information will be periodically sent to contribute to overall statistics only. It will not be made public on any central listing.</p> {$a}', '<p> Informasi berikut akan dikirim secara berkala untuk berkontribusi hanya pada statistik keseluruhan. Ini tidak akan dipublikasikan di daftar pusat mana pun. </p> {$a}', NULL, 1785718290, NULL, 0, 0),
