	(27570, 'id', 363, 'usersmobileregistered', 'Number of users with registered mobile devices ({$a})', 'Jumlah pengguna dengan perangkat seluler terdaftar ({$a})', NULL, 1785718290, NULL, 0, 0),
	(27571, 'id', 363, 'validationerror', 'Registration key validation has failed. Check that your registered site URL and keys are correct.', 'Validasi kunci registrasi gagal. Pastikan URL dan kunci situs terdaftar Anda sudah benar.', NULL, 1785718290, NULL, 0, 0),
	(27572, 'id', 363, 'activityresults:pluginname', 'Activity breakdown accessibility tool report', 'Laporan alat aksesibilitas rincian aktivitas', NULL, 1785718290, NULL, 0, 0),
