	(27720, 'id', 367, 'modifiednum', 'There are {$a} modified strings. Do you wish to save these changes to your local language pack?', 'Terdapat {$a} string ubahan. Anda ingin menyimpannya pada paket bahasa lokal?', NULL, 1785718291, NULL, 0, 0),
	(27721, 'id', 367, 'nolocallang', 'No local strings found.', 'Tidak ditemukan string lokal.', NULL, 1785718291, NULL, 0, 0),
