	(27723, 'id', 367, 'notice_ignoreupdate', 'Ignoring string {$a->component}/{$a->stringid} because it is already defined.', 'Abaikan string {$a->component}/{$a->stringid} karena sudah ditentukan.', NULL, 1785718291, NULL, 0, 0),
	(27724, 'id', 367, 'notice_inexitentstring', 'String {$a->component}/{$a->stringid} not found.', 'String {$a->component}/{$a->stringid} tidak ditemukan.', NULL, 1785718291, NULL, 0, 0),
