	(27726, 'id', 367, 'notice_success', 'String {$a->component}/{$a->stringid} updated successfully.', 'String {$a->component}/{$a->stringid} berhasil diperbarui.', NULL, 1785718291, NULL, 0, 0),
	(27727, 'id', 367, 'nostringsfound', 'No strings found, please modify the filter settings', 'String tidak ditemukan, silakan ubah setelah filter', NULL, 1785718291, NULL, 0, 0),
	(27728, 'id', 367, 'placeholder', 'Placeholders', 'Placeholder', NULL, 1785718291, NULL, 0, 0),
	(27729, 'id', 367, 'placeholder_help', 'Placeholders are special statements like `{$a}` or `{$a->something}` within the string. They are replaced with a value when the string is actually printed.\n\nIt is important to copy them exactly as they are in the original string. Do not translate them nor change their left-to-right orientation.', 'Placeholder adalah pernyataan khusus seperti `{$a}` atau `{$a->something}` di dalam string. Mereka diganti dengan nilai ketika string benar-benar dicetak. Penting untuk menyalinnya persis seperti di string aslinya. Jangan menerjemahkannya atau mengubah orientasi kiri-ke-kanannya.', NULL, 1785718291, NULL, 0, 0),
	(27730, 'id', 367, 'placeholderwarning', 'string contains a placeholder', 'string berisi placeholder', NULL, 1785718291, NULL, 0, 0),
	(27731, 'id', 367, 'pluginname', 'Language customisation', 'Kustomisasi bahasa', NULL, 1785718291, NULL, 0, 0),
