	(27771, 'id', 368, 'confirmapproval', 'Do you really want to approve this data request?', 'Apakah Anda benar-benar ingin menyetujui permintaan data ini?', NULL, 1785718291, NULL, 0, 0),
	(27772, 'id', 368, 'confirmbulkapproval', 'Do you really want to bulk approve the selected data requests?', 'Anda yakin ingin menyetujui permintaan data yang dipilih secara massal?', NULL, 1785718291, NULL, 0, 0),
	(27773, 'id', 368, 'confirmcompletion', 'Do you really want to mark this user enquiry as complete?', 'Anda yakin ingin menandai pertanyaan pengguna ini selesai?', NULL, 1785718291, NULL, 0, 0),
	(27774, 'id', 368, 'confirmcontextdeletion', 'Do you really want to confirm the deletion of the selected contexts? This will also delete all of the user data for their respective sub-contexts.', 'Apakah Anda benar-benar ingin mengkonfirmasi penghapusan konteks yang dipilih? Ini juga akan menghapus semua data pengguna untuk sub-konteksnya masing-masing.', NULL, 1785718291, NULL, 0, 0),
	(27775, 'id', 368, 'confirmdenial', 'Do you really want deny this data request?', 'Apakah Anda benar-benar ingin menolak permintaan data ini?', NULL, 1785718291, NULL, 0, 0),
	(27776, 'id', 368, 'confirmbulkdenial', 'Do you really want to bulk deny the selected data requests?', 'Anda yakin ingin menolak permintaan data yang dipilih secara massal?', NULL, 1785718291, NULL, 0, 0),
	(27777, 'id', 368, 'confirmrequestresubmit', 'Are you sure you wish to cancel the current {$a->type} request for {$a->username} and resubmit it?', 'Anda yakin ingin membatalkan permintaan {$a->type} saat ini untuk {$a->username} dan mengajukan ulang kembali?', NULL, 1785718291, NULL, 0, 0),
