	(27816, 'id', 368, 'defaultsinfo', 'Default categories and purposes are applied to all new and existing instances where a value is not set.', 'Kategori dan tujuan bawaan diterapkan ke semua model baru dan yang sudah ada di mana nilai tidak ditetapkan.', NULL, 1785718291, NULL, 0, 0),
	(27817, 'id', 368, 'defaultswarninginfo', 'Warning: Changing these defaults may affect the retention period of existing instances.', 'Peringatan: Mengubah setelan bawaan ini dapat memengaruhi periode retensi model yang ada.', NULL, 1785718291, NULL, 0, 0),
