	(27836, 'id', 368, 'dporolemapping_desc', 'The privacy officer can manage data requests. The capability tool/dataprivacy:managedatarequests must be allowed for a role to be listed as a privacy officer role mapping option.', 'Petugas privasi dapat mengelola permintaan data. The capability tool/dataprivacy:managedatarequests harus diizinkan agar peran dicantumkan sebagai opsi pemetaan peran petugas privasi.', NULL, 1785718291, NULL, 0, 0),
	(27837, 'id', 368, 'editcategories', 'Edit categories', 'Edit kategori', NULL, 1785718291, NULL, 0, 0),
	(27838, 'id', 368, 'editcategory', 'Edit category', 'Edit kategori', NULL, 1785718291, NULL, 0, 0),
