	(27843, 'id', 368, 'effectiveretentionperiodcourse', '{$a} (after the course end date)', '{$a} (setelah tanggal akhir kursus)', NULL, 1785718291, NULL, 0, 0),
	(27844, 'id', 368, 'effectiveretentionperioduser', '{$a} (since the last time the user accessed the site)', '{$a} (sejak terakhir kali pengguna mengakses situs)', NULL, 1785718291, NULL, 0, 0),
	(27845, 'id', 368, 'emailsalutation', 'Dear {$a},', 'Hai {$a},', NULL, 1785718291, NULL, 0, 0),
	(27846, 'id', 368, 'errorcannotrequestdeleteforself', 'You don\'t have permission to create deletion request for yourself.', 'Anda tidak memiliki izin untuk membuat permintaan penghapusan untuk diri Anda sendiri.', NULL, 1785718291, NULL, 0, 0),
	(27847, 'id', 368, 'errorcannotrequestdeleteforother', 'You don\'t have permission to create deletion request for this user.', 'Anda tidak memiliki izin untuk membuat permintaan penghapusan untuk pengguna ini.', NULL, 1785718291, NULL, 0, 0),
	(27848, 'id', 368, 'errorcannotrequestexportforself', 'You don\'t have permission to create export request for yourself.', 'Anda tidak memiliki izin untuk membuat permintaan ekspor untuk diri sendiri.', NULL, 1785718291, NULL, 0, 0),
	(27849, 'id', 368, 'errorcontactdpodisabled', 'The option to contact the privacy officer is disabled.', 'Opsi untuk menghubungi petugas privasi dinonaktifkan.', NULL, 1785718291, NULL, 0, 0),
	(27850, 'id', 368, 'errorinvalidrequestcomments', 'The comments field may contain plain text only.', 'Kolom komentar hanya boleh berisi teks biasa.', NULL, 1785718291, NULL, 0, 0),
	(27851, 'id', 368, 'errorinvalidrequestcreationmethod', 'Invalid request creation method!', 'Metode pembuatan permintaan tidak valid!', NULL, 1785718291, NULL, 0, 0),
	(27852, 'id', 368, 'errorinvalidrequeststatus', 'Invalid request status!', 'Status permintaan tidak valid!', NULL, 1785718291, NULL, 0, 0),
	(27853, 'id', 368, 'errorinvalidrequesttype', 'Invalid request type!', 'Jenis permintaan tidak valid!', NULL, 1785718291, NULL, 0, 0),
	(27854, 'id', 368, 'errornocapabilitytorequestforothers', 'User {$a->requestedby} doesn\'t have the capability to make a data request on behalf of user {$a->userid}', 'Pengguna {$a->requestedby} tidak memiliki kemampuan untuk membuat permintaan data atas nama pengguna {$a->userid}', NULL, 1785718291, NULL, 0, 0),
	(27855, 'id', 368, 'errornoselectedcourse', 'You must select at least one course', 'Anda harus memilih setidaknya satu kursus', NULL, 1785718291, NULL, 0, 0),
	(27856, 'id', 368, 'errornoexpiredcontexts', 'There are no expired contexts to process', 'Tidak ada konteks kedaluwarsa untuk diproses', NULL, 1785718291, NULL, 0, 0),
	(27857, 'id', 368, 'errorcontexthasunexpiredchildren', 'The context "{$a}" still has sub-contexts that have not yet expired. No contexts have been flagged for deletion.', 'Konteks "{$a}" masih memiliki subkonteks yang belum kedaluwarsa. Tidak ada konteks yang telah ditandai untuk dihapus.', NULL, 1785718291, NULL, 0, 0),
	(27858, 'id', 368, 'errorrequestalreadyexists', 'You already have an ongoing request.', 'Anda sudah memiliki permintaan yang sedang berlangsung.', NULL, 1785718291, NULL, 0, 0),
	(27859, 'id', 368, 'errorrequestnotfound', 'Request not found', 'Permintaan tidak ditemukan', NULL, 1785718291, NULL, 0, 0),
	(27860, 'id', 368, 'errorrequestnotwaitingforapproval', 'The request is not awaiting approval. Either it is not yet ready or it has already been processed.', 'Permintaan tersebut tidak menunggu persetujuan. Bisa jadi belum siap atau sudah diproses.', NULL, 1785718291, NULL, 0, 0),
	(27861, 'id', 368, 'errorsendingmessagetodpo', 'An error was encountered while trying to send a message to {$a}.', 'Galat saat mencoba mengirim pesan ke {$a}.', NULL, 1785718291, NULL, 0, 0),
	(27862, 'id', 368, 'exceptionnotificationsubject', 'Exception occurred while processing privacy data', 'Pengecualian terjadi saat memproses data privasi', NULL, 1785718291, NULL, 0, 0),
	(27863, 'id', 368, 'exceptionnotificationbody', '<p>Exception occurred while calling <b>{$a->fullmethodname}</b>.<br>This means that plugin <b>{$a->component}</b> did not complete the processing of data. The following exception information may be passed on to the plugin developer:</p><pre>{$a->message}<br>\n\n{$a->backtrace}</pre>', '<p> Pengecualian terjadi saat memanggil <b> {$a->fullmethodname} </b>. <br> Ini berarti pengaya <b> {$a->component} </b> tidak menyelesaikan pemrosesan data. Informasi pengecualian berikut dapat diteruskan ke pengembang pengaya: </p> <pre> {$a->message} <br> {$a->backtrace} </pre>', NULL, 1785718291, NULL, 0, 0),
	(27864, 'id', 368, 'expiredretentionperiodtask', 'Expired retention period', 'Periode retensi kedaluwarsa', NULL, 1785718291, NULL, 0, 0),
	(27865, 'id', 368, 'expiry', 'Expiry', 'Kedaluwarsa', NULL, 1785718291, NULL, 0, 0),
	(27866, 'id', 368, 'expandplugin', 'Expand and collapse plugin.', 'Luaskan dan ciutkan pengaya.', NULL, 1785718291, NULL, 0, 0),
	(27867, 'id', 368, 'expandplugintype', 'Expand and collapse plugin type.', 'Luaskan dan ciutkan tipe pengaya.', NULL, 1785718291, NULL, 0, 0),
	(27868, 'id', 368, 'explanationtitle', 'Icons used on this page and what they mean.', 'Ikon yang digunakan di halaman ini dan artinya.', NULL, 1785718291, NULL, 0, 0),
	(27869, 'id', 368, 'external', 'Additional', 'Tambahan', NULL, 1785718291, NULL, 0, 0),
	(27870, 'id', 368, 'externalexplanation', 'An additional plugin installed on this site.', 'Pengaya tambahan dipasang di situs ini.', NULL, 1785718291, NULL, 0, 0),
	(27871, 'id', 368, 'filteroption', '{$a->category}: {$a->name}', '{$a->category}: {$a->name}', NULL, 1785718291, NULL, 0, 0),
	(27872, 'id', 368, 'filterexportdata', 'Approve request (data from selected courses)', 'Menyetujui permintaan (data dari kursus terpilih)', NULL, 1785718291, NULL, 0, 0),
	(27873, 'id', 368, 'frontpagecourse', 'Site home course', 'Kursus beranda situs', NULL, 1785718291, NULL, 0, 0),
	(27874, 'id', 368, 'gdpr_art_6_1_a_description', 'The data subject has given consent to the processing of his or her personal data for one or more specific purposes', 'Subjek data telah memberikan persetujuan untuk pemrosesan data pribadinya untuk satu atau beberapa tujuan tertentu', NULL, 1785718291, NULL, 0, 0),
	(27875, 'id', 368, 'gdpr_art_6_1_a_name', 'Consent (GDPR Art. 6.1(a))', 'Persetujuan (GDPR Art. 6.1(a))', NULL, 1785718291, NULL, 0, 0),
	(27876, 'id', 368, 'gdpr_art_6_1_b_description', 'Processing is necessary for the performance of a contract to which the data subject is party or in order to take steps at the request of the data subject prior to entering into a contract', 'Pemrosesan diperlukan untuk pelaksanaan kontrak di mana subjek data menjadi pihak atau untuk mengambil langkah-langkah atas permintaan subjek data sebelum menandatangani kontrak', NULL, 1785718291, NULL, 0, 0),
	(27877, 'id', 368, 'gdpr_art_6_1_b_name', 'Contract (GDPR Art. 6.1(b))', 'Kontrak (GDPR Art. 6.1(b))', NULL, 1785718291, NULL, 0, 0),
	(27878, 'id', 368, 'gdpr_art_6_1_c_description', 'Processing is necessary for compliance with a legal obligation to which the controller is subject', 'Pemrosesan diperlukan untuk mematuhi kewajiban hukum yang tunduk pada pengontrol', NULL, 1785718291, NULL, 0, 0),
	(27879, 'id', 368, 'gdpr_art_6_1_c_name', 'Legal obligation (GDPR Art 6.1(c))', 'Kewajiban hukum (GDPR Art 6.1(c))', NULL, 1785718291, NULL, 0, 0),
	(27880, 'id', 368, 'gdpr_art_6_1_d_description', 'Processing is necessary in order to protect the vital interests of the data subject or of another natural person', 'Pemrosesan diperlukan untuk melindungi kepentingan vital subjek data atau orang perseorangan lainnya', NULL, 1785718291, NULL, 0, 0),
	(27881, 'id', 368, 'gdpr_art_6_1_d_name', 'Vital interests (GDPR Art. 6.1(d))', 'Kepentingan vital (GDPR Art. 6.1(d))', NULL, 1785718291, NULL, 0, 0),
	(27882, 'id', 368, 'gdpr_art_6_1_e_description', 'Processing is necessary for the performance of a task carried out in the public interest or in the exercise of official authority vested in the controller', 'Pemrosesan diperlukan untuk pelaksanaan tugas yang dilakukan untuk kepentingan umum atau dalam pelaksanaan kewenangan resmi yang diberikan kepada pengawas', NULL, 1785718291, NULL, 0, 0),
	(27883, 'id', 368, 'gdpr_art_6_1_e_name', 'Public task (GDPR Art. 6.1(e))', 'Tugas publik (GDPR Art. 6.1(e))', NULL, 1785718291, NULL, 0, 0),
	(27884, 'id', 368, 'gdpr_art_6_1_f_description', 'Processing is necessary for the purposes of the legitimate interests pursued by the controller or  by a third party, except where such interests are overridden by the interests or fundamental rights and freedoms of the data subject which require protection of personal data, in particular where the data subject is a child', 'Pemrosesan diperlukan untuk tujuan kepentingan sah yang dikejar oleh pengontrol atau oleh pihak ketiga, kecuali jika kepentingan tersebut disampingkan oleh kepentingan atau hak dasar dan kebebasan subjek data yang memerlukan perlindungan data pribadi, khususnya di mana datanya subjek adalah anak-anak', NULL, 1785718291, NULL, 0, 0),
	(27885, 'id', 368, 'gdpr_art_6_1_f_name', 'Legitimate interests (GDPR Art. 6.1(f))', 'Kepentingan yang sah (GDPR Art. 6.1(f))', NULL, 1785718291, NULL, 0, 0),
	(27886, 'id', 368, 'gdpr_art_9_2_a_description', 'The data subject has given explicit consent to the processing of those personal data for one or more specified purposes, except where Union or Member State law provide that the prohibition referred to in paragraph 1 of GDPR Article 9 may not be lifted by the data subject', 'Subjek data telah memberikan persetujuan eksplisit untuk pemrosesan data pribadi tersebut untuk satu atau beberapa tujuan tertentu, kecuali jika undang-undang Union atau Member State mengatur bahwa larangan yang disebutkan dalam paragraf 1 GDPR Pasal 9 tidak dapat dicabut oleh subjek data', NULL, 1785718291, NULL, 0, 0),
	(27887, 'id', 368, 'gdpr_art_9_2_a_name', 'Explicit consent (GDPR Art. 9.2(a))', 'Persetujuan eksplisit (GDPR Art. 9.2(a))', NULL, 1785718291, NULL, 0, 0),
	(27888, 'id', 368, 'gdpr_art_9_2_b_description', 'Processing is necessary for the purposes of carrying out the obligations and exercising specific rights of the controller or of the data subject in the field of employment and social security and social protection law in so far as it is authorised by Union or Member State law or a collective agreement pursuant to Member State law providing for appropriate safeguards for the fundamental rights and the interests of the data subject', 'Pemrosesan diperlukan untuk tujuan melaksanakan kewajiban dan melaksanakan hak khusus dari pengontrol atau subjek data di bidang ketenagakerjaan dan jaminan sosial dan undang-undang perlindungan sosial sejauh diizinkan oleh undang-undang Uni atau Negara Anggota atau a kesepakatan bersama sesuai dengan hukum Negara Anggota yang menyediakan perlindungan yang sesuai untuk hak-hak dasar dan kepentingan subjek data', NULL, 1785718291, NULL, 0, 0),
	(27889, 'id', 368, 'gdpr_art_9_2_b_name', 'Employment and social security/protection law (GDPR Art. 9.2(b))', 'Undang-undang ketenagakerjaan dan jaminan / perlindungan sosial (GDPR Art. 9.2(b))', NULL, 1785718291, NULL, 0, 0),
	(27890, 'id', 368, 'gdpr_art_9_2_c_description', 'Processing is necessary to protect the vital interests of the data subject or of another natural person where the data subject is physically or legally incapable of giving consent', 'Pemrosesan diperlukan untuk melindungi kepentingan vital subjek data atau orang perseorangan lainnya di mana subjek data secara fisik atau hukum tidak dapat memberikan persetujuan', NULL, 1785718291, NULL, 0, 0),
	(27891, 'id', 368, 'gdpr_art_9_2_c_name', 'Protection of vital interests (GDPR Art. 9.2(c))', 'Perlindungan kepentingan vital (GDPR Art. 9.2(c))', NULL, 1785718291, NULL, 0, 0),
	(27892, 'id', 368, 'gdpr_art_9_2_d_description', 'Processing is carried out in the course of its legitimate activities with appropriate safeguards by a foundation, association or any other not-for-profit body with a political, philosophical, religious or trade-union aim and on condition that the processing relates solely to the members or to former members of the body or to persons who have regular contact with it in connection with its purposes and that the personal data are not disclosed outside that body without the consent of the data subjects', 'Pemrosesan dilakukan dalam aktivitasnya yang sah dengan pengamanan yang sesuai oleh yayasan, asosiasi atau badan nirlaba lainnya dengan tujuan politik, filosofis, agama atau serikat pekerja dan dengan syarat bahwa pemrosesan hanya berkaitan dengan anggota atau mantan anggota badan atau orang-orang yang secara teratur berhubungan dengannya sehubungan dengan tujuannya dan bahwa data pribadi tidak diungkapkan di luar badan itu tanpa persetujuan dari subjek data', NULL, 1785718291, NULL, 0, 0),
	(27893, 'id', 368, 'gdpr_art_9_2_d_name', 'Legitimate activities regarding the members/close contacts  of a foundation, association or other not-for-profit body (GDPR Art. 9.2(d))', 'Aktivitas yang sah mengenai anggota / kontak dekat yayasan, asosiasi atau badan nirlaba lainnya (GDPR Art. 9.2(d))', NULL, 1785718291, NULL, 0, 0),
	(27894, 'id', 368, 'gdpr_art_9_2_e_description', 'Processing relates to personal data which are manifestly made public by the data subject', 'Pemrosesan berkaitan dengan data pribadi yang secara nyata dipublikasikan oleh subjek data', NULL, 1785718291, NULL, 0, 0),
	(27895, 'id', 368, 'gdpr_art_9_2_e_name', 'Data made public by the data subject (GDPR Art. 9.2(e))', 'Data dipublikasikan oleh subjek data (GDPR Art. 9.2(e))', NULL, 1785718291, NULL, 0, 0),
	(27896, 'id', 368, 'gdpr_art_9_2_f_description', 'Processing is necessary for the establishment, exercise or defence of legal claims or whenever courts are acting in their judicial capacity', 'Pemrosesan diperlukan untuk pembentukan, pelaksanaan, atau pembelaan tuntutan hukum atau kapan pun pengadilan bertindak dalam kapasitas yudisial mereka', NULL, 1785718291, NULL, 0, 0),
	(27897, 'id', 368, 'gdpr_art_9_2_f_name', 'Legal claims and court actions (GDPR Art. 9.2(f))', 'Tuntutan hukum dan tindakan pengadilan (GDPR Art. 9.2(f))', NULL, 1785718291, NULL, 0, 0),
	(27898, 'id', 368, 'gdpr_art_9_2_g_description', 'Processing is necessary for reasons of substantial public interest, on the basis of Union or Member State law which shall be proportionate to the aim pursued, respect the essence of the right to data protection and provide for suitable and specific measures to safeguard the fundamental rights and the interests of the data subject', 'Pemrosesan diperlukan untuk alasan kepentingan publik yang substansial, berdasarkan undang-undang Union atau Negara Anggota yang harus proporsional dengan tujuan yang dicapai, menghormati esensi hak atas perlindungan data dan menyediakan tindakan yang sesuai dan spesifik untuk melindungi hak-hak fundamental dan kepentingan subjek data', NULL, 1785718291, NULL, 0, 0),
	(27899, 'id', 368, 'gdpr_art_9_2_g_name', 'Substantial public interest (GDPR Art. 9.2(g))', 'Kepentingan publik substansial (GDPR Art. 9.2(g))', NULL, 1785718291, NULL, 0, 0),
	(27900, 'id', 368, 'gdpr_art_9_2_h_description', 'Processing is necessary for the purposes of preventive or occupational medicine, for the assessment of the working capacity of the employee, medical diagnosis, the provision of health or social care or treatment or the management of health or social care systems and services on the basis of Union or Member State law or pursuant to contract with a health professional and subject to the conditions and safeguards referred to in paragraph 3 of GDPR Article 9', 'Pemrosesan diperlukan untuk tujuan pengobatan pencegahan atau pekerjaan, untuk penilaian kapasitas kerja karyawan, diagnosis medis, penyediaan perawatan atau perawatan kesehatan atau sosial atau pengelolaan sistem dan layanan perawatan kesehatan atau sosial berdasarkan Hukum Serikat atau Negara Anggota atau sesuai dengan kontrak dengan profesional kesehatan dan tunduk pada persyaratan dan perlindungan yang dirujuk pada paragraf 3 GDPR Pasal 9', NULL, 1785718291, NULL, 0, 0),
	(27901, 'id', 368, 'gdpr_art_9_2_h_name', 'Medical purposes (GDPR Art. 9.2(h))', 'Tujuan medis (GDPR Art. 9.2 (h))', NULL, 1785718291, NULL, 0, 0),
	(27902, 'id', 368, 'gdpr_art_9_2_i_description', 'Processing is necessary for reasons of public interest in the area of public health, such as protecting against serious cross-border threats to health or ensuring high standards of quality and safety of health care and of medicinal products or medical devices, on the basis of Union or Member State law which provides for suitable and specific measures to safeguard the rights and freedoms of the data subject, in particular professional secrecy', 'Pemrosesan diperlukan untuk alasan kepentingan publik di bidang kesehatan masyarakat, seperti melindungi dari ancaman lintas batas yang serius terhadap kesehatan atau memastikan standar kualitas dan keamanan perawatan kesehatan yang tinggi dan produk obat atau peralatan medis, berdasarkan Union atau hukum Negara Anggota yang mengatur tindakan yang sesuai dan spesifik untuk melindungi hak dan kebebasan subjek data, khususnya kerahasiaan profesional.', NULL, 1785718291, NULL, 0, 0),
	(27903, 'id', 368, 'gdpr_art_9_2_i_name', 'Public health (GDPR Art. 9.2(i))', 'Kesehatan masyarakat (GDPR Art. 9.2(i))', NULL, 1785718291, NULL, 0, 0),
	(27904, 'id', 368, 'gdpr_art_9_2_j_description', 'Processing is necessary for archiving purposes in the public interest, scientific or historical research purposes or statistical purposes in accordance with Article 89(1) based on Union or Member State law which shall be proportionate to the aim pursued, respect the essence of the right to data protection and provide for suitable and specific measures to safeguard the fundamental rights and the interests of the data subject', 'Pemrosesan diperlukan untuk tujuan pengarsipan untuk kepentingan umum, tujuan penelitian ilmiah atau sejarah atau tujuan statistik sesuai dengan Pasal 89 (1) berdasarkan undang-undang Uni atau Negara Anggota yang harus proporsional dengan tujuan yang dikejar, menghormati esensi hak untuk perlindungan data dan menyediakan langkah-langkah yang sesuai dan spesifik untuk melindungi hak-hak dasar dan kepentingan subjek data', NULL, 1785718291, NULL, 0, 0),
	(27905, 'id', 368, 'gdpr_art_9_2_j_name', 'Public interest, or scientific/historical/statistical research (GDPR Art. 9.2(j))', 'Kepentingan publik, atau penelitian ilmiah/sejarah/statistik (GDPR Art. 9.2(j))', NULL, 1785718291, NULL, 0, 0),
	(27906, 'id', 368, 'hide', 'Collapse all', 'Ciutkan semua', NULL, 1785718291, NULL, 0, 0),
	(27907, 'id', 368, 'httpwarning', 'Any data downloaded from this site may not be encrypted. Please contact your system administrator and request that they install SSL on this site.', 'Setiap data yang diunduh dari situs ini mungkin tidak dienkripsi. Silakan hubungi administrator sistem Anda dan minta mereka menginstal SSL di situs ini.', NULL, 1785718291, NULL, 0, 0),
	(27908, 'id', 368, 'inherit', 'Inherit', 'Mewarisi', NULL, 1785718291, NULL, 0, 0),
	(27909, 'id', 368, 'lawfulbases', 'Lawful bases', 'Dasar yang sah', NULL, 1785718291, NULL, 0, 0),
	(27910, 'id', 368, 'lawfulbases_help', 'Select at least one option that will serve as the lawful basis for processing personal data. For details on these lawful bases, please see <a href="https://gdpr-info.eu/art-6-gdpr/" target="_blank">GDPR Art. 6.1</a>', 'Pilih setidaknya satu opsi yang akan berfungsi sebagai dasar hukum untuk memproses data pribadi. Untuk detail tentang dasar hukum ini, silakan lihat <a href="https://gdpr-info.eu/art-6-gdpr/" target="_blank">GDPR Art. 6.1</a>', NULL, 1785718291, NULL, 0, 0),
	(27911, 'id', 368, 'markcomplete', 'Mark as complete', 'Tandai selesai', NULL, 1785718291, NULL, 0, 0),
	(27912, 'id', 368, 'markedcomplete', 'Your enquiry has been marked as complete by the privacy officer.', 'Permintaan Anda telah ditandai sebagai selesai oleh petugas privasi.', NULL, 1785718291, NULL, 0, 0),
	(27913, 'id', 368, 'messageprovider:contactdataprotectionofficer', 'Data requests', 'Permintaan data', NULL, 1785718291, NULL, 0, 0),
