	(27915, 'id', 368, 'messageprovider:notifyexceptions', 'Data requests exceptions notifications', 'Pemberitahuan pengecualian permintaan data', NULL, 1785718291, NULL, 0, 0),
	(27916, 'id', 368, 'message', 'Message', 'Pesan', NULL, 1785718291, NULL, 0, 0),
