	(27918, 'id', 368, 'moduleinstancename', '{$a->instancename} ({$a->modulename})', '{$a->instancename} ({$a->modulename})', NULL, 1785718291, NULL, 0, 0),
	(27919, 'id', 368, 'mypersonaldatarequests', 'My personal data requests', 'Permintaan data pribadiku', NULL, 1785718291, NULL, 0, 0),
	(27920, 'id', 368, 'nameandparent', '{$a->parent} / {$a->name}', '{$a->parent} / {$a->name}', NULL, 1785718291, NULL, 0, 0),
