	(27924, 'id', 368, 'nodatarequests', 'There are no data requests', 'Tidak ada permintaan data', NULL, 1785718292, NULL, 0, 0),
	(27925, 'id', 368, 'nodatarequestsmatchingfilter', 'There are no data requests matching the given filter', 'Tidak ada permintaan data yang cocok dengan filter yang diberikan', NULL, 1785718292, NULL, 0, 0),
	(27926, 'id', 368, 'noactivitiestoload', 'No activities', 'Tidak ada aktivitas', NULL, 1785718292, NULL, 0, 0),
