	(27944, 'id', 368, 'privacy:metadata:preference:tool_dataprivacy_request-filters', 'The filters currently applied to the data requests page.', 'Filter saat ini diterapkan ke halaman permintaan data.', NULL, 1785718292, NULL, 0, 0),
	(27945, 'id', 368, 'privacy:metadata:preference:tool_dataprivacy_request-perpage', 'The number of data requests the user prefers to see on one page', 'Jumlah permintaan data yang lebih disukai pengguna untuk dilihat di satu halaman', NULL, 1785718292, NULL, 0, 0),
	(27946, 'id', 368, 'privacy:metadata:purpose', 'Information from data purposes made for this site.', 'Informasi dari tujuan data yang dibuat untuk situs ini.', NULL, 1785718292, NULL, 0, 0),
