	(27948, 'id', 368, 'privacy:metadata:request', 'Information from personal data requests (subject access and deletion requests) made for this site.', 'Informasi dari permintaan data pribadi (akses subjek dan permintaan penghapusan) dibuat untuk situs ini.', NULL, 1785718292, NULL, 0, 0),
	(27949, 'id', 368, 'privacy:metadata:request:comments', 'Any user comments accompanying the request.', 'Setiap komentar pengguna yang menyertai permintaan tersebut.', NULL, 1785718292, NULL, 0, 0),
