	(27983, 'id', 368, 'requesttype', 'Type', 'Tipe', NULL, 1785718292, NULL, 0, 0),
	(27984, 'id', 368, 'requesttypeuser', '{$a->typename} ({$a->user})', '{$a->typename} ({$a->user})', NULL, 1785718292, NULL, 0, 0),
	(27985, 'id', 368, 'requesttype_help', 'Select the reason for contacting the privacy officer. Be aware that deletion of all personal  data will result in you no longer being able to log in to the site.', 'Pilih alasan menghubungi petugas privasi. Ketahuilah bahwa penghapusan semua data pribadi akan mengakibatkan Anda tidak dapat lagi masuk ke situs.', NULL, 1785718292, NULL, 0, 0),
	(27986, 'id', 368, 'requesttypedelete', 'Delete all of my personal data', 'Hapus semua data pribadiku', NULL, 1785718292, NULL, 0, 0),
	(27987, 'id', 368, 'requesttypedeleteshort', 'Delete', 'Hapus', NULL, 1785718292, NULL, 0, 0),
