	(28009, 'id', 368, 'selectdatarequests', 'Please select data requests.', 'Please select data requests.', NULL, 1785718292, NULL, 0, 0),
	(28010, 'id', 368, 'selectuserdatarequest', 'Select {$a->username}\'s {$a->requesttype} data request.', 'Pilih permintaan data {{$a->username} {$a->requesttype}.', NULL, 1785718292, NULL, 0, 0),
	(28011, 'id', 368, 'send', 'Send', 'Kirim', NULL, 1785718292, NULL, 0, 0),
	(28012, 'id', 368, 'sensitivedatareasons', 'Sensitive personal data processing reasons', 'Alasan pemrosesan data pribadi yang sensitif', NULL, 1785718292, NULL, 0, 0),
	(28013, 'id', 368, 'sensitivedatareasons_help', 'Select one or more applicable reasons that exempts the prohibition of processing sensitive personal data tied to this purpose. For more information, please see  <a href="https://gdpr-info.eu/art-9-gdpr/" target="_blank">GDPR Art. 9.2</a>', 'Pilih satu atau beberapa alasan yang berlaku yang mengecualikan larangan memproses data pribadi sensitif yang terkait dengan tujuan ini. Untuk informasi lebih lanjut, silakan lihat\n<a href="https://gdpr-info.eu/art-9-gdpr/" target="_blank">GDPR Art. 9.2</a>', NULL, 1785718292, NULL, 0, 0),
	(28014, 'id', 368, 'setdefaults', 'Set defaults', 'Setel bawaan', NULL, 1785718292, NULL, 0, 0),
	(28015, 'id', 368, 'showdataretentionsummary', 'Show data retention summary', 'Tampilkan ringkasan retensi data', NULL, 1785718292, NULL, 0, 0),
	(28016, 'id', 368, 'showdataretentionsummary_desc', 'If enabled, a link to the data retention summary is displayed in the page footer and in users\' profiles.', 'Jika diaktifkan, tautan ke ringkasan retensi data akan ditampilkan di footer halaman dan di profil pengguna.', NULL, 1785718292, NULL, 0, 0),
