	(28028, 'id', 368, 'subjectscope', 'Subject scope', 'Ruang lingkup subjek', NULL, 1785718292, NULL, 0, 0),
	(28029, 'id', 368, 'subjectscope_help', 'The subject scope lists the roles which may be assigned in this context.', 'Ruang lingkup subjek mencantumkan peran yang mungkin ditugaskan dalam konteks ini.', NULL, 1785718292, NULL, 0, 0),
	(28030, 'id', 368, 'summary', 'Registry configuration summary', 'Ringkasan konfigurasi registri', NULL, 1785718292, NULL, 0, 0),
	(28031, 'id', 368, 'systemconfignotsetwarning', 'A site purpose and category have not been defined. When these are not defined, all data will be removed when processing deletion requests.', 'Tujuan dan kategori situs belum ditentukan. Jika ini tidak ditentukan, semua data akan dihapus saat memproses permintaan penghapusan.', NULL, 1785718292, NULL, 0, 0),
	(28032, 'id', 368, 'selectcourses', 'Select courses to export', 'Pilih kursus untuk diekspor', NULL, 1785718292, NULL, 0, 0),
