	(28034, 'id', 368, 'user', 'User', 'Pengguna', NULL, 1785718292, NULL, 0, 0),
	(28035, 'id', 368, 'userlistnoncompliant', 'Userlist provider missing', 'Penyedia daftar pengguna tidak ada', NULL, 1785718292, NULL, 0, 0),
	(28036, 'id', 368, 'userlistexplanation', 'This plugin has the base provider but should also implement the userlist provider for full support of privacy functionality.', 'Pengaya ini memiliki penyedia dasar tetapi juga harus mengimplementasikan penyedia daftar pengguna untuk dukungan penuh fungsionalitas privasi.', NULL, 1785718292, NULL, 0, 0),
	(28037, 'id', 368, 'allowfiltering', 'Allow filtering of exports by course', 'Izinkan pemfilteran ekspor berdasarkan kursus', NULL, 1785718292, NULL, 0, 0),
	(28038, 'id', 368, 'allowfiltering_desc', 'If enabled, the privacy officer can choose to export user data from selected courses instead of all courses. When this feature is enabled,\n export requests will start from \'Pending\' and can only be approved after a background task has completed.', 'Jika diaktifkan, petugas privasi dapat memilih untuk mengekspor data pengguna dari kursus yang dipilih daripada semua kursus. Saat fitur ini diaktifkan, permintaan ekspor akan dimulai dari \'Tertunda\' dan hanya dapat disetujui setelah tugas latar belakang selesai.', NULL, 1785718292, NULL, 0, 0),
	(28039, 'id', 368, 'viewrequest', 'View the request', 'Lihat permintaan', NULL, 1785718292, NULL, 0, 0),
	(28040, 'id', 368, 'visible', 'Expand all', 'Luaskan semua', NULL, 1785718292, NULL, 0, 0),
	(28041, 'id', 368, 'unexpiredrolewithretention', '{$a->retention} (Unexpired)', '{$a->retention} (belum kedaluwarsa)', NULL, 1785718292, NULL, 0, 0),
	(28042, 'id', 368, 'expiredrolewithretention', '{$a->retention} (Expired)', '{$a->retention} (Kedaluwarsa)', NULL, 1785718292, NULL, 0, 0),
	(28043, 'id', 368, 'defaultexpired', 'Data for all users', 'Data semua pengguna', NULL, 1785718292, NULL, 0, 0),
	(28044, 'id', 368, 'defaultexpiredexcept', 'Data for all users, except those who hold any of the following roles:<br>\n{$a->unexpired}', 'Data untuk semua pengguna, kecuali mereka yang memegang salah satu peran berikut: <br> {$a->unexpired}', NULL, 1785718292, NULL, 0, 0),
	(28045, 'id', 368, 'defaultunexpiredwithexceptions', 'Only data for users who hold any of the following roles:<br>\n{$a->expired}\nUnless they also hold any of the following roles:<br>\n{$a->unexpired}', 'Hanya data untuk pengguna yang memegang salah satu peran berikut: <br> {$a->expired}\nKecuali mereka juga memegang salah satu peran berikut: <br> {$a->unexpired}', NULL, 1785718292, NULL, 0, 0),
	(28046, 'id', 368, 'defaultunexpired', 'Only data for users holding any of the following roles:<br>\n{$a->expired}', 'Hanya data untuk pengguna yang memegang salah satu peran berikut:<br> {$a->expired}', NULL, 1785718292, NULL, 0, 0),
	(28047, 'id', 368, 'tobedeleted', 'Data to be deleted', 'Data yang akan dihapus', NULL, 1785718292, NULL, 0, 0),
	(28048, 'id', 368, 'addroleoverride', 'Add role override', 'Tambahkan penyampingan peran', NULL, 1785718292, NULL, 0, 0),
