	(28671, 'id', 379, 'warningcouldnotremovemodulecompetency', 'The activity or resource competency could not be removed.', 'Aktivitas atau kompetensi sumber tidak dapat dihapus.', NULL, 1785718295, NULL, 0, 0),
	(28672, 'id', 379, 'warningdestinationcoursecompetencyalreadyexists', 'The destination course competency already exists.', 'Kompetensi kursus tujuan sudah ada.', NULL, 1785718295, NULL, 0, 0),
