	(28769, 'id', 381, 'error:actionnotfound', 'Action \'{$a}\' not supported', 'Aksi \'{$a}\' tidak didukung', NULL, 1785718296, NULL, 0, 0),
	(28770, 'id', 381, 'error:couldnotreplace', 'Could not replace this factor.', 'Tidak dapat menggantikan faktor ini.', NULL, 1785718296, NULL, 0, 0),
	(28771, 'id', 381, 'error:directaccess', 'This page shouldn\'t be accessed directly', 'Halaman ini tidak boleh diakses secara langsung', NULL, 1785718296, NULL, 0, 0),
	(28772, 'id', 381, 'error:factornotenabled', 'Multi-factor authentication factor \'{$a}\' not enabled', 'Faktor autentikasi multi-faktor \'{$a}\' tidak diaktifkan', NULL, 1785718296, NULL, 0, 0),
	(28773, 'id', 381, 'error:factornotfound', 'Multi-factor authentication factor \'{$a}\' not found', 'Faktor autentikasi multi-faktor \'{$a}\' tidak ditemukan', NULL, 1785718296, NULL, 0, 0),
	(28774, 'id', 381, 'error:isguestuser', 'Guests are not allowed here.', 'Tamu tidak diperbolehkan di sini.', NULL, 1785718296, NULL, 0, 0),
	(28775, 'id', 381, 'error:notenoughfactors', 'Unable to authenticate', 'Tidak dapat mengautentikasi', NULL, 1785718296, NULL, 0, 0),
	(28776, 'id', 381, 'error:reauth', 'We couldn\'t confirm your identity sufficiently to meet the site authentication security policy.<br>This may be due to: <br> 1) Steps being locked - please wait a few minutes and try again.\n     <br> 2) Steps being failed - please double check the details for each step. <br> 3) Steps were skipped - please reload this page or try logging in again.', 'Kami tidak dapat mengonfirmasi identitas Anda secara memadai untuk memenuhi kebijakan keamanan autentikasi situs.<br>Hal ini mungkin disebabkan oleh: <br> 1) Langkah-langkah terkunci - harap tunggu beberapa menit dan coba lagi.\n     <br> 2) Langkah-langkah gagal - harap periksa kembali detail setiap langkah. <br> 3) Langkah-langkah dilewati - harap muat ulang halaman ini atau coba masuk lagi.', NULL, 1785718296, NULL, 0, 0),
