	(29872, 'id', 398, 'description', 'Description', 'Deskripsi', NULL, 1785718301, NULL, 0, 0),
	(29873, 'id', 398, 'description_help', 'The description of a tour may be added as plain text, enclosed in multilang tags (for use with the multi-language content filter) if required.\n\nAlternatively, a language string ID may be entered in the format identifier,component (with no brackets or space after the comma).', 'Deskripsi tur dapat ditambahkan sebagai teks biasa, dilampirkan dalam tag multibahasa (untuk digunakan dengan filter konten multibahasa) jika diperlukan.\n\nAtau, ID string bahasa dapat dimasukkan dalam pengenal format,komponen (tanpa tanda kurung atau spasi setelah koma).', NULL, 1785718301, NULL, 0, 0),
	(29874, 'id', 398, 'displaystepnumbers', 'Display step numbers', 'Tampilkan nomor langkah', NULL, 1785718301, NULL, 0, 0),
	(29875, 'id', 398, 'displaystepnumbers_help', 'Whether to display a step number count e.g. 1/4, 2/4 etc. to indicate the length of the user tour.', 'Apakah akan menampilkan jumlah langkah, mis. 1/4, 2/4 dst. untuk menunjukkan lamanya tur pengguna.', NULL, 1785718301, NULL, 0, 0),
