	(30065, 'id', 398, 'tour_navigation_mycourses_content', '@@PIXICON::tour/tour_mycourses::tool_usertours@@<br>Add, copy, delete and hide courses from this menu.', '@@PIXICON::tour/tour_mycourses::tool_usertours@@<br>Tambah, salin, hapus, dan sembunyikan kursus dari menu ini.', NULL, 1785718302, NULL, 0, 0),
	(30066, 'id', 398, 'tour_navigation_mycourses_endtourlabel', 'I understand', 'Saya mengerti', NULL, 1785718302, NULL, 0, 0),
