	(30339, 'id', 406, 'test_issuerinvalid', 'The OAuth service in the document converter settings is set to an invalid value.', 'Layanan OAuth dalam setelan konverter dokumen diatur ke nilai yang tidak valid.', NULL, 1785718304, NULL, 0, 0),
	(30340, 'id', 406, 'test_issuernotenabled', 'The OAuth service set in the document converter settings is not enabled.', 'Layanan OAuth yang diatur dalam setelan konverter dokumen tidak diaktifkan.', NULL, 1785718304, NULL, 0, 0),
	(30341, 'id', 406, 'test_issuernotconnected', 'The OAuth service set in the document converter settings does not have a system account connected.', 'Layanan OAuth yang diatur dalam setelan konverter dokumen tidak memiliki akun sistem yang terhubung.', NULL, 1785718304, NULL, 0, 0),
	(30342, 'id', 406, 'test_issuernotset', 'The OAuth service needs to be set in the document converter settings.', 'Layanan OAuth perlu diatur dalam setelan konverter dokumen.', NULL, 1785718304, NULL, 0, 0),
	(30343, 'id', 407, 'pathtounoconv', 'Path to unoconv document converter', 'Jalur ke konverter dokumen unoconv', NULL, 1785718304, NULL, 0, 0),
	(30344, 'id', 407, 'pathtounoconv_help', 'Path to unoconv document converter. This is an executable that is capable of converting between document formats supported by LibreOffice. This is optional, but if specified, Moodle will use it to automatically convert between document formats. This is used to support a wider range of input files for the assignment annotate PDF feature.', 'Letak konverter dokumen unoconv. Ini adalah dapat dieksekusi yang mampu mengkonversi antara format dokumen yang didukung oleh LibreOffice. Ini opsional, tetapi jika ditentukan, Moodle akan menggunakannya untuk secara otomatis mengkonversi antar format dokumen. Ini digunakan untuk mendukung lebih banyak berkas input untuk fitur anotasi tugas PDF.', NULL, 1785718304, NULL, 0, 0),
	(30345, 'id', 407, 'pluginname', 'Unoconv', 'Unoconv', NULL, 1785718304, NULL, 0, 0),
	(30346, 'id', 407, 'privacy:metadata', 'The Unoconv document converter plugin does not store any personal data.', 'Pengaya Konverter dokumen tidak menyimpan data pribadi apa pun.', NULL, 1785718304, NULL, 0, 0),
	(30347, 'id', 407, 'test_unoconv', 'Test unoconv path', 'Uji jalur unoconv', NULL, 1785718304, NULL, 0, 0),
	(30348, 'id', 407, 'test_unoconvdoesnotexist', 'The unoconv path does not point to the unoconv program. Please review your path settings.', 'Jalur unoconv tidak mengarah ke program unoconv. Harap tinjau setalan jalur Anda.', NULL, 1785718304, NULL, 0, 0),
	(30349, 'id', 407, 'test_unoconvdownload', 'Download the converted pdf test file.', 'Unduh berkas tes pdf yang dikonversi.', NULL, 1785718304, NULL, 0, 0),
	(30350, 'id', 407, 'test_unoconvempty', 'The unoconv path is not set. Please review your path settings.', 'Jalur unoconv tidak disetel. Harap tinjau setelan jalur Anda.', NULL, 1785718304, NULL, 0, 0),
	(30351, 'id', 407, 'test_unoconvisdir', 'The unoconv path points to a folder, please include the unoconv program in the path you specify', 'Jalur unoconv menunjuk ke folder, harap sertakan program unoconv di jalur yang Anda tentukan', NULL, 1785718304, NULL, 0, 0),
	(30352, 'id', 407, 'test_unoconvnotestfile', 'The test document to be converted to PDF is missing.', 'Dokumen uji yang akan dikonversi ke PDF tidak ada.', NULL, 1785718304, NULL, 0, 0),
	(30353, 'id', 407, 'test_unoconvnotexecutable', 'The unoconv path points to a file that is not executable', 'Jalur unoconv menunjuk ke berkas yang tidak dapat dieksekusi', NULL, 1785718304, NULL, 0, 0),
