	(30390, 'id', 409, 'privacy:metadata:preference:draweropenblock', 'The user\'s preference for hiding or showing the drawer with blocks.', 'Preferensi pengguna untuk menyembunyikan atau menampilkan laci dengan balok.', NULL, 1785718304, NULL, 0, 0),
