	(31009, 'id', 442, 'partialgs', 'Use this service for grade sync only', 'Gunakan layanan ini hanya untuk sinkronisasi nilai', NULL, 1785718308, NULL, 0, 0),
	(31010, 'id', 442, 'pluginname', 'LTI Assignment and Grade Services', 'Layanan Penugasan dan Penilaian LTI', NULL, 1785718308, NULL, 0, 0),
