	(32614, 'id', 516, 'jsonformat', 'JSON format', 'Format JSON', NULL, 1785718317, NULL, 0, 0),
	(32615, 'id', 516, 'jsonformat_desc', 'Use standard JSON format instead of PHP serialised data in the \'other\' database field.', 'Gunakan format JSON standar sebagai ganti data serial PHP di ruas  basis data \'lainnya\'.', NULL, 1785718317, NULL, 0, 0),
	(32616, 'id', 516, 'pluginname', 'Standard log', 'Log standar', NULL, 1785718317, NULL, 0, 0),
	(32617, 'id', 516, 'pluginname_desc', 'A log plugin stores log entries in a Moodle database table.', 'Pengaya log menyimpan entri log dalam tabel basis data Moodle.', NULL, 1785718317, NULL, 0, 0),
	(32618, 'id', 516, 'privacy:metadata:log', 'A collection of past events', 'Kumpulan acara lampau', NULL, 1785718317, NULL, 0, 0),
	(32619, 'id', 516, 'privacy:metadata:log:anonymous', 'Whether the event was flagged as anonymous', 'Apakah acara ditandai sebagai anonim', NULL, 1785718317, NULL, 0, 0),
