	(32624, 'id', 516, 'privacy:metadata:log:realuserid', 'The ID of the real user behind the event, when masquerading a user.', 'ID pengguna sebenarnya di balik acara, saat menyamar sebagai pengguna.', NULL, 1785718317, NULL, 0, 0),
	(32625, 'id', 516, 'privacy:metadata:log:relateduserid', 'The ID of a user related to this event', 'ID pengguna yang terkait dengan acara ini', NULL, 1785718317, NULL, 0, 0),
	(32626, 'id', 516, 'privacy:metadata:log:timecreated', 'The time when the event occurred', 'Waktu terjadinya peristiwa tersebut', NULL, 1785718317, NULL, 0, 0),
	(32627, 'id', 516, 'privacy:metadata:log:userid', 'The ID of the user who triggered this event', 'Waktu terjadinya peristiwa tersebut', NULL, 1785718317, NULL, 0, 0),
	(32628, 'id', 516, 'taskcleanup', 'Log table cleanup', 'Pembersihan tabel log', NULL, 1785718317, NULL, 0, 0),
	(32629, 'id', 517, 'info', 'This factor allows for NOT being an administrator to count as a factor. Its intended use is to ensure administators require tighter security, so regular users get the weight for free, while admins must use other factors.', 'Faktor ini memungkinkan TIDAK menjadi administrator untuk dihitung sebagai faktor. Tujuan penggunaannya adalah untuk memastikan administrator memerlukan keamanan yang lebih ketat, sehingga pengguna biasa mendapatkan beban secara gratis, sedangkan admin harus menggunakan faktor lain.', NULL, 1785718317, NULL, 0, 0),
	(32630, 'id', 517, 'pluginname', 'Non-administrator', 'Non-administrator', NULL, 1785718317, NULL, 0, 0),
	(32631, 'id', 517, 'privacy:metadata', 'The Non-administrator factor plugin does not store any personal data.', 'Pengaya faktor Non-administrator tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32632, 'id', 517, 'settings:weight_help', 'Weight is given to regular users for this factor, so admins must have more factors than a regular user to pass.', 'Bobot diberikan kepada pengguna biasa untuk faktor ini, jadi admin harus memiliki lebih banyak faktor daripada pengguna biasa untuk bisa lolos.', NULL, 1785718317, NULL, 0, 0),
	(32633, 'id', 517, 'summarycondition', 'is not an admin', 'bukan admin', NULL, 1785718317, NULL, 0, 0),
	(32634, 'id', 518, 'info', 'Check the type of authentication used to log in as an MFA factor.', 'Periksa jenis autentikasi yang digunakan untuk masuk sebagai faktor MFA.', NULL, 1785718317, NULL, 0, 0),
	(32635, 'id', 518, 'pluginname', 'Authentication type', 'Jenis Autentikasi', NULL, 1785718317, NULL, 0, 0),
	(32636, 'id', 518, 'privacy:metadata', 'The Authentication type factor plugin does not store any personal data.', 'Pengaya faktor tipe otentikasi tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32637, 'id', 518, 'settings:goodauth', 'Factor authentication types', 'Jenis otentikasi faktor', NULL, 1785718317, NULL, 0, 0),
	(32638, 'id', 518, 'settings:goodauth_help', 'Select all authentication types to use as a factor for MFA. Any types not selected will not be treated as a FAIL in MFA.', 'Pilih semua jenis autentikasi untuk digunakan sebagai faktor MFA. Jenis apa pun yang tidak dipilih tidak akan dianggap GAGAL di MFA.', NULL, 1785718317, NULL, 0, 0),
	(32639, 'id', 518, 'summarycondition', 'has an authentication type of {$a}', 'memiliki tipe autentikasi {$a}', NULL, 1785718317, NULL, 0, 0),
	(32640, 'id', 519, 'capability:cannotpassfactor', 'Must use other factor in MFA to authenticate', 'Harus menggunakan faktor lain dalam MFA untuk mengotentikasi', NULL, 1785718317, NULL, 0, 0),
	(32641, 'id', 519, 'pluginname', 'User capability', 'Kemampuan pengguna', NULL, 1785718317, NULL, 0, 0),
	(32642, 'id', 519, 'privacy:metadata', 'The User capability factor plugin does not store any personal data.', 'Pengaya faktor kemampuan Pengguna tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32643, 'id', 519, 'settings:adminpasses', 'Site admins can pass this factor', 'Admin situs dapat melewati faktor ini', NULL, 1785718317, NULL, 0, 0),
	(32644, 'id', 519, 'settings:adminpasses_help', 'By default admins pass all capability checks, including this one which uses \'factor/capability:cannotpassfactor\', which means they will fail this factor.\n    If checked then all site admins will pass this factor if they do not have this capability from another role.\n    If unchecked site admins will fail this factor.', 'Secara bawaan admin melewati semua pemeriksaan kemampuan, termasuk yang menggunakan \'\'factor/capability:cannotpassfactor\', yang berarti mereka akan gagal dalam faktor ini. Jika dicentang maka semua admin situs akan melewati faktor ini jika mereka tidak memiliki kemampuan ini dari peran lain. Jika admin situs tidak dicentang, faktor ini akan gagal.', NULL, 1785718317, NULL, 0, 0),
	(32645, 'id', 519, 'summarycondition', 'does NOT have the factor/capability:cannotpassfactor capability in any role including site administrator.', 'TIDAK memiliki kemampuan factor/capability:cannotpassfactor dalam peran apa pun termasuk administrator situs.', NULL, 1785718317, NULL, 0, 0),
	(32646, 'id', 520, 'pluginname', 'Cohort', 'Cohort', NULL, 1785718317, NULL, 0, 0),
	(32647, 'id', 520, 'privacy:metadata', 'The Cohort factor plugin does not store any personal data.', 'Pengaya faktor kohor tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32648, 'id', 520, 'settings:cohort', 'Non-passing cohorts', 'Pengaya faktor kohor tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32649, 'id', 520, 'settings:cohort_help', 'Select the cohorts that will not pass this factor. This allows you to force these cohorts to use other factors to authenticate.', 'Pilih kohor yang tidak lolos faktor ini. Hal ini memungkinkan Anda memaksa kohor ini menggunakan faktor lain untuk mengautentikasi.', NULL, 1785718317, NULL, 0, 0),
	(32650, 'id', 520, 'summarycondition', 'does NOT have any of the following cohorts assigned in any context: {$a}', 'TIDAK memiliki cohor berikut yang ditetapkan dalam konteks apa pun: {$a}', NULL, 1785718317, NULL, 0, 0),
	(32651, 'id', 521, 'email:accident', 'If you didn\'t request the email, click continue to invalidate the login attempt. If you clicked the link by accident, click cancel, and no action will be taken.', 'Jika Anda tidak meminta surel, klik lanjutkan untuk membatalkan upaya masuk. Jika Anda mengeklik tautan secara tidak sengaja, mengeklik batal, dan tidak ada tindakan yang akan diambil.', NULL, 1785718317, NULL, 0, 0),
	(32652, 'id', 521, 'email:browseragent', 'The browser details for this request are: \'{$a}\'', 'Detail peramban untuk permintaan ini adalah: \'{$a}\'', NULL, 1785718317, NULL, 0, 0),
	(32653, 'id', 521, 'email:geoinfo', 'This request appears to have originated from approximately:', 'Permintaan ini tampaknya berasal dari sekitar:', NULL, 1785718317, NULL, 0, 0),
	(32654, 'id', 521, 'email:greeting', 'Hello {$a} &#128075;', 'Halo {$a} 👋', NULL, 1785718317, NULL, 0, 0),
	(32655, 'id', 521, 'email:ipinfo', 'Login request details:', 'Detail permintaan masuk:', NULL, 1785718317, NULL, 0, 0),
	(32656, 'id', 521, 'email:link', 'verification link', 'tautan verifikasi', NULL, 1785718317, NULL, 0, 0),
	(32657, 'id', 521, 'email:loginlink', 'Or, if you\'re on the same device, use this {$a}.', 'Atau, jika Anda menggunakan perangkat yang sama, gunakan {$a} ini.', NULL, 1785718317, NULL, 0, 0),
	(32658, 'id', 521, 'email:message', 'Here\'s your verification code for {$a->sitename} ({$a->siteurl}).', 'Berikut kode verifikasi Anda untuk {$a->sitename} ({$a->siteurl}).', NULL, 1785718317, NULL, 0, 0),
	(32659, 'id', 521, 'email:originatingip', 'This login request was made from \'{$a}\'', 'Permintaan log masuk ini dibuat dari \'{$a}\'', NULL, 1785718317, NULL, 0, 0),
	(32660, 'id', 521, 'email:revokelink', 'If this wasn\'t you, you can {$a}.', 'Jika ini bukan Anda, Anda dapat {$a}.', NULL, 1785718317, NULL, 0, 0),
	(32661, 'id', 521, 'email:revokesuccess', 'This code has been successfully revoked. All sessions for this user have been ended.\n    Email will not be usable as a factor until account security has been verified.', 'Kode ini telah berhasil dibatalkan. Semua sesi untuk pengguna ini telah berakhir.\n     Surel tidak akan dapat digunakan sebagai faktor hingga keamanan akun diverifikasi.', NULL, 1785718317, NULL, 0, 0),
	(32662, 'id', 521, 'email:subject', 'Here\'s your verification code', 'Ini kode verifikasi Anda', NULL, 1785718317, NULL, 0, 0),
	(32663, 'id', 521, 'email:stoploginlink', 'stop this login attempt', 'hentikan upaya masuk ini', NULL, 1785718317, NULL, 0, 0),
	(32664, 'id', 521, 'email:uadescription', 'Browser identity for this request:', 'Identitas  peramban untuk permintaan ini:', NULL, 1785718317, NULL, 0, 0),
	(32665, 'id', 521, 'email:validity', 'The code can only be used once and is valid for {$a}.', 'Kode hanya dapat digunakan satu kali dan berlaku selama {$a}.', NULL, 1785718317, NULL, 0, 0),
	(32666, 'id', 521, 'error:badcode', 'Code was not found. This may be an old link, a new code may have been emailed, or the login attempt with this code was successful.', 'Kode tidak ditemukan. Ini mungkin tautan lama, kode baru mungkin telah dikirim melalui surel, atau upaya masuk dengan kode ini berhasil.', NULL, 1785718317, NULL, 0, 0),
	(32667, 'id', 521, 'error:parameters', 'Incorrect page parameters.', 'Parameter halaman salah.', NULL, 1785718317, NULL, 0, 0),
	(32668, 'id', 521, 'error:wrongverification', 'Wrong code. Try again.', 'Salah kode. Coba lagi.', NULL, 1785718317, NULL, 0, 0),
	(32669, 'id', 521, 'event:unauthemail', 'Unauthorised email received', 'Surel tidak sah diterima', NULL, 1785718317, NULL, 0, 0),
	(32670, 'id', 521, 'info', 'You are using email {$a} to authenticate. This has been set up by your site administrator.', 'Anda menggunakan surel {$a} untuk mengautentikasi. Ini telah disiapkan oleh administrator situs Anda.', NULL, 1785718317, NULL, 0, 0),
	(32671, 'id', 521, 'logindesc', 'We\'ve just sent a 6-digit code to your email: {$a}', 'Kami baru saja mengirimkan kode 6 digit ke surel Anda: {$a}', NULL, 1785718317, NULL, 0, 0),
	(32672, 'id', 521, 'loginoption', 'Have a code emailed to you', 'Dapatkan kode yang dikirimkan ke surel Anda', NULL, 1785718317, NULL, 0, 0),
	(32673, 'id', 521, 'loginskip', 'I didn\'t receive a code', 'Saya tidak menerima kode', NULL, 1785718317, NULL, 0, 0),
	(32674, 'id', 521, 'loginsubmit', 'Continue', 'Lanjutkan', NULL, 1785718317, NULL, 0, 0),
	(32675, 'id', 521, 'logintitle', 'Verify it\'s you by email', 'Verifikasi bahwa ini memang Anda melalui surel', NULL, 1785718317, NULL, 0, 0),
	(32676, 'id', 521, 'managefactor', 'Manage email', 'Kelola surel', NULL, 1785718317, NULL, 0, 0),
	(32677, 'id', 521, 'manageinfo', '\'{$a}\' is being used to authenticate. This has been set up by your administrator.', '\'{$a}\' digunakan untuk mengautentikasi. Ini telah diatur oleh administrator Anda.', NULL, 1785718317, NULL, 0, 0),
	(32678, 'id', 521, 'pluginname', 'Email', 'Surel', NULL, 1785718317, NULL, 0, 0),
	(32679, 'id', 521, 'privacy:metadata', 'The Email factor plugin does not store any personal data', 'Pengaya faktor surel tidak menyimpan data pribadi apa pun', NULL, 1785718317, NULL, 0, 0),
	(32680, 'id', 521, 'settings:duration', 'Validity duration', 'Durasi validitas', NULL, 1785718317, NULL, 0, 0),
	(32681, 'id', 521, 'settings:duration_help', 'The period of time that the code is valid.', 'Jangka waktu validitas kode tersebut.', NULL, 1785718317, NULL, 0, 0),
	(32682, 'id', 521, 'settings:suspend', 'Suspend unauthorised accounts', 'Tangguhkan akun yang tidak sah', NULL, 1785718317, NULL, 0, 0),
	(32683, 'id', 521, 'settings:suspend_help', 'Check this to suspend user accounts if an unauthorised email verification is received.', 'Centang ini untuk menangguhkan akun pengguna jika verifikasi surel yang tidak sah diterima.', NULL, 1785718317, NULL, 0, 0),
	(32684, 'id', 521, 'setupfactor', 'Set up email', 'Siapkan surel', NULL, 1785718317, NULL, 0, 0),
	(32685, 'id', 521, 'summarycondition', 'has valid email setup', 'memiliki setelan surel yang valid', NULL, 1785718317, NULL, 0, 0),
	(32686, 'id', 521, 'unauthloginattempt', 'The user with ID {$a->userid} made an unauthorised login attempt using email verification from\nIP {$a->ip} with browser agent {$a->useragent}.', 'Pengguna dengan ID {$a->userid} melakukan upaya masuk tanpa izin menggunakan verifikasi surel dari IP {$a->ip} dengan agen peramban {$a->useragent}.', NULL, 1785718317, NULL, 0, 0),
	(32687, 'id', 521, 'unauthemail', 'Unauthorised email', 'Surel tidak sah', NULL, 1785718317, NULL, 0, 0),
	(32688, 'id', 521, 'verificationcode', 'Enter verification code for confirmation', 'Masukkan kode verifikasi untuk konfirmasi', NULL, 1785718317, NULL, 0, 0),
	(32689, 'id', 521, 'verificationcode_help', 'A verification code has been sent to your email.', 'Kode verifikasi telah dikirim ke surel Anda.', NULL, 1785718317, NULL, 0, 0),
	(32690, 'id', 522, 'info', 'Allows login without other factor for a specified period of time.', 'Memungkinkan masuk tanpa faktor lain untuk jangka waktu tertentu.', NULL, 1785718317, NULL, 0, 0),
	(32691, 'id', 522, 'pluginname', 'Grace period', 'Masa tenggang', NULL, 1785718317, NULL, 0, 0),
	(32692, 'id', 522, 'preferences', 'User preferences', 'Preferensi pengguna', NULL, 1785718317, NULL, 0, 0),
	(32693, 'id', 522, 'privacy:metadata', 'The Grace period factor plugin does not store any personal data', 'Pengaya faktor masa tenggang tidak menyimpan data pribadi apa pun', NULL, 1785718317, NULL, 0, 0),
	(32694, 'id', 522, 'redirectsetup', 'You must complete setup for Multi-factor authentication before you can proceed.', 'Anda harus menyelesaikan penyiapan Autentikasi multifaktor sebelum dapat melanjutkan.', NULL, 1785718317, NULL, 0, 0),
	(32695, 'id', 522, 'revokeexpiredfactors', 'Revoke expired grace period factors', 'Cabut faktor masa tenggang yang sudah habis masa berlakunya', NULL, 1785718317, NULL, 0, 0),
	(32696, 'id', 522, 'settings:customwarning', 'Warning banner content', 'Peringatan konten spanduk', NULL, 1785718317, NULL, 0, 0),
	(32697, 'id', 522, 'settings:customwarning_help', 'Add content here to replace the grace warning notification with custom HTML contents. Adding {timeremaining} in text will replace it with the current grace duration for the user, and {setuplink} will replace with the URL of the setup page for the user.', 'Tambahkan konten di sini untuk mengganti pemberitahuan peringatan tenggang dengan konten HTML kustom. Menambahkan {timeremaining} dalam teks akan menggantikannya dengan durasi tenggang saat ini bagi pengguna, dan {setuplink} akan menggantikan URL laman penyiapan untuk pengguna.', NULL, 1785718317, NULL, 0, 0),
	(32698, 'id', 522, 'settings:forcesetup', 'Force factor setup', 'Paksa setelan faktor', NULL, 1785718317, NULL, 0, 0),
	(32699, 'id', 522, 'settings:forcesetup_help', 'Forces a user to the preferences page to set up multi-factor authentication when the grace period expires. If unchecked, users will be unable to authenticate when the grace period expires.', 'Memaksa pengguna ke halaman preferensi untuk menyiapkan autentikasi multifaktor ketika masa tenggang berakhir. Jika tidak dicentang, pengguna tidak akan dapat mengautentikasi ketika masa tenggang berakhir.', NULL, 1785718317, NULL, 0, 0),
	(32700, 'id', 522, 'settings:graceperiod', 'Grace period', 'Masa tenggang', NULL, 1785718317, NULL, 0, 0),
	(32701, 'id', 522, 'settings:graceperiod_help', 'Period of time when users can access the site without configured and enabled factors.', 'Periode waktu ketika pengguna dapat mengakses situs tanpa faktor yang dikonfigurasi dan diaktifkan.', NULL, 1785718317, NULL, 0, 0),
	(32702, 'id', 522, 'settings:ignorelist', 'Ignored factors', 'Faktor yang diabaikan', NULL, 1785718317, NULL, 0, 0),
	(32703, 'id', 522, 'settings:ignorelist_help', 'Grace period will not give points if there are other factors that users can use to authenticate with multi-factor authentication. Any factors here will not be counted by Grace period when deciding whether to give points. This can allow Grace period to allow authentication if another factor like email, has configuration or system issues.', 'Masa tenggang tidak akan memberikan poin jika ada faktor lain yang dapat digunakan pengguna untuk melakukan autentikasi dengan autentikasi multifaktor. Faktor apa pun di sini tidak akan dihitung dalam masa tenggang saat memutuskan apakah akan memberikan poin. Hal ini memungkinkan masa tenggang untuk mengizinkan autentikasi jika faktor lain seperti surel, memiliki masalah konfigurasi atau sistem.', NULL, 1785718317, NULL, 0, 0),
	(32704, 'id', 522, 'setupfactors', 'You are currently in the grace period, and may not have enough factors set up to log in once the grace period expires. Go to {$a->url} to check your authentication status and set up more authentication factors. Your grace period expires in {$a->time}.', 'Saat ini Anda berada dalam masa tenggang, dan mungkin tidak memiliki cukup faktor untuk masuk setelah masa tenggang berakhir. Buka {$a->url} untuk memeriksa status autentikasi Anda dan menyiapkan faktor autentikasi lainnya. Masa tenggang Anda akan berakhir dalam {$a->time}.', NULL, 1785718317, NULL, 0, 0),
	(32705, 'id', 522, 'summarycondition', 'is within grace period', 'berada dalam masa tenggang', NULL, 1785718317, NULL, 0, 0),
	(32706, 'id', 523, 'allowedipsempty', 'Nobody will currently pass this factor! You can add your own IP address (<i>{$a->ip}</i>)', 'Saat ini tidak ada seorang pun yang akan melewati faktor ini! Anda dapat menambahkan alamat IP Anda sendiri (<i>{$a->ip}</i>)', NULL, 1785718317, NULL, 0, 0),
	(32707, 'id', 523, 'allowedipshasmyip', 'Your IP (<i>{$a->ip}</i>) is in the list and you will pass this factor.', 'IP Anda (<i>{$a->ip}</i>) ada dalam daftar dan Anda akan melewati faktor ini.', NULL, 1785718317, NULL, 0, 0),
	(32708, 'id', 523, 'allowedipshasntmyip', 'Your IP (<i>{$a->ip}</i>) is not in the list and you will not pass this factor.', 'IP Anda (<i>{$a->ip}</i>) tidak ada dalam daftar dan Anda tidak akan melewati faktor ini.', NULL, 1785718317, NULL, 0, 0),
	(32709, 'id', 523, 'pluginname', 'IP range', 'rentang IP', NULL, 1785718317, NULL, 0, 0),
	(32710, 'id', 523, 'privacy:metadata', 'The IP range factor plugin does not store any personal data.', 'Pengaya faktor rentang IP tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32711, 'id', 523, 'settings:safeips', 'Safe IP ranges', 'Rentang IP aman', NULL, 1785718317, NULL, 0, 0),
	(32712, 'id', 523, 'settings:safeips_help', 'Enter a list of IP addresses or subnets to be counted as a pass in factor. If empty nobody will pass this factor. {$a->info} {$a->syntax}', 'Masukkan daftar alamat IP atau subnet untuk dihitung sebagai faktor kelulusan. Jika kosong tidak ada yang akan melewati faktor ini. {$a->info} {$a->syntax}', NULL, 1785718317, NULL, 0, 0),
	(32713, 'id', 523, 'summarycondition', 'is on a secured network', 'berada di jaringan aman', NULL, 1785718317, NULL, 0, 0),
	(32714, 'id', 524, 'deleteunusablefactors', 'Delete unusable Nosetup factors', 'Hapus faktor Nosetup yang tidak dapat digunakan', NULL, 1785718317, NULL, 0, 0),
	(32715, 'id', 524, 'info', 'This factor passes if the user has no other factors set up.', 'Faktor ini lolos jika pengguna tidak menyiapkan faktor lain.', NULL, 1785718317, NULL, 0, 0),
	(32716, 'id', 524, 'pluginname', 'No other factors', 'Tidak ada faktor lain', NULL, 1785718317, NULL, 0, 0),
	(32717, 'id', 524, 'privacy:metadata', 'The No other factors plugin does not store any personal data', 'Pengaya Tidak ada faktor lain tidak menyimpan data pribadi apa pun', NULL, 1785718317, NULL, 0, 0),
	(32718, 'id', 524, 'summarycondition', 'has no other factors set up', 'tidak ada faktor lain yang diatur', NULL, 1785718317, NULL, 0, 0),
	(32719, 'id', 525, 'pluginname', 'Role', 'Peran', NULL, 1785718317, NULL, 0, 0),
	(32720, 'id', 525, 'privacy:metadata', 'The Role factor plugin does not store any personal data.', 'Pengaya Faktor Peran tidak menyimpan data pribadi apa pun.', NULL, 1785718317, NULL, 0, 0),
	(32721, 'id', 525, 'settings:roles', 'Non-passing roles', 'Peran yang tidak bisa dilewati', NULL, 1785718317, NULL, 0, 0),
	(32722, 'id', 525, 'settings:roles_help', 'Select the roles that will not pass this factor. This allows you to force these roles to use other factors to authenticate.', 'Pilih peran yang tidak lolos faktor ini. Hal ini memungkinkan Anda memaksa peran tersebut untuk menggunakan faktor lain untuk mengautentikasi.', NULL, 1785718318, NULL, 0, 0),
	(32723, 'id', 525, 'summarycondition', 'does NOT have any of the following roles assigned in any context: {$a}', 'TIDAK memiliki salah satu peran berikut yang ditetapkan dalam konteks apa pun: {$a}', NULL, 1785718318, NULL, 0, 0),
	(32724, 'id', 526, 'action:manage', 'Manage mobile phone number', 'Kelola nomor ponsel', NULL, 1785718318, NULL, 0, 0),
