	(32753, 'id', 526, 'settings:heading', 'Users will receive an SMS with 6-digit code during login, which they must enter to complete the login process.\n\nUsers will need to register their mobile phone number first.', 'Pengguna akan menerima SMS dengan kode 6 digit saat login, yang harus mereka masukkan untuk menyelesaikan proses login.', NULL, 1785718318, NULL, 0, 0),
	(32754, 'id', 526, 'settings:setupdesc', 'To use SMS as an authentication factor, you first need to <a href="{$a}">set up an SMS gateway</a>.', 'Untuk menggunakan SMS sebagai faktor autentikasi, pertama-tama Anda perlu <a href="{$a}">menyiapkan gerbang SMS</a>.', NULL, 1785718318, NULL, 0, 0),
