	(32779, 'id', 527, 'privacy:metadata', 'The Trust this device factor plugin does not store any personal data.', 'Pengaya Percayai faktor perangkat ini tidak menyimpan data pribadi apa pun.', NULL, 1785718318, NULL, 0, 0),
	(32780, 'id', 527, 'settings:expireovernight', 'Expire trust overnight', 'Kedaluwarsa kepercayaan dalam semalam', NULL, 1785718318, NULL, 0, 0),
	(32781, 'id', 527, 'settings:expireovernight_help', 'This forces tokens to expire overnight, preventing midday interruptions for users. Instead they will be asked to multi-factor authenticate at the start of a day after expiry.', 'Hal ini memaksa token untuk kedaluwarsa dalam semalam, mencegah gangguan tengah hari bagi pengguna. Sebaliknya, mereka akan diminta untuk melakukan autentikasi multi-faktor di awal hari setelah habis masa berlakunya.', NULL, 1785718318, NULL, 0, 0),
	(32782, 'id', 527, 'settings:expiry', 'Trust duration', 'Durasi kepercayaan', NULL, 1785718318, NULL, 0, 0),
	(32783, 'id', 527, 'settings:expiry_help', 'The duration a device is trusted before requiring a new multi-factor authentication.', 'Durasi perangkat dipercaya sebelum memerlukan autentikasi multifaktor baru.', NULL, 1785718318, NULL, 0, 0),
	(32784, 'id', 527, 'summarycondition', 'the user has previously trusted this device', 'pengguna sebelumnya telah mempercayai perangkat ini', NULL, 1785718318, NULL, 0, 0),
	(32785, 'id', 527, 'tokenstoredindevice', 'The user with ID {$a->userid} has a multi-factor authentication token stored on their device. <br> Information: {$a->string}.', 'Pengguna dengan ID {$a->userid} memiliki token autentikasi multifaktor yang disimpan di perangkatnya. <br> Informasi: {$a->string}.', NULL, 1785718318, NULL, 0, 0),
	(32786, 'id', 528, 'action:manage', 'Manage time-based one-time password (TOTP) authenticator', 'Kelola pengautentikasi kata sandi satu kali (TOTP) berbasis waktu', NULL, 1785718318, NULL, 0, 0),
	(32787, 'id', 528, 'action:revoke', 'Remove time-based one-time password (TOTP) authenticator', 'Hapus pengautentikasi kata sandi satu kali berbasis waktu (TOTP).', NULL, 1785718318, NULL, 0, 0),
	(32788, 'id', 528, 'devicename', 'Device label', 'Label perangkat', NULL, 1785718318, NULL, 0, 0),
	(32789, 'id', 528, 'devicename_help', 'This is the device you have an authenticator app installed on. You can set up multiple devices so this label helps track which ones are being used. You should set up each device with their own unique code so they can be revoked separately.', 'Ini adalah perangkat tempat Anda menginstal aplikasi autentikator. Anda dapat mengatur beberapa perangkat sehingga label ini membantu melacak perangkat mana yang sedang digunakan. Anda harus menyiapkan setiap perangkat dengan kode uniknya masing-masing sehingga dapat dicabut secara terpisah.', NULL, 1785718318, NULL, 0, 0),
	(32790, 'id', 528, 'devicenameexample', 'eg "Work iPhone 11"', 'misalnya "Work iPhone 11"', NULL, 1785718318, NULL, 0, 0),
	(32791, 'id', 528, 'error:alreadyregistered', 'This time-based one-time password (TOTP) secret has already been registered.', 'Kunci kata sandi satu kali berbasis waktu (TOTP) ini telah didaftarkan.', NULL, 1785718318, NULL, 0, 0),
	(32792, 'id', 528, 'error:codealreadyused', 'This code has already been used to authenticate. Please wait for a new code to be generated, and try again.', 'Kode ini telah digunakan untuk mengautentikasi. Harap tunggu hingga kode baru dibuat, lalu coba lagi.', NULL, 1785718318, NULL, 0, 0),
	(32793, 'id', 528, 'error:futurecode', 'This code is invalid. Please verify the time on your authenticator device is correct and try again.\n    Current system time is {$a}.', 'Kode ini tidak valid. Harap verifikasi waktu pada perangkat pengautentikasi Anda sudah benar dan coba lagi. Waktu sistem saat ini adalah {$a}.', NULL, 1785718318, NULL, 0, 0),
	(32794, 'id', 528, 'error:oldcode', 'This code is too old. Please verify the time on your authenticator device is correct and try again.\n    Current system time is {$a}.', 'Kode ini terlalu lama. Harap verifikasi waktu pada perangkat pengautentikasi Anda sudah benar dan coba lagi.\n   Waktu sistem saat ini adalah {$a}.', NULL, 1785718318, NULL, 0, 0),
	(32795, 'id', 528, 'error:wrongverification', 'Incorrect verification code.', 'Kode verifikasi salah.', NULL, 1785718318, NULL, 0, 0),
