	(32848, 'id', 529, 'error:alreadyregistered', 'This security key secret has already been registered.', 'Rahasia kunci keamanan ini telah didaftarkan.', NULL, 1785718318, NULL, 0, 0),
	(32849, 'id', 529, 'info', 'Use a physical security key or fingerprint scanner.', 'Gunakan kunci keamanan fisik atau pemindai sidik jari.', NULL, 1785718318, NULL, 0, 0),
	(32850, 'id', 529, 'logindesc', 'Click continue to use your security key.', 'Klik lanjutkan untuk menggunakan kunci keamanan Anda.', NULL, 1785718318, NULL, 0, 0),
	(32851, 'id', 529, 'loginoption', 'Use security key', 'Gunakan kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32852, 'id', 529, 'loginskip', 'I don\'t have my security key', 'Saya tidak memiliki kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32853, 'id', 529, 'loginsubmit', 'Continue', 'Lanjutkan', NULL, 1785718318, NULL, 0, 0),
	(32854, 'id', 529, 'logintitle', 'Verify it\'s you by security key', 'Verifikasi bahwa ini memang Anda dengan kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32855, 'id', 529, 'pluginname', 'Security key', 'Kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32856, 'id', 529, 'privacy:metadata', 'The Security key factor plugin does not store any personal data.', 'Pengaya Faktor Kunci Keamanan tidak menyimpan data pribadi apa pun.', NULL, 1785718318, NULL, 0, 0),
	(32857, 'id', 529, 'register', 'Register security key', 'Daftarkan kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32858, 'id', 529, 'replacefactor', 'Replace security key', 'Ganti kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32859, 'id', 529, 'replacefactorconfirmation', 'Replace \'{$a}\' security key?', 'Ganti kunci keamanan \'{$a}\'?', NULL, 1785718318, NULL, 0, 0),
	(32860, 'id', 529, 'revokefactorconfirmation', 'Remove \'{$a}\' security key?', 'Hapus kunci keamanan \'{$a}\'?', NULL, 1785718318, NULL, 0, 0),
	(32861, 'id', 529, 'settings:authenticatortypes', 'Types of authenticator', 'Jenis pengautentikasi', NULL, 1785718318, NULL, 0, 0),
	(32862, 'id', 529, 'settings:authenticatortypes_help', 'Toggle certain types of authenticators', 'Alihkan jenis pengautentikasi tertentu', NULL, 1785718318, NULL, 0, 0),
	(32863, 'id', 529, 'settings:userverification', 'User verification', 'Verifikasi pengguna', NULL, 1785718318, NULL, 0, 0),
	(32864, 'id', 529, 'settings:userverification_help', 'Serves to ensure the person authenticating is in fact who they say they are. User verification can take various forms, such as password, PIN, fingerprint, etc.', 'Berfungsi untuk memastikan orang yang mengautentikasi memang benar seperti yang mereka katakan. Verifikasi pengguna dapat dilakukan dalam berbagai bentuk, seperti kata sandi, PIN, sidik jari, dll.', NULL, 1785718318, NULL, 0, 0),
	(32865, 'id', 529, 'setupfactor', 'Set up security key', 'Siapkan kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32866, 'id', 529, 'setupfactorbutton', 'Set up', 'Persiapkan', NULL, 1785718318, NULL, 0, 0),
	(32867, 'id', 529, 'setupfactorbuttonadditional', 'Add security key', 'Tambahkan kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32868, 'id', 529, 'setupfactor:instructionsregistersecuritykey', '2. Register a security key.', '2. Daftarkan kunci keamanan.', NULL, 1785718318, NULL, 0, 0),
	(32869, 'id', 529, 'setupfactor:instructionssecuritykeyname', '1. Give your key a name.', '1. Beri nama pada kunci Anda.', NULL, 1785718318, NULL, 0, 0),
	(32870, 'id', 529, 'setupfactor:intro', 'A security key is a physical device that you can use to authenticate yourself. Security keys can be USB tokens, Bluetooth devices, or event built-in fingerprint scanners on your phone or computer.', 'Kunci keamanan adalah perangkat fisik yang dapat Anda gunakan untuk mengautentikasi diri Anda sendiri. Kunci keamanan dapat berupa token USB, perangkat Bluetooth, atau pemindai sidik jari bawaan di ponsel atau komputer Anda.', NULL, 1785718318, NULL, 0, 0),
	(32871, 'id', 529, 'setupfactor:securitykeyinfo', 'This helps you identify which security key you are using.', 'Ini membantu Anda mengidentifikasi kunci keamanan mana yang Anda gunakan.', NULL, 1785718318, NULL, 0, 0),
	(32872, 'id', 529, 'summarycondition', 'using a WebAuthn supported authenticator', 'menggunakan autentikator yang didukung WebAuthn', NULL, 1785718318, NULL, 0, 0),
	(32873, 'id', 529, 'managefactor', 'Manage security key', 'Kelola kunci keamanan', NULL, 1785718318, NULL, 0, 0),
	(32874, 'id', 529, 'managefactorbutton', 'Manage', 'Kelola', NULL, 1785718318, NULL, 0, 0),
	(32875, 'id', 529, 'manageinfo', 'You are using \'{$a}\' to authenticate.', 'Anda menggunakan \'{$a}\' untuk mengautentikasi.', NULL, 1785718318, NULL, 0, 0),
	(32876, 'id', 529, 'userverification:discouraged', 'User verification should not be employed, for example to minimize user interaction', 'Verifikasi pengguna tidak boleh digunakan, misalnya untuk meminimalkan interaksi pengguna', NULL, 1785718318, NULL, 0, 0),
	(32877, 'id', 529, 'userverification:preferred', 'User verification is preferred, authentication will not fail if user verification is missing', 'Verifikasi pengguna lebih disukai, otentikasi tidak akan gagal jika verifikasi pengguna tidak ada', NULL, 1785718318, NULL, 0, 0),
	(32878, 'id', 529, 'userverification:required', 'User verification is required (e.g. by pin). Authentication fails if key does not have user verification', 'Verifikasi pengguna diperlukan (misalnya dengan pin). Autentikasi gagal jika kunci tidak memiliki verifikasi pengguna', NULL, 1785718318, NULL, 0, 0);
